<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>ユーザー追加 - FUJIN-P</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
            background: #f5f5f5;
            padding: 20px;
        }
        .container { max-width: 600px; margin: 0 auto; }
        .header {
            background: white;
            padding: 20px;
            border-radius: 8px;
            margin-bottom: 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }
        h1 { color: #333; }
        .back-btn {
            padding: 10px 20px;
            background: #e5e7eb;
            color: #333;
            text-decoration: none;
            border-radius: 6px;
        }
        .back-btn:hover { background: #d1d5db; }
        .form-container {
            background: white;
            border-radius: 8px;
            padding: 30px;
        }
        .form-group {
            margin-bottom: 20px;
        }
        label {
            display: block;
            margin-bottom: 8px;
            color: #333;
            font-weight: 500;
        }
        input[type="email"],
        input[type="text"],
        select {
            width: 100%;
            padding: 12px;
            border: 1px solid #ddd;
            border-radius: 6px;
            font-size: 1rem;
        }
        input:focus, select:focus {
            outline: none;
            border-color: #667eea;
        }
        .radio-group {
            display: flex;
            flex-direction: column;
            gap: 12px;
        }
        .radio-option {
            display: flex;
            align-items: flex-start;
            gap: 10px;
            padding: 12px;
            border: 2px solid #e5e7eb;
            border-radius: 6px;
            cursor: pointer;
            transition: all 0.2s;
        }
        .radio-option:hover {
            border-color: #667eea;
            background: #f9fafb;
        }
        .radio-option input[type="radio"] {
            margin-top: 3px;
            cursor: pointer;
        }
        .radio-option.selected {
            border-color: #667eea;
            background: #eef2ff;
        }
        .radio-label {
            flex: 1;
            cursor: pointer;
        }
        .radio-label strong {
            display: block;
            color: #333;
            margin-bottom: 4px;
        }
        .radio-label .description {
            font-size: 0.9rem;
            color: #666;
        }
        .submit-btn {
            width: 100%;
            padding: 12px;
            background: #667eea;
            color: white;
            border: none;
            border-radius: 6px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
        }
        .submit-btn:hover { background: #5568d3; }
        .flash-messages {
            margin-bottom: 20px;
