        }
        th, td {
            padding: 12px;
            text-align: left;
            border-bottom: 1px solid #e0e0e0;
        }
        th {
            background: #f8f9fa;
            font-weight: 600;
            color: #333;
        }
        tr:hover {
            background: #f8f9fa;
        }
        .btn {
            padding: 6px 12px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 0.9rem;
            text-decoration: none;
            display: inline-block;
        }
        .btn-remove {
            background: #28a745;
            color: white;
        }
        .btn-remove:hover { background: #218838; }
        .no-data {
            text-align: center;
            padding: 40px;
            color: #999;
        }
        .badge {
            display: inline-block;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 0.85rem;
            font-weight: 500;
        }
        .badge-blacklisted {
            background: #f8d7da;
            color: #721c24;
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <div>
                <h1>ブラックリストユーザー</h1>
                <p style="color: #666;">登録を拒否されたユーザーの管理</p>
            </div>
            <a href="{{ url_for('admin.dashboard') }}" class="back-btn">ダッシュボードに戻る</a>
        </div>

        <div class="content">
            <div class="warning-box">
                <strong>注意:</strong> ブラックリストに登録されたメールアドレスは、
                登録申請時に自動的に却下されます。
            </div>

            {% if blacklisted %}
            <table>
                <thead>
                    <tr>
                        <th>メールアドレス</th>
                        <th>氏名</th>
                        <th>所属</th>
                        <th>登録日時</th>
                        <th>処理者</th>
                        <th>操作</th>
                    </tr>
                </thead>
                <tbody>
                    {% for user in blacklisted %}
                    <tr>
                        <td>{{ user.email }}</td>
                        <td>{{ user.full_name }}</td>
                        <td>{{ user.affiliation or '－' }}</td>
                        <td>{{ user.processed_at }}</td>
                        <td>{{ user.processor_name or '－' }}</td>
                        <td>
                            <form action="{{ url_for('admin.remove_from_blacklist', request_id=user.id) }}" 
                                  method="POST" style="display: inline;">
                                <button type="submit" class="btn btn-remove" 
                                        onclick="return confirm('{{ user.email }}をブラックリストから解除しますか？')">
                                    解除
                                </button>
                            </form>
                        </td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
            {% else %}
            <div class="no-data">
                <p>ブラックリストに登録されているユーザーはいません</p>
            </div>
            {% endif %}
        </div>
    </div>
</body>
</html>

