<body>
    <div class="container">
        <div class="header">
            <div>
                <h1>削除済みユーザー</h1>
                <p style="color: #666;">論理削除されたユーザーの管理</p>
            </div>
            <div>
                <a href="{{ url_for('admin.users') }}" class="back-btn" style="margin-right: 10px;">ユーザー一覧に戻る</a>
                <a href="{{ url_for('admin.dashboard') }}" class="back-btn">ダッシュボードに戻る</a>
            </div>
        </div>

        <div class="content">
            <div class="info-box">
                <strong>論理削除について:</strong> 
                削除されたユーザーは物理的にはデータベースに残っていますが、システムからはアクセスできません。
                必要に応じて復元することができます。
            </div>

            <div class="warning-box">
                <strong>⚠️ 物理削除について:</strong> 
                「完全削除」ボタンはユーザーをデータベースから完全に削除します。
                この操作は取り消せません。削除後、同じメールアドレスで再登録が可能になります。
            </div>

            {% if users %}
            <div class="stats-box">
                <strong>削除済みユーザー数:</strong> {{ users|length }}人
            </div>

            <table>
                <thead>
                    <tr>
                        <th>メールアドレス</th>
                        <th>氏名</th>
                        <th>カテゴリ</th>
                        <th>所属</th>
                        <th>削除日時</th>
                        <th>削除者</th>
                        <th>操作</th>
                    </tr>
                </thead>
                <tbody>
                    {% for user in users %}
                    <tr>
                        <td>{{ user.email }}</td>
                        <td>{{ user.full_name }}</td>
                        <td><span class="badge badge-deleted">{{ user.category }}</span></td>
                        <td>{{ user.affiliation or '－' }}</td>
                        <td>{{ user.deleted_at }}</td>
                        <td>{{ user.deleted_by_name or '－' }}</td>
                        <td>
                            <div class="action-buttons">
                                <form action="{{ url_for('admin.restore_user', user_id=user.id) }}" 
                                      method="POST" style="display: inline;">
                                    <button type="submit" class="btn btn-restore" 
                                            onclick="return confirm('{{ user.full_name }}さんを復元しますか？')">
                                        復元
                                    </button>
                                </form>

                                <form action="{{ url_for('admin.permanent_delete_user', user_id=user.id) }}" 
                                      method="POST" style="display: inline;">
                                    <button type="submit" class="btn btn-danger" 
                                            onclick="return confirm('⚠️ 警告 ⚠️\n\n{{ user.full_name }} ({{ user.email }}) をデータベースから完全に削除します。\n\nこの操作は取り消せません！\n本当に削除しますか？')">
                                        完全削除
                                    </button>
                                </form>
                            </div>
                        </td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
            {% else %}
            <div class="no-data">
                <p>削除済みのユーザーはいません</p>
            </div>
            {% endif %}
        </div>
    </div>
</body>
</html>

