<body>
    <div class="container">
        <div class="header">
            <div>
                <h1>ユーザー管理</h1>
                <p style="color: #666;">アクティブなユーザーの管理</p>
            </div>
            <div class="header-actions">
                <a href="{{ url_for('admin.add_user') }}" class="btn btn-primary">+ ユーザー追加</a>
                <a href="{{ url_for('admin.deleted_users') }}" class="btn btn-secondary">削除済みユーザー</a>
                <a href="{{ url_for('admin.dashboard') }}" class="btn btn-secondary">ダッシュボード</a>
            </div>
        </div>

        <div class="content">
            <!-- 統計 -->
            <div class="stats">
                <div class="stat-card">
                    <h3>総ユーザー数</h3>
                    <div class="number">{{ users|length }}</div>
                </div>
            </div>

            <!-- 検索フォーム -->
            <div class="search-form">
                <form method="GET" action="{{ url_for('admin.users') }}">
                    <div class="search-grid">
                        <div class="form-group">
                            <label for="email">メールアドレス</label>
                            <input type="text" id="email" name="email"
                                   value="{{ request.args.get('email', '') }}"
                                   placeholder="部分一致検索">
                        </div>
                        <div class="form-group">
                            <label for="name">氏名</label>
                            <input type="text" id="name" name="name"
                                   value="{{ request.args.get('name', '') }}"
                                   placeholder="部分一致検索">
                        </div>
                        <div class="form-group">
                            <label for="category">カテゴリ</label>
                            <select id="category" name="category">
                                <option value="">すべて</option>
                                <option value="admin" {% if request.args.get('category') == 'admin' %}selected{% endif %}>admin</option>
                                <option value="学生" {% if request.args.get('category') == '学生' %}selected{% endif %}>学生</option>
                                <option value="教員" {% if request.args.get('category') == '教員' %}selected{% endif %}>教員</option>
                                <option value="常勤役員" {% if request.args.get('category') == '常勤役員' %}selected{% endif %}>常勤役員</option>
                                <option value="事務職員" {% if request.args.get('category') == '事務職員' %}selected{% endif %}>事務職員</option>
                                <option value="学外関係者" {% if request.args.get('category') == '学外関係者' %}selected{% endif %}>学外関係者</option>
                            </select>
                        </div>
                    </div>
                    <div class="search-actions">
                        <button type="submit" class="btn btn-primary btn-sm">検索</button>
                        <a href="{{ url_for('admin.users') }}" class="btn btn-secondary btn-sm">リセット</a>
                    </div>
                </form>
            </div>

            <!-- ユーザー一覧 -->
            {% if users %}
            <table>
                <thead>
                    <tr>
                        <th>メールアドレス</th>
                        <th>氏名</th>
                        <th>カテゴリ</th>
                        <th>所属</th>
                        <th>フィーチャー</th>
                        <th>状態</th>
                        <th>作成日時</th>
                        <th>操作</th>
                    </tr>
                </thead>
                <tbody>
                    {% for user in users %}
                    <tr>
                        <td>{{ user.email }}</td>
                        <td>{{ user.full_name }}</td>
                        <td>
                            {% if user.category == 'admin' %}
                                <span class="badge badge-admin">{{ user.category }}</span>
                            {% elif user.category == '学生' %}
                                <span class="badge badge-student">{{ user.category }}</span>
                            {% elif user.category == '教員' or user.category == '常勤役員' %}
                                <span class="badge badge-faculty">{{ user.category }}</span>
                            {% elif user.category == '事務職員' %}
                                <span class="badge badge-staff">{{ user.category }}</span>
                            {% else %}
                                <span class="badge badge-external">{{ user.category }}</span>
                            {% endif %}
                        </td>
                        <td>{{ user.affiliation or '－' }}</td>
                        <td style="font-size: 0.85rem; color: #666;">{{ user.features or '－' }}</td>
                        <td>
                            {% if user.password_hash == 'PENDING_INVITATION' %}
                                <span class="badge" style="background: #fbbf24; color: #78350f;">招待待ち</span>
                            {% elif user.is_active %}
                                <span class="badge badge-active">有効</span>
                            {% else %}
                                <span class="badge badge-inactive">無効</span>
                            {% endif %}
                        </td>
                        <td style="font-size: 0.85rem;">{{ user.created_at[:10] if user.created_at else '—' }}</td>
                        <td>
                            <div class="action-buttons">
                                <a href="{{ url_for('admin.edit_user', user_id=user.id) }}"
                                   class="btn btn-primary btn-sm">編集</a>

                                <a href="{{ url_for('admin.manage_user_features', user_id=user.id) }}"
                                   class="btn btn-secondary btn-sm">権限</a>

                                <!-- ★★★ ここに追加 ★★★ -->
                                {% if user.password_hash == 'PENDING_INVITATION' %}
                                <form action="{{ url_for('admin.send_invitation', user_id=user.id) }}"
                                      method="POST" style="display: inline;">
                                    <button type="submit" class="btn btn-primary btn-sm"
                                            style="background: #f59e0b;"
                                            onclick="return confirm('{{ user.email }} に招待メールを送信しますか？')">
                                        📧 招待
                                    </button>
                                </form>
                                {% endif %}
