                                        削除
                                    </button>
                                </form>
                                {% endif %}
                            </div>
                        </td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
            {% else %}
            <div class="no-data">
                <p>ユーザーが見つかりません</p>
                {% if request.args.get('email') or request.args.get('name') or request.args.get('category') %}
                <p style="margin-top: 10px;">
                    <a href="{{ url_for('admin.users') }}" class="btn btn-secondary btn-sm">すべてのユーザーを表示</a>
                </p>
                {% endif %}
            </div>
            {% endif %}
        </div>
    </div>
</body>
