      .warning-list {
        margin: 0;
        padding-left: 20px;
      }
      .warning-list li {
        margin-bottom: 0.25rem;
      }
        .btn-action {
            padding: 10px 20px;
            color: white;
            border: none;
            border-radius: 5px;
            font-weight: bold;
            cursor: pointer;
        }
        .btn-action:disabled {
            background-color: #ccc !important;
            cursor: not-allowed;
