        // ===========================================
        // SQLクエリ実行
        // ===========================================
        $(document).on('click', '#btn-sql-query', function() {
            if (!currentTable) return;

            $('#sql-query-context').val(`${currentTable.database}.${currentTable.tableName}`);

            // 全カラムを列挙したクエリを生成
            const { columns, primary_keys } = currentData;
            const columnList = columns.map(col => `\n    \`${col}\``).join(',');

            // ORDER BY句（主キーがあればそれを使用、なければ最初のカラム）
            const orderByCol = primary_keys.length > 0 ? primary_keys[0] : columns[0];

            const defaultQuery = `SELECT${columnList}
FROM \`${currentTable.tableName}\`
ORDER BY \`${orderByCol}\`
LIMIT 100;`;

            $('#sql-query-text').val(defaultQuery);
            $('#sql-query-modal').show();
            makeModalDraggable();
        });

        $('#sql-query-execute').click(function() {
            const query = $('#sql-query-text').val().trim();

            if (!query) {
                showResult('クエリを入力してください', true);
                return;
            }

            // 許可する文のみ実行（複数クエリ対応）
            const queries = query.split(';').map(q => q.trim()).filter(q => q);
            const queryLower = queries.map(q => q.toLowerCase());
            const allowedCommands = ['select', 'show', 'describe', 'desc', 'explain', 'use'];

            for (let i = 0; i < queryLower.length; i++) {
                const isAllowed = allowedCommands.some(cmd => queryLower[i].startsWith(cmd));
                if (!isAllowed) {
                    showResult('SELECT、SHOW、DESCRIBE、EXPLAIN、USE文のみ実行可能です', true);
                    return;
                }
            }

            // 実行
            $.ajax({
                url: '{{ url_for("table_master.execute_query") }}',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({
                    database: currentTable.database,
                    query: query
                }),
                success: function(resp) {
                    if (resp.success) {
                        $('#sql-query-modal').hide();
                        displayQueryResult(resp, query);
                    } else {
                        showResult('クエリエラー: ' + resp.error, true);
                    }
                },
                error: function(xhr) {
                    const errorMsg = xhr.responseJSON?.error || xhr.responseText;
                    showResult('クエリエラー: ' + errorMsg, true);
                }
            });
        });

        $('#sql-query-cancel').click(function() {
            $('#sql-query-modal').hide();
            // 位置をリセット
            $('#sql-query-modal .modal-content').css({position: '', left: '', top: '', margin: ''});
        });

        // 結果表示
        function displayQueryResult(data, originalQuery) {
            const { columns, rows, execution_time } = data;

            // 行数情報
            $('#result-row-count').text(`${rows.length} 行 (実行時間: ${execution_time}秒)`);

            // テーブル表示
            let tableHtml = '<thead><tr>';
            columns.forEach(col => {
                tableHtml += `<th>${escapeHtml(col)}</th>`;
            });
            tableHtml += '</tr></thead><tbody>';

            rows.forEach(row => {
                tableHtml += '<tr>';
                columns.forEach(col => {
                    const val = row[col];
                    if (val === null || val === undefined) {
                        tableHtml += '<td style="color:#e74c3c;font-style:italic;">NULL</td>';
                    } else {
                        tableHtml += `<td>${escapeHtml(String(val))}</td>`;
                    }
                });
                tableHtml += '</tr>';
            });
            tableHtml += '</tbody>';
            $('#result-table').html(tableHtml);

            // Markdown表示
            const markdown = generateMarkdownTable(columns, rows);
            $('#result-markdown').text(markdown);

            // HTML編集テーブルを生成
            generateEditableTable(columns, rows);

            // モーダル表示
            $('#sql-result-modal').show();
            makeModalDraggable();

            // HTMLコードを初回生成（即座に実行）
            setTimeout(function() {
                console.log('Generating initial HTML code...');
                updateHtmlCode();
            }, 100);

            // 再クエリ用に保存
            $('#sql-result-modal').data('last-query', originalQuery);
        }

        // 編集可能なテーブルを生成
        function generateEditableTable(columns, rows) {
            let html = '<thead><tr>';
            columns.forEach((col, idx) => {
                html += `<th data-col-idx="${idx}">
                    <div class="col-resize-handle left" data-col-idx="${idx}"></div>
                    ${escapeHtml(col)}
                    <div class="col-resize-handle right" data-col-idx="${idx}"></div>
                </th>`;
            });
            html += '</tr></thead><tbody>';

            rows.forEach((row, rowIdx) => {
                html += `<tr data-row-idx="${rowIdx}">`;
                columns.forEach((col, colIdx) => {
                    const val = row[col];
                    const displayVal = (val === null || val === undefined) ? '' : escapeHtml(String(val));
                    html += `<td contenteditable="true" data-row-idx="${rowIdx}" data-col-idx="${colIdx}">${displayVal}</td>`;
                });
                html += '</tr>';
            });
            html += '</tbody>';

            $('#editable-table').html(html);

            // セル選択機能を追加
            setupCellSelection();

            // 列幅変更ハンドルを設定
            setupColumnResize();

            // テーブル全体のリサイズを設定
            setupTableResize();

            // HTMLコード更新（内部でエラーハンドリング済み）
            updateHtmlCode();
        }

        // テーブル全体のリサイズ機能
        function setupTableResize() {
            let isResizing = false;
            let startX = 0;
            let startY = 0;
            let startWidth = 0;
            let startHeight = 0;

            $('#table-resize-handle').off('mousedown').on('mousedown', function(e) {
                e.preventDefault();
                e.stopPropagation();

                isResizing = true;
                const $table = $('#editable-table');

                startX = e.pageX;
                startY = e.pageY;
                startWidth = $table.outerWidth();
                startHeight = $table.outerHeight();

                $(document).on('mousemove.tableresize', function(e) {
                    if (!isResizing) return;

                    const diffX = e.pageX - startX;
                    const diffY = e.pageY - startY;

                    let newWidth = startWidth + diffX;
                    let newHeight = startHeight + diffY;

                    // 最小サイズ
                    if (newWidth < 200) newWidth = 200;
                    if (newHeight < 100) newHeight = 100;

                    $table.css({
                        'width': newWidth + 'px',
                        'height': newHeight + 'px'
                    });
                });

                $(document).on('mouseup.tableresize', function() {
                    if (isResizing) {
                        isResizing = false;
                        $(document).off('mousemove.tableresize mouseup.tableresize');
                        updateHtmlCode();
                    }
                });
            });
        }

        // セル選択機能
        let selectedCells = [];

        // 列幅変更機能
        function setupColumnResize() {
            let isResizing = false;
            let startX = 0;
            let startWidth = 0;
            let $currentCol = null;
            let colIdx = -1;

            $('.col-resize-handle').off('mousedown').on('mousedown', function(e) {
                e.preventDefault();
                e.stopPropagation();

                isResizing = true;
                const $handle = $(this);
                colIdx = parseInt($handle.data('col-idx'));
                $currentCol = $(`#editable-table th[data-col-idx="${colIdx}"]`);

                startX = e.pageX;
                startWidth = $currentCol.outerWidth();

                $(document).on('mousemove.colresize', function(e) {
                    if (!isResizing) return;

                    const diff = e.pageX - startX;
                    let newWidth = startWidth + diff;

                    // 最小幅を設定
                    if (newWidth < 50) newWidth = 50;

                    // 列全体に幅を適用
                    $(`#editable-table th[data-col-idx="${colIdx}"]`).css('width', newWidth + 'px');
                    $(`#editable-table td[data-col-idx="${colIdx}"]`).css('width', newWidth + 'px');
                });

                $(document).on('mouseup.colresize', function() {
                    if (isResizing) {
                        isResizing = false;
                        $(document).off('mousemove.colresize mouseup.colresize');
                        updateHtmlCode();
                    }
                });
            });
        }

        function setupCellSelection() {
            $('#editable-table td').off('click').on('click', function(e) {
                const $cell = $(this);

                if (e.ctrlKey || e.metaKey) {
                    // Ctrl/Cmd + クリック: 複数選択
                    $cell.toggleClass('selected');
                } else if (e.shiftKey && selectedCells.length > 0) {
                    // Shift + クリック: 範囲選択
                    const lastCell = selectedCells[selectedCells.length - 1];
                    selectRange(lastCell, $cell);
                } else {
                    // 通常クリック: 単一選択
                    $('#editable-table td').removeClass('selected');
                    $cell.addClass('selected');
                }

                updateSelectedCells();
            });

            // ダブルクリックで編集モード（contenteditableを有効化）
            $('#editable-table td').off('dblclick').on('dblclick', function(e) {
                e.stopPropagation();
                const $cell = $(this);
                $cell.attr('contenteditable', 'true').focus();
            });

            // セル編集時の処理を改善
            $('#editable-table td').off('blur').on('blur', function() {
                // 編集完了時にHTMLコード更新
                setTimeout(function() {
                    updateHtmlCode();
                }, 50);
            });

            // 入力時にHTMLコード更新
            $('#editable-table td').off('input').on('input', function() {
                // 少し遅延させて更新
                clearTimeout(window.htmlUpdateTimer);
                window.htmlUpdateTimer = setTimeout(function() {
                    updateHtmlCode();
                }, 300);
            });
        }

        function updateSelectedCells() {
            selectedCells = $('#editable-table td.selected').toArray();
        }

        function selectRange(cell1, cell2) {
            const $cell1 = $(cell1);
            const $cell2 = $(cell2);

            const row1 = parseInt($cell1.data('row-idx'));
            const row2 = parseInt($cell2.data('row-idx'));
            const col1 = parseInt($cell1.data('col-idx'));
            const col2 = parseInt($cell2.data('col-idx'));

            const minRow = Math.min(row1, row2);
            const maxRow = Math.max(row1, row2);
            const minCol = Math.min(col1, col2);
            const maxCol = Math.max(col1, col2);

            $('#editable-table td').removeClass('selected');

            for (let r = minRow; r <= maxRow; r++) {
                for (let c = minCol; c <= maxCol; c++) {
                    $(`#editable-table td[data-row-idx="${r}"][data-col-idx="${c}"]`).addClass('selected');
                }
            }
        }

        // ===========================================
        // 文字装飾機能
        // ===========================================

        // 選択テキストにタグを適用する共通関数
        function applyTagToSelection(tagName, attributes = {}) {
            const selection = window.getSelection();

            if (!selection || selection.rangeCount === 0 || selection.isCollapsed) {
                showResult('テキストを選択してください', true);
                return false;
            }

            try {
                const range = selection.getRangeAt(0);
                const selectedText = range.toString();

                // タグを作成
                const tag = document.createElement(tagName);

                // 属性を設定
                for (let attr in attributes) {
                    tag.setAttribute(attr, attributes[attr]);
                }

                tag.textContent = selectedText;

                // 選択範囲を削除して新しいタグを挿入
                range.deleteContents();
                range.insertNode(tag);

                // 選択を解除
                selection.removeAllRanges();

                updateHtmlCode();
                return true;

            } catch (error) {
                console.error('applyTagToSelection error:', error);
                showResult('テキスト装飾の適用に失敗しました', true);
                return false;
            }
        }

