                const rt = document.createElement('rt');
                rt.textContent = rubyText;
                ruby.appendChild(rt);

                // 選択範囲を削除して新しいタグを挿入
                range.deleteContents();
                range.insertNode(ruby);

                // 選択を解除
                selection.removeAllRanges();

                // 入力欄をクリア
                $('#input-ruby-text').val('');

                updateHtmlCode();
                showResult('ふりがなを適用しました', false);

