        // セル結合
        $('#btn-merge-cells').click(function() {
            if (selectedCells.length < 2) {
                showResult('2つ以上のセルを選択してください', true);
                return;
            }

            // 選択範囲を計算
            const rows = selectedCells.map(c => parseInt($(c).data('row-idx')));
            const cols = selectedCells.map(c => parseInt($(c).data('col-idx')));

            const minRow = Math.min(...rows);
            const maxRow = Math.max(...rows);
            const minCol = Math.min(...cols);
            const maxCol = Math.max(...cols);

            const rowspan = maxRow - minRow + 1;
            const colspan = maxCol - minCol + 1;

            // 最初のセルにrowspan/colspanを設定
            const $firstCell = $(`#editable-table td[data-row-idx="${minRow}"][data-col-idx="${minCol}"]`);

            if (rowspan > 1) $firstCell.attr('rowspan', rowspan);
            if (colspan > 1) $firstCell.attr('colspan', colspan);

            // 他のセルを非表示
            selectedCells.forEach(cell => {
                const $cell = $(cell);
                const r = parseInt($cell.data('row-idx'));
                const c = parseInt($cell.data('col-idx'));

                if (r !== minRow || c !== minCol) {
                    $cell.hide().attr('data-merged', 'true');
                }
            });

            $('#editable-table td').removeClass('selected');
            updateHtmlCode();
        });

        // セル結合解除
        $('#btn-unmerge-cells').click(function() {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            selectedCells.forEach(cell => {
                const $cell = $(cell);
                $cell.removeAttr('rowspan').removeAttr('colspan');
            });

            // 非表示セルを再表示
            $('#editable-table td[data-merged="true"]').show().removeAttr('data-merged');

            updateHtmlCode();
        });

