            applyVerticalAlignment('bottom');
        });

        function applyAlignment(align) {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            selectedCells.forEach(cell => {
                $(cell).css('text-align', align);
            });

            updateHtmlCode();
        }

        function applyVerticalAlignment(valign) {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            selectedCells.forEach(cell => {
                $(cell).css('vertical-align', valign);
            });

            updateHtmlCode();
        }

        // Markdown変換機能
        $('#btn-md-itemize').click(function() {
            applyMarkdownFormat('itemize');
        });

        $('#btn-md-enumerate').click(function() {
            applyMarkdownFormat('enumerate');
        });
        $('#btn-md-clear').click(function() {
            applyMarkdownFormat('clear');
        });

        // ぶら下げインデント
        $('#btn-apply-hanging').click(function() {
            const indent = $('#input-hanging-indent').val();
            const unit = $('#select-hanging-unit').val();

            if (!indent || parseFloat(indent) <= 0) {
                showResult('インデント幅を入力してください', true);
                return;
            }

            const indentValue = indent + unit;

            // テキスト選択を確認
            const selection = window.getSelection();

            if (selection && selection.rangeCount > 0 && !selection.isCollapsed) {
                // テキストが選択されている場合：選択範囲のみに適用
                try {
                    const range = selection.getRangeAt(0);

                    // 選択されたテキストを取得
                    const selectedText = range.toString();

                    // 改行で分割して各段落に字下げを適用
                    const paragraphs = selectedText.split('\n').filter(p => p.trim());
                    const html = paragraphs.map(para =>
                        `<div style="text-indent: -${indentValue}; padding-left: ${indentValue}; margin-bottom: 0;">${escapeHtml(para.trim())}</div>`
                    ).join('');

                    // 選択範囲を削除して新しいHTMLを挿入
                    range.deleteContents();
                    const fragment = range.createContextualFragment(html);
                    range.insertNode(fragment);

                    // 選択を解除
                    selection.removeAllRanges();

                    updateHtmlCode();
                    showResult('選択したテキストに字下げを適用しました', false);

                } catch (error) {
                    console.error('Text selection hanging indent error:', error);
                    showResult('テキスト選択での適用に失敗しました', true);
                }

            } else if (selectedCells.length > 0) {
                // セルが選択されている場合：セル全体に適用（従来の動作）
                selectedCells.forEach(cell => {
                    const $cell = $(cell);
                    const text = $cell.text().trim();

                    // 改行で分割して段落ごとに処理
                    const paragraphs = text.split('\n').filter(p => p.trim());

                    if (paragraphs.length === 0) {
                        return;
                    }

                    // 各段落をdivで囲み、ぶら下げインデントを適用
                    const html = paragraphs.map(para => {
                        return `<div style="text-indent: -${indentValue}; padding-left: ${indentValue}; margin-bottom: 0;">${escapeHtml(para)}</div>`;
                    }).join('');

                    $cell.html(html);
                });

                updateHtmlCode();
                showResult('セル全体に字下げを適用しました', false);

            } else {
                showResult('セルを選択するか、セル内のテキストを選択してください', true);
                return;
            }
        });

        function applyMarkdownFormat(format) {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            selectedCells.forEach(cell => {
                const $cell = $(cell);
                const text = $cell.text().trim();

                if (format === 'clear') {
                    // HTML要素を削除してテキストのみに
                    $cell.html(escapeHtml(text));
                } else if (format === 'itemize') {
                    // 箇条書きに変換
                    const lines = text.split('\n').map(line => line.trim()).filter(line => line);
                    const items = lines.map(line => {
                        // "- " や "* " で始まる場合は除去
                        return line.replace(/^[-*]\s+/, '');
                    });
                    const html = '<ul>' + items.map(item => `<li>${escapeHtml(item)}</li>`).join('') + '</ul>';
                    $cell.html(html);
                } else if (format === 'enumerate') {
                    // 番号付きリストに変換
                    const lines = text.split('\n').map(line => line.trim()).filter(line => line);
                    const items = lines.map(line => {
                        // "1. " などで始まる場合は除去
                        return line.replace(/^\d+\.\s+/, '');
                    });
                    const html = '<ol>' + items.map(item => `<li>${escapeHtml(item)}</li>`).join('') + '</ol>';
                    $cell.html(html);
                } else if (format === 'quote') {
                    // 引用に変換
                    const lines = text.split('\n').map(line => line.trim()).filter(line => line);
                    const content = lines.map(line => {
                        // "> " で始まる場合は除去
                        return line.replace(/^>\s+/, '');
                    }).join('<br>');
                    const html = `<blockquote>${content}</blockquote>`;
                    $cell.html(html);
                }
            });

            updateHtmlCode();
        }

        // 背景色設定
        $('#btn-apply-bg-color').click(function() {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            const color = $('#input-bg-color').val();

            selectedCells.forEach(cell => {
                $(cell).css('background-color', color);
            });

            updateHtmlCode();
        });

        // 背景色クリア
        $('#btn-clear-bg-color').click(function() {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            selectedCells.forEach(cell => {
                $(cell).css('background-color', '');
            });

            updateHtmlCode();
        });

        // 枠線設定
        $('#btn-apply-border').click(function() {
            if (selectedCells.length === 0) {
                showResult('セルを選択してください', true);
                return;
            }

            const borderStyle = $('#select-border-style').val();

            selectedCells.forEach(cell => {
                $(cell).css('border', borderStyle);
            });

            updateHtmlCode();
        });

        // カラム幅設定
        $('#btn-apply-col-width').click(function() {
            const width = $('#input-col-width').val();

            if (!width || selectedCells.length === 0) {
                showResult('セルを選択して幅を入力してください', true);
                return;
            }

            // 選択されたセルの列を取得
            const cols = [...new Set(selectedCells.map(c => parseInt($(c).data('col-idx'))))];

            cols.forEach(colIdx => {
                $(`#editable-table td[data-col-idx="${colIdx}"]`).css('width', width + 'px');
                $(`#editable-table th[data-col-idx="${colIdx}"]`).css('width', width + 'px');
            });

            updateHtmlCode();
        });

        // 行高さ設定
        $('#btn-apply-row-height').click(function() {
            const height = $('#input-row-height').val();

            if (!height || selectedCells.length === 0) {
                showResult('セルを選択して高さを入力してください', true);
                return;
            }

            // 選択されたセルの行を取得
            const rows = [...new Set(selectedCells.map(c => parseInt($(c).data('row-idx'))))];

            rows.forEach(rowIdx => {
                $(`#editable-table tr[data-row-idx="${rowIdx}"] td`).css('height', height + 'px');
            });

            updateHtmlCode();
        });

        // スタイルリセット
        $('#btn-reset-styles').click(function() {
            if (!confirm('すべてのスタイルと書式をリセットしますか？\n（テキスト内容は保持されます）')) return;

            $('#editable-table td, #editable-table th').each(function() {
                const $cell = $(this);
                // テキストのみを抽出
                const text = $cell.text();
                // スタイルと属性をクリア
                $cell.removeAttr('style rowspan colspan data-merged').show();
                // テキストのみに戻す
                $cell.text(text);
            });

            // テーブルの幅もリセット
            $('#editable-table').removeAttr('style');

            updateHtmlCode();
        });

        // HTMLコード生成と表示（シンプル版）
        function updateHtmlCode() {
            console.log('=== updateHtmlCode called ===');

            const $htmlCode = $('#html-code');
            if ($htmlCode.length === 0) {
                console.error('HTML code container not found!');
                return;
            }

            const $table = $('#editable-table');
            if ($table.length === 0) {
                console.warn('Table not found');
                $htmlCode.text('<!-- テーブルがまだ生成されていません -->');
                return;
            }

            try {
                // テーブル要素を直接コピー
                const tableElement = $table[0];

                // outerHTMLを取得
                let html = tableElement.outerHTML;

                if (!html) {
                    $htmlCode.text('<!-- HTML取得エラー -->');
                    return;
                }

                // 不要な属性を正規表現で削除
                html = html.replace(/\s*contenteditable="[^"]*"/g, '');
                html = html.replace(/\s*data-[a-z-]+="[^"]*"/g, '');
                html = html.replace(/\s*class="selected[^"]*"/g, '');

                // リサイズハンドルのdivを削除
                html = html.replace(/<div class="col-resize-handle[^>]*>.*?<\/div>/g, '');

                // 改行を追加して見やすく
                html = html.replace(/></g, '>\n<');

                // インデント追加（シンプル版）
                const lines = html.split('\n');
                let formatted = '';
                let indent = 0;

                for (let line of lines) {
                    line = line.trim();
                    if (!line) continue;

                    if (line.startsWith('</')) {
                        indent = Math.max(0, indent - 1);
                    }

                    formatted += '  '.repeat(indent) + line + '\n';

                    if (line.startsWith('<') && !line.startsWith('</') && !line.endsWith('/>') && !line.includes('</')) {
                        indent++;
                    }
                }

                // 表示
                $htmlCode.text(formatted.trim());
                console.log('HTML code updated successfully, length:', formatted.length);

            } catch (error) {
                console.error('Error in updateHtmlCode:', error);
                $htmlCode.text('<!-- エラー: ' + error.message + ' -->');
            }
        }

        // HTML整形（エラーセーフ）
        function formatHtml(html) {
            try {
                if (!html) return '';

                let formatted = '';
                let indent = 0;
                const lines = html.split('\n');

                lines.forEach(line => {
                    line = line.trim();
                    if (!line) return;

                    // 閉じタグの場合、インデントを減らす
                    if (line.startsWith('</')) {
                        indent = Math.max(0, indent - 1);
                    }

                    // インデントを追加
                    formatted += '  '.repeat(indent) + line + '\n';

                    // 開きタグの場合
                    if (line.startsWith('<') && !line.startsWith('</') && !line.endsWith('/>') && !line.includes('</')) {
                        // 自己閉じタグや同じ行に閉じタグがない場合、インデントを増やす
                        indent++;
                    }
                });

                return formatted.trim();
            } catch (e) {
                console.error('formatHtml error:', e);
                return html; // エラー時は元のHTMLをそのまま返す
            }
        }

        // HTMLコードをクリップボードにコピー
        $('#copy-html-btn-top').click(function() {
            copyHtmlToClipboard($(this));
        });

        // HTMLコピー処理
        function copyHtmlToClipboard($btn) {
            const html = $('#html-code').text();

            console.log('Copying HTML, length:', html ? html.length : 0);

            if (!html || html.trim() === '' || html.startsWith('エラー') || html.startsWith('<!--')) {
                showResult('コピーするHTMLがありません', true);
                return;
            }

            // まずクリップボードAPIを試す
            if (navigator.clipboard && navigator.clipboard.writeText) {
                navigator.clipboard.writeText(html).then(() => {
                    $btn.addClass('copied').text('✓ コピー完了');
                    setTimeout(() => {
                        $btn.removeClass('copied').text('📋 HTMLコードをクリップボードにコピー');
                    }, 2000);
                }).catch(err => {
                    console.error('Clipboard API failed:', err);
                    // フォールバック
                    fallbackCopyHtml(html, $btn);
                });
            } else {
                // フォールバック
                fallbackCopyHtml(html, $btn);
            }
        }

        // フォールバックコピー関数
        function fallbackCopyHtml(text, $btn) {
            const $temp = $('<textarea>');
            $temp.css({
                position: 'fixed',
                top: 0,
                left: 0,
                width: '2em',
                height: '2em',
                padding: 0,
                border: 'none',
                outline: 'none',
                boxShadow: 'none',
                background: 'transparent'
            });
            $('body').append($temp);
            $temp.val(text).select();

            try {
                const successful = document.execCommand('copy');
                if (successful) {
                    $btn.addClass('copied').text('✓ コピー完了');
                    setTimeout(() => {
                        $btn.removeClass('copied').text('📋 HTMLコードをクリップボードにコピー');
                    }, 2000);
                } else {
                    showResult('コピーに失敗しました', true);
                }
            } catch (err) {
                console.error('Fallback copy failed:', err);
                showResult('コピーに失敗しました', true);
            }

            $temp.remove();
        }

        // Markdownテーブル生成
        function generateMarkdownTable(columns, rows) {
            if (columns.length === 0) {
                return 'データがありません';
            }

            // ヘッダー行
            let md = '| ' + columns.join(' | ') + ' |\n';

            // セパレータ行
            md += '|' + columns.map(() => ' --- ').join('|') + '|\n';

            // データ行
            rows.forEach(row => {
                const values = columns.map(col => {
                    const val = row[col];
                    if (val === null || val === undefined) {
                        return 'NULL';
                    }
                    // Markdown特殊文字のエスケープ
                    return String(val).replace(/\|/g, '\\|').replace(/\n/g, ' ');
                });
                md += '| ' + values.join(' | ') + ' |\n';
            });

            return md;
        }

        // タブ切り替え
        $(document).on('click', '.result-tab', function() {
            const tab = $(this).data('tab');

            $('.result-tab').removeClass('active');
            $(this).addClass('active');

            $('.result-content').removeClass('active');
            $(`#result-${tab}-view`).addClass('active');

            // コピーボタンの表示切り替え
            if (tab === 'markdown') {
                $('#copy-markdown-btn').show();
            } else {
                $('#copy-markdown-btn').hide();
            }

            // HTML編集タブに切り替えたときにHTMLコードを更新
            if (tab === 'html') {
                // 即座に更新
                console.log('Tab switched to HTML, updating code...');
                updateHtmlCode();
            }
        });

        // Markdownコピー
        $('#copy-markdown-btn').click(function() {
            const markdown = $('#result-markdown').text();

            navigator.clipboard.writeText(markdown).then(() => {
                const $btn = $(this);
                $btn.addClass('copied').text('✓ コピー完了');
                setTimeout(() => {
                    $btn.removeClass('copied').text('📋 Markdownをコピー');
                }, 2000);
            }).catch(err => {
                showResult('コピーに失敗しました', true);
            });
        });

        // 再クエリ実行
        $('#sql-result-requery').click(function() {
            const lastQuery = $('#sql-result-modal').data('last-query');
            if (lastQuery) {
                $('#sql-result-modal').hide();
                $('#sql-query-text').val(lastQuery);
                $('#sql-query-modal').show();
            }
        });

        $('#sql-result-close').click(function() {
            $('#sql-result-modal').hide();
            $('#sql-result-modal .modal-content').css({position: '', left: '', top: '', margin: ''});

            // 選択状態をリセット
            selectedCells = [];
            $('#editable-table td').removeClass('selected');

            // タブを最初に戻す
            $('.result-tab').removeClass('active');
            $('.result-tab[data-tab="table"]').addClass('active');
            $('.result-content').removeClass('active');
            $('#result-table-view').addClass('active');
            $('#copy-markdown-btn').hide();
        });

        // ===========================================
        // 再読込
        // ===========================================
        $(document).on('click', '#btn-refresh', function() {
            if (currentTable) {
                loadTableData(currentTable.database, currentTable.tableName, currentTable.key);
            }
        });

        // ===========================================
        // モーダルのドラッグ機能
        // ===========================================
        function makeModalDraggable() {
            $('.modal-header').off('mousedown').on('mousedown', function(e) {
                const $modal = $(this).closest('.modal-content');
                const $modalParent = $modal.parent();

                // モーダルを絶対配置に変更（初回のみ）
                if ($modal.css('position') !== 'absolute') {
                    const rect = $modal[0].getBoundingClientRect();
                    $modal.css({
                        position: 'absolute',
                        left: rect.left + 'px',
                        top: rect.top + 'px',
                        margin: 0
                    });
                }

                const startX = e.pageX - parseInt($modal.css('left'));
                const startY = e.pageY - parseInt($modal.css('top'));

                function handleMouseMove(e) {
                    $modal.css({
                        left: (e.pageX - startX) + 'px',
                        top: (e.pageY - startY) + 'px'
                    });
                }

                function handleMouseUp() {
                    $(document).off('mousemove', handleMouseMove);
                    $(document).off('mouseup', handleMouseUp);
                }

                $(document).on('mousemove', handleMouseMove);
                $(document).on('mouseup', handleMouseUp);

                e.preventDefault();
            });
        }

        // ===========================================
        // 初期化
        // ===========================================
        loadTableList();

        // ★ Enterキーはここ（ready内の末尾）に1回だけ
        $('#archive-title-input').on('keydown', function(e) {
            if (e.key === 'Enter') doArchiveSave();
        });
    });

    // ===== アーカイブ保存 =====

    function openArchiveSaveDialog() {
        const html = $('#html-code').text().trim();
        if (!html || html === '<!-- HTMLコードがここに表示されます -->') {
            alert('HTMLコードがありません。先にクエリを実行してHTML編集タブを開いてください。');
            return;
        }
        $('#archive-title-input').val('');
        $('#archive-desc-input').val('');
        $('#archive-public-select').val('1');
        $('#archive-save-result').hide();
        $('#archive-save-error').hide();
        $('#btn-do-archive-save').prop('disabled', false).text('💾 保存');
        $('#archive-save-overlay, #archive-save-dialog').show();
        setTimeout(() => $('#archive-title-input').focus(), 100);
    }

    function closeArchiveSaveDialog() {
        $('#archive-save-overlay, #archive-save-dialog').hide();
    }

    function doArchiveSave() {
        const title = $('#archive-title-input').val().trim();
        if (!title) {
            $('#archive-title-input').css('border-color', '#e74c3c').focus();
            setTimeout(() => $('#archive-title-input').css('border-color', '#ccc'), 2000);
            return;
        }
        const html      = $('#html-code').text().trim();
        const desc      = $('#archive-desc-input').val().trim();
        const isPublic  = $('#archive-public-select').val() === '1';
        const sourceDb = (typeof currentTable !== 'undefined' && currentTable)
                         ? currentTable.database : '';
        const sourceQ  = $('#sql-result-modal').data('last-query') || '';

        $('#btn-do-archive-save').prop('disabled', true).text('保存中...');
        $('#archive-save-error').hide();

        $.ajax({
            url: '/table_master/archive/save',
            type: 'POST',
            contentType: 'application/json',
            data: JSON.stringify({
                id:              null,
                title:           title,
                description:     desc,
                source_view_id:  null,
                source_database: sourceDb,
                source_query:    sourceQ,
                html_content:    html,
                is_public:       isPublic
            }),
            success: function(res) {
                if (res.success) {
                    const url = window.location.origin + '/table_master/archive/' + res.archive_number;
                    $('#archive-saved-url').attr('href', url).text(url);
                    $('#archive-save-result').show();
                    $('#btn-do-archive-save').prop('disabled', true).text('✓ 保存済み');
                } else {
                    $('#archive-save-error').text('エラー: ' + res.error).show();
                    $('#btn-do-archive-save').prop('disabled', false).text('💾 保存');
                }
            },
            error: function(xhr) {
                const msg = xhr.responseJSON?.error || '通信エラーが発生しました';
                $('#archive-save-error').text(msg).show();
                $('#btn-do-archive-save').prop('disabled', false).text('💾 保存');
            }
        });

    }

    </script>
