            box-shadow:0 10px 40px rgba(0,0,0,.35);z-index:201;flex-direction:column}
#view-modal.show{display:flex}

/* ヘッダー */
#vm-header{background:#6c3483;color:#fff;padding:10px 16px;border-radius:6px 6px 0 0;
