.btn-hdr:hover{opacity:.85}
.btn-hdr-prev  {background:#e8f4f8;color:#1a5276}
.btn-hdr-code  {background:#fdf2e9;color:#784212}
.btn-hdr-dlh   {background:#2980b9;color:#fff}
.btn-hdr-dlmd  {background:#16a085;color:#fff}
#vm-close{background:none;border:none;color:#fff;font-size:20px;cursor:pointer;line-height:1;padding:2px 4px;margin-left:4px}

/* アコーディオン展開行 */
.vm-expand-row{display:none}
.vm-expand-row.open{display:table-row}
.vm-expand-cell{padding:0 !important;border-bottom:2px solid #6c3483 !important}
.vm-expand-inner{padding:12px 14px;background:#faf7ff}
.vm-sub-btns{display:flex;gap:6px;margin-bottom:0}
.btn-row-prev{background:#e8f4f8;color:#1a5276;border:1px solid #aed6f1;
              font-size:11px;padding:3px 9px;border-radius:3px;cursor:pointer;font-weight:600}
.btn-row-prev:hover{background:#d4e9f7}
.btn-row-code{background:#fdf2e9;color:#784212;border:1px solid #f0b27a;
              font-size:11px;padding:3px 9px;border-radius:3px;cursor:pointer;font-weight:600}
.btn-row-code:hover{background:#fce8d0}
.btn-row-prev.active,.btn-row-code.active{font-weight:700;box-shadow:inset 0 1px 3px rgba(0,0,0,.15)}
.vm-row-preview{display:none;margin-top:8px}
.vm-row-code   {display:none;margin-top:8px;background:#1e1e1e;color:#d4d4d4;
                font-family:'Courier New',monospace;font-size:11px;padding:10px;
                border-radius:3px;white-space:pre-wrap;word-wrap:break-word;max-height:300px;overflow:auto}
/* ビュー一覧テーブル */
#vm-view-list{flex-shrink:0;overflow-y:auto;max-height:220px;border-bottom:2px solid #e0d0f0}
#vm-view-table{width:100%;border-collapse:collapse;font-size:12px}
#vm-view-table thead th{background:#f5f0ff;color:#4a235a;padding:7px 12px;
                         text-align:left;font-weight:600;border-bottom:1px solid #e0d0f0;
                         position:sticky;top:0;z-index:1}
#vm-view-table tbody tr{border-bottom:1px solid #f0f0f0}
#vm-view-table tbody tr:hover{background:#faf7ff}
#vm-view-table td{padding:6px 12px;vertical-align:middle}
.vt-name{font-weight:600;color:#4a235a}
.vt-desc{color:#888;font-size:11px}
.vt-badge-ok  {background:#d5f5e3;color:#1e8449;border-radius:8px;padding:2px 8px;font-size:11px}
.vt-badge-none{background:#f0f0f0;color:#aaa;border-radius:8px;padding:2px 8px;font-size:11px}
.btn-vdl{font-size:11px;padding:3px 8px;border:none;border-radius:3px;cursor:pointer;font-weight:500}
.btn-vdl:hover{opacity:.85}
.btn-vdl-html{background:#2980b9;color:#fff}
.btn-vdl-md  {background:#16a085;color:#fff}
.btn-vdl-dis {background:#e0e0e0;color:#bbb;cursor:not-allowed}

/* コンテンツエリア（プレビュー・HTMLコード） */
#vm-content-area{flex:1;overflow:hidden;display:flex;flex-direction:column;min-height:0}
#vm-content-placeholder{flex:1;display:flex;align-items:center;justify-content:center;
                         color:#bbb;font-size:13px;flex-direction:column;gap:10px}
#vm-preview-wrap{flex:1;overflow:auto;padding:14px;background:#fff;display:none}
#vm-code-wrap   {flex:1;overflow:auto;padding:10px 14px;font-family:'Courier New',monospace;
                 font-size:11px;background:#1e1e1e;color:#d4d4d4;
                 white-space:pre-wrap;word-wrap:break-word;display:none}
/* ボタン無効 */
.btn-disabled{opacity:.4 !important;cursor:not-allowed !important}

/* ===== トースト ===== */
#toast{position:fixed;bottom:20px;right:20px;padding:10px 16px;border-radius:4px;
       color:#fff;font-size:13px;z-index:9999;display:none;max-width:300px}
#toast.ok {background:#27ae60}
#toast.err{background:#e74c3c}
.loading{color:#aaa;padding:30px;text-align:center;font-style:italic}
