</head>
<body>

<!-- ヘッダー -->
<div id="header">
  <h1>📁 プロジェクト</h1>
  <div class="nav-links">
    <a href="{{ url_for('guest.dashboard') }}">← ダッシュボード</a>
  </div>
</div>

<!-- プロジェクト一覧 -->
<div id="main">
  <div class="section-header">
    <h2>📁 プロジェクト一覧</h2>
    <button class="btn btn-primary" onclick="loadProjects()" style="margin-left:auto">⟳ 更新</button>
  </div>
  <div id="project-grid" class="project-grid">
    <div class="loading">読み込み中...</div>
  </div>
</div>



<!-- 閲覧モーダル -->
<div id="view-overlay" onclick="closeViewer()"></div>
<div id="view-modal">
  <div id="vm-header">
    <h2 id="vm-title">📄 プロジェクト閲覧</h2>
    <div class="vm-hdr-btns">
      <button class="btn-hdr btn-hdr-prev" onclick="showProjectView('preview')">👁 プレビュー</button>
      <button class="btn-hdr btn-hdr-code" onclick="showProjectView('code')">&lt;/&gt; HTMLコード</button>
      <button class="btn-hdr btn-hdr-dlh"  onclick="bulkDownload('html')">⬇ HTML一括</button>
      <button class="btn-hdr btn-hdr-dlmd" onclick="bulkDownload('md')">⬇ MD一括</button>
    </div>
    <button id="vm-close" onclick="closeViewer()">✕</button>
  </div>
  <!-- ビュー一覧 -->
  <div id="vm-view-list">
    <table id="vm-view-table">
      <thead><tr>
        <th>ビュー名</th><th>説明</th><th>状態</th><th>表示</th><th>ダウンロード</th>
      </tr></thead>
      <tbody id="vm-view-tbody"></tbody>
    </table>
  </div>
  <!-- プレビュー・HTMLコードエリア -->
  <div id="vm-content-area">
    <div id="vm-content-placeholder">
      <span>↑ 上のボタンで「👁 プレビュー」または「&lt;/&gt; HTMLコード」を表示</span>
    </div>
    <div id="vm-preview-wrap"></div>
    <div id="vm-code-wrap"></div>
  </div>
</div>

<div id="toast"></div>

<script>
// ===== 状態 =====
let allViewerData = []; // {link_id, view_name, description, html_content}
let currentViewerProjectName = '';

// ===== 起動 =====
$(function(){ loadProjects(); });

// ===== プロジェクト一覧 =====
function loadProjects(){
  $.get('/table_master/projects/list', function(data){
    const $g = $('#project-grid').empty();
    if(!data.success){ $g.html('<div class="loading" style="color:#e74c3c">'+esc(data.error)+'</div>'); return; }
    if(!data.projects.length){ $g.html('<div class="loading" style="color:#bbb">プロジェクトがありません</div>'); return; }
    data.projects.forEach(p => {
      const vc = p.view_count || 0;
      $g.append(`
        <div class="project-card">
          <div class="pc-name" onclick="location.href='/table_master/projects/${p.id}'">${esc(p.name)}</div>
          <div class="pc-desc">${esc(p.description||'')}</div>
          <div class="pc-meta">
            <span>
              <span class="badge-count">${p.table_count} テーブル</span>
              <span class="badge-view">${vc} ビュー</span>
            </span>
            <span style="display:flex;gap:5px;align-items:center">
              <button class="btn btn-view" style="padding:2px 9px;font-size:11px"
                onclick="openViewer(${p.id},'${escAttr(p.name)}')">👁 閲覧</button>
            </span>
          </div>
        </div>
      `);
    });
  });
}



// ===== 閲覧モーダル =====
function openViewer(projectId, projectName){
  allViewerData = [];
  currentViewerProjectName = projectName;
  $('#vm-title').text('📄 ' + projectName);
  $('#vm-tab-bar').html('<div class="loading" style="padding:10px">読み込み中...</div>');
  $('#vm-body').empty();
  $('#view-overlay').show();
  $('#view-modal').addClass('show');

  $.get('/table_master/projects/'+projectId+'/all_html', function(data){
    if(!data.success){
      toast('エラー: '+(data.error||'不明なエラー'),'err');
      // エラーでもモーダルは閉じずにメッセージ表示
      $('#vm-tab-bar').html('<div style="padding:12px;color:#e74c3c;font-size:12px">❌ '+(data.error||'取得失敗')+'</div>');
      return;
    }
    allViewerData = data.views || [];
    currentViewerProjectName = data.project_name || projectName;
    $('#vm-title').text('📄 ' + currentViewerProjectName);
    renderViewer(allViewerData);
  }).fail(function(xhr){
    var status = xhr.status;
    var msg = (xhr.responseJSON&&xhr.responseJSON.error?xhr.responseJSON.error:"") || xhr.responseText || '通信エラー';
    $('#vm-tab-bar').html('<div style="padding:12px;color:#e74c3c;font-size:12px">❌ HTTP '+status+': '+esc(msg.substring(0,200))+'</div>');
    toast('HTTP '+status+': 読み込みに失敗しました','err');
  });
}

function renderViewer(views){
  const $tbody = $('#vm-view-tbody').empty();
  $('#vm-content-placeholder').show();
  $('#vm-preview-wrap').hide().empty();
  $('#vm-code-wrap').hide().text('');

  if(!views.length){
    $tbody.append('<tr><td colspan="5" style="padding:16px;color:#aaa;text-align:center">ビューが登録されていません</td></tr>');
    return;
  }

  views.forEach(function(v, i){
    const hasHtml = !!v.has_html;
    const expandId = 'vm-expand-'+i;
    const $tr = $('<tr>');

    // ビュー名
    $tr.append($('<td class="vt-name">').text(v.view_name));
    // 説明
    $tr.append($('<td class="vt-desc">').text(v.description||''));
    // 状態バッジ
    const $badge = hasHtml
      ? $('<span class="vt-badge-ok">').text('✓ HTML保存済')
      : $('<span class="vt-badge-none">').text('未保存');
    $tr.append($('<td>').append($badge));

    // 個別プレビュー・HTMLコードボタン
    const $tdView = $('<td style="white-space:nowrap">');
    if(hasHtml){
      const $btnPrev = $('<button class="btn-row-prev">').text('👁 プレビュー');
      const $btnCode = $('<button class="btn-row-code">').text('</> HTMLコード');
      $btnPrev.on('click', function(){
        toggleRowExpand(expandId, 'preview', $btnPrev, $btnCode, v);
      });
      $btnCode.on('click', function(){
        toggleRowExpand(expandId, 'code', $btnPrev, $btnCode, v);
      });
      $tdView.append($btnPrev, ' ', $btnCode);
    } else {
      $tdView.append(
        $('<button class="btn-row-prev" disabled style="opacity:.35;cursor:not-allowed">').text('👁 プレビュー'),
        ' ',
        $('<button class="btn-row-code" disabled style="opacity:.35;cursor:not-allowed">').text('</> HTMLコード')
      );
    }
    $tr.append($tdView);

    // ダウンロードボタン
    const $tdBtn = $('<td style="white-space:nowrap">');
    if(hasHtml){
      $tdBtn.append(
        $('<button class="btn-vdl btn-vdl-html">').text('⬇ HTML')
          .on('click', function(){ downloadHtml(v); }),
        ' ',
        $('<button class="btn-vdl btn-vdl-md">').text('⬇ MD')
          .on('click', function(){ downloadMd(v); })
      );
    } else {
      $tdBtn.append(
        $('<button class="btn-vdl btn-vdl-dis" disabled>').text('⬇ HTML'),
        ' ',
        $('<button class="btn-vdl btn-vdl-dis" disabled>').text('⬇ MD')
      );
    }
    $tr.append($tdBtn);
    $tbody.append($tr);

    // アコーディオン展開行（初期非表示）
    const $expandRow = $('<tr class="vm-expand-row">').attr('id', expandId);
    const $expandCell = $('<td class="vm-expand-cell">').attr('colspan', 5);
    const $inner = $('<div class="vm-expand-inner">');
    // プレビューエリア
    const $prevDiv = $('<div class="vm-row-preview">');
    const $iframe = $('<iframe>').css({width:'100%',border:'1px solid #ddd',
      borderRadius:'3px',display:'block',minHeight:'120px'})
      .attr('sandbox','allow-same-origin allow-scripts').attr('scrolling','no');
    $prevDiv.append($iframe);
    // HTMLコードエリア
    const $codeDiv = $('<div class="vm-row-code">').text(v.html_content||'');
    $inner.append($prevDiv, $codeDiv);
    $expandCell.append($inner);
    $expandRow.append($expandCell);
    // iframeとviewデータを紐づけ
    $expandRow.data('iframe', $iframe[0]);
    $expandRow.data('html', v.html_content||'');
    $expandRow.data('loaded', false);
    $tbody.append($expandRow);
  });
}

function toggleRowExpand(expandId, mode, $btnPrev, $btnCode, v){
  const $row = $('#'+expandId);
  const $prevDiv = $row.find('.vm-row-preview');
  const $codeDiv = $row.find('.vm-row-code');
  const iframe   = $row.data('iframe');
  const html     = $row.data('html');

  // 同じボタンを再クリック → 折りたたむ
  const isOpen   = $row.hasClass('open');
  const curMode  = $row.data('mode');
  if(isOpen && curMode === mode){
    $row.removeClass('open');
    $btnPrev.removeClass('active');
    $btnCode.removeClass('active');
    return;
  }

  // 展開
  $row.addClass('open').data('mode', mode);
  if(mode === 'preview'){
    $prevDiv.show(); $codeDiv.hide();
    $btnPrev.addClass('active'); $btnCode.removeClass('active');
    // iframeはまだ書き込まれていなければ書き込む
    if(!$row.data('loaded')){
      $row.data('loaded', true);
      var doc = iframe.contentDocument || iframe.contentWindow.document;
      doc.open();
      doc.write('<html><head><style>body{margin:8px;font-family:sans-serif;font-size:13px}'
        +'table{border-collapse:collapse;width:100%}'
        +'th{background:#2e6da4;color:#fff;padding:5px 9px;text-align:left}'
        +'td{padding:4px 9px;border:1px solid #ccc}</style></head><body>'+html+'</body></html>');
      doc.close();
      setTimeout(function(){
        try{ iframe.style.height=(iframe.contentDocument.body.scrollHeight+20)+'px'; }catch(e){}
      }, 120);
    }
  } else {
    $prevDiv.hide(); $codeDiv.show();
    $btnCode.addClass('active'); $btnPrev.removeClass('active');
  }
}

// プロジェクト全体のプレビュー or HTMLコードを表示
function showProjectView(mode){
  const downloadable = allViewerData.filter(function(v){ return !!v.has_html; });

  $('#vm-content-placeholder').hide();
  $('#vm-preview-wrap').hide();
  $('#vm-code-wrap').hide();

  if(!downloadable.length){
    $('#vm-content-placeholder').show()
      .html('<span style="color:#e67e22">⚠️ HTMLが保存されているビューがありません</span>');
    return;
  }

  if(mode === 'preview'){
    const $wrap = $('#vm-preview-wrap').empty().show();
    downloadable.forEach(function(v){
      // セクションヘッダー
      $wrap.append(
        $('<div>').css({
          fontWeight:'700', fontSize:'14px', color:'#4a235a',
          borderBottom:'2px solid #6c3483', paddingBottom:'4px',
          margin:'16px 0 10px'
        }).text(v.view_name)
      );
      if(v.description){
        $wrap.append($('<div>').css({fontSize:'11px',color:'#888',marginBottom:'8px'}).text(v.description));
      }
      // iframe でレンダリング
      const $iframe = $('<iframe>').css({
        width:'100%', border:'1px solid #ddd', borderRadius:'3px',
        display:'block', marginBottom:'8px'
      }).attr('sandbox','allow-same-origin allow-scripts').attr('scrolling','no');
      $wrap.append($iframe);
      // DOM追加後に書き込み
      setTimeout((function(iframe, html){
        return function(){
          var doc = iframe.contentDocument || iframe.contentWindow.document;
          doc.open();
          doc.write('<html><head><style>body{margin:8px;font-family:sans-serif;font-size:13px}table{border-collapse:collapse;width:100%}th{background:#2e6da4;color:#fff;padding:5px 9px;text-align:left}td{padding:4px 9px;border:1px solid #ccc}</style></head><body>'+html+'</body></html>');
          doc.close();
          // コンテンツに合わせてiframe高さを自動調整
          setTimeout(function(){
            try{ iframe.style.height=(iframe.contentDocument.body.scrollHeight+20)+'px'; }catch(e){}
          }, 80);
        };
      })($iframe[0], v.html_content), 30);
    });
  } else {
    // HTMLコード表示（全ビュー連結）
    var code = '';
    downloadable.forEach(function(v){
      code += '<!-- ========== '+v.view_name+' ========== -->\n';
      code += v.html_content + '\n\n';
    });
    $('#vm-code-wrap').text(code).show();
  }
}

function closeViewer(){
  $('#view-overlay').hide();
  $('#view-modal').removeClass('show');
}

// ===== ダウンロード =====
function downloadHtml(v){
  const blob = new Blob([buildFullHtml(v)], {type:'text/html;charset=utf-8'});
  triggerDownload(blob, safeFilename(v.view_name)+'.html');
}

function downloadMd(v){
  const md = htmlTableToMd(v.html_content, v.view_name);
  const blob = new Blob([md], {type:'text/markdown;charset=utf-8'});
  triggerDownload(blob, safeFilename(v.view_name)+'.md');
}

function bulkDownload(type){
  const downloadable = allViewerData.filter(function(v){ return !!v.has_html; });
  if(!downloadable.length){ toast('HTMLが保存されているビューがありません','err'); return; }
  // allViewerData を downloadable に差し替えてダウンロード
  const _orig = allViewerData;
  allViewerData = downloadable;
  if(type === 'html'){
    // 全ビューを1つのHTMLファイルに結合
    let html = '<!DOCTYPE html>\n<html lang="ja">\n<head>\n<meta charset="UTF-8">\n';
    html += '<title>'+escHtml(currentViewerProjectName)+'</title>\n';
    html += '<style>body{font-family:sans-serif;font-size:13px;margin:20px}';
    html += 'h2{color:#1a3a5c;border-bottom:2px solid #2e6da4;padding-bottom:6px;margin:30px 0 12px}';
    html += 'table{border-collapse:collapse;width:100%;margin-bottom:30px}';
    html += 'th{background:#2e6da4;color:#fff;padding:6px 10px;text-align:left}';
    html += 'td{padding:5px 10px;border:1px solid #ccc}</style>\n</head>\n<body>\n';
    html += '<h1>'+escHtml(currentViewerProjectName)+'</h1>\n';
    allViewerData.forEach(function(v){
      html += '<h2>'+escHtml(v.view_name)+'</h2>\n';
      if(v.description) html += '<p style="color:#666;font-size:12px;margin-bottom:8px">'+escHtml(v.description)+'</p>\n';
      html += v.html_content + '\n';
    });
    html += '</body>\n</html>';
    const blob = new Blob([html], {type:'text/html;charset=utf-8'});
    triggerDownload(blob, safeFilename(currentViewerProjectName)+'_all.html');
  } else {
    // 全ビューを1つのMDファイルに結合
    let md = '# '+currentViewerProjectName+'\n\n';
    allViewerData.forEach(function(v){
      md += '## '+v.view_name+'\n\n';
      if(v.description) md += '*'+v.description+'*\n\n';
      md += htmlTableToMd(v.html_content, '') + '\n\n';
    });
    const blob = new Blob([md], {type:'text/markdown;charset=utf-8'});
    triggerDownload(blob, safeFilename(currentViewerProjectName)+'_all.md');
  }
  allViewerData = _orig; // 元に戻す
}

// ===== HTML→Markdown テーブル変換 =====
function htmlTableToMd(htmlContent, title){
  var md = title ? '## ' + title + '\n\n' : '';
  var $tmp = $('<div>').html(htmlContent);
  $tmp.find('table').each(function(){
    var $tbl = $(this);
    var rows = [];
    // ヘッダ行
    var headerCells = [];
    $tbl.find('thead th').each(function(){ headerCells.push(cellText($(this))); });
    // thead がなければ最初の tr の th/td をヘッダとして扱う
    if(!headerCells.length){
      $tbl.find('tr:first th, tr:first td').each(function(){ headerCells.push(cellText($(this))); });
    }
    if(headerCells.length){
      rows.push('| '+headerCells.join(' | ')+' |');
      rows.push('|'+headerCells.map(()=>' --- ').join('|')+'|');
    }
    // データ行
    $tbl.find('tbody tr').each(function(){
      var cols = [];
      $(this).find('td,th').each(function(){ cols.push(cellText($(this))); });
      if(cols.length) rows.push('| '+cols.join(' | ')+' |');
    });
    // thead なしパターン（tr が body に直接）
    if(!$tbl.find('tbody').length){
      $tbl.find('tr').each(function(ri){
        if(ri===0 && headerCells.length) return; // ヘッダ行はスキップ
        var cols = [];
        $(this).find('td,th').each(function(){ cols.push(cellText($(this))); });
        if(cols.length) rows.push('| '+cols.join(' | ')+' |');
      });
    }
    md += rows.join('\n') + '\n';
  });
  if(!$tmp.find('table').length){
    // テーブルがない場合はテキストとして出力
    md += $tmp.text().trim() + '\n';
  }
  return md;
}

function cellText($el){
  return $el.text().trim().replace(/\|/g,'\\|').replace(/\n/g,' ');
}

function buildFullHtml(v){
  return '<!DOCTYPE html>\n<html lang="ja">\n<head>\n<meta charset="UTF-8">\n'
    +'<title>'+escHtml(v.view_name)+'</title>\n'
    +'<style>body{font-family:sans-serif;font-size:13px;margin:20px}'
    +'h1{color:#1a3a5c;border-bottom:2px solid #2e6da4;padding-bottom:6px;margin-bottom:14px}'
    +'table{border-collapse:collapse;width:100%}'
    +'th{background:#2e6da4;color:#fff;padding:6px 10px;text-align:left}'
    +'td{padding:5px 10px;border:1px solid #ccc}</style>\n</head>\n<body>\n'
    +'<h1>'+escHtml(v.view_name)+'</h1>\n'
    +(v.description?'<p style="color:#666;font-size:12px;margin-bottom:14px">'+escHtml(v.description)+'</p>\n':'')
    +v.html_content+'\n</body>\n</html>';
}

function triggerDownload(blob, filename){
  const url = URL.createObjectURL(blob);
  const $a = $('<a>').attr({href:url, download:filename}).appendTo('body');
  $a[0].click();
  $a.remove();
  setTimeout(()=>URL.revokeObjectURL(url), 1000);
}

function safeFilename(s){
  return (s||'download').replace(/[\\/:*?"<>|]/g,'_').replace(/\s+/g,'_');
}

// ===== ユーティリティ =====
function esc(s){ return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function escHtml(s){ return esc(s); }
function escAttr(s){ return String(s??'').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }
function toast(msg,type='ok'){
  $('#toast').attr('class',type).text(msg).fadeIn(200);
  setTimeout(()=>$('#toast').fadeOut(400),3000);
}
</script>
</body>
</html>

