<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>ビューエディタ - テーブルマスター</title>
<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
<style>
/* ===== レイアウト ===== */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body { font-family: 'Helvetica Neue', Arial, 'Hiragino Kaku Gothic ProN', sans-serif;
       font-size: 13px; background: #f0f2f5; color: #333; height: 100vh;
       display: flex; flex-direction: column; }

/* ===== ヘッダー ===== */
#header { background: #1a3a5c; color: #fff; padding: 10px 16px;
          display: flex; align-items: center; gap: 12px; flex-shrink: 0; }
#header h1 { font-size: 16px; font-weight: 600; }
#header .nav-links { margin-left: auto; display: flex; gap: 8px; }
#header a { color: #aed6f1; text-decoration: none; font-size: 12px; padding: 4px 8px;
            border: 1px solid #2e6da4; border-radius: 3px; }
#header a:hover { background: #2e6da4; }

/* ===== メインレイアウト ===== */
#main { display: flex; flex: 1; overflow: hidden; }

/* ===== 左パネル: ビュー一覧 ===== */
#left-panel { width: 260px; flex-shrink: 0; background: #fff; border-right: 1px solid #ddd;
              display: flex; flex-direction: column; }
#left-panel .panel-title { background: #2e6da4; color: #fff; padding: 8px 12px;
