                            align-items: center; justify-content: space-between; }
#view-search { padding: 8px; border-bottom: 1px solid #eee; }
#view-search input { width: 100%; padding: 5px 8px; border: 1px solid #ccc;
                     border-radius: 3px; font-size: 12px; }
#view-list { flex: 1; overflow-y: auto; }
.view-item { padding: 8px 12px; border-bottom: 1px solid #f0f0f0; cursor: pointer;
             display: flex; flex-direction: column; gap: 2px; }
.view-item:hover { background: #eef4fb; }
.view-item.active { background: #dbeafe; border-left: 3px solid #2e6da4; }
.view-item .vname { font-size: 13px; font-weight: 600; color: #1a3a5c; }
.view-item .vdb   { font-size: 11px; color: #888; }
.view-item .vdesc { font-size: 11px; color: #666; white-space: nowrap;
                    overflow: hidden; text-overflow: ellipsis; }

/* ===== 右パネル: エディタ ===== */
#right-panel { flex: 1; display: flex; flex-direction: column; overflow: hidden; }

/* ===== エディタ上部 ===== */
#editor-area { background: #fff; border-bottom: 1px solid #ddd; padding: 12px 16px;
               flex-shrink: 0; }
#editor-toolbar { display: flex; gap: 8px; margin-bottom: 10px; flex-wrap: wrap;
                  align-items: center; }
#editor-toolbar .toolbar-title { font-size: 13px; font-weight: 600; color: #1a3a5c;
                                  flex: 1; }
.btn { padding: 5px 12px; border: none; border-radius: 3px; cursor: pointer;
       font-size: 12px; font-weight: 500; transition: opacity .15s; }
.btn:hover { opacity: .85; }
.btn-primary  { background: #2e6da4; color: #fff; }
.btn-success  { background: #27ae60; color: #fff; }
.btn-danger   { background: #e74c3c; color: #fff; }
.btn-warning  { background: #f39c12; color: #fff; }
.btn-secondary{ background: #7f8c8d; color: #fff; }
.btn-new      { background: #1a3a5c; color: #fff; }

#meta-form { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 12px; }
#meta-form .full-width { grid-column: 1 / -1; }
label { font-size: 11px; color: #666; display: block; margin-bottom: 3px; }
input[type=text], select, textarea {
    width: 100%; padding: 5px 8px; border: 1px solid #ccc; border-radius: 3px;
    font-size: 12px; font-family: inherit; }
textarea { resize: vertical; }
#query-textarea { font-family: 'Courier New', monospace; font-size: 12px;
                  background: #f8f9fa; min-height: 80px; }

/* ===== プレビューエリア ===== */
#preview-area { flex: 1; overflow-y: auto; padding: 12px 16px; }
#preview-status { margin-bottom: 8px; font-size: 12px; color: #666; }
#preview-status .status-ok  { color: #27ae60; font-weight: 600; }
#preview-status .status-err { color: #e74c3c; font-weight: 600; }
#preview-table-wrap { overflow-x: auto; }
#preview-table { border-collapse: collapse; font-size: 12px; width: 100%; }
#preview-table th { background: #2e6da4; color: #fff; padding: 6px 10px;
                    text-align: left; white-space: nowrap; border: 1px solid #1a5276; }
#preview-table td { padding: 5px 10px; border: 1px solid #ddd;
                    white-space: nowrap; max-width: 300px;
                    overflow: hidden; text-overflow: ellipsis; }
#preview-table tr:nth-child(even) td { background: #f7fafd; }

/* ===== トースト通知 ===== */
#toast { position: fixed; bottom: 20px; right: 20px; padding: 10px 16px;
         border-radius: 4px; color: #fff; font-size: 13px; z-index: 9999;
         display: none; max-width: 320px; }
#toast.ok  { background: #27ae60; }
#toast.err { background: #e74c3c; }

/* ===== ローディング ===== */
.loading { color: #888; font-style: italic; padding: 20px; text-align: center; }
</style>
