<body>

<!-- ヘッダー -->
<div id="header">
  <h1>📋 ビューエディタ</h1>
  <div class="nav-links">
    <a href="/table_master/archive/">📦 アーカイブ管理</a>
    <a href="/table_master/">← テーブルマスター</a>
  </div>
</div>

<!-- メインレイアウト -->
<div id="main">

  <!-- 左: ビュー一覧 -->
  <div id="left-panel">
    <div class="panel-title">
      <span>保存済みビュー</span>
      <button class="btn btn-new" style="padding:2px 8px;font-size:11px;" onclick="newView()">＋ 新規</button>
    </div>
    <div id="view-search">
      <input type="text" id="search-input" placeholder="ビュー名で絞り込み..." oninput="filterViews()">
    </div>
    <div id="view-list">
      <div class="loading">読み込み中...</div>
    </div>
  </div>

  <!-- 右: エディタ + プレビュー -->
  <div id="right-panel">

    <!-- エディタ -->
    <div id="editor-area">
      <div id="editor-toolbar">
        <span class="toolbar-title" id="editor-title">ビューを選択または新規作成</span>
        <button class="btn btn-warning" onclick="previewQuery()">▶ プレビュー</button>
        <button class="btn btn-success" onclick="saveView()">💾 保存</button>
        <button class="btn btn-danger"  onclick="deleteView()" id="btn-delete" style="display:none">🗑 削除</button>
        <button class="btn btn-primary" onclick="sendToArchive()" id="btn-archive" style="display:none">📦 アーカイブへ</button>
      </div>
      <div id="meta-form">
        <input type="hidden" id="view-id">
        <div>
          <label>ビュー名（英数字・アンダースコア）</label>
          <input type="text" id="field-view-name" placeholder="例: sales_monthly_2026">
        </div>
        <div>
          <label>表示名</label>
          <input type="text" id="field-display-name" placeholder="例: 月別売上集計 2026年">
        </div>
        <div>
          <label>対象データベース</label>
          <select id="field-database">
            <option value="">DB選択...</option>
          </select>
        </div>
        <div>
          <label>説明・メモ</label>
          <input type="text" id="field-description" placeholder="このビューの用途・メモ">
        </div>
        <div class="full-width">
          <label>SQLクエリ（SELECT / SHOW / DESCRIBE / EXPLAIN）</label>
          <textarea id="query-textarea" rows="4"
            placeholder="SELECT * FROM table_name WHERE ..."></textarea>
        </div>
      </div>
    </div>

    <!-- プレビュー -->
    <div id="preview-area">
      <div id="preview-status"></div>
      <div id="preview-table-wrap"></div>
    </div>

  </div><!-- /right-panel -->
</div><!-- /main -->

<div id="toast"></div>

<script>
// ===== 状態 =====
let allViews = [];
let currentViewId = null;
let lastPreviewResult = null; // アーカイブ送信用

// ===== 起動 =====
$(function() {
  loadDatabases();
  loadViews();
});

// ===== DB一覧取得 =====
function loadDatabases() {
  $.get('/table_master/get_all_tables', function(data) {
    if (!data.tables) return;
    const dbs = [...new Set(data.tables.map(t => t.database))].sort();
    const $sel = $('#field-database');
    dbs.forEach(db => $sel.append(`<option value="${esc(db)}">${esc(db)}</option>`));
  });
}

// ===== ビュー一覧 =====
function loadViews() {
  $.get('/table_master/view_editor/list', function(data) {
    if (data.success) {
      allViews = data.views;
      renderViewList(allViews);
    }
  });
}

function renderViewList(views) {
  const $list = $('#view-list').empty();
  if (!views.length) {
    $list.html('<div class="loading" style="color:#aaa">ビューがありません</div>');
    return;
  }
  views.forEach(v => {
    const $item = $(`
      <div class="view-item ${v.id == currentViewId ? 'active' : ''}" data-id="${v.id}">
        <div class="vname">${esc(v.display_name)}</div>
        <div class="vdb">${esc(v.source_database)} / <code>${esc(v.view_name)}</code></div>
        <div class="vdesc">${esc(v.description || '(説明なし)')}</div>
      </div>
    `).on('click', () => selectView(v.id));
    $list.append($item);
  });
}

function filterViews() {
  const q = $('#search-input').val().toLowerCase();
  renderViewList(allViews.filter(v =>
    (v.view_name + v.display_name + (v.description||'')).toLowerCase().includes(q)
  ));
}

// ===== ビュー選択 =====
function selectView(id) {
  const v = allViews.find(x => x.id == id);
  if (!v) return;
  currentViewId = id;
  lastPreviewResult = null;
  $('#view-id').val(v.id);
  $('#field-view-name').val(v.view_name);
  $('#field-display-name').val(v.display_name);
  $('#field-description').val(v.description || '');
  $('#field-database').val(v.source_database);
  $('#query-textarea').val(v.query_text);
  $('#editor-title').text(v.display_name);
  $('#btn-delete').show();
  $('#btn-archive').hide();
  $('#preview-status').html('');
  $('#preview-table-wrap').empty();
  renderViewList(allViews); // active更新
}

// ===== 新規 =====
function newView() {
  currentViewId = null;
  lastPreviewResult = null;
  $('#view-id').val('');
  $('#field-view-name').val('');
  $('#field-display-name').val('');
  $('#field-description').val('');
  $('#field-database').val('');
  $('#query-textarea').val('');
  $('#editor-title').text('新規ビュー');
  $('#btn-delete').hide();
  $('#btn-archive').hide();
  $('#preview-status').html('');
  $('#preview-table-wrap').empty();
  renderViewList(allViews);
}

// ===== プレビュー =====
function previewQuery() {
  const db = $('#field-database').val();
  const q  = $('#query-textarea').val().trim();
  if (!db || !q) { toast('データベースとクエリを入力してください', 'err'); return; }

  $('#preview-status').html('<span style="color:#888">実行中...</span>');
  $('#preview-table-wrap').empty();

  $.ajax({
    url: '/table_master/view_editor/preview',
    type: 'POST',
    contentType: 'application/json',
    data: JSON.stringify({ source_database: db, query_text: q }),
    success: function(res) {
      if (!res.success) {
        $('#preview-status').html(`<span class="status-err">エラー: ${esc(res.error)}</span>`);
        return;
      }
      lastPreviewResult = res;
      $('#preview-status').html(
        `<span class="status-ok">✓ ${res.row_count}行</span>` +
        ` &nbsp; 実行時間: ${res.execution_time}秒` +
        ` &nbsp; <small style="color:#aaa">(最大1000行表示)</small>`
      );
      renderPreviewTable(res.columns, res.rows);
      $('#btn-archive').show();
    },
    error: function(xhr) {
      const msg = xhr.responseJSON?.error || '通信エラー';
      $('#preview-status').html(`<span class="status-err">エラー: ${esc(msg)}</span>`);
    }
  });
}

function renderPreviewTable(columns, rows) {
  let html = '<table id="preview-table"><thead><tr>';
  columns.forEach(c => { html += `<th>${esc(c)}</th>`; });
  html += '</tr></thead><tbody>';
  rows.forEach(row => {
    html += '<tr>';
    columns.forEach(c => { html += `<td>${esc(row[c] ?? '')}</td>`; });
    html += '</tr>';
  });
  html += '</tbody></table>';
  $('#preview-table-wrap').html(html);
}

// ===== 保存 =====
function saveView() {
  const payload = {
    id:              $('#view-id').val() || null,
    view_name:       $('#field-view-name').val().trim(),
    display_name:    $('#field-display-name').val().trim(),
    description:     $('#field-description').val().trim(),
    source_database: $('#field-database').val(),
    query_text:      $('#query-textarea').val().trim()
  };
  if (!payload.view_name || !payload.display_name || !payload.source_database || !payload.query_text) {
    toast('必須項目をすべて入力してください', 'err'); return;
  }
  $.ajax({
    url: '/table_master/view_editor/save',
    type: 'POST', contentType: 'application/json',
    data: JSON.stringify(payload),
    success: function(res) {
      if (res.success) {
        toast(res.message, 'ok');
        currentViewId = res.id;
        $('#view-id').val(res.id);
        $('#btn-delete').show();
        loadViews();
      } else {
        toast(res.error, 'err');
      }
    },
    error: function(xhr) { toast(xhr.responseJSON?.error || '保存エラー', 'err'); }
  });
}

// ===== 削除 =====
function deleteView() {
  const id = $('#view-id').val();
  if (!id) return;
  const name = $('#field-display-name').val();
  if (!confirm(`「${name}」を削除しますか？`)) return;
  $.ajax({
    url: '/table_master/view_editor/delete',
    type: 'POST', contentType: 'application/json',
    data: JSON.stringify({ id }),
    success: function(res) {
      if (res.success) { toast(res.message, 'ok'); newView(); loadViews(); }
      else toast(res.error, 'err');
    }
  });
}

// ===== アーカイブへ送信 =====
function sendToArchive() {
  if (!lastPreviewResult) { toast('先にプレビューを実行してください', 'err'); return; }
  // アーカイブ管理画面にパラメータを渡して遷移
  const params = new URLSearchParams({
    from_view:  currentViewId || '',
    db:         $('#field-database').val(),
    query:      $('#query-textarea').val().trim(),
    title:      $('#field-display-name').val().trim()
  });
  window.location.href = '/table_master/archive/?' + params.toString();
}

// ===== ユーティリティ =====
function esc(s) {
  return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function toast(msg, type='ok') {
  $('#toast').attr('class', type).text(msg).fadeIn(200);
  setTimeout(() => $('#toast').fadeOut(400), 3000);
}
</script>
</body>
</html>

tech_spec_app_info.endpoints:
GET  /                    - メイン画面（index）．3タブ構成のダッシュボードを返す
GET  /databases           - 対象DB一覧をJSONで返す（key, db, table_count, reachable, error）
GET  /audit               - 操作履歴を新しい順に返す（query: limit，既定100・上限500）
POST /backup/start        - バックアップジョブを作成，または未完了ジョブを再開
                            body: {"databases": ["default","fujinp",...], "resume_job_id": "job_..."〔任意〕}
                            → {success, job_id, resumed, progress}
POST /backup/step         - 未処理テーブルを最大BATCH（=10）件処理
                            body: {"job_id": "job_..."}
                            → {success, job_id, processed[], complete, progress}
POST /backup/finalize     - 全完了を確認して manifest.json を書き，zip化して作業ディレクトリを削除
                            body: {"job_id": "job_..."}
                            → {success, message, zip_name, zip_size, summary[]}
GET  /download/<zip_name> - 作成済みzipを添付ダウンロード（basename化・接頭辞/拡張子検査・実パス確認）
POST /clear_all           - 作業領域の中身を全削除（旧static保存先があれば併せて削除）
                            body: {"force": true|false}
                            → {success, message, removed, freed}
                            進行中の作業がある場合は 409 {success:false, need_force:true, error}
POST /restore/inspect     - zipをアップロードして展開・解析（DBは変更しない）
                            multipart/form-data: file=<*.zip>
                            → {success, token, report[{db, allowed, reachable,
                                 tables[{table, will_overwrite, invalid}],
                                 overwrite_count, new_count}]}
POST /restore/start       - 復元計画（plan）を作って restore_state.json に保存
                            body: {"token": ..., "databases": [<dbname>,...],
                                   "tables": {<dbname>: [<table>,...]}〔任意・省略時は全テーブル〕}
                            → {success, token, skipped[], progress}
POST /restore/step        - 計画の先頭から最大RESTORE_BATCH（=5）テーブルを完全置換
                            body: {"token": ...}
                            → {success, token, processed[], complete, progress}
POST /restore/finish      - 結果をまとめ，履歴に記録し，展開データを削除
                            body: {"token": ...}
                            → {success, message, results[{db, restored[], errors[]}], skipped[]}
POST /restore/cancel      - 展開済み作業ディレクトリを削除 body: {"token": ...} → {success}
GET  /return_to_fujin     - FUJIN-Pダッシュボードへ戻る

※ Blueprint全体に before_request（require_admin）を適用し，管理者以外は画面も含めて一切実行できない．
   各ルートには @login_required も併記しているが，判定は require_admin が先に行うため実質は冗長．
※ /download はファイル応答，その他は JSON を返す．エラー時のHTTPコードは
   400（パラメータ不正）／401（未ログイン）／403（非admin）／404（ジョブ・ファイル不明）／
   409（進行中の作業あり）／500（例外）．

