<body>
    <div class="container">
        <div class="header">
            <h1>時空資源予約</h1>
            <div class="navigation">
                <a href="{{ url_for('strm.overview') }}" class="nav-button">予約状況</a>
                {% if show_pending_link %}
                <a href="{{ url_for('strm.pending') }}" class="nav-button">承認ダッシュボード{% if pending_count %}<span class="pending-badge">{{ pending_count }}</span>{% endif %}</a>
                {% endif %}
                {% if is_admin %}
                <a href="{{ url_for('strm.resources') }}" class="nav-button">資源管理</a>
                {% endif %}
                <a href="{{ url_for('strm.return_to_fujin') }}" class="btn-return">🏠 FUJIN-Pダッシュボードに戻る</a>
            </div>
        </div>

        <div id="result"></div>

        <div class="calendar-header">
            <div class="week-navigation">
                <button id="prevWeek" class="secondary-button">&lt; 前週</button>
                <span id="currentWeek"></span>
                <button id="nextWeek" class="secondary-button">次週 &gt;</button>
            </div>
        </div>

        <div class="table-container">
            <table class="resource-table">
                <thead id="resource-table-head"></thead>
            </table>
            <div class="table-body-container">
                <table class="resource-table">
                    <tbody id="resource-table-body"></tbody>
                </table>
            </div>
        </div>

        <!-- 新規予約モーダル -->
        <div id="reservation-form" class="modal">
            <h3 id="form-title">新規予約</h3>
            <p id="approval-notice" class="approval-notice">この資源の予約には承認が必要です</p>
            <form id="new-reservation-form">
                <input type="hidden" id="form-resource-id">
                <input type="hidden" id="form-date">
                <div id="form-resource-name" class="resource-name"></div>
                <div id="form-date-display"></div>
                <label for="start-time">開始時間:</label>
                <input type="time" id="start-time" required>
                <label for="end-time">終了時間:</label>
                <input type="time" id="end-time" required>
                <label for="summary">概要:</label>
                <input type="text" id="summary" maxlength="200" required>
                <p id="form-error" class="form-error"></p>
                <div class="modal-footer">
                    <button type="button" class="secondary-button" onclick="closeModals()">キャンセル</button>
                    <button type="submit" id="submit-button">予約する</button>
                </div>
            </form>
        </div>

        <!-- 予約詳細モーダル -->
        <div id="reservation-details" class="modal">
            <h3>予約詳細</h3>
            <p><strong>資源名：</strong><span id="detail-resource"></span></p>
            <p><strong>予約者：</strong><span id="detail-reserver"></span></p>
            <p><strong>開始時間：</strong><span id="detail-start"></span></p>
            <p><strong>終了時間：</strong><span id="detail-end"></span></p>
            <p><strong>概要：</strong><span id="detail-summary"></span></p>
            <p><strong>状態：</strong><span id="detail-status"></span></p>
            <div class="modal-footer">
                <button class="secondary-button" onclick="closeModals()">閉じる</button>
                <span id="detail-buttons"></span>
            </div>
        </div>

        <div id="modal-backdrop" class="modal-backdrop"></div>
    </div>

    <script>
        const API = {
            week:   '{{ url_for("strm.api_week") }}',
            create: '{{ url_for("strm.api_create_reservation") }}',
            cancel:  id => '{{ url_for("strm.api_cancel_reservation", reservation_id=0) }}'.replace('/0/', '/' + id + '/'),
            approve: id => '{{ url_for("strm.api_approve_reservation", reservation_id=0) }}'.replace('/0/', '/' + id + '/'),
            reject:  id => '{{ url_for("strm.api_reject_reservation", reservation_id=0) }}'.replace('/0/', '/' + id + '/')
        };

        let currentStart = '';   // 表示中の週の開始日（サーバから返る文字列）
        let resourceMap = {};    // id -> {name, requires_approval}

        function showResult(message, isError) {
            const $r = $('#result');
            $r.text(message).removeClass('success error')
              .addClass(isError ? 'error' : 'success').show();
            setTimeout(() => $r.fadeOut(), 5000);
        }

        function closeModals() {
            $('#reservation-form, #reservation-details, #modal-backdrop').hide();
            $('#new-reservation-form')[0].reset();
            $('#form-error').hide().text('');
            $('#approval-notice').hide();
            $('#submit-button').prop('disabled', false).text('予約する');
        }

        function loadWeek(start) {
            $.get(API.week, start ? { start: start } : {}, function(resp) {
                if (!resp.success) { showResult(resp.error || '読み込みに失敗しました。', true); return; }
                currentStart = resp.week_dates[0].date;
                $('#currentWeek').text(resp.week_label);
                $('#prevWeek').data('start', resp.prev_start);
                $('#nextWeek').data('start', resp.next_start);
                resourceMap = {};
                resp.resources.forEach(r => { resourceMap[r.id] = r; });
                renderWeek(resp);
            }).fail(() => showResult('データの取得中にエラーが発生しました。', true));
        }

        function renderWeek(resp) {
            const $head = $('#resource-table-head').empty();
            const $headRow = $('<tr>').append($('<th>').text('資源名'));
            resp.week_dates.forEach((d, i) => {
                const cls = i === 0 ? 'sunday' : (i === 6 ? 'saturday' : '');
                $headRow.append($('<th>').addClass(cls).text(d.label + '(' + d.weekday + ')'));
            });
            $head.append($headRow);

            const $body = $('#resource-table-body').empty();
            resp.resources.forEach(resource => {
                const $row = $('<tr>');
                const $name = $('<td>').append($('<span>').addClass('resource-name').text(resource.name));
                if (resource.requires_approval) {
                    $name.append('<br>').append($('<span>').addClass('approval-tag').text('要承認'));
                }
                $row.append($name);

                resp.week_dates.forEach(d => {
                    const $cell = $('<td>');
                    if (d.is_today) $cell.addClass('today');
                    const dayList = (resp.reservations[String(resource.id)] || {})[d.date] || [];
                    dayList.forEach(item => $cell.append(buildSlot(item, resource.name)));
                    if (resource.can_apply) {
                        const $add = $('<button>').addClass('add-reservation-btn').text('＋')
                            .on('click', () => openForm(resource.id, d.date));
                        $cell.append($add);
                    }
                    $row.append($cell);
                });
                $body.append($row);
            });
        }

        function buildSlot(item, resourceName) {
            let cls = 'reservation-slot reservation-' + item.time_state;
            if (item.status === 'pending' && item.time_state !== 'past') cls += ' pending-approval';
            const summary = item.summary.length > 7 ? item.summary.substring(0, 7) + '...' : item.summary;
            const $div = $('<div>').addClass(cls)
                .append($('<div>').text(item.start_time + '-' + item.end_time))
                .append($('<div>').text(summary));
            if (item.status === 'pending') {
                $div.append($('<div>').css({ color: '#c62828', 'font-weight': 'bold' }).text('承認待ち'));
            }
            $div.on('click', e => { e.stopPropagation(); openDetail(item, resourceName); });
            return $div;
        }

        function openForm(resourceId, date) {
            closeModals();
            const resource = resourceMap[resourceId];
            if (!resource) { showResult('資源情報の取得に失敗しました。', true); return; }
            $('#form-resource-id').val(resourceId);
            $('#form-date').val(date);
            $('#form-resource-name').text(resource.name);
            $('#form-date-display').text(date);
            if (resource.needs_approval) {
                $('#approval-notice').show();
                $('#submit-button').text('予約申請する');
            }
            $('#reservation-form, #modal-backdrop').show();
        }

        function openDetail(item, resourceName) {
            closeModals();
            $('#detail-resource').text(resourceName);
            $('#detail-reserver').text(item.reserver_name);
            $('#detail-start').text(item.date + ' ' + item.start_time);
            $('#detail-end').text(item.date + ' ' + item.end_time);
            $('#detail-summary').text(item.summary || 'なし');
            $('#detail-status').empty().append(
                $('<span>').addClass('status-badge status-' + item.status).text(item.status_label)
            );
            const $btns = $('#detail-buttons').empty();
            if (item.can_approve) {
                $btns.append($('<button>').addClass('approve-button').text('承認')
                    .on('click', () => decide(API.approve(item.id), 'この予約を承認しますか？')));
                $btns.append(' ');
                $btns.append($('<button>').addClass('reject-button').text('却下')
                    .on('click', () => decide(API.reject(item.id), 'この予約を却下しますか？')));
                $btns.append(' ');
            }
            if (item.can_cancel) {
                $btns.append($('<button>').addClass('cancel-button').text('取り下げ')
                    .on('click', () => decide(API.cancel(item.id), 'この予約を取り下げますか？')));
            }
            $('#reservation-details, #modal-backdrop').show();
        }

        function decide(url, confirmMessage) {
            if (!confirm(confirmMessage)) return;
            $.ajax({
                url: url, method: 'POST', contentType: 'application/json', data: '{}',
                success: resp => {
                    closeModals();
                    if (resp.success) { showResult(resp.message, false); loadWeek(currentStart); }
                    else showResult(resp.error || '処理に失敗しました。', true);
                },
                error: xhr => {
                    closeModals();
                    const r = xhr.responseJSON;
                    showResult((r && r.error) || '通信エラーが発生しました。', true);
                }
            });
        }

        $('#new-reservation-form').on('submit', function(e) {
            e.preventDefault();
            const payload = {
                resource_id: $('#form-resource-id').val(),
                date: $('#form-date').val(),
                start_time: $('#start-time').val(),
                end_time: $('#end-time').val(),
                summary: $('#summary').val()
            };
            const $btn = $('#submit-button').prop('disabled', true);
            $.ajax({
                url: API.create, method: 'POST', contentType: 'application/json',
                data: JSON.stringify(payload),
                success: resp => {
                    if (resp.success) { closeModals(); showResult(resp.message, false); loadWeek(currentStart); }
                    else { $('#form-error').text(resp.error).show(); $btn.prop('disabled', false); }
                },
                error: xhr => {
                    const r = xhr.responseJSON;
                    $('#form-error').text((r && r.error) || '通信エラーが発生しました。').show();
                    $btn.prop('disabled', false);
                }
            });
        });

        $('#prevWeek').on('click', function() { loadWeek($(this).data('start')); });
        $('#nextWeek').on('click', function() { loadWeek($(this).data('start')); });
        $('#modal-backdrop').on('click', closeModals);

        loadWeek();
    </script>
</body>
</html>

