<script>
// ── 状態 ────────────────────────────────
let selectedChannel = null;   // {id, name, is_member}
let currentSessionId = null;
let currentMessages  = [];
let botName          = '';    // ★v1.2 招待手順表示用

// ── ユーティリティ ───────────────────────
function showResult(msg, isError) {
    const $r = $('#result');
    $r.text(msg).removeClass('success error')
      .addClass(isError ? 'error' : 'success').show();
    setTimeout(() => $r.fadeOut(400, () => $r.hide()), 5000);
}

function statusBadge(s) {
    if (s === 'done')    return '<span class="badge badge-done">完了</span>';
    if (s === 'running') return '<span class="badge badge-run">実行中</span>';
    return '<span class="badge badge-error">エラー</span>';
}

// ── ★v1.2 ワークスペース情報 ─────────────
function loadWorkspaceInfo() {
    $.ajax({
        url: '{{ url_for("slack_minutes.api_workspace") }}',
        method: 'GET',
        success: function(resp) {
            if (!resp.success) return;
            botName = resp.bot_name || '';
            $('.bot-name').text(botName ? '@' + botName : '@<Bot名>');
            if (resp.workspaces && resp.workspaces.length) {
                const label = resp.workspaces.map(w => '「' + w + '」').join('・')
                            + ' ワークスペース';
                $('#ws-names').text(label);
                $('#ws-notice').show();
            }
        }
        // 失敗時は注意書きを出さないだけ（他機能に影響させない）
    });
}

// ── ★v1.2 Bot参加状態に応じた表示切り替え ──
function updateMemberState() {
    if (!selectedChannel) {
        $('#invite-guide').hide();
        $('#fetch-btn').prop('disabled', true);
        return;
    }
    if (selectedChannel.is_member) {
        $('#invite-guide').hide();
        $('#probe-status').text('');
        $('#fetch-btn').prop('disabled', false);
    } else {
        $('#guide-ch-name').text('#' + selectedChannel.name);
        $('#probe-status').text('');
        $('#invite-guide').show();
        $('#fetch-btn').prop('disabled', true);
    }
}

// ── ★v1.2 参加確認（probe） ──────────────
$('#probe-btn').on('click', function() {
    if (!selectedChannel) return;
    const $btn = $(this);
    $btn.html('<span class="spinner"></span>確認中…').prop('disabled', true);
    $('#probe-status').text('');
    $.ajax({
        url: '{{ url_for("slack_minutes.api_sessions") }}'
                 .replace('/sessions', `/probe/${selectedChannel.id}`),
        method: 'GET',
        success: function(resp) {
            $btn.html('✅ 参加を確認する').prop('disabled', false);
            if (!resp.success) { showResult(resp.error, true); return; }
            if (resp.is_member) {
                selectedChannel.is_member = true;
                const c = allChannels.find(c => c.id === selectedChannel.id);
                if (c) c.is_member = true;
                buildChannelList(filteredChannels());
                updateMemberState();
                showResult(`Bot の参加を確認しました：#${selectedChannel.name} から取得できます`, false);
            } else {
                $('#probe-status').text(
                    'まだ参加が確認できません。手順を実施後、再度お試しください。');
            }
        },
        error: function() {
            $btn.html('✅ 参加を確認する').prop('disabled', false);
            showResult('通信エラー', true);
        }
    });
});

// ── チャンネル一覧読み込み ────────────────
$('#load-ch-btn').on('click', function() {
    const $btn = $(this);
    $btn.html('<span class="spinner"></span>読み込み中…').prop('disabled', true);
    $.ajax({
        url: '{{ url_for("slack_minutes.api_channels") }}',
        method: 'GET',
        success: function(resp) {
            $btn.html('再読み込み').prop('disabled', false);
            if (!resp.success) { showResult(resp.error, true); return; }
            renderChannels(resp.channels);
            $('#ch-search').show();
        },
        error: function() {
            $btn.html('チャンネル一覧を読み込む').prop('disabled', false);
            showResult('通信エラー', true);
        }
    });
});

let allChannels = [];

function filteredChannels() {
    const q = ($('#ch-search').val() || '').toLowerCase();
    return q ? allChannels.filter(c => c.name.includes(q)) : allChannels;
}

function renderChannels(channels) {
    allChannels = channels;
    buildChannelList(filteredChannels());
}

function buildChannelList(channels) {
    const $list = $('#ch-list');
    if (!channels.length) {
        $list.html('<div class="empty-note" style="padding:20px">チャンネルが見つかりません</div>');
        return;
    }
    $list.empty();
    channels.forEach(ch => {
        const lock  = ch.is_private ? '<span class="lock">🔒</span>' : '';
        const badge = ch.is_member
            ? '<span class="ok">● 取得可</span>'
            : '<span class="nm">Bot未参加</span>';
        const $item = $(`<div class="ch-item" data-id="${ch.id}" data-name="${ch.name}">
            ${lock}#${ch.name}
            ${badge}
            <span class="members">${ch.num_members}人</span>
        </div>`);
        $item.on('click', function() {
            $('.ch-item').removeClass('selected');
            $(this).addClass('selected');
            selectedChannel = { id: ch.id, name: ch.name,
                                is_member: !!ch.is_member };
            updateMemberState();
        });
        // 既存選択を復元
        if (selectedChannel && selectedChannel.id === ch.id) {
            $item.addClass('selected');
        }
        $list.append($item);
    });
}

$('#ch-search').on('input', function() {
    buildChannelList(filteredChannels());
});

// ── 取得ボタン ───────────────────────────
$('#fetch-btn').on('click', function() {
    if (!selectedChannel) { showResult('チャンネルを選択してください', true); return; }
    if (!selectedChannel.is_member) {
        showResult('Bot がこのチャンネルに参加していません', true); return;
    }
    const dateVal = $('#oldest-date').val();
    let oldestTs  = null;
    if (dateVal) {
        oldestTs = String(Math.floor(new Date(dateVal).getTime() / 1000));
    }
    const $btn = $(this);
    $btn.html('<span class="spinner"></span>取得中…').prop('disabled', true);

    $.ajax({
        url: '{{ url_for("slack_minutes.api_fetch") }}',
        method: 'POST',
        contentType: 'application/json',
        data: JSON.stringify({
            channel_id:   selectedChannel.id,
            channel_name: selectedChannel.name,
            oldest_ts:    oldestTs
        }),
        success: function(resp) {
            $btn.html('取得して保存').prop('disabled', false);
            if (!resp.success) { showResult(resp.error, true); return; }
            showResult(
                `取得完了：${resp.fetched}件取得 / ${resp.saved}件新規保存 / ${resp.skipped}件スキップ`,
                false
            );
            loadSessions();
        },
        error: function() {
            $btn.html('取得して保存').prop('disabled', false);
            showResult('通信エラー', true);
        }
    });
});

// ── セッション一覧 ───────────────────────
function loadSessions() {
    $.ajax({
        url: '{{ url_for("slack_minutes.api_sessions") }}',
        method: 'GET',
        success: function(resp) {
            const $list = $('#session-list');
            if (!resp.success || !resp.sessions.length) {
                $list.html('<div class="empty-note">取得履歴がありません</div>');
                return;
            }
            $list.empty();
            resp.sessions.forEach(s => {
                const $item = $(`
                  <div class="session-item${s.id === currentSessionId ? ' active' : ''}"
                       data-sid="${s.id}">
                    <div class="si-top">
                      <span class="si-ch">#${s.channel_name}</span>
                      <span>
                        ${statusBadge(s.status)}
                        <span class="si-del" data-sid="${s.id}">削除</span>
                      </span>
                    </div>
                    <div class="si-meta">
                      ${s.fetched_at}
                      ${s.saved_count != null ? `新規${s.saved_count}件保存` : ''}
                    </div>
                  </div>`);
                $item.on('click', function(e) {
                    if ($(e.target).hasClass('si-del')) return;
                    loadMessages(s.id, s.channel_name);
                });
                $item.find('.si-del').on('click', function(e) {
                    e.stopPropagation();
                    if (!confirm(`セッション（#${s.channel_name} / ${s.fetched_at}）を削除しますか？\nメッセージも全削除されます。`)) return;
                    deleteSession(s.id);
                });
                $list.append($item);
            });
        }
    });
}

function deleteSession(sid) {
    $.ajax({
        url: '{{ url_for("slack_minutes.api_sessions") }}'.replace('/sessions', `/delete/${sid}`),
        method: 'POST',
        success: function(resp) {
            if (!resp.success) { showResult(resp.error, true); return; }
            if (currentSessionId === sid) {
                currentSessionId = null;
                $('#msg-card').hide();
            }
            loadSessions();
            showResult('削除しました', false);
        },
        error: function() { showResult('削除に失敗しました', true); }
    });
}

// ── メッセージ表示 ───────────────────────
function loadMessages(sid, chName) {
    currentSessionId = sid;
    $('.session-item').removeClass('active');
    $(`.session-item[data-sid="${sid}"]`).addClass('active');
    $('#msg-title').text(`#${chName} のメッセージ`);
    $('#msg-card').show();
    $('#msg-list').html('<div class="empty-note"><span class="spinner"></span>読み込み中…</div>');

    $.ajax({
        url: '{{ url_for("slack_minutes.api_sessions") }}'.replace('/sessions', `/messages/${sid}`),
        method: 'GET',
        success: function(resp) {
            if (!resp.success) {
                $('#msg-list').html('<div class="empty-note">取得失敗</div>');
                return;
            }
            currentMessages = resp.messages;
            renderMessages(resp.messages);
        }
    });
}

function renderMessages(msgs) {
    const $list = $('#msg-list');
    if (!msgs.length) {
        $list.html('<div class="empty-note">メッセージがありません</div>');
        return;
    }
    $list.empty();
    msgs.forEach(m => {
        const isThread = m.thread_ts && m.thread_ts !== m.slack_ts;
        const text = $('<div>').text(m.text || '').html();  // XSSエスケープ
        $list.append(`
          <div class="msg-bubble${isThread ? ' thread' : ''}">
            <div class="mb-meta">
              <span class="mb-sender">${$('<span>').text(m.sender_name || '不明').html()}</span>
              <span>${m.posted_at}</span>
              ${isThread ? '<span>↳ スレッド</span>' : ''}
            </div>
            <div class="mb-text">${text}</div>
          </div>`);
    });
}

// ── テキスト出力 ─────────────────────────
$('#export-btn').on('click', function() {
    if (!currentMessages.length) return;
    const title = $('#msg-title').text();
    let txt = `${title}\n${'='.repeat(40)}\n\n`;
    currentMessages.forEach(m => {
        const prefix = (m.thread_ts && m.thread_ts !== m.slack_ts) ? '  └ ' : '';
        txt += `${prefix}[${m.posted_at}] ${m.sender_name || '不明'}\n`;
        txt += `${prefix}${(m.text || '').replace(/\n/g, `\n${prefix}`)}\n\n`;
    });
    const blob = new Blob([txt], {type: 'text/plain;charset=utf-8'});
    const url  = URL.createObjectURL(blob);
    const a    = document.createElement('a');
    a.href     = url;
    a.download = `slack_minutes_${Date.now()}.txt`;
    a.click();
    URL.revokeObjectURL(url);
});

// ── 初期化 ──────────────────────────────
$(function() {
    loadSessions();
    loadWorkspaceInfo();   // ★v1.2

    // delete URL を動的に組み立てるための補助
    // （Jinja url_for はビルド時に固定されるため JS 側で組み替え）
    window._baseUrl = '{{ url_for("slack_minutes.api_sessions") }}';
});
</script>
</body>
</html>

