            const table = $(this).data('table');
            $('#sub-remote-db').val(db);
            $('#sub-remote-table').val(table);
            showResult(`${db}.${table} を選択しました`, false);
        });

        // 購読設定追加
        $('#add-subscription-btn').click(function() {
            const siteId = $('#sub-site-select').val();
            const remoteDb = $('#sub-remote-db').val();
            const remoteTable = $('#sub-remote-table').val();
            const localDb = $('#sub-local-db').val();
            const localTable = $('#sub-local-table').val();

            if (!siteId || !remoteDb || !remoteTable || !localDb) {
                showResult('必須項目を入力してください', true);
                return;
            }

            $('#loading').show();
            $.ajax({
                url: '{{ url_for("table_share.add_subscription") }}',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({
                    alliance_site_id: siteId,
                    remote_database: remoteDb,
                    remote_table: remoteTable,
                    local_database: localDb,
                    local_table: localTable
                }),
                success: function(resp) {
                    if (resp.success) {
                        showResult(resp.message, false);
                        loadSubscriptions();
                        // フォームクリア
                        $('#sub-remote-db, #sub-remote-table, #sub-local-table').val('');
                    } else {
                        showResult('エラー: ' + resp.error, true);
                    }
                },
                error: (xhr) => showResult('エラー: ' + xhr.responseText, true),
                complete: () => $('#loading').hide()
            });
        });

        // 購読一覧
        function loadSubscriptions() {
            $.ajax({
                url: '{{ url_for("table_share.get_subscriptions") }}',
                method: 'GET',
                success: function(resp) {
                    if (resp.success) {
                        const $tbody = $('#subscriptions-table tbody');
                        $tbody.empty();
                        if (resp.subscriptions.length === 0) {
                            $tbody.append('<tr><td colspan="6" style="text-align:center;">購読設定がありません</td></tr>');
                        } else {
                            resp.subscriptions.forEach(s => {
                                $tbody.append(`
                                    <tr id="sub-row-${s.id}">
                                        <td>${s.remote_site_name || '-'}</td>
                                        <td>${s.remote_database}.${s.remote_table}</td>
                                        <td>${s.local_database}.${s.local_table || s.remote_table}</td>
                                        <td>${s.last_synced_at || '未同期'}</td>
                                        <td>${s.last_synced_version ? 'v' + s.last_synced_version : '-'}</td>
                                        <td>
                                            <div class="action-buttons" id="action-${s.id}">
                                                <button class="success sync-btn" data-id="${s.id}">🔄 同期</button>
                                                <button class="danger delete-sub-btn" data-id="${s.id}" data-name="${s.remote_table}">✕ 解除</button>
                                            </div>
                                            <div class="sync-progress" id="progress-${s.id}" style="display:none;">
                                                <span class="progress-text"></span>
                                            </div>
                                        </td>
                                    </tr>
                                `);
                            });
                        }
                    } else {
                        showResult('購読一覧取得エラー: ' + resp.error, true);
                    }
                },
                error: function(xhr) {
                    showResult('購読一覧取得エラー: ' + xhr.responseText, true);
                }
            });
        }

        // 同期進捗表示のステージ
        const syncStages = [
            '[SYNC] 開始...',
            '[FETCH] リモート接続中...',
            '[FETCH] データ取得中...',
            '[BACKUP] バックアップ作成中...',
            '[UPDATE] テーブル更新中...',
            '[SAVE] 履歴保存中...'
        ];

        // 同期ボタンイベント（イベント委譲）
        $(document).on('click', '.sync-btn', function() {
            const $btn = $(this);

            // 既に処理中なら無視（連打防止）
            if ($btn.prop('disabled') || $btn.data('syncing')) {
                console.log('既に同期処理中です');
                return false;
            }

            const subId = $btn.data('id');
            console.log('=== 同期開始 ===');
            console.log('subscription_id:', subId);

            if (!confirm('テーブルを同期します。バックアップが自動作成されます。続行しますか？')) {
                return false;
            }

            // 処理中フラグを立てる
            $btn.data('syncing', true);
            $btn.prop('disabled', true);

            // ボタンを非表示にし、進捗表示に切り替え
            const $actionDiv = $(`#action-${subId}`);
            const $progressDiv = $(`#progress-${subId}`);
            const $progressText = $progressDiv.find('.progress-text');

            $actionDiv.hide();
            $progressDiv.show();

            // 進捗ステージを順番に表示
            let stageIndex = 0;
            $progressText.text(syncStages[stageIndex]);

            const stageInterval = setInterval(() => {
                stageIndex++;
                if (stageIndex < syncStages.length) {
                    $progressText.text(syncStages[stageIndex]);
                }
            }, 500);

            // ボタンをリセットする関数
            const resetButton = function() {
                $btn.data('syncing', false);
                $btn.prop('disabled', false);
            };

            $.ajax({
                url: '{{ url_for("table_share.sync_table") }}',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({ subscription_id: subId }),
                timeout: 120000,
                success: function(resp) {
                    clearInterval(stageInterval);
                    console.log('=== 同期成功 ===');
                    console.log('レスポンス:', resp);
                    if (resp.success) {
                        $progressText.text('✅ ' + resp.message);
                        showResult(resp.message, false);
                        overviewLoaded = false;
                        setTimeout(() => {
                            $progressDiv.hide();
                            $actionDiv.show();
                            resetButton();
                            loadSubscriptions();
                            loadSyncHistory();
                        }, 2000);
                    } else {
                        console.error('=== 同期失敗（サーバーエラー）===');
                        console.error('エラー詳細:', resp.error);
                        $progressText.text('❌ エラー: ' + resp.error);
                        alert('同期エラーの詳細:\n\n' + resp.error);
                        showResult('エラー: ' + resp.error, true);
                        setTimeout(() => {
                            $progressDiv.hide();
                            $actionDiv.show();
                            resetButton();
                        }, 5000);
                    }
                },
                error: function(xhr, status, error) {
                    clearInterval(stageInterval);
                    console.error('=== 同期失敗（ネットワーク/通信エラー）===');
                    console.error('ステータス:', status);
                    console.error('エラー:', error);
                    console.error('レスポンス:', xhr.responseText);

                    let errMsg = 'エラーが発生しました';
                    if (xhr.responseJSON && xhr.responseJSON.error) {
                        errMsg = xhr.responseJSON.error;
                    } else if (xhr.responseText) {
                        errMsg = xhr.responseText.substring(0, 200);
                    }

                    $progressText.text('❌ エラー');
                    alert('同期エラー:\n\n' + errMsg + '\n\nHTTPステータス: ' + xhr.status);
                    showResult('同期エラー: ' + errMsg, true);

                    setTimeout(() => {
                        $progressDiv.hide();
                        $actionDiv.show();
                        resetButton();
                    }, 5000);
                }
            });

            return false;  // イベント伝播を止める
        });

        // 購読解除ボタンイベント（イベント委譲）
        $(document).on('click', '.delete-sub-btn', function() {
            const subId = $(this).data('id');
            const tableName = $(this).data('name');

            if (!confirm(`「${tableName}」の購読設定を解除しますか？\n（ローカルテーブルは削除されません）`)) return;

            $('#loading').show();
            $.ajax({
                url: '{{ url_for("table_share.delete_subscription") }}',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({ subscription_id: subId }),
                success: function(resp) {
                    if (resp.success) {
                        showResult(resp.message, false);
                        loadSubscriptions();
                        loadSyncHistory();
                    } else {
                        showResult('エラー: ' + resp.error, true);
                    }
                },
                error: function(xhr) {
                    showResult('解除エラー: ' + (xhr.responseJSON?.error || xhr.responseText), true);
                },
                complete: () => $('#loading').hide()
            });
        });

        // ===========================================
        // Allianceタブ
        // ===========================================

        // 自サイトのURL表示
        $('#my-site-url').text(window.location.origin);

        // 接続確認ボタン
        $('#check-site-btn').click(function() {
            const siteUrl = $('#alliance-site-url').val().trim().replace(/\/$/, '');
            if (!siteUrl) {
                $('#check-site-result').html('<span style="color: red;">URLを入力してください</span>');
                return;
            }

            $('#check-site-result').html('<span style="color: gray;">確認中...</span>');
            $.ajax({
                url: '{{ url_for("table_share.check_site") }}',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({ site_url: siteUrl }),
                success: function(resp) {
                    if (resp.success) {
                        const info = resp.site_info;
                        $('#check-site-result').html(`<span style="color: green;">✅ FUJIN-P対応（${info.site_name}）</span>`);
                        // サイト名を自動入力
                        if (!$('#alliance-site-name').val()) {
                            $('#alliance-site-name').val(info.site_name);
                        }
                        if (info.description && !$('#alliance-description').val()) {
                            $('#alliance-description').val(info.description);
                        }
                    } else {
                        $('#check-site-result').html(`<span style="color: orange;">⚠️ ${resp.error}</span>`);
                    }
                },
                error: function() {
                    $('#check-site-result').html('<span style="color: red;">❌ 接続エラー</span>');
                }
            });
        });

        $('#add-alliance-btn').click(function() {
            const siteName = $('#alliance-site-name').val();
            const siteUrl = $('#alliance-site-url').val();
            const apiKey = $('#alliance-api-key').val();
            const desc = $('#alliance-description').val();

            if (!siteName || !siteUrl || !apiKey) {
                showResult('必須項目を入力してください', true);
                return;
            }

            $('#loading').show();
            $.ajax({
                url: '{{ url_for("table_share.add_alliance_site") }}',
                method: 'POST',
                contentType: 'application/json',
                data: JSON.stringify({
                    site_name: siteName,
                    site_url: siteUrl,
                    api_key: apiKey,
                    description: desc
                }),
                success: function(resp) {
                    if (resp.success) {
                        showResult(resp.message, false);
                        loadAllianceSites();
                        // フォームクリア
                        $('#alliance-site-name, #alliance-site-url, #alliance-api-key, #alliance-description').val('');
                        // Overview キャッシュ無効化
                        overviewLoaded = false;
                    } else {
                        showResult('エラー: ' + resp.error, true);
                    }
                },
                error: (xhr) => showResult('エラー: ' + xhr.responseText, true),
                complete: () => $('#loading').hide()
            });
        });

        // ===========================================
        // Historyタブ
        // ===========================================

        function loadSyncHistory() {
            $.ajax({
                url: '{{ url_for("table_share.get_sync_history") }}',
                method: 'GET',
                success: function(resp) {
                    if (resp.success) {
                        const $tbody = $('#history-table tbody');
                        $tbody.empty();
                        if (resp.history.length === 0) {
                            $tbody.append('<tr><td colspan="7" style="text-align:center;">同期履歴がありません</td></tr>');
                        } else {
                            resp.history.forEach(h => {
                                const statusBadge = h.status === 'success'
                                    ? '<span class="badge badge-success">成功</span>'
                                    : '<span class="badge badge-warning">失敗</span>';
                                $tbody.append(`
                                    <tr>
                                        <td>${h.synced_at}</td>
                                        <td>${h.remote_table}</td>
                                        <td>${h.local_table}</td>
                                        <td>v${h.remote_version}</td>
                                        <td>${h.row_count}行</td>
                                        <td>${h.backup_table || '-'}</td>
                                        <td>${statusBadge}</td>
                                    </tr>
                                `);
                            });
                        }
                    }
                }
            });
        }

        // ===========================================
        // 初期化
        // ===========================================
        loadOverview();          // ← Overview が初期タブなので最初に読み込む
        loadDatabases();
        loadPublishedTables();
        loadAllianceSites();
        loadSubscriptions();
        loadSyncHistory();
    });
    </script>
</body>
