</div>

<!-- ═══ タブ1: マイグレーション ═══ -->
<div id="tab-migrate" class="tab-content active">

  <div class="steps">
    <div class="step active" id="step1"><span class="step-num">1</span>取得・分析</div>
    <div class="step"        id="step2"><span class="step-num">2</span>コンフリクト解決</div>
    <div class="step"        id="step3"><span class="step-num">3</span>実行・完了</div>
  </div>

  <!-- Step1 -->
  <div id="panel-step1" class="card">
    <h3>🔍 Step 1：移行元サイトを選択してユーザ・グループを一括取得</h3>
    <div class="alert alert-info">
      <span>ℹ️</span>
      <span>ユーザとグループを一度に取得・分析します。コンフリクトを解決したら一括実行（ユーザ→グループの順）します。</span>
    </div>
    <div class="form-row">
      <div style="flex:1">
        <label>移行元サイト</label>
        <select id="sel-site" style="width:100%">
          <option value="">-- サイトを選択 --</option>
        </select>
      </div>
      <div style="display:flex; align-items:flex-end;">
        <button class="btn btn-primary" onclick="fetchAndAnalyze()" id="btn-fetch">
          取得・分析
        </button>
      </div>
    </div>

    <!-- サイト選択後に表示するリクエストボタン -->
    <div id="permission-request-area" style="display:none; margin-top:8px;">
        <div style="font-size:.8rem; color:var(--gray-600); margin-bottom:6px;">
            「リモート接続エラー: 401」になる場合など、このサイトからのエクスポート許可がまだ有効でないとき：
        </div>
        <button class="btn btn-outline btn-sm" onclick="requestFromMigrationTab(event)">
            📤 エクスポート許可をリクエスト
        </button>
        <div style="font-size:.75rem; color:var(--gray-400); margin-top:6px;">
            一覧に無いサイトへの申請は「🔐 エクスポート許可」タブからURLを直接指定してください。
        </div>
        <div id="inline-req-result" style="margin-top:8px;"></div>
    </div>


    <div id="analysis-result" style="display:none;">
      <hr style="margin:16px 0; border-color:var(--gray-100);">
      <h4 style="font-size:.875rem; font-weight:600; margin-bottom:12px;">分析結果</h4>
      <div style="display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin-bottom:8px;">
        <div style="grid-column:span 3; font-size:.8rem; font-weight:600; color:var(--gray-600);">👤 ユーザ</div>
        <div style="text-align:center; padding:12px; background:var(--gray-50); border-radius:8px;">
          <div id="cnt-remote-u" style="font-size:1.6rem; font-weight:700; color:var(--primary);">0</div>
          <div style="font-size:.75rem; color:var(--gray-600);">取得件数</div>
        </div>
        <div style="text-align:center; padding:12px; background:var(--gray-50); border-radius:8px;">
          <div id="cnt-new-u" style="font-size:1.6rem; font-weight:700; color:var(--success);">0</div>
          <div style="font-size:.75rem; color:var(--gray-600);">新規追加</div>
        </div>
        <div style="text-align:center; padding:12px; background:var(--gray-50); border-radius:8px;">
          <div id="cnt-conf-u" style="font-size:1.6rem; font-weight:700; color:var(--warning);">0</div>
          <div style="font-size:.75rem; color:var(--gray-600);">コンフリクト</div>
        </div>
      </div>
      <div style="display:grid; grid-template-columns:repeat(3,1fr); gap:12px;">
        <div style="grid-column:span 3; font-size:.8rem; font-weight:600; color:var(--gray-600);">👥 グループ</div>
        <div style="text-align:center; padding:12px; background:var(--gray-50); border-radius:8px;">
          <div id="cnt-remote-g" style="font-size:1.6rem; font-weight:700; color:var(--primary);">0</div>
          <div style="font-size:.75rem; color:var(--gray-600);">取得件数</div>
        </div>
        <div style="text-align:center; padding:12px; background:var(--gray-50); border-radius:8px;">
          <div id="cnt-new-g" style="font-size:1.6rem; font-weight:700; color:var(--success);">0</div>
          <div style="font-size:.75rem; color:var(--gray-600);">新規追加</div>
        </div>
        <div style="text-align:center; padding:12px; background:var(--gray-50); border-radius:8px;">
          <div id="cnt-conf-g" style="font-size:1.6rem; font-weight:700; color:var(--warning);">0</div>
          <div style="font-size:.75rem; color:var(--gray-600);">コンフリクト</div>
        </div>
      </div>
      <div style="margin-top:14px; text-align:right;">
        <button class="btn btn-primary" onclick="goToStep2()" id="btn-next1">
          コンフリクト解決へ →
        </button>
      </div>
    </div>
  </div>

  <!-- Step2 -->
  <div id="panel-step2" class="card" style="display:none;">
    <h3>⚡ Step 2：コンフリクト解決</h3>
    <div class="alert alert-warning">
      <span>⚠️</span>
      <div>全てのコンフリクトを解決してから実行してください。<br>
           <small>解決すると、ユーザとグループが一括で実行されます（ユーザ→グループの順）。</small></div>
    </div>
    <div id="pending-count-bar" style="font-size:.875rem; margin-bottom:14px; color:var(--gray-600);">
      未解決：<b id="cnt-pending">0</b> 件
    </div>
    <div id="conflict-list-container"></div>
    <div style="margin-top:16px; text-align:right;">
      <button class="btn btn-outline" onclick="goToStep1()" style="margin-right:8px;">← 戻る</button>
      <button class="btn btn-primary" onclick="goToStep3()" id="btn-next2" disabled>実行へ →</button>
    </div>
  </div>

  <!-- Step3 -->
  <div id="panel-step3" class="card" style="display:none;">
    <h3>✅ Step 3：マイグレーション実行</h3>
    <div id="execute-summary"></div>
    <div style="margin-top:16px; display:flex; gap:10px; justify-content:flex-end;">
      <button class="btn btn-outline" onclick="goToStep2()" id="btn-back3">← 戻る</button>
      <button class="btn btn-success" onclick="executeMigration()" id="btn-execute">
        🚀 マイグレーション実行
      </button>
    </div>
    <div id="execute-result" style="margin-top:16px;"></div>
  </div>

</div>

<!-- ═══ タブ2: アライアンスサイト ═══ -->
