@login_required
def create_note_route():
    """新規ノート作成 - 空のノートを作成して編集画面へ"""
    note_id = create_note(session['user_id'], '新規ノート', 0)
    if note_id:
        return redirect(url_for('my_md_notes.edit_note', note_id=note_id))

    flash('ノートの作成に失敗しました。', 'error')
