                        </div>
                    </div>

                    <input type="file" id="imageUpload" accept=".png,.jpg,.jpeg,.pdf,image/png,image/jpeg,application/pdf" style="display:none" onchange="uploadImage(this)">
                </form>
            </div>
        </div>

        <!-- 右ペイン: プレビュー -->
        <div class="preview-pane">
            <div class="pane-header">プレビュー</div>
            <div class="preview-content" id="preview">
                プレビューを読み込み中...
            </div>
        </div>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.9/katex.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.9/contrib/auto-render.min.js"></script>

    <script>
        let debounceTimer;

        // 共有設定の表示切り替え
        document.querySelectorAll('input[name="share_key"]').forEach(radio => {
            radio.addEventListener('change', function() {
                const userList = document.getElementById('userList');
                userList.style.display = this.value === 'shared' ? 'block' : 'none';
            });
        });

        function debouncePreview() {
            clearTimeout(debounceTimer);
            debounceTimer = setTimeout(updatePreview, 500);
        }

        function updatePreview() {
            const content = document.getElementById('content').value;

            fetch("{{ url_for('my_md_notes.preview_markdown') }}", {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({ markdown: content })
            })
            .then(response => response.json())
            .then(data => {
                document.getElementById('preview').innerHTML = data.html;

                // KaTeX レンダリング
                renderMathInElement(document.getElementById('preview'), {
                    delimiters: [
                        {left: '$$', right: '$$', display: true},
                        {left: '$', right: '$', display: false},
                        {left: '\\[', right: '\\]', display: true},
                        {left: '\\(', right: '\\)', display: false}
                    ]
                });
            })
            .catch(error => console.error('Error:', error));
        }

        function insertMarkdown(before, after = '') {
            const textarea = document.getElementById('content');
            const start = textarea.selectionStart;
            const end = textarea.selectionEnd;
            const selectedText = textarea.value.substring(start, end);
            const replacement = before + selectedText + after;

            textarea.value = textarea.value.substring(0, start) + replacement + textarea.value.substring(end);
            textarea.focus();
            textarea.setSelectionRange(start + before.length, start + before.length + selectedText.length);

            debouncePreview();
        }

        const MAX_UPLOAD_BYTES = 20 * 1024 * 1024; // 20MB

        function uploadImage(input) {
            const file = input.files[0];
            if (!file) return;

            if (file.size > MAX_UPLOAD_BYTES) {
                alert('ファイルサイズが上限（20MB）を超えています。');
                input.value = '';
                return;
            }

            const formData = new FormData();
            formData.append('file', file);

            fetch("{{ url_for('my_md_notes.upload_image') }}", {
                method: 'POST',
                body: formData
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    if (data.kind === 'pdf') {
                        insertMarkdown(`[${data.filename}](${data.url})`);
                        showStatus('PDFを添付しました');
                    } else {
                        insertMarkdown(`![画像](${data.url})`);
                        showStatus('画像をアップロードしました');
                    }
                } else {
                    alert('アップロードに失敗しました: ' + data.error);
                }
            })
            .catch(error => {
                console.error('Error:', error);
                alert('アップロードに失敗しました');
            })
            .finally(() => { input.value = ''; });
        }

        function saveContent() {
            const form = document.getElementById('noteForm');
            const formData = new FormData(form);

            fetch(form.action || window.location.href, {
                method: 'POST',
                body: formData
            })
            .then(response => {
                if (response.redirected) {
                    window.location.href = response.url;
                } else {
                    return response.text();
                }
            })
            .catch(error => {
                console.error('Error:', error);
                alert('保存に失敗しました');
            });
        }

        function showStatus(message) {
            const statusMsg = document.getElementById('statusMessage');
            statusMsg.textContent = message;
            statusMsg.classList.add('show');
            setTimeout(() => {
                statusMsg.classList.remove('show');
            }, 3000);
        }

        // 初期プレビュー
        updatePreview();
    </script>
</body>
</html>

