            color: #f6ad55;
        }

        .note-type-note {
            color: #4299e1;
        }

        .result-count {
            padding: 10px 20px;
            background-color: #edf2f7;
            border-bottom: 1px solid #e2e8f0;
            color: #4a5568;
            font-size: 0.9rem;
        }

        .result-count strong {
            color: #2d3748;
            font-size: 1rem;
        }

        .highlight {
            background-color: #fef5e7;
            padding: 2px 4px;
            border-radius: 2px;
        }
    </style>
</head>
<body>
    <div class="header-container">
        <h1>ノート検索</h1>
        <div class="header-buttons">
            <a href="{{ url_for('my_md_notes.index') }}" class="nav-button">一覧に戻る</a>
            <a href="{{ return_to }}" class="nav-button dashboard-return">メインダッシュボードに戻る</a>
        </div>
    </div>

    <div class="search-container">
        <form method="GET" action="{{ url_for('my_md_notes.search_notes') }}" class="search-form">
            <div class="form-group">
                <label for="keyword">キーワード（ノート名の部分一致）</label>
                <input type="text" id="keyword" name="keyword" value="{{ keyword }}" placeholder="例: 会議、プロジェクト、2024...">
            </div>

            <div class="form-group" style="flex: 0.6; min-width: 200px;">
                <label for="sort_by">並び順</label>
                <select id="sort_by" name="sort_by">
                    <option value="updated_desc" {% if sort_by == 'updated_desc' %}selected{% endif %}>更新日時（新しい順）</option>
                    <option value="updated_asc" {% if sort_by == 'updated_asc' %}selected{% endif %}>更新日時（古い順）</option>
                    <option value="sequence_asc" {% if sort_by == 'sequence_asc' %}selected{% endif %}>序列（昇順）</option>
                    <option value="sequence_desc" {% if sort_by == 'sequence_desc' %}selected{% endif %}>序列（降順）</option>
                </select>
            </div>

            <button type="submit" class="search-button">🔍 検索</button>
            <a href="{{ url_for('my_md_notes.search_notes') }}" class="clear-button">クリア</a>
        </form>

        {% if keyword or sort_by != 'updated_desc' %}
        <div class="search-info">
            {% if keyword %}
            <strong>検索中:</strong> 「{{ keyword }}」を含むノート
            {% else %}
            <strong>すべてのノート</strong>を表示中
            {% endif %}
            {% if sort_by == 'updated_asc' %}
            （更新日時の古い順）
            {% elif sort_by == 'sequence_asc' %}
            （序列の昇順）
            {% elif sort_by == 'sequence_desc' %}
            （序列の降順）
            {% else %}
            （更新日時の新しい順）
            {% endif %}
        </div>
        {% endif %}
    </div>

    <div class="notes-table-container">
        {% if notes %}
            <div class="result-count">
                検索結果: <strong>{{ notes|length }}</strong> 件のノートが見つかりました
            </div>
            <table class="notes-table">
                <thead>
                    <tr>
                        <th style="width: 30%;">ノート名</th>
                        {% if user_category == 'admin' %}
                        <th style="width: 10%;">オーナー</th>
                        {% endif %}
                        <th style="width: 8%;">序列</th>
                        <th style="width: 12%;">共有状態</th>
                        <th style="width: 13%;">作成日時</th>
                        <th style="width: 13%;">更新日時</th>
                        {% if user_category != 'admin' %}
                        <th style="width: 8%;">権限</th>
                        {% endif %}
                        <th style="width: 18%;">操作</th>
                    </tr>
                </thead>
                <tbody>
                    {% for note in notes %}
                    <tr>
                        <td>
                            <span class="note-icon note-type-note">📄</span>
                            <span class="note-name">
                                {%- if keyword and keyword in note.名前 -%}
                                    {%- for part in note.名前.split(keyword) -%}
                                        {%- if not loop.first %}<span class="highlight">{{ keyword }}</span>{% endif -%}
                                        {{- part -}}
                                    {%- endfor -%}
                                {%- else -%}
                                    {{ note.名前 }}
                                {%- endif -%}
                            </span>
                            <span class="note-id">(ID: {{ note.id }})</span>
                        </td>
                        {% if user_category == 'admin' %}
                        <td class="owner-cell">
                            {{ note.オーナー名 if note.オーナー名 else 'N/A' }}
                        </td>
                        {% endif %}
                        <td class="date-cell">
                            {{ note.序列 if note.序列 is not none else 0 }}
                        </td>
                        <td>
                            {% if note.共有キー == 'public' %}
                                <span class="permission-badge" style="background-color: #c6f6d5; color: #22543d;">公開</span>
                            {% elif note.共有キー == 'shared' %}
                                <span class="permission-badge" style="background-color: #bee3f8; color: #2c5282;">特定共有</span>
                            {% else %}
                                <span class="permission-badge" style="background-color: #fed7d7; color: #742a2a;">非公開</span>
                            {% endif %}
                        </td>
                        <td class="date-cell">{{ note.作成日時表示 }}</td>
                        <td class="date-cell">{{ note.更新日時表示 or '-' }}</td>
                        {% if user_category != 'admin' %}
                        <td>
                            {% if note.権限 == '所有者' or note.オーナーID == session.user_id %}
                                <span class="permission-badge permission-所有者">所有者</span>
                            {% elif note.権限 == '編集' %}
                                <span class="permission-badge permission-編集">編集</span>
                            {% elif note.権限 == '閲覧' %}
                                <span class="permission-badge permission-閲覧">閲覧</span>
                            {% else %}
                                <span class="permission-badge permission-所有者">所有者</span>
                            {% endif %}
                        </td>
                        {% endif %}
                        <td>
                            <div class="action-buttons">
                                <button class="view-btn" onclick="viewNote({{ note.id }})">閲覧</button>
                                {% if user_category == 'admin' or note.オーナーID == session.user_id or note.権限 == '編集' %}
                                <button class="edit-btn" onclick="editNote({{ note.id }})">編集</button>
                                {% endif %}
                                {% if user_category == 'admin' or note.オーナーID == session.user_id %}
                                <button class="delete-btn" data-name="{{ note.名前 }}" onclick="deleteNote({{ note.id }}, this)">削除</button>
                                {% endif %}
                            </div>
                        </td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
        {% else %}
            <div class="no-notes">
                {% if keyword %}
                    <p>「{{ keyword }}」に一致するノートが見つかりませんでした。</p>
                    <p>キーワードを変更して再度検索してください。</p>
                {% else %}
                    <p>ノートがありません。</p>
                {% endif %}
            </div>
        {% endif %}
    </div>

    <script>
        function viewNote(noteId) {
            window.location.href = "{{ url_for('my_md_notes.view_note', note_id=0) }}".replace('0', noteId);
        }
        function editNote(noteId) {
            window.location.href = "{{ url_for('my_md_notes.edit_note', note_id=0) }}".replace('0', noteId);
        }
        function deleteNote(noteId, btn) {
            const noteName = btn.dataset.name;
            if (!confirm(`ノート「${noteName}」を本当に削除しますか？\n\n※ 削除すると元に戻せません。`)) {
                return;
            }

            fetch("{{ url_for('my_md_notes.delete_note', note_id=0) }}".replace('0', noteId), {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                }
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    alert(data.message);
                    location.reload();
                } else {
                    alert('削除エラー: ' + data.error);
                }
            })
            .catch(error => {
                console.error('Error:', error);
                alert('削除処理中にエラーが発生しました。');
            });
        }
    </script>
</body>
</html>

