        .copy-btn:hover {
            background-color: #ed8936;
            color: white;
        }

        .view-btn {
            background-color: #4299e1;
            color: white;
        }

        .view-btn:hover {
            background-color: #3182ce;
        }

        .back-btn {
            background-color: #718096;
            color: white;
        }

        .back-btn:hover {
            background-color: #4a5568;
        }

        .content-container {
            max-width: 1400px;
            margin: 30px auto;
            padding: 0 20px;
        }

        .info-bar {
            background-color: #fef5e7;
            border-left: 4px solid #f6ad55;
            padding: 15px 20px;
            border-radius: 8px;
            margin-bottom: 20px;
            color: #744210;
        }

        .info-bar strong {
            color: #744210;
