        }

        .source-header {
            background-color: #2d3748;
            color: white;
            padding: 12px 20px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .source-header h2 {
            margin: 0;
            font-size: 1rem;
            font-weight: 500;
        }

        .source-stats {
            font-size: 0.85rem;
            color: #a0aec0;
        }

        .source-content {
            position: relative;
        }

        .source-code {
            margin: 0;
            padding: 20px;
            background-color: #1e1e1e;
