        }

        @keyframes slideIn {
            from {
                transform: translateX(100%);
                opacity: 0;
            }
            to {
                transform: translateX(0);
                opacity: 1;
            }
        }

        /* レスポンシブ */
        @media (max-width: 768px) {
            .top-bar-content {
                flex-direction: column;
                align-items: stretch;
            }

            .top-bar-buttons {
                justify-content: stretch;
            }

            .top-bar button, .top-bar a {
