<body>
    <div class="top-bar">
        <div class="top-bar-content">
            <h1>{{ note.名前 }} - Markdownソース</h1>
            <div class="top-bar-buttons">
                <button class="copy-btn" onclick="copySource()">📋 ソースをコピー</button>
                <a href="{{ url_for('my_md_notes.view_note', note_id=note.id) }}" class="view-btn">👁️ レンダリング表示</a>
                <a href="{{ url_for('my_md_notes.index') }}" class="back-btn">一覧に戻る</a>
            </div>
        </div>
    </div>

    <div class="copy-success" id="copySuccess">✓ ソースコードをクリップボードにコピーしました！</div>

    <div class="content-container">
        <!-- 情報バー -->
        <div class="info-bar">
            <strong>💡 Markdownソースコード閲覧</strong><br>
            このページではノートの生のMarkdownソースコードを確認できます。
            Markdownの学習や、安全性の確認にご利用ください。
        </div>

        <!-- メタ情報 -->
        <div class="meta-info">
            <div class="meta-info-item">
                <strong>ID:</strong>
                <span>{{ note.id }}</span>
            </div>
            <div class="meta-info-item">
                <strong>作成:</strong>
                <span>{{ note.作成日時表示 }}</span>
            </div>
            {% if note.更新日時表示 %}
            <div class="meta-info-item">
                <strong>更新:</strong>
                <span>{{ note.更新日時表示 }}</span>
            </div>
            {% endif %}
        </div>

        <!-- ソースコード -->
        <div class="source-container">
            <div class="source-header">
                <h2>📄 Markdownソースコード</h2>
                <div class="source-stats">
                    {% if note.内容 %}
                    {{ note.内容|length }} 文字 / {{ note.内容.count('\n') + 1 }} 行
                    {% else %}
                    0 文字 / 0 行
                    {% endif %}
                </div>
            </div>
            <div class="source-content">
                {% if note.内容 %}
                <div class="line-numbers" id="lineNumbers"></div>
                <pre class="source-code source-code-content" id="sourceCode">{{ note.内容 }}</pre>
                {% else %}
                <div class="empty-note">
                    <p>📝 このノートは空です</p>
                    <p>編集画面からコンテンツを追加してください。</p>
                </div>
                {% endif %}
            </div>
        </div>
    </div>

    <script>
        // 行番号を生成
        function generateLineNumbers() {
            const sourceCode = document.getElementById('sourceCode');
            const lineNumbersDiv = document.getElementById('lineNumbers');

            if (!sourceCode || !lineNumbersDiv) return;

            const content = sourceCode.textContent || '';
            const lines = content.split('\n');
            const lineCount = lines.length;

            let html = '';
            for (let i = 1; i <= lineCount; i++) {
                html += `<span>${i}</span>`;
            }
            lineNumbersDiv.innerHTML = html;
        }

        // ソースコードをコピー
        function copySource() {
            const sourceCode = document.getElementById('sourceCode');
            if (!sourceCode) return;

            const text = sourceCode.textContent;

            navigator.clipboard.writeText(text).then(function() {
                showCopySuccess();
            }, function() {
                // フォールバック
                const textArea = document.createElement('textarea');
                textArea.value = text;
                textArea.style.position = 'fixed';
                textArea.style.left = '-999999px';
                document.body.appendChild(textArea);
                textArea.select();
                try {
                    document.execCommand('copy');
                    showCopySuccess();
                } catch (err) {
                    alert('コピーに失敗しました: ' + err);
                }
                document.body.removeChild(textArea);
            });
        }

        function showCopySuccess() {
            const successMsg = document.getElementById('copySuccess');
            successMsg.classList.add('show');
            setTimeout(() => {
                successMsg.classList.remove('show');
            }, 3000);
        }

        // ページ読み込み時に行番号を生成
        document.addEventListener('DOMContentLoaded', function() {
            generateLineNumbers();
        });
    </script>
</body>
</html>

