<body>
    <div class="top-bar">
        <div class="top-bar-content">
            <h1>{{ note.名前 }}</h1>
            <div class="top-bar-buttons">
                {% if session.user_category == 'admin' or note.オーナーID == session.user_id or note.権限 == '編集' %}
                <a href="{{ url_for('my_md_notes.edit_note', note_id=note.id) }}" class="edit-btn">編集</a>
                {% endif %}
                <button class="source-btn" onclick="showSourceModal()">ソース</button>
                <a href="{{ url_for('my_md_notes.index') }}" class="back-btn">一覧に戻る</a>
            </div>
        </div>
    </div>

    <div class="content-container">
        <!-- フラッシュメッセージ -->
        {% with messages = get_flashed_messages(with_categories=true) %}
          {% if messages %}
            {% for category, message in messages %}
              <div class="alert alert-{{ category }}">
                {{ message }}
              </div>
            {% endfor %}
          {% endif %}
        {% endwith %}

        <!-- メタ情報 -->
        <div class="meta-info">
            <div class="meta-info-item">
                <strong>ID:</strong>
                <span>{{ note.id }}</span>
            </div>
            <div class="meta-info-item">
                <strong>作成:</strong>
                <span>{{ note.作成日時表示 }}</span>
            </div>
            {% if note.更新日時表示 %}
            <div class="meta-info-item">
                <strong>更新:</strong>
                <span>{{ note.更新日時表示 }}</span>
            </div>
            {% endif %}
            <div class="meta-info-item">
                <strong>共有設定:</strong>
                <span>
                    {%- if note.共有キー == 'public' -%}公開
                    {%- elif note.共有キー == 'shared' -%}特定のユーザーと共有
                    {%- else -%}非公開{%- endif -%}
                </span>
            </div>
        </div>

        {% if public_url %}
        <!-- 公開URL表示 -->
        <div class="meta-info" style="background-color: #f0fff4; border-left: 4px solid #48bb78;">
            <div style="flex: 1;">
                <strong>🌐 公開URL:</strong>
                <div style="margin-top: 8px;">
                    <code id="publicUrlText" style="background-color: white; padding: 8px 12px; border-radius: 4px; display: inline-block; font-size: 0.85rem;">{{ public_url }}</code>
                    <br><small style="color: #718096; margin-top: 5px; display: block;">ログイン不要で閲覧できます。IDは連番のため推測可能です。</small>
                </div>
            </div>
            <button onclick="copyPublicUrl()" style="background-color: #48bb78; color: white; padding: 8px 16px; border: none; border-radius: 4px; cursor: pointer;">
                📋 URLをコピー
            </button>
        </div>
        {% endif %}

        <!-- コンテンツ -->
        <div class="content-area">
            {{ html_content|safe }}
        </div>
    </div>

    <!-- コピー成功トースト -->
    <div class="copy-success-toast" id="copySuccessToast">
        ✓ ソースコードをクリップボードにコピーしました！
    </div>

    <!-- Markdownソースモーダル -->
    <div id="sourceModal" class="modal">
        <div class="modal-content">
            <div class="modal-header">
                <h2>📄 Markdownソース - {{ note.名前 }}</h2>
                <div class="modal-buttons">
                    <button class="modal-btn copy-modal-btn" onclick="copySourceCode()">📋 コピー</button>
                    <button class="modal-btn close-modal-btn" onclick="closeSourceModal()">✕ 閉じる</button>
                </div>
            </div>
            <div class="modal-body">
                <div class="modal-info">
                    💡 このページではノートの生のMarkdownソースコードを確認できます。Markdownの学習や、安全性の確認にご利用ください。
                </div>
                <div class="source-container">
                    <div class="source-stats">
                        {% if note.内容 %}
                        📊 {{ note.内容|length }} 文字 / {{ note.内容.count('\n') + 1 }} 行
                        {% else %}
                        📊 0 文字 / 0 行
                        {% endif %}
                    </div>
                    <div class="source-code-wrapper">
                        <pre class="source-code" id="sourceCodeContent">{{ note.内容 if note.内容 else '(空のノートです)' }}</pre>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.9/katex.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/KaTeX/0.16.9/contrib/auto-render.min.js"></script>
    <script>
        // KaTeX数式レンダリング
        document.addEventListener("DOMContentLoaded", function() {
            renderMathInElement(document.querySelector('.content-area'), {
                delimiters: [
                    {left: '$$', right: '$$', display: true},
                    {left: '$', right: '$', display: false},
                    {left: '\\[', right: '\\]', display: true},
                    {left: '\\(', right: '\\)', display: false}
                ],
                throwOnError: false
            });
        });

        // 公開URLをコピー
        function copyPublicUrl() {
            const el = document.getElementById('publicUrlText');
            const url = el ? el.textContent.trim() : '';

            if (url) {
                navigator.clipboard.writeText(url).then(function() {
                    alert('公開URLをクリップボードにコピーしました！\n\n' + url);
                }, function() {
                    // フォールバック
                    const textArea = document.createElement('textarea');
                    textArea.value = url;
                    document.body.appendChild(textArea);
                    textArea.select();
                    document.execCommand('copy');
                    document.body.removeChild(textArea);
                    alert('公開URLをコピーしました！\n\n' + url);
                });
            }
        }

        // モーダルの表示
        function showSourceModal() {
            document.getElementById('sourceModal').classList.add('show');
            document.body.style.overflow = 'hidden'; // 背景のスクロールを防ぐ
        }

        // モーダルを閉じる
        function closeSourceModal() {
            document.getElementById('sourceModal').classList.remove('show');
            document.body.style.overflow = 'auto'; // スクロールを再開
        }

        // モーダル外をクリックで閉じる
        window.onclick = function(event) {
            const modal = document.getElementById('sourceModal');
            if (event.target === modal) {
                closeSourceModal();
            }
        }

        // ESCキーでモーダルを閉じる
        document.addEventListener('keydown', function(event) {
            if (event.key === 'Escape') {
                closeSourceModal();
            }
        });

        // ソースコードをコピー
        function copySourceCode() {
            const sourceCode = document.getElementById('sourceCodeContent');
            const text = sourceCode.textContent;
            
            if (navigator.clipboard) {
                navigator.clipboard.writeText(text).then(function() {
                    showCopySuccess();
                }).catch(function(err) {
                    fallbackCopy(text);
                });
            } else {
                fallbackCopy(text);
            }
        }

        // フォールバックコピー（古いブラウザ用）
        function fallbackCopy(text) {
            const textArea = document.createElement('textarea');
            textArea.value = text;
            textArea.style.position = 'fixed';
            textArea.style.left = '-999999px';
            document.body.appendChild(textArea);
            textArea.select();
            try {
                document.execCommand('copy');
                showCopySuccess();
            } catch (err) {
                alert('コピーに失敗しました: ' + err);
            }
            document.body.removeChild(textArea);
        }

        // コピー成功メッセージを表示
        function showCopySuccess() {
            const toast = document.getElementById('copySuccessToast');
            toast.classList.add('show');
            setTimeout(function() {
                toast.classList.remove('show');
            }, 3000);
        }
    </script>
