                    <div class="btn-group me-2" role="group">
                        <button type="button" class="btn btn-outline-info" onclick="insertTemplate('basic')">
                            <i class="fas fa-file-medical"></i> 基本テンプレート
                        </button>
                        <button type="button" class="btn btn-outline-info" onclick="insertTemplate('workflow')">
                            <i class="fas fa-project-diagram"></i> ワークフロー
                        </button>
                    </div>
                </div>

                <!-- 隠し要素：ファイル入力 -->
                <input type="file" id="imageInput" accept="image/*" style="display: none;">
            </div>
        </div>

        <!-- エディタとプレビュー -->
        <div class="row editor-container">
            <div class="col-md-6">
                <div class="h-100">
                    <label for="editor" class="form-label fw-bold">Composer (Markdown)</label>
                    <textarea class="form-control font-monospace" id="editor"
                              placeholder="プロジェクトの統合方法とメタ情報をMarkdownで記述してください...">{{ project.Composer or '' }}</textarea>
                </div>
            </div>
            <div class="col-md-6">
                <div class="h-100">
                    <label class="form-label fw-bold">プレビュー</label>
