    <!-- メッセージ表示用コンテナ -->
    <div id="messageContainer" class="fixed-top mt-3 mx-3"></div>

    <!-- Bootstrap JavaScript -->
    <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/js/bootstrap.bundle.min.js"></script>

    <script src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/katex.min.js"></script>
    <script src="https://cdn.jsdelivr.net/npm/katex@0.16.9/dist/contrib/auto-render.min.js"></script>

    <script src="https://cdn.jsdelivr.net/npm/mermaid@10.9.0/dist/mermaid.min.js"></script>


    <script>
        // テンプレート定義
        const templates = {
            basic: `# {{ project.プロジェクト名 }} - 統合指示書

## プロジェクト概要
- **目的**: [プロジェクトの目的を記述]
- **期間**: [開始日] ～ [終了日]
- **成果物**: [最終的な成果物の形式]

## タスク統合方法

### 1. データ収集・整理フェーズ
- [ ] 各作業者からの成果物確認
- [ ] データ形式の統一
- [ ] 品質チェック

### 2. 統合・編集フェーズ
- [ ] データの組み合わせ
- [ ] 全体構成の調整
- [ ] 最終レビュー

## 品質基準
1. [基準1を記述]
2. [基準2を記述]
3. [基準3を記述]

## 参考資料・注意点
- [関連資料のリンクや参考情報]
- [特別な注意点や制約事項]

---
*最終更新: {{ current_date }}*`,

            workflow: `# ワークフロー図

## 作業フロー

\`\`\`mermaid
graph TD
    A[プロジェクト開始] --> B[タスク分割・アサイン]
    B --> C[各作業者が作業実行]
    C --> D{品質チェック}
    D -->|OK| E[統合作業]
    D -->|NG| F[修正指示]
    F --> C
    E --> G[最終レビュー]
    G --> H[完了]
\`\`\`

## データフロー

\`\`\`mermaid
flowchart LR
    A[原データ] --> B[作業者1]
    A --> C[作業者2]
    A --> D[作業者3]
    B --> E[統合処理]
    C --> E
    D --> E
    E --> F[最終成果物]
\`\`\`

## チェックポイント
| フェーズ | チェック項目 | 責任者 |
|----------|-------------|--------|
| データ収集 | 完全性確認 | 責任者 |
| 統合処理 | 整合性確認 | 責任者 |
| 最終確認 | 品質確認 | 全員 |`
        };

        class ComposerEditor {
            constructor() {
                this.projectId = {{ project.id }};
                this.editor = document.getElementById('editor');
                this.preview = document.getElementById('preview');
                this.saveBtn = document.getElementById('saveBtn');
                this.cancelBtn = document.getElementById('cancelBtn');
                this.previewBtn = document.getElementById('previewBtn');
                this.uploadBtn = document.getElementById('uploadBtn');
                this.imageInput = document.getElementById('imageInput');

                this.setupEventListeners();
                // this.updatePreview();
            }

            setupEventListeners() {
                // 保存ボタン
                this.saveBtn.addEventListener('click', () => this.saveComposer());

                // キャンセルボタン
                this.cancelBtn.addEventListener('click', () => this.cancelEdit());

                // プレビューボタン
                this.previewBtn.addEventListener('click', () => this.updatePreview());

                // 画像アップロードボタン
                this.uploadBtn.addEventListener('click', () => this.imageInput.click());

                // 画像選択時
                this.imageInput.addEventListener('change', (e) => this.handleImageUpload(e));

                // 削除または以下のようにコメントアウト
                // // リアルタイムプレビュー（入力時）
                // this.editor.addEventListener('input', () => {
                //     clearTimeout(this.previewTimeout);
                //     this.previewTimeout = setTimeout(() => this.updatePreview(), 500);
                // });

                // Ctrl+S でも保存
                document.addEventListener('keydown', (e) => {
                    if (e.ctrlKey && e.key === 's') {
                        e.preventDefault();
                        this.saveComposer();
                    }
                });

                // ESCキーでキャンセル
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') {
                        e.preventDefault();
                        this.cancelEdit();
                    }
                });
            }

            async saveComposer() {
                const content = this.editor.value.trim();

                try {
                    this.saveBtn.disabled = true;
                    this.saveBtn.textContent = '保存中...';

                    const response = await fetch(`/colrep/save_composer_external/${this.projectId}`, {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json',
                        },
                        body: JSON.stringify({
                            composer: content
                        })
                    });

                    const result = await response.json();

                    if (result.success) {
                        this.showMessage('Composerを保存しました。', 'success');

                        // 親ウィンドウにコールバック
                        if (window.opener && window.opener.composerCallback) {
                            window.opener.composerCallback({ success: true });
                        }

                        // 少し待ってからウィンドウを閉じる
                        setTimeout(() => {
                            window.close();
                        }, 1000);

                    } else {
                        this.showMessage(result.error || '保存に失敗しました', 'error');
                        if (window.opener && window.opener.composerCallback) {
                            window.opener.composerCallback({ success: false, error: result.error });
                        }
                    }

                } catch (error) {
                    console.error('Save error:', error);
                    this.showMessage('保存に失敗しました', 'error');
                    if (window.opener && window.opener.composerCallback) {
                        window.opener.composerCallback({ success: false, error: error.message });
                    }
                } finally {
                    this.saveBtn.disabled = false;
                    this.saveBtn.innerHTML = '<i class="fas fa-save"></i> 保存して閉じる';
                }
            }

            cancelEdit() {
                if (confirm('編集内容を破棄してもよろしいですか？')) {
                    // 親ウィンドウにコールバック
                    if (window.opener && window.opener.composerCallback) {
                        window.opener.composerCallback({ aborted: true });
                    }
                    window.close();
                }
            }

            async updatePreview() {
                const markdown = this.editor.value;

                if (!markdown) {
                    this.preview.innerHTML = '<p class="text-muted">プレビューがここに表示されます</p>';
                    return;
                }

                try {
                    const response = await fetch('/colrep/preview_composer', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({
                            markdown: markdown,
                            project_id: this.projectId
                        })
                    });
                    const result = await response.json();

                    if (result.html) {
                        this.preview.innerHTML = result.html;
                        // Mermaidとmath処理
                        if (window.mermaid) {
                            mermaid.run({ nodes: this.preview.querySelectorAll('.mermaid') });
                        }
                        if (window.renderMathInElement) {
                            renderMathInElement(this.preview, {
                                delimiters: [
                                    {left: '$$', right: '$$', display: true},
                                    {left: '$', right: '$', display: false}
                                ]
                            });
                        }

                    } else {
                        this.preview.innerHTML = '<p class="text-danger">プレビューの生成に失敗しました</p>';
                    }

                } catch (error) {
                    console.error('Preview error:', error);
                    this.preview.innerHTML = '<p class="text-danger">プレビューの生成に失敗しました</p>';
                }
            }

            async handleImageUpload(event) {
                const file = event.target.files[0];
                if (!file) return;

                // ファイルサイズチェック（5MB制限）
                if (file.size > 10 * 1024 * 1024) {
                    this.showMessage('ファイルサイズは10MB以下にしてください', 'error');
                    return;
                }

                // 画像ファイルかチェック
                if (!file.type.startsWith('image/')) {
                    this.showMessage('画像ファイルを選択してください', 'error');
                    return;
                }

                try {
                    this.uploadBtn.disabled = true;
                    this.uploadBtn.textContent = 'アップロード中...';

                    const formData = new FormData();
                    formData.append('file', file);

                    const response = await fetch('/colrep/upload_image', {
                        method: 'POST',
                        body: formData
                    });

                    const result = await response.json();

                    if (result.success) {
                        // エディタに画像マークダウンを挿入
                        const imageMarkdown = `![${result.filename}](${result.url})`;
                        this.insertTextAtCursor(imageMarkdown);
                        this.showMessage('画像がアップロードされました', 'success');
                        this.updatePreview();
                    } else {
                        this.showMessage(result.error || 'アップロードに失敗しました', 'error');
                    }

                } catch (error) {
                    console.error('Upload error:', error);
                    this.showMessage('アップロードに失敗しました', 'error');
                } finally {
                    this.uploadBtn.disabled = false;
                    this.uploadBtn.innerHTML = '<i class="fas fa-image"></i> 画像アップロード';
                    // input要素をクリア
                    this.imageInput.value = '';
                }
            }

            insertTextAtCursor(text) {
                const start = this.editor.selectionStart;
                const end = this.editor.selectionEnd;
                const value = this.editor.value;

                this.editor.value = value.substring(0, start) + text + value.substring(end);
                this.editor.selectionStart = this.editor.selectionEnd = start + text.length;
                this.editor.focus();
            }

            showMessage(message, type = 'info') {
                let messageContainer = document.getElementById('messageContainer');
                if (!messageContainer) {
                    messageContainer = document.createElement('div');
                    messageContainer.id = 'messageContainer';
                    messageContainer.className = 'fixed-top mt-3 mx-3';
                    document.body.appendChild(messageContainer);
                }

                const alertDiv = document.createElement('div');
                alertDiv.className = `alert alert-${type === 'error' ? 'danger' : type === 'success' ? 'success' : 'info'} alert-dismissible fade show`;
                alertDiv.innerHTML = `
                    ${message}
                    <button type="button" class="btn-close" data-bs-dismiss="alert"></button>
                `;

                messageContainer.appendChild(alertDiv);

                // 3秒後に自動削除
                setTimeout(() => {
                    if (alertDiv.parentNode) {
                        alertDiv.remove();
                    }
                }, 3000);
            }
        }

        // グローバル関数: テンプレート挿入
        function insertTemplate(templateType) {
            const editor = document.getElementById('editor');
            const template = templates[templateType];

            if (template) {
                // カーソル位置にテンプレートを挿入
                const start = editor.selectionStart;
                const end = editor.selectionEnd;
                const value = editor.value;

                const newValue = value.substring(0, start) + template + value.substring(end);
                editor.value = newValue;
                editor.selectionStart = editor.selectionEnd = start + template.length;
                editor.focus();

                // プレビュー更新
                if (window.composerEditor) {
                    window.composerEditor.updatePreview();
                }
            }
        }

        // mermaid初期化
        if (window.mermaid) {
            mermaid.initialize({ startOnLoad: true });
        }

        // DOM読み込み完了後に初期化
        document.addEventListener('DOMContentLoaded', () => {
            window.composerEditor = new ComposerEditor();
        });
    </script>
</body>
</html>

