                <i data-lucide="file-text" class="h-6 w-6"></i>
                <span class="text-xl font-semibold">CoRePo</span>
            </a>
            <a href="{{ url_for('colrep.return_to_fujin') }}" class="bg-red-500 hover:bg-red-600 text-white text-sm px-4 py-2 rounded shadow transition-colors flex items-center">
