<!DOCTYPE html>
<html lang="ja">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CoRePo - Collaborative RePort composer</title>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.0/font/bootstrap-icons.css">
    <style>
        .btn-return {
            padding: 8px 14px;
            background: #e74c3c;
            color: #fff;
            border: none;
            border-radius: 6px;
            cursor: pointer;
            text-decoration: none;
            font-size: 0.85rem;
            font-weight: 600;
            white-space: nowrap;
            box-shadow: 0 1px 3px rgba(0,0,0,.2);
            transition: 0.2s;
            display: inline-flex;
            align-items: center;
            gap: 6px;
        }
        .btn-return:hover {
            background: #c0392b;
            color: #fff;
        }
    </style>
</head>
<body>
<div class="container mt-4">
    <!-- ヘッダー部分 -->
    <div class="mb-4 d-flex justify-content-between align-items-start">
        <div>
            <h1><i class="bi bi-globe"></i> 公開プロジェクト一覧</h1>
            <p class="text-muted mb-0">CoRePo - 公開されているプロジェクトを閲覧できます</p>
        </div>
        <a href="{{ url_for('colrep_public.return_to_fujin') }}" class="btn-return">🏠 FUJIN-Pダッシュボードに戻る</a>
    </div>

    <!-- プロジェクト一覧 -->
    <div id="projects-container">
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">読み込み中...</span>
            </div>
        </div>
    </div>
</div>

<!-- プレビューモーダル -->
<div class="modal fade" id="previewModal" tabindex="-1">
    <div class="modal-dialog modal-xl">
        <div class="modal-content">
            <div class="modal-header">
                <h5 class="modal-title">統合プレビュー</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
            </div>
            <div class="modal-body" id="previewContent">
                <div class="text-center py-4">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">読み込み中...</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', function() {
    loadPublicProjects();
});

function loadPublicProjects() {
    fetch('/colrep_public/api/projects')
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                renderProjects(data.projects);
            } else {
                showError('プロジェクト一覧の取得に失敗しました');
            }
        })
        .catch(error => {
            console.error('Error:', error);
            showError('エラーが発生しました');
        });
}

function renderProjects(projects) {
    const container = document.getElementById('projects-container');

    if (projects.length === 0) {
        container.innerHTML = `
            <div class="row">
                <div class="col-md-8 mx-auto">
                    <div class="card">
                        <div class="card-body text-center py-5">
                            <i class="bi bi-folder-x" style="font-size: 3rem; color: #6c757d;"></i>
                            <h4 class="mt-3 text-muted">公開プロジェクトがありません</h4>
                            <p class="text-muted">現在、公開されているプロジェクトはありません。</p>
                        </div>
                    </div>
                </div>
            </div>
        `;
        return;
    }

    let html = `
        <div class="card">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0"><i class="bi bi-list"></i> 公開プロジェクト一覧</h5>
                <small class="text-muted">${projects.length} 件</small>
            </div>
            <div class="card-body p-0">
                <div class="table-responsive">
                    <table class="table table-hover mb-0">
                        <thead class="table-light">
                            <tr>
                                <th style="width: 8%;">ID</th>
                                <th style="width: 35%;">プロジェクト名</th>
                                <th style="width: 20%;">責任者</th>
                                <th style="width: 15%;">更新日時</th>
                                <th style="width: 22%;">操作</th>
                            </tr>
                        </thead>
                        <tbody>
    `;

    projects.forEach(project => {
        const updatedDate = formatDate(project['更新日時']);
        html += `
            <tr>
                <td>
                    <span class="badge bg-info">#${project.id}</span>
                </td>
                <td>
                    <strong>${escapeHtml(project['プロジェクト名'])}</strong>
                </td>
                <td>
                    ${project['責任者名'] ? `<i class="bi bi-person"></i> ${escapeHtml(project['責任者名'])}` : '<span class="text-muted">未設定</span>'}
                </td>
                <td>
                    <small>${updatedDate}</small>
                </td>
                <td>
                    <div class="btn-group btn-group-sm">
                        <button class="btn btn-outline-info btn-sm"
                                onclick="showPreview(${project.id})"
                                title="統合プレビュー">
                            <i class="bi bi-eye"></i> プレビュー
                        </button>
                        <a href="/colrep_public/${project.id}/detail"
                           class="btn btn-outline-primary btn-sm"
                           title="詳細を表示">
                            <i class="bi bi-file-text"></i> 詳細
                        </a>
                    </div>
                </td>
            </tr>
        `;
    });

    html += `
                        </tbody>
                    </table>
                </div>
            </div>
        </div>
    `;

    container.innerHTML = html;
}

function showPreview(projectId) {
    const uniqueWindowId = 'preview_' + Date.now() + '_' + projectId;

    fetch(`/colrep_public/${projectId}/preview`)
        .then(response => {
            if (!response.ok) {
                throw new Error('プレビューの取得に失敗しました');
            }
            return response.text();
        })
        .then(htmlContent => {
            const newWindow = window.open('', uniqueWindowId, 'width=1200,height=900,scrollbars=yes');
            newWindow.document.write(htmlContent);
            newWindow.document.close();
        })
        .catch(error => {
            console.error('Error:', error);
            alert('プレビューの取得に失敗しました: ' + error.message);
        });
}

function formatDate(dateString) {
    if (!dateString) return '-';
    const date = new Date(dateString);
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${month}/${day} ${hours}:${minutes}`;
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function showError(message) {
    const container = document.getElementById('projects-container');
    container.innerHTML = `
        <div class="alert alert-danger" role="alert">
            <i class="bi bi-exclamation-triangle"></i> ${message}
        </div>
    `;
}
</script>

<style>
.table-hover tbody tr:hover {
    background-color: #f8f9fa;
}
</style>
</body>
</html>

