<!DOCTYPE html>
<html lang="ja">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CoRePo - Collaborative RePort composer</title>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.0/font/bootstrap-icons.css">
</head>
<body>

<style>
pre {
    margin: 0;
    background-color: #f5f5f5;
    border: 1px solid #ddd;
    border-radius: 4px;
    padding: 15px;
    overflow: auto;
}

code {
    background-color: transparent;
    color: inherit;
    padding: 0;
}

/* ダークモード対応 */
@media (prefers-color-scheme: dark) {
    pre {
        background-color: #2d2d2d;
        color: #f8f8f2;
        border-color: #444;
    }
}
</style>

<div class="container mt-4">
    <!-- ヘッダー部分 -->
    <div class="d-flex justify-content-between align-items-start mb-4">
        <div>
            <h1><i class="bi bi-file-text"></i> {{ project.プロジェクト名 }}</h1>
            <p class="text-muted">
                <i class="bi bi-person"></i> 責任者:
                {% if project.責任者名 %}
                    {{ project.責任者名 }}
                {% else %}
                    未設定
                {% endif %}
            </p>
            <p class="text-muted">
                <i class="bi bi-clock"></i> 更新日時: {{ project.更新日時.strftime('%Y年%m月%d日 %H:%M') }}
            </p>
        </div>
        <a href="/colrep_public/" class="btn btn-secondary">
            <i class="bi bi-arrow-left"></i> 一覧に戻る
        </a>
    </div>

    <!-- ✅ 修正：Composerセクション（ソースコードのみ） -->
    <div class="card mb-4">
        <div class="card-header">
            <h5 class="mb-0"><i class="bi bi-book"></i> 統合指示書（Composer）</h5>
        </div>
        <div class="card-body" id="composerContent">
            <div class="text-center py-4">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">読み込み中...</span>
                </div>
            </div>
        </div>
    </div>

    <!-- 部品一覧 -->
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0"><i class="bi bi-list-task"></i> 部品一覧</h5>
        </div>
        <div class="card-body p-0">
            <div id="componentsContainer">
                <div class="text-center py-4">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">読み込み中...</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- コンポーネント詳細モーダル -->
<div class="modal fade" id="componentModal" tabindex="-1">
    <div class="modal-dialog modal-xl">
        <div class="modal-content">
            <div class="modal-header">
                <h5 class="modal-title" id="componentTitle">部品詳細</h5>
                <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
            </div>
            <div class="modal-body" id="componentContent">
                <div class="text-center py-4">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">読み込み中...</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<script>
const projectId = {{ project.id }};

document.addEventListener('DOMContentLoaded', function() {
    loadComposerInfo();
    loadComponents();
});

// ✅ 修正：Composerのソースコードのみ表示
function loadComposerInfo() {
    fetch(`/colrep_public/${projectId}/api/composer`)
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                const container = document.getElementById('composerContent');
                if (data.composer_md) {
                    container.innerHTML = `
                        <h6>マークダウンソース</h6>
                        <pre style="max-height: 400px; overflow-y: auto; background: #f5f5f5; padding: 15px; border-radius: 4px; font-size: 0.85rem; white-space: pre-wrap; word-wrap: break-word; font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Courier New', monospace;"><code>${escapeHtml(data.composer_md)}</code></pre>
                    `;
                } else {
                    container.innerHTML = `<p class="text-muted">Composerがまだ作成されていません</p>`;
                }
            } else {
                showComposerError('Composerの取得に失敗しました');
            }
        })
        .catch(error => {
            console.error('Error:', error);
            showComposerError('エラーが発生しました');
        });
}

function showComposerError(message) {
    const container = document.getElementById('composerContent');
    container.innerHTML = `<p class="text-danger"><i class="bi bi-exclamation-triangle"></i> ${message}</p>`;
}

function loadComponents() {
    fetch(`/colrep_public/${projectId}/api/components`)
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                renderComponents(data.components);
            } else {
                showComponentsError('部品一覧の取得に失敗しました');
            }
        })
        .catch(error => {
            console.error('Error:', error);
            showComponentsError('エラーが発生しました');
        });
}

function renderComponents(components) {
    const container = document.getElementById('componentsContainer');

    if (components.length === 0) {
        container.innerHTML = `
            <div class="alert alert-info" role="alert">
                <i class="bi bi-info-circle"></i> 部品がまだ追加されていません
            </div>
        `;
        return;
    }

    let html = `
        <div class="table-responsive">
            <table class="table table-hover mb-0">
                <thead class="table-light">
                    <tr>
                        <th style="width: 6%;">ID</th>
                        <th style="width: 20%;">カラム名</th>
                        <th style="width: 25%;">説明</th>
                        <th style="width: 10%;">ステータス</th>
                        <th style="width: 15%;">担当者</th>
                        <th style="width: 10%;">コンテンツ</th>
                        <th style="width: 14%;">操作</th>
                    </tr>
                </thead>
                <tbody>
    `;

    components.forEach(comp => {
        const statusBadge = getStatusBadge(comp.status);
        const contentStatus = comp.has_content
            ? `<span class="badge bg-success">あり</span>`
            : `<span class="badge bg-secondary">なし</span>`;
        const assignee = comp.full_name
            ? `<small>${escapeHtml(comp.full_name)}</small>`
            : '<span class="text-muted">-</span>';

        html += `
            <tr>
                <td><span class="badge bg-secondary">#${comp.id}</span></td>
                <td><strong>${escapeHtml(comp['カラム名'])}</strong></td>
                <td><small>${escapeHtml((comp['説明'] || '').substring(0, 50))}</small></td>
                <td>${statusBadge}</td>
                <td>${assignee}</td>
                <td>${contentStatus}</td>
                <td>
                    <button class="btn btn-sm btn-outline-primary"
                            onclick="showComponentDetail(${comp.id})"
                            ${comp.has_content ? '' : 'disabled'}>
                        <i class="bi bi-eye"></i> 詳細
                    </button>
                </td>
            </tr>
        `;
    });

    html += `
                </tbody>
            </table>
        </div>
    `;

    container.innerHTML = html;
}

function showComponentsError(message) {
    const container = document.getElementById('componentsContainer');
    container.innerHTML = `<div class="alert alert-danger" role="alert"><i class="bi bi-exclamation-triangle"></i> ${message}</div>`;
}

function showComponentDetail(componentId) {
    const componentTitle = document.getElementById('componentTitle');
    const componentContent = document.getElementById('componentContent');

    componentTitle.textContent = '読み込み中...';
    componentContent.innerHTML = `
        <div class="text-center py-4">
            <div class="spinner-border text-primary" role="status">
                <span class="visually-hidden">読み込み中...</span>
            </div>
        </div>
    `;

    // モーダルを表示
    const modal = new bootstrap.Modal(document.getElementById('componentModal'));
    modal.show();

    // コンポーネント詳細を取得
    fetch(`/colrep_public/${projectId}/api/component/${componentId}`)
        .then(response => response.json())
        .then(data => {
            if (data.success) {
                const comp = data.component;
                const statusBadge = getStatusBadge(comp.status);

                componentTitle.textContent = escapeHtml(comp['カラム名']);

                // ✅ 修正：ソースコンテンツのみ表示
                let html = `
                    <div class="mb-3">
                        <div class="row">
                            <div class="col-md-6">
                                <small class="text-muted">
                                    <strong>ステータス:</strong> ${statusBadge}
                                </small>
                            </div>
                            <div class="col-md-6">
                                <small class="text-muted">
                                    <strong>担当者:</strong> ${comp['ユーザ名'] ? escapeHtml(comp['ユーザ名']) : '-'}
                                </small>
                            </div>
                        </div>
                        <div class="row mt-2">
                            <div class="col-md-6">
                                <small class="text-muted">
                                    <strong>更新日時:</strong> ${formatDateTime(comp['更新日時'])}
                                </small>
                            </div>
                        </div>
                    </div>

                    <hr>

                    <div class="mb-3">
                        <h6><strong>説明</strong></h6>
                        <p>${escapeHtml(comp['説明'] || '')}</p>
                    </div>

                    <hr>

                    <div>
                        <h6><strong>ソースコンテンツ</strong></h6>
                        <pre style="max-height: 600px; overflow-y: auto; background: #f5f5f5; padding: 15px; border-radius: 4px; font-size: 0.85rem; white-space: pre-wrap; word-wrap: break-word; font-family: 'Monaco', 'Menlo', 'Ubuntu Mono', 'Courier New', monospace; line-height: 1.4;"><code>${escapeHtml(comp['content_md'])}</code></pre>
                    </div>
                `;

                componentContent.innerHTML = html;
            } else {
                componentContent.innerHTML = `<p class="text-danger">エラー: ${data.error}</p>`;
            }
        })
        .catch(error => {
            console.error('Error:', error);
            componentContent.innerHTML = `<p class="text-danger">エラーが発生しました</p>`;
        });
}

function getStatusBadge(status) {
    switch(status) {
        case '作業中':
            return '<span class="badge bg-warning">作業中</span>';
        case '改訂中':
            return '<span class="badge bg-info">改訂中</span>';
        case '完了':
            return '<span class="badge bg-success">完了</span>';
        default:
            return '<span class="badge bg-secondary">-</span>';
    }
}

function formatDateTime(dateString) {
    if (!dateString) return '-';
    const date = new Date(dateString);
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    const hours = String(date.getHours()).padStart(2, '0');
    const minutes = String(date.getMinutes()).padStart(2, '0');
    return `${month}/${day} ${hours}:${minutes}`;
}

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}
</script>

<!-- ✅ 追加：Bootstrap JavaScriptを読み込み -->
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>

<style>
.table-hover tbody tr:hover {
    background-color: #f8f9fa;
}

h7 {
    font-size: 0.9rem;
    font-weight: 600;
}
</style>
</body>
