        .btn-manual{background:#0ea5e9;color:#fff}.btn-manual:hover{background:#0284c7}
        .btn-spec{background:#8b5cf6;color:#fff}.btn-spec:hover{background:#7c3aed}
        .btn-export{background:#10b981;color:#fff}.btn-export:hover{background:#059669}
        .btn-import{background:#f59e0b;color:#fff}.btn-import:hover{background:#d97706}
        .btn-mgmt{background:#475569;color:#fff}.btn-mgmt:hover{background:#334155}
