        .modal-footer{padding:15px 20px;border-top:1px solid #e5e7eb;display:flex;gap:10px;justify-content:flex-end;position:sticky;bottom:0;background:#fff}
        .m-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:20px;padding:12px 16px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px}
        .m-toolbar .mlbl{font-size:.8rem;color:#64748b;margin-right:4px}
        .m-toolbar button.act{box-shadow:0 0 0 2px #6366f1}
        .vs{border:1px solid #e5e7eb;border-radius:8px;margin-bottom:16px;overflow:hidden}
        .vs-h{background:#f1f5f9;padding:10px 16px;font-weight:700;font-size:.9rem;color:#334155;border-bottom:1px solid #e5e7eb}
        .vs-b{padding:12px 16px}.vs-b.empty{color:#9ca3af;font-style:italic;font-size:.85rem}
        .md-r{font-size:.88rem;line-height:1.7;color:#1e293b}
        .md-r h2{font-size:1.05rem;margin:12px 0 6px;color:#1e40af;border-bottom:1px solid #e2e8f0;padding-bottom:4px}
        .md-r h3{font-size:.95rem;margin:10px 0 4px;color:#334155}.md-r p{margin:4px 0}
        .md-r ul,.md-r ol{padding-left:1.5em;margin:4px 0}.md-r li{margin:2px 0}
        .md-r pre{background:#1e293b;color:#e2e8f0;padding:12px;border-radius:6px;overflow-x:auto;font-size:.82rem;line-height:1.5;margin:8px 0}
        .md-r code{background:#e2e8f0;padding:1px 5px;border-radius:3px;font-size:.82rem}
        .md-r pre code{background:none;padding:0}
        .md-r table{border-collapse:collapse;width:100%;margin:8px 0}.md-r th,.md-r td{border:1px solid #d1d5db;padding:6px 10px}.md-r th{background:#f3f4f6}
        .vn{margin-top:8px;padding:6px 10px;background:#fffbeb;border-left:3px solid #f59e0b;font-size:.8rem;color:#92400e;border-radius:0 4px 4px 0}
        .gn-view{background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;padding:12px 16px;margin-bottom:16px;font-size:.85rem;color:#92400e;white-space:pre-wrap;font-family:monospace}
        .ef{border:1px solid #e5e7eb;border-radius:8px;margin-bottom:16px;overflow:hidden}
        .ef-h{background:#f1f5f9;padding:10px 16px;font-weight:700;font-size:.9rem;color:#334155;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:center}
        .ef-b{padding:12px 16px}
        .ef .fv{width:100%;padding:10px;border:1px solid #d1d5db;border-radius:5px;font-family:'Consolas',monospace;font-size:.85rem;resize:vertical;line-height:1.5}
        .ef .fn{width:100%;padding:8px;border:1px solid #fcd34d;border-radius:5px;background:#fffbeb;font-size:.85rem;resize:vertical;margin-top:8px}
        .nlbl{font-size:.8rem;color:#92400e;margin-top:8px;margin-bottom:3px}
        .htgl{background:#e0f2fe;border:none;padding:4px 8px;border-radius:4px;font-size:.75rem;cursor:pointer;color:#0369a1}
        .hbox{background:#f0fdf4;border:1px solid #bbf7d0;border-radius:5px;padding:10px;margin-bottom:10px;font-size:.8rem;color:#166534;white-space:pre-wrap;font-family:monospace;display:none}
        .gn-edit{background:#fef3c7;border:1px solid #fcd34d;border-radius:8px;padding:15px;margin-bottom:16px}
        .gn-edit h4{margin:0 0 8px;color:#92400e;font-size:.9rem}
        .jt{display:flex;gap:8px;margin-bottom:12px;flex-wrap:wrap;align-items:center}
        .jt button{padding:6px 14px;font-size:.8rem}
        #json-editor{width:100%;min-height:500px;padding:15px;border:2px solid #d1d5db;border-radius:8px;font-family:'Consolas',monospace;font-size:.85rem;line-height:1.5;resize:vertical;tab-size:2;background:#1e293b;color:#e2e8f0;outline:none}
        #json-editor:focus{border-color:#6366f1}
        #json-editor.jv{border-color:#10b981}#json-editor.ji{border-color:#ef4444}
        .js{margin-top:8px;padding:8px 12px;border-radius:5px;font-size:.8rem;font-family:monospace}
        .js.valid{background:#d1fae5;color:#065f46;border:1px solid #6ee7b7}
        .js.invalid{background:#fee2e2;color:#991b1b;border:1px solid #fca5a5}
        .js.info{background:#dbeafe;color:#1e40af;border:1px solid #93c5fd}
        .jhelp{background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:15px;margin-bottom:15px;font-size:.82rem;color:#475569}
        .jhelp h4{color:#334155;margin-bottom:8px;font-size:.9rem}
        .jli{font-size:.75rem;color:#9ca3af;margin-top:4px}
        .mc{display:none}.mc.active{display:block}
        .man-content{padding:24px;background:#fff;font-size:.92rem;line-height:1.8;color:#1e293b}
        .man-content h1{font-size:1.5rem;border-bottom:2px solid #e2e8f0;padding-bottom:8px;margin-bottom:16px}
        .man-content h2{font-size:1.2rem;border-bottom:1px solid #e2e8f0;padding-bottom:6px;color:#1e40af;margin:20px 0 10px}
        .man-content pre{background:#1e293b;color:#e2e8f0;padding:16px;border-radius:8px;overflow-x:auto;font-size:.85rem}
        .man-content code{background:#e2e8f0;padding:2px 6px;border-radius:4px;font-size:.85rem}
        .man-content pre code{background:none;padding:0}
        .man-content table{border-collapse:collapse;width:100%;margin:12px 0}
        .man-content th,.man-content td{border:1px solid #d1d5db;padding:8px 12px}.man-content th{background:#f3f4f6}
        .man-content blockquote{border-left:4px solid #6366f1;margin:12px 0;padding:8px 16px;background:#f8fafc}
        .man-content img{max-width:100%;border-radius:8px}
        .man-empty{text-align:center;padding:60px 20px;color:#9ca3af}
        .man-empty .me-icon{font-size:3rem;margin-bottom:16px}
        .man-meta{background:#f8fafc;border:1px solid #e2e8f0;border-radius:6px;padding:10px 16px;margin-bottom:16px;font-size:.82rem;color:#64748b;display:flex;gap:20px}
        .add-form .form-group{margin-bottom:12px}
        .add-form .row2{display:flex;gap:12px}
        .add-form .row2 .form-group{flex:1}
    </style>
</head>
<body>
<div class="container">
    <div class="header">
        <a href="{{ url_for('app_share.return_to_fujin') }}" class="btn-return">
            🏠 FUJINダッシュボードに戻る
        </a>
        <h1>📦 アプシャ（App Share）
            {% if is_admin %}<span class="role-badge role-admin">管理者</span>
            {% else %}<span class="role-badge role-guest">閲覧モード</span>{% endif %}
        </h1>
        <p class="subtitle">FUJIN-P アプリケーション共有システム</p>
    </div>
    <div id="result"></div>
    <div id="loading">⏳ 処理中...</div>
    <div class="tabs">
        <button class="tab active" data-tab="local">📂 ローカルアプリ</button>
        {% if is_admin %}
        <button class="tab" data-tab="admin">🛠 管理</button>
        {% endif %}
    </div>
    <div id="local-tab" class="tab-content active">
        <h2>📂 登録済みアプリ
            <span style="float:right;display:inline-flex;gap:8px">
                <button class="btn-import" onclick="openAppImport()">📦 新規アプリ取り込み</button>
                <button class="secondary" onclick="startExport('{{ url_for('app_share.export_kernel_package') }}','カーネル')">⚙ カーネルエクスポート</button>
                <button class="primary" onclick="startExport('{{ url_for('app_share.export_site_overview') }}','全アプリパッケージ')">⬇ 全アプリパッケージエクスポート</button>
            </span>
        </h2>
        {% if is_admin %}
        <p style="margin-bottom:15px;color:#666">📖マニュアル・📋仕様書の閲覧、⚙で編集、↑↓で並べ替え。＋で新規登録。</p>
        <div id="migrate-bar" style="display:none;margin-bottom:15px">
            <div class="warning-box">⚠️ レジストリが空です。<button class="primary" onclick="doMigrate()" style="margin-left:12px">📥 既存アプリを一括取り込み</button></div>
        </div>
        {% else %}
        <p style="margin-bottom:15px;color:#666">📖マニュアル・📋仕様書を閲覧できます。</p>
        {% endif %}
        <div id="local-apps-list" class="app-list"></div>
    </div>
    {% if is_admin %}
    <div id="admin-tab" class="tab-content">
        <h2>📥 全アプリパッケージからのアプリインポート</h2>
        <div class="info-box">エクスポート機能「⬇ 全アプリパッケージエクスポート」で出力したJSONを選択してください。<br>
        ・<strong>パッケージ入り</strong>（各アプリのソース一式を含む）JSONなら、アプリを選んで<strong>個別アプリ取り込み</strong>を一括実行します。<br>
        ・<strong>説明のみ</strong>（軽量版）JSONなら、レジストリ・マニュアル・仕様書だけを更新します。</div>
        <div class="form-group"><label>JSONファイル:</label><input type="file" id="imp-file" accept=".json,application/json"></div>
        <div id="imp-meta" class="success-box" style="display:none"></div>

        <!-- ① 必須テーブルのスキーマ宣言（共通コードが使うテーブル） -->
        <div id="imp-core" style="display:none">
            <h3>① 必須テーブルのスキーマ宣言</h3>
            <div class="info-box" style="margin-top:0">共通コード（admin.py / auth.py 等）が使う必須テーブルです。<strong>アプリ取り込みの前に</strong>「実行」でこのサイトに宣言してください（<code>CREATE TABLE IF NOT EXISTS</code>。既存テーブルは変更しません）。</div>
            <div id="imp-core-list" class="gc-list"></div>
            <div style="margin-top:6px">
                <button class="primary" id="imp-core-go" onclick="doImportCore()">🗄 スキーマ宣言を実行</button>
                <button class="secondary btn-sm" onclick="copyEl('imp-core-sql',this)">📋 SQLをコピー</button>
                <textarea id="imp-core-sql" readonly style="display:none"></textarea>
            </div>
            <div id="imp-core-result" style="margin-top:8px"></div>
        </div>

        <!-- 軽量（説明のみ）JSON: 従来の一覧 -->
        <div id="imp-listwrap" style="display:none">
            <h3>📦 含まれるアプリ</h3>
            <table id="imp-table"><thead><tr><th>アプリ</th><th>インポート側の更新日時</th><th>ローカルの更新日時</th><th>状態</th></tr></thead><tbody></tbody></table>
            <div id="imp-count" style="margin-top:8px"></div>
        </div>

        <!-- パッケージ入りJSON: 選択して一括取り込み -->
        <div id="imp-batchwrap" style="display:none">
            <h3>② 取り込むアプリを選択</h3>
            <p style="font-size:.83rem;color:#666;margin-bottom:8px">デフォルトは<strong>受け入れ側に既にディレクトリがあるアプリ</strong>にチェック（オプトイン）。必要に応じて切り替えてください。<button class="secondary btn-sm" style="margin-left:8px" onclick="batchSelect('all')">全選択</button> <button class="secondary btn-sm" onclick="batchSelect('none')">全解除</button> <button class="secondary btn-sm" onclick="batchSelect('updated')">新規・更新のみ</button></p>
            <table id="imp-batch-table"><thead><tr><th style="width:36px"></th><th>アプリ</th><th>パッケージ</th><th>受け入れ側</th><th>バージョン</th></tr></thead><tbody></tbody></table>
            <div id="imp-batch-count" style="margin-top:8px"></div>
        </div>

        <div id="imp-result" style="display:none"></div>

        <div style="margin-top:16px;text-align:right">
            <button class="danger" id="imp-all" style="display:none" onclick="doImport('all')">⬆ 全部上書き</button>
            <button class="success" id="imp-newer" style="display:none" onclick="doImport('newer')">⬆ 新しいものだけ上書き</button>
            <button class="success" id="imp-batch-go" style="display:none" onclick="doBatchImport()">📥 選択アプリを取り込む</button>
        </div>
    </div>
    {% endif %}
</div>
{% if is_admin %}
<div id="add-modal" class="modal-overlay">
    <div class="modal" style="max-width:550px">
        <div class="modal-header"><h2>➕ アプリ新規登録</h2><button class="modal-close" onclick="closeAdd()">&times;</button></div>
        <div class="modal-body add-form">
            <div class="form-group"><label>アプリ名（ディレクトリ名）*</label><input type="text" id="add-name" placeholder="例: my_app"></div>
            <div class="row2">
                <div class="form-group"><label>表示名 *</label><input type="text" id="add-display" placeholder="例: マイアプリ"></div>
                <div class="form-group" style="max-width:100px"><label>アイコン</label><input type="text" id="add-icon" value="📦" style="font-size:1.5rem;text-align:center"></div>
            </div>
            <div class="form-group"><label>概要（2行程度）</label><textarea id="add-desc" rows="2" placeholder="アプリの簡単な説明..."></textarea></div>
        </div>
<div class="modal-footer"><button class="success" onclick="doAdd()">✓ 登録</button><button class="secondary" onclick="closeAdd()">キャンセル</button></div>
    </div>
</div>
{% endif %}
{% if is_admin %}
<div id="ce-modal" class="modal-overlay">
    <div class="modal" style="max-width:560px">
        <div class="modal-header"><h2>⚙ アプリ情報の編集</h2><button class="modal-close" onclick="closeCE()">&times;</button></div>
        <div class="modal-body add-form">
            <div class="row2">
                <div class="form-group" style="max-width:110px"><label>アイコン</label><input type="text" id="ce-i" maxlength="4" style="font-size:1.8rem;text-align:center"></div>
                <div class="form-group"><label>表示名 *</label><input type="text" id="ce-n"></div>
            </div>
            <div class="form-group"><label>ディレクトリ名</label>
                <input type="text" id="ce-a" spellcheck="false" autocapitalize="off" autocomplete="off" style="font-family:monospace">
                <div style="font-size:.78rem;color:#6b7280;margin-top:4px">英数字とアンダースコアのみ。<code>~/fujinp/&lt;名前&gt;/__init__.py</code> が実在しないと保存できません。変更するとマニュアル・仕様書の紐付けも一緒に移ります。</div>
            </div>
            <div class="form-group" style="max-width:160px"><label>表示順</label>
                <input type="text" id="ce-o" inputmode="decimal" style="text-align:right">
            </div>
            <div style="font-size:.78rem;color:#6b7280;margin:-8px 0 12px">小さい順に並びます。既存の間に入れたいときは <code>12.5</code> のような小数が使えます。</div>
            <div class="form-group"><label>概要（2行程度）</label><textarea id="ce-d" rows="3"></textarea></div>
        </div>
        <div class="modal-footer"><button class="success" onclick="saveCE()">✓ 保存</button><button class="secondary" onclick="closeCE()">キャンセル</button></div>
    </div>
</div>
{% endif %}
{% if is_admin %}
<div id="appimport-modal" class="modal-overlay">
    <div class="modal" style="max-width:600px">
        <div class="modal-header"><h2>📦 新規アプリ取り込み</h2><button class="modal-close" onclick="closeAppImport()">&times;</button></div>
        <div class="modal-body">
            <div class="info-box">アプリ単位のエクスポートパッケージ（fujinp_app_package）を取り込みます。パッケージJSONを選ぶとアプリ名を自動判定します。まだレジストリに無い新規アプリでも取り込めます。次の画面で検証してから実行します。</div>
            <div class="form-group"><label>① パッケージJSONから自動判定（推奨）:</label><input type="file" id="ai-file" accept=".json,application/json"></div>
            <div id="ai-detected" class="success-box" style="display:none"></div>
            <div class="form-group"><label>② またはアプリ名（ディレクトリ名）を直接入力:</label><input type="text" id="ai-name" placeholder="例: app_share"></div>
        </div>
        <div class="modal-footer">
            <button class="success" id="ai-go" onclick="goAppImport()">📥 取り込み画面を開く</button>
            <button class="secondary" onclick="closeAppImport()">キャンセル</button>
        </div>
    </div>
</div>
<div id="gc-modal" class="modal-overlay">
    <div class="modal" style="max-width:900px">
        <div class="modal-header"><h2>🗑 ガーベージコレクション</h2><button class="modal-close" onclick="closeGC()">&times;</button></div>
        <div class="modal-body">
            <div class="danger-box">⚠️ <strong>破壊的操作です。</strong>未登録アプリの<strong>ディレクトリ削除</strong>と、参照されないSQLテーブルの<strong>DROP</strong>を行います（元に戻せません）。まず「プレビュー」で対象を確認し、問題なければ確認欄に <code>DELETE</code> と入力して実行してください。保護対象: <code>app_share</code> 本体・templates・static・各バックアップ、テーブル <code>users</code> / <code>app_share_registry</code> / <code>app_share_documents</code>。</div>
            <button class="primary" id="gc-preview-btn" onclick="runGCPreview()">🔍 プレビュー（削除対象を確認）</button>
            <div id="gc-progress" style="display:none;margin-top:10px">
                <div style="font-size:.85rem;color:#334155" id="gc-progress-label">準備中...</div>
                <div style="background:#e5e7eb;border-radius:6px;height:12px;overflow:hidden;margin-top:4px"><div id="gc-progress-bar" style="height:100%;width:0%;background:#6366f1;transition:width .15s"></div></div>
            </div>
            <div id="gc-warn" class="danger-box" style="display:none;margin-top:12px">⚠️ 削除するには、下の入力欄に <code>DELETE</code> と入力して「🗑 実行」を押してください（元に戻せません）。</div>
            <div id="gc-preview-area" style="display:none;margin-top:12px"></div>
            <div id="gc-result" style="display:none;margin-top:12px"></div>
        </div>
        <div class="modal-footer">
            <span id="gc-confirm-label" style="display:none;font-size:.82rem;color:#991b1b;font-weight:700;margin-right:auto">実行するには「DELETE」と入力 →</span>
            <input type="text" id="gc-confirm" class="gc-confirm" placeholder="DELETE" autocomplete="off" oninput="gcConfirmChanged()" style="display:none">
            <button class="danger" id="gc-exec-btn" disabled onclick="runGCExecute()" style="display:none">🗑 実行（削除する）</button>
            <button class="secondary" id="gc-download" style="display:none" onclick="downloadGCReport()">⬇ レポートをダウンロード</button>
            <button class="secondary" onclick="closeGC()">閉じる</button>
        </div>
    </div>
</div>
<div id="mgmt-modal" class="modal-overlay">
    <div class="modal" style="max-width:1000px">
        <div class="modal-header"><h2>🛠 アプリ管理 - <span id="mg-app"></span></h2><button class="modal-close" onclick="closeMgmt()">&times;</button></div>
        <div class="modal-body">
            <div id="mg-body"><p style="color:#9ca3af">読み込み中...</p></div>
        </div>
        <div class="modal-footer">
            <button class="primary" onclick="runDiag()">🔄 再診断</button>
            <button class="secondary" onclick="closeMgmt()">閉じる</button>
        </div>
    </div>
</div>
{% endif %}
<div id="manual-modal" class="modal-overlay">
    <div class="modal">
        <div class="modal-header"><h2>📖 <span id="man-title">ユーザマニュアル</span></h2><button class="modal-close" onclick="closeManual()">&times;</button></div>
        <div class="modal-body">
            <div class="man-meta" id="man-meta" style="display:none"><span>📝 更新: <span id="man-date"></span></span><span>👤 <span id="man-author"></span></span></div>
            <div id="man-body" class="man-content"></div>
        </div>
        <div class="modal-footer">
            {% if is_admin %}<button class="primary" onclick="goEditManual()">📝 編集</button>{% endif %}
            <button class="secondary" onclick="openManualPage()">🔗 単独ページ</button>
            <button class="secondary" onclick="copyManualUrl()">📋 URLコピー</button>
            <button class="secondary" onclick="closeManual()">閉じる</button>
        </div>
    </div>
</div>
<div id="spec-modal" class="modal-overlay">
    <div class="modal">
        <div class="modal-header"><h2>📋 技術仕様書 - <span id="spec-app-name"></span></h2><button class="modal-close" onclick="closeSpec()">&times;</button></div>
        <div class="modal-body">
            {% if is_admin %}
            <div class="m-toolbar">
                <span class="mlbl">モード:</span>
                <button class="secondary act" id="btn-m-view" onclick="specMode('view')">👁 閲覧</button>
                <button class="secondary" id="btn-m-edit" onclick="specMode('edit')">📝 フィールド編集</button>
                <button class="secondary" id="btn-m-json" onclick="specMode('json')">{ } JSON</button>
            </div>
            {% endif %}
            <div id="sm-view" class="mc active"><div id="sv-gn"></div><div id="sv-fields"></div></div>
            {% if is_admin %}
            <div id="sm-edit" class="mc">
                <div class="gn-edit"><h4>📝 全体の備考</h4><textarea id="gn-ta" style="width:100%;padding:10px;border:1px solid #d1d5db;border-radius:5px;font-family:monospace;font-size:.85rem" rows="3"></textarea></div>
                <div id="se-fields"></div>
            </div>
            <div id="sm-json" class="mc">
                <div class="jhelp"><h4>💡 使い方</h4><p>生成AIの出力JSONを貼り付けて保存。</p></div>
                <div class="jt">
                    <button class="primary" onclick="jLoad()">📥 読込</button><button class="warning" onclick="jSync()">📝→{} 生成</button>
                    <button class="primary" onclick="jFmt()">🔧 整形</button><button class="primary" onclick="jVal()">✅ 検証</button><button class="primary" onclick="jCopy()">📋 コピー</button>
                </div>
                <textarea id="json-editor" spellcheck="false" placeholder="JSONをここに..."></textarea>
                <div class="jli"><span id="j-cur">行:1, 列:1</span><span style="margin-left:20px" id="j-sz">0字</span></div>
                <div id="j-st" class="js info" style="display:none"></div>
            </div>
            {% endif %}
        </div>
        <div class="modal-footer" id="sf-view"><button class="secondary" onclick="closeSpec()">閉じる</button></div>
        {% if is_admin %}
        <div class="modal-footer" id="sf-edit" style="display:none"><button class="success" onclick="specSaveFields()">💾 保存</button><button class="secondary" onclick="specMode('view')">キャンセル</button></div>
        <div class="modal-footer" id="sf-json" style="display:none"><button class="success" onclick="jSave()">💾 JSON保存</button><button class="secondary" onclick="specMode('view')">キャンセル</button></div>
        {% endif %}
    </div>
</div>
<script>
const IS_ADMIN = {{ is_admin|tojson }};
marked.setOptions({breaks:true,gfm:true});
function showResult(m,e){const $r=$('#result');$r.text(m).removeClass('success error').addClass(e?'error':'success').show();setTimeout(()=>$r.fadeOut(),5000)}
function esc(t){return t?t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'):''}
$('.tab').click(function(){const id=$(this).data('tab');$('.tab').removeClass('active');$(this).addClass('active');$('.tab-content').removeClass('active');$(`#${id}-tab`).addClass('active');if(id==='admin'&&typeof openImport==='function')openImport()});
// ========== ローカルアプリ ==========
function loadLocalApps(){
    $.ajax({url:'/app_share/get_registry_apps',success(r){
        if(!r.success){showResult('読込エラー',true);return}
        const $l=$('#local-apps-list').empty();
        r.apps.forEach(a=>{
            const desc=a.description||'';
            let ctrl='';
            if(IS_ADMIN){
                ctrl=`<div class="card-ctrl">
                    <button class="btn-move btn-sm" onclick="moveApp(${a.id},'up',event)" title="上へ">▲</button>
                    <button class="btn-move btn-sm" onclick="moveApp(${a.id},'down',event)" title="下へ">▼</button>
                    <button class="btn-gear btn-sm" onclick="openCE(${a.id},event)" title="編集">⚙</button>
                    <button class="btn-del btn-sm" onclick="delApp(${a.id},'${esc(a.display_name||a.app_name)}',event)" title="削除">✕</button>
                </div>`;
            }
            $l.append(`<div class="app-card" data-id="${a.id}" data-name="${a.app_name}" data-sort="${a.sort_order??''}">
                ${ctrl}
                <div class="card-top">

                    <div class="card-icon">${a.icon||'📦'}</div>
                    <div class="card-titles">
                        <div class="card-name">${esc(a.display_name||a.app_name)}</div>
                        <div class="card-dir">${esc(a.app_name)}</div>
                    </div>
