    $.ajax({url:'/app_share/confirm_version/'+encodeURIComponent(name),method:'POST',contentType:'application/json',
        success(d){
            if(d.success){showResult('🏷 バージョンを確定しました: '+d.version_id,false);loadLocalApps();}
            else showResult('確定に失敗: '+(d.error||''),true);
        },
        error(x){showResult('確定に失敗: '+((x.responseJSON&&x.responseJSON.error)||x.statusText),true)}
