// 新規アプリ取り込み（ローカルアプリタブのボタンから。カードが無い新規アプリでも開始できる入口）
let aiPkg=null;
function openAppImport(){aiPkg=null;$('#ai-file').val('');$('#ai-name').val('');$('#ai-detected').hide();$('#ai-go').prop('disabled',false).text('📥 取り込み画面を開く');$('#appimport-modal').addClass('active')}
function closeAppImport(){$('#appimport-modal').removeClass('active')}
$('#appimport-modal').click(function(e){if(e.target===this)closeAppImport()});
$('#ai-file').change(function(){
    const f=this.files[0];if(!f){aiPkg=null;return}
    const rd=new FileReader();
    rd.onload=function(ev){
        let d;
        try{d=JSON.parse(ev.target.result)}catch(x){aiPkg=null;showResult('JSON解析に失敗: '+x.message,true);return}
        if(d.export_type!=='fujinp_app_package'){aiPkg=null;showResult('アプリ単位のパッケージではありません（export_type: '+(d.export_type||'なし')+'）',true);return}
        if(!d.app_name){aiPkg=null;showResult('パッケージに app_name がありません',true);return}
        aiPkg=d;
        $('#ai-name').val(d.app_name);
        $('#ai-detected').html(`✅ 検出: <strong>${esc(d.icon||'')} ${esc(d.display_name||d.app_name)}</strong>（${esc(d.app_name)}） v${esc(d.updated_at||'日時なし')}<br>このまま「取り込み画面を開く」を押すと、次の画面で再アップロード不要です。`).show();
    };
    rd.readAsText(f,'utf-8');
});
function goAppImport(){
    const name=$('#ai-name').val().trim();
    if(!name){alert('アプリ名を入力するか、パッケージJSONを選択してください');return}
    if(!/^[A-Za-z0-9_]+$/.test(name)){alert('アプリ名（ディレクトリ名）は英数字とアンダースコアのみです');return}
    // ファイルから読み込んだパッケージがあれば、サーバにステージングしてトークンで受け渡す
    // （取り込み画面での再アップロードを省略）
    if(aiPkg&&aiPkg.app_name===name){
        $('#ai-go').prop('disabled',true).text('⏳ 準備中...');
        $.ajax({url:'/app_share/stage_package',method:'POST',contentType:'application/json',
            data:JSON.stringify(aiPkg),
            success(r){
                if(r.success&&r.token){location.href='/app_share/import_package/'+encodeURIComponent(name)+'?token='+encodeURIComponent(r.token)}
                else{showResult('準備に失敗しました（再アップロード方式で続行）: '+(r.error||''),true);location.href='/app_share/import_package/'+encodeURIComponent(name)}
            },
            error(){location.href='/app_share/import_package/'+encodeURIComponent(name)}});
    }else{
        location.href='/app_share/import_package/'+encodeURIComponent(name);
    }
}

