// ========== 技術仕様書モーダル ==========
let specApp=null,specInfo=null,specOrig=null,specCurMode='view',jDirty=false,eDirty=false;
const FL={'display_name':'表示名','description':'説明（短）','url':'URL','blueprint_name':'Blueprint名','overview':'概要（詳細）','directory_structure':'ディレクトリ構造','python_files':'Pythonファイル','template_files':'テンプレートファイル','endpoints':'エンドポイント','mysql_schema':'MySQLスキーマ','sql_tables_description':'SQLテーブル説明','libraries':'依存ライブラリ','migration_guide':'マイグレーションガイド','config_notes':'config.py 設定メモ'};
const FO=['display_name','description','url','blueprint_name','overview','directory_structure','python_files','template_files','endpoints','mysql_schema','sql_tables_description','libraries','migration_guide','config_notes'];
const FR={'display_name':1,'description':2,'url':1,'blueprint_name':1,'overview':8,'directory_structure':10,'python_files':5,'template_files':5,'endpoints':10,'mysql_schema':15,'sql_tables_description':8,'libraries':5,'migration_guide':12,'config_notes':6};

function openSpec(name){
    specApp=name;jDirty=false;eDirty=false;
    $('#spec-app-name').text(name);$('#loading').show();
    if(IS_ADMIN){$('#json-editor').val('').removeClass('jv ji');$('#j-st').hide()}
    $.ajax({url:`/app_share/get_app_info/${name}`,
        success(r){if(r.success){specInfo=r.app_info;specOrig=JSON.stringify(r.app_info);if(IS_ADMIN)specMode('view');else renderSV(specInfo);$('#spec-modal').addClass('active')}else showResult('エラー: '+r.error,true)},
        error(){showResult('情報取得エラー',true)},complete(){$('#loading').hide()}});
}
function closeSpec(){
    if(IS_ADMIN&&((specCurMode==='edit'&&eDirty)||(specCurMode==='json'&&jDirty))){if(!confirm('未保存の変更があります。閉じますか？'))return}
    $('#spec-modal').removeClass('active');specApp=null;specInfo=null;
}
$('#spec-modal').click(function(e){if(e.target===this)closeSpec()});

function specMode(m){
    if(!IS_ADMIN)return;
    if(specCurMode==='edit'&&eDirty&&m!=='edit'&&!confirm('変更が未保存です。破棄しますか？'))return;
    if(specCurMode==='json'&&jDirty&&m!=='json'&&!confirm('変更が未保存です。破棄しますか？'))return;
    specCurMode=m;
    $('#btn-m-view,#btn-m-edit,#btn-m-json').removeClass('act');$(`#btn-m-${m}`).addClass('act');
    $('.mc').removeClass('active');$(`#sm-${m}`).addClass('active');
    $('#sf-view,#sf-edit,#sf-json').hide();$(`#sf-${m}`).show();
    if(m==='view')renderSV(specInfo);
    else if(m==='edit'){eDirty=false;renderSE(specInfo)}
    else if(m==='json'){jDirty=false;const e=document.getElementById('json-editor');if(!e.value.trim())e.value=JSON.stringify(specInfo,null,2);jUpd()}
}

function renderSV(info){
    const n=info.general_notes||'';
    n.trim()?$('#sv-gn').html(`<div class="gn-view">${esc(n)}</div>`).show():$('#sv-gn').empty().hide();
    const $c=$('#sv-fields').empty(),f=info.fields||{};
    FO.forEach(k=>{if(!f[k])return;const d=f[k],lb=FL[k]||k,v=(d.value||'').trim(),nt=(d.note||'').trim();
        const $s=$('<div class="vs">');$s.append(`<div class="vs-h">${esc(lb)}</div>`);
        if(v){let h;
            if(['mysql_schema','config_notes'].includes(k))h=`<pre style="background:#1e293b;color:#e2e8f0;padding:12px;border-radius:6px;overflow-x:auto;font-size:.82rem;margin:0">${esc(v)}</pre>`;
            else if(k==='directory_structure')h=`<pre style="background:#f8fafc;color:#334155;padding:12px;border-radius:6px;overflow-x:auto;font-size:.82rem;margin:0;border:1px solid #e2e8f0">${esc(v)}</pre>`;
            else h=`<div class="md-r">${marked.parse(v)}</div>`;
            $s.append(`<div class="vs-b">${h}</div>`)
        }else $s.append('<div class="vs-b empty">（未入力）</div>');
        if(nt)$s.append(`<div class="vn">📌 ${esc(nt)}</div>`);$c.append($s)});
}

function renderSE(info){
    $('#gn-ta').val(info.general_notes||'');const $c=$('#se-fields').empty(),f=info.fields||{};
    FO.forEach(k=>{if(!f[k])return;const d=f[k],lb=FL[k]||k,rows=FR[k]||5,h=d.hint||'';
        $c.append(`<div class="ef" data-field="${k}"><div class="ef-h"><span>${esc(lb)}</span>${h?'<button class="htgl" onclick="$(this).closest(\'.ef\').find(\'.hbox\').toggle()">💡</button>':''}</div>
        <div class="ef-b">${h?`<div class="hbox">${esc(h)}</div>`:''}<textarea class="fv" data-key="${k}" rows="${rows}">${esc(d.value||'')}</textarea>
        <div class="nlbl">📌 備考:</div><textarea class="fn" data-key="${k}" rows="2">${esc(d.note||'')}</textarea></div></div>`)});
}
$(document).on('input','#sm-edit textarea',function(){eDirty=true});

function specCollect(){
    const ai={general_notes:$('#gn-ta').val(),fields:{}};
    $('.ef').each(function(){const k=$(this).data('field');ai.fields[k]={value:$(this).find('.fv').val(),note:$(this).find('.fn').val(),hint:specInfo.fields[k]?.hint||''}});return ai;
