        error(){showResult('保存エラー',true)},complete(){$('#loading').hide()}});
}

// === JSON編集（admin専用） ===
function jLoad(){if(!specApp||!IS_ADMIN)return;$('#loading').show();$.ajax({url:`/app_share/get_app_info_json/${specApp}`,success(r){if(r.success){$('#json-editor').val(r.json_text);jDirty=false;jUpd();jSt('info','読込完了')}else jSt('invalid','エラー: '+r.error)},error(){jSt('invalid','読込エラー')},complete(){$('#loading').hide()}})}
function jSync(){$('#json-editor').val(JSON.stringify(specInfo,null,2));jDirty=false;jUpd();jSt('info','JSON生成しました')}
function jFmt(){const e=document.getElementById('json-editor'),t=e.value.trim();if(!t)return;try{e.value=JSON.stringify(JSON.parse(t),null,2);jUpd();jSt('valid','整形完了')}catch(x){jSt('invalid','失敗: '+x.message)}}
function jVal(){const t=$('#json-editor').val().trim();if(!t){jSt('invalid','空です');return}$.ajax({url:'/app_share/validate_json',method:'POST',contentType:'application/json',data:JSON.stringify({json_text:t}),success(r){if(r.valid){$('#json-editor').removeClass('ji').addClass('jv');jSt('valid','✅ '+r.message)}else{$('#json-editor').removeClass('jv').addClass('ji');jSt('invalid','❌ '+r.error)}}})}
function jCopy(){const e=document.getElementById('json-editor');if(!e.value.trim()){jSt('invalid','テキストなし');return}navigator.clipboard.writeText(e.value).then(()=>jSt('info','📋 コピーしました')).catch(()=>{e.select();document.execCommand('copy');jSt('info','📋 コピーしました')})}
function jSave(){
    if(!specApp||!IS_ADMIN)return;const t=$('#json-editor').val().trim();
    if(!t){jSt('invalid','テキストなし');return}try{JSON.parse(t)}catch(e){jSt('invalid','JSON構文エラー: '+e.message);return}
    $('#loading').show();
    $.ajax({url:`/app_share/save_app_info_json/${specApp}`,method:'POST',contentType:'application/json',data:JSON.stringify({json_text:t}),
        success(r){if(r.success){showResult(r.message,false);jSt('valid','💾 保存しました');jDirty=false;
            $.ajax({url:`/app_share/get_app_info/${specApp}`,success(r2){if(r2.success){specInfo=r2.app_info;specOrig=JSON.stringify(r2.app_info)}}});
            setTimeout(()=>specMode('view'),800)}else jSt('invalid','エラー: '+r.error)},
        error(xhr){jSt('invalid',xhr.responseJSON?xhr.responseJSON.error:'保存エラー')},complete(){$('#loading').hide()}});
}
function jSt(t,m){const $s=$('#j-st');$s.removeClass('valid invalid info').addClass(t).text(m).show();if(t!=='invalid')setTimeout(()=>$s.fadeOut(),4000)}
function jUpd(){const e=document.getElementById('json-editor');if(!e)return;const t=e.value;$('#j-sz').text(t.length+'字');if(t.trim()){try{JSON.parse(t);e.classList.remove('ji');e.classList.add('jv')}catch{e.classList.remove('jv');e.classList.add('ji')}}else{e.classList.remove('jv','ji')}}
$(document).on('input','#json-editor',function(){jDirty=true;jUpd()});
$(document).on('click keyup','#json-editor',function(){const t=this.value.substring(0,this.selectionStart),l=t.split('\n');$('#j-cur').text(`行:${l.length}, 列:${l[l.length-1].length+1}`)});
$(document).on('keydown','#json-editor',function(e){if(e.key==='Tab'){e.preventDefault();const s=this.selectionStart;this.value=this.value.substring(0,s)+'  '+this.value.substring(this.selectionEnd);this.selectionStart=this.selectionEnd=s+2;jDirty=true}});

