const IMP_BADGE={new:'<span class="badge badge-info">🆕 新規</span>',newer:'<span class="badge badge-warning">⬆ 更新あり</span>',same:'<span class="badge badge-success">変更なし</span>',older:'<span class="badge badge-danger">ローカルが新しい</span>',unknown:'<span class="badge" style="background:#e5e7eb;color:#374151">日時なし</span>'};
