}
$('#imp-file').change(function(){
    const f=this.files[0];if(!f)return;
    const rd=new FileReader();
    rd.onload=function(ev){
        let d;
        try{d=JSON.parse(ev.target.result)}catch(x){showResult('JSONの解析に失敗: '+x.message,true);return}
        if(!Array.isArray(d.apps)){showResult('apps 配列が見つかりません（エクスポート形式のJSONを指定してください）',true);return}
        if(d.export_type&&d.export_type!=='fujinp_apps_overview'){showResult('エクスポート形式が異なります: '+d.export_type,true);return}
        impData=d;
        impHasPackages=d.apps.some(a=>a&&a.package);
        impCore=Array.isArray(d.core_schemas)?d.core_schemas:[];
        $('#imp-meta').html(`✅ <strong>${esc(d.site_name||'(サイト名なし)')}</strong> のエクスポート ／ 生成: ${esc(d.generated_at||'不明')} ／ ${d.apps.length}アプリ ／ ${impHasPackages?'📦 パッケージ入り（個別取り込み可）':'説明のみ（軽量）'}`).show();
        $('#imp-result').hide().empty();
        renderCoreSchemas();
        if(impHasPackages){
            $('#imp-listwrap,#imp-all,#imp-newer').hide();
            refreshBatchPreview();
        }else{
            $('#imp-batchwrap,#imp-batch-go').hide();
            $('#imp-all,#imp-newer').show();
            refreshImpPreview();
        }
    };
    rd.readAsText(f,'utf-8');
});
// --- ① 必須テーブルのスキーマ宣言 ---
function renderCoreSchemas(){
    const cs=(impCore||[]).filter(x=>x&&x.create_sql);
    if(!cs.length){$('#imp-core').hide();return}
    $('#imp-core-list').html(cs.map(x=>`🗄 <code>${esc(x.database||'default')}</code> . <code>${esc(x.table)}</code>`).join('<br>'));
    $('#imp-core-sql').val(cs.map(x=>x.create_sql.replace(/^\s*CREATE\s+TABLE\s+/i,'CREATE TABLE IF NOT EXISTS ').replace(/;?\s*$/,';')).join('\n\n'));
    $('#imp-core-result').empty();$('#imp-core-go').prop('disabled',false);
    $('#imp-core').show();
}
function doImportCore(){
    const cs=(impCore||[]).filter(x=>x&&x.create_sql);
    if(!cs.length)return;
    if(!confirm(`必須テーブル ${cs.length}件を CREATE TABLE IF NOT EXISTS で宣言します。よろしいですか？`))return;
    $('#loading').show();$('#imp-core-go').prop('disabled',true);
    $.ajax({url:'/app_share/import_core_schema',method:'POST',contentType:'application/json',
        data:JSON.stringify({schemas:cs}),
        success(r){
            if(!r.success){showResult('エラー: '+r.error,true);$('#imp-core-go').prop('disabled',false);return}
            showResult(r.message,false);
            let h=`<div class="success-box" style="margin:0"><strong>✅ ${esc(r.message)}</strong><ul class="plain" style="margin:6px 0 0 1.2em">`;
            (r.results||[]).forEach(x=>{
                const ic=x.status==='created'?'🆕':(x.status==='exists'?'✓':'❌');
                h+=`<li>${ic} ${esc(x.database||'')} . ${esc(x.table)}${x.error?' - '+esc(x.error):''}</li>`;
            });
            h+='</ul></div>';
            $('#imp-core-result').html(h);
        },
        error(xhr){showResult('スキーマ宣言エラー: '+(xhr.responseJSON?.error||xhr.statusText),true);$('#imp-core-go').prop('disabled',false)},
        complete(){$('#loading').hide()}});
}

function refreshImpPreview(){
    if(!impData)return;$('#loading').show();
    $.ajax({url:'/app_share/import_preview',method:'POST',contentType:'application/json',
        data:JSON.stringify({apps:impData.apps.map(a=>({app_name:a.app_name,updated_at:a.updated_at||null}))}),
        success(r){
            if(!r.success){showResult('エラー: '+r.error,true);return}
            const $t=$('#imp-table tbody').empty();
            const byName={};impData.apps.forEach(a=>{byName[a.app_name]=a});
            let updCount=0;
            r.results.forEach(x=>{
                if(x.status==='new'||x.status==='newer')updCount++;
                const a=byName[x.app_name]||{};
                $t.append(`<tr><td>${a.icon||'📦'} ${esc(a.display_name||x.app_name)}<div style="font-size:.75rem;color:#999">${esc(x.app_name)}</div></td><td>${x.import_updated_at||'-'}</td><td>${x.local_updated_at||'-'}</td><td>${IMP_BADGE[x.status]||x.status}</td></tr>`);
            });
            $('#imp-listwrap').show();
            $('#imp-count').html(`<div class="info-box" style="margin:0">🆕/⬆ 新規・更新あり: <strong>${updCount}件</strong>（「新しいものだけ上書き」の対象）</div>`);
            $('#imp-all,#imp-newer').prop('disabled',false);
        },
        error(){showResult('比較エラー',true)},complete(){$('#loading').hide()}});
}
function doImport(mode){
