            showResult(r.message,false);
            let h=`<div class="success-box"><strong>✅ ${esc(r.message)}</strong><ul style="margin:8px 0 0 1.2em">`;
            r.results.forEach(x=>{
                const ic=x.action==='imported'?'✅':(x.action==='skipped'?'⏭':'❌');
