// ---- パッケージ入りJSON: 選択して個別アプリ取り込みを一括実行 ----
const BATCH_VBADGE={new:'<span class="badge badge-info">🆕 新規</span>',newer:'<span class="badge badge-warning">⬆ 更新あり</span>',same:'<span class="badge badge-success">変更なし</span>',older:'<span class="badge badge-danger">ローカルが新しい</span>',unknown:'<span class="badge" style="background:#e5e7eb;color:#374151">日時なし</span>'};
function refreshBatchPreview(){
    if(!impData)return;$('#loading').show();
    $.ajax({url:'/app_share/import_site_preview',method:'POST',contentType:'application/json',
        data:JSON.stringify({apps:impData.apps.map(a=>({app_name:a.app_name,updated_at:a.updated_at||null,has_package:!!a.package}))}),
        success(r){
            if(!r.success){showResult('エラー: '+r.error,true);return}
            const byName={};impData.apps.forEach(a=>{byName[a.app_name]=a});
            const $t=$('#imp-batch-table tbody').empty();
            r.results.forEach(x=>{
                const a=byName[x.app_name]||{};
                const dis=x.has_package?'':'disabled title="このアプリにはパッケージが含まれていません"';
                const chk=(x.default_selected)?'checked':'';
                $t.append(`<tr>
                    <td><input type="checkbox" class="imp-chk" value="${esc(x.app_name)}" ${chk} ${dis}></td>
                    <td>${a.icon||'📦'} ${esc(a.display_name||x.app_name)}<div style="font-size:.75rem;color:#999">${esc(x.app_name)}</div></td>
                    <td>${x.has_package?'<span class="badge badge-success">あり</span>':'<span class="badge badge-gray">なし</span>'}</td>
                    <td>${x.local_dir_exists?'<span class="badge badge-info">既存</span>':'<span class="badge" style="background:#e5e7eb;color:#374151">新規</span>'}</td>
                    <td>${BATCH_VBADGE[x.version_status]||esc(x.version_status)}</td>
                </tr>`);
            });
            $('#imp-batchwrap,#imp-batch-go').show();
            $('#imp-batch-go').prop('disabled',false);
            updateBatchCount();
        },
        error(){showResult('比較エラー',true)},complete(){$('#loading').hide()}});
}
function batchSelect(which){
    if(which==='all')$('.imp-chk:not(:disabled)').prop('checked',true);
    else if(which==='none')$('.imp-chk').prop('checked',false);
    else if(which==='updated'){
        $('.imp-chk').each(function(){
            const st=$(this).closest('tr').find('td:last .badge').text();
            $(this).prop('checked',!$(this).prop('disabled')&&(st.indexOf('新規')>=0||st.indexOf('更新')>=0));
        });
    }
    updateBatchCount();
}
$(document).on('change','.imp-chk',updateBatchCount);
function updateBatchCount(){
    const n=$('.imp-chk:checked').length;
    $('#imp-batch-count').html(`<div class="info-box" style="margin:0">選択中: <strong>${n}件</strong>。実行すると各アプリで個別取り込み（事前バックアップ→ファイル置換→説明/マニュアル/仕様書更新）が走ります。SQL・pip・ランチャは実行後に案内表示します（自動実行しません）。</div>`);
    $('#imp-batch-go').prop('disabled',n===0);
}
function doBatchImport(){
    const names=$('.imp-chk:checked').map(function(){return $(this).val()}).get();
    if(!names.length){alert('取り込むアプリを選択してください');return}
    const byName={};impData.apps.forEach(a=>{byName[a.app_name]=a});
    const packages=names.map(n=>byName[n]&&byName[n].package).filter(Boolean);
    if(!packages.length){showResult('選択アプリにパッケージが見つかりません',true);return}
    if(!confirm(`${packages.length}件のアプリを取り込みます。\n各アプリのファイルが置き換えられ（事前バックアップあり）、説明・マニュアル・仕様書が更新されます。よろしいですか？`))return;
    $('#loading').show();
    $.ajax({url:'/app_share/import_site_apply',method:'POST',contentType:'application/json',
        data:JSON.stringify({packages:packages}),
        success(r){
            if(!r.success){showResult('エラー: '+r.error,true);return}
            showResult(r.message,false);
            $('#imp-result').html(renderBatchResults(r)).show();
            loadLocalApps();refreshBatchPreview();
        },
        error(xhr){showResult('取り込みエラー: '+(xhr.responseJSON?.error||xhr.statusText),true)},complete(){$('#loading').hide()}});
}
let _copyId=0;
function copyEl(id,btn){const el=document.getElementById(id);if(!el)return;const t=el.value!==undefined?el.value:el.textContent;
    (navigator.clipboard?navigator.clipboard.writeText(t):Promise.reject()).then(()=>{$(btn).text('✅ コピー済み');setTimeout(()=>$(btn).text('📋 コピー'),2000)}).catch(()=>{el.select&&el.select();document.execCommand('copy')})}
function renderBatchResults(r){
    let h=`<div class="success-box"><strong>✅ ${esc(r.message)}</strong></div>`;
    (r.results||[]).forEach(x=>{
        if(!x.ok){h+=`<div class="warning-box">❌ <strong>${esc(x.app_name)}</strong> - ${esc(x.error||'失敗')}</div>`;return}
        h+=`<div class="vs"><div class="vs-h">✅ ${esc(x.display_name||x.app_name)} <span style="font-weight:400;color:#666">（${esc(x.app_name)}）${x.written}ファイル置換${x.backup?' / backup: '+esc(x.backup):''}</span></div><div class="vs-b">`;
        (x.file_errors||[]).forEach(e=>{h+=`<div style="color:#991b1b;font-size:.82rem">⚠ ${esc(e)}</div>`});
        const g=x.guidance||{};
        if(g.sql){const id='cg-sql-'+(_copyId++);h+=`<div style="margin-top:6px"><strong>🗄 実行するSQL</strong><textarea id="${id}" readonly style="width:100%;min-height:70px;font-family:monospace;font-size:.8rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px">${esc(g.sql)}</textarea><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`;}
        if(g.pip){const id='cg-pip-'+(_copyId++);h+=`<div style="margin-top:6px"><strong>📚 未インストールのライブラリ</strong><textarea id="${id}" readonly style="width:100%;min-height:40px;font-family:monospace;font-size:.8rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px">${esc(g.pip)}</textarea><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`;}
        (g.launchers||[]).forEach(l=>{const id='cg-ln-'+(_copyId++);h+=`<div style="margin-top:6px"><strong>🔗 ランチャ（${esc(l.source||'')} → ダッシュボードに貼付）</strong><textarea id="${id}" readonly style="width:100%;min-height:60px;font-family:monospace;font-size:.8rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px">${esc(l.snippet)}</textarea><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`;});
        if(g.blueprint){const id='cg-bp-'+(_copyId++);h+=`<div style="margin-top:6px"><strong>🧩 app.py へ追加するBlueprint登録</strong>（新規アプリの場合）<textarea id="${id}" readonly style="width:100%;min-height:60px;font-family:monospace;font-size:.8rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px">${esc(g.blueprint)}</textarea><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`;}
        if(!g.sql&&!g.pip&&!(g.launchers||[]).length&&!g.blueprint)h+='<div style="font-size:.83rem;color:#065f46">追加のSQL・ライブラリ・ランチャ・Blueprint作業はありません。</div>';
        h+='</div></div>';
    });
    h+='<div class="warning-box">🔄 取り込み後は <strong>Webアプリのリロード</strong>が必要です。上のSQL・pip・ランチャは自動実行されません。新規アプリは app.py への Blueprint 登録も別途必要です。</div>';
    return h;
}


// ========== ガーベージコレクション（admin専用・破壊的） ==========
// UI入口は当面設けない（破壊的操作のため）。エンドポイント（/app_share/gc_*）と
// 以下のコードは温存してあり、openGC() を呼ぶボタンを管理タブに追加すれば復活する。
let gcToken=null, gcReport=null;
function gcHideConfirm(){$('#gc-warn,#gc-confirm-label,#gc-confirm,#gc-exec-btn').hide()}
function gcShowConfirm(){$('#gc-warn').show();$('#gc-confirm-label,#gc-exec-btn').css('display','inline-block');$('#gc-confirm').css('display','inline-block')}
function openGC(){
    gcToken=null;gcReport=null;
    $('#gc-preview-area,#gc-result').hide().empty();$('#gc-progress').hide();
    gcHideConfirm();
    $('#gc-confirm').val('');$('#gc-exec-btn').prop('disabled',true);
    $('#gc-download').hide();$('#gc-preview-btn').prop('disabled',false);
    $('#gc-modal').addClass('active');
}
function closeGC(){$('#gc-modal').removeClass('active')}
$('#gc-modal').click(function(e){if(e.target===this)closeGC()});
function gcSetProgress(done,total,label){
    const pct=total?Math.round(done/total*100):0;
    $('#gc-progress-bar').css('width',pct+'%');
    $('#gc-progress-label').text(`解析中… ${done}/${total}`+(label?'（'+label+'）':''));
}
function runGCPreview(){
    gcToken=null;gcReport=null;
    $('#gc-result').hide().empty();$('#gc-preview-area').hide().empty();$('#gc-download').hide();
    gcHideConfirm();
    $('#gc-preview-btn').prop('disabled',true);
    $('#gc-progress').show();gcSetProgress(0,1,'準備中');
    $.ajax({url:'/app_share/gc_preview_init',method:'POST',contentType:'application/json',data:'{}',
        success(r){
            if(!r.success){gcPreviewFail(r.error);return}
            const token=r.token,total=r.total;
            gcSetProgress(0,total,'開始');
            gcStep(token,0,total);
        },
        error(xhr){gcPreviewFail(xhr.responseJSON?.error||xhr.statusText)}});
}
function gcStep(token,index,total){
    if(index>=total){gcFinish(token);return}
    $.ajax({url:'/app_share/gc_preview_step',method:'POST',contentType:'application/json',
        data:JSON.stringify({token:token,index:index}),
        success(r){
            if(!r.success){gcPreviewFail(r.error);return}
            gcSetProgress(r.processed,r.total,r.label);
            gcStep(token,index+1,total);
        },
        error(xhr){gcPreviewFail(xhr.responseJSON?.error||xhr.statusText)}});
}
function gcFinish(token){
    $('#gc-progress-label').text('集計中…');
    $.ajax({url:'/app_share/gc_preview_finish',method:'POST',contentType:'application/json',
        data:JSON.stringify({token:token}),
        success(r){
            $('#gc-progress').hide();$('#gc-preview-btn').prop('disabled',false);
            if(!r.success){gcPreviewFail(r.error);return}
            gcToken=r.token;
            gcRenderPreview(r);
        },
        error(xhr){gcPreviewFail(xhr.responseJSON?.error||xhr.statusText)}});
}
function gcPreviewFail(msg){
    $('#gc-progress').hide();$('#gc-preview-btn').prop('disabled',false);
    showResult('プレビューエラー: '+msg,true);
}
function gcRenderPreview(r){
    let h=`<div class="info-box" style="margin:0 0 10px">対象ベース: <code>${esc(r.details.base_dir)}</code><br>削除ディレクトリ: <strong>${r.dir_count}件</strong> ／ DROPするテーブル: <strong>${r.table_count}件</strong></div>`;
    // 残す方の app.py Blueprint 登録（主役）
    if(r.details.blueprint_keep){
        h+=`<h3>🧩 削除後の app.py Blueprint登録（この内容で置き換え）</h3>
            <div style="font-size:.8rem;color:#64748b;margin-bottom:4px">生き残るアプリ全部の登録です。app.py の該当ブロックをこれで置き換えてください（fujinp配下以外＝auth等の行はそのまま残す）。</div>
            <textarea id="gc-bpkeep" readonly style="width:100%;min-height:180px;font-family:monospace;font-size:.82rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px">${esc(r.details.blueprint_keep)}</textarea>
            <div><button class="secondary btn-sm" onclick="copyEl('gc-bpkeep',this)">📋 コピー</button></div>`;
    }
    // dirs
    h+='<h3>📁 削除するディレクトリ（未登録アプリ）</h3>';
    if(r.plan.dirs.length){h+='<div class="gc-list">'+r.plan.dirs.map(d=>'🗑 '+esc(d)).join('<br>')+'</div>';}
    else{h+='<p class="muted" style="color:#065f46">削除対象のディレクトリはありません。</p>';}
    // tables per db
    h+='<h3>🗄 DROPするテーブル</h3>';
    let anyTbl=false;
    (r.details.databases||[]).forEach(db=>{
        h+=`<div class="gc-list"><div class="gc-db">DB: ${esc(db.database)}${db.error?' <span style="color:#991b1b">（接続エラー: '+esc(db.error)+'）</span>':''}</div>`;
        const drop=db.tables_to_drop||[];
        if(drop.length){anyTbl=true;h+=drop.map(t=>'🗑 '+esc(t)).join('<br>');}
        else if(!db.error){h+='<span style="color:#065f46">DROP対象なし</span>';}
        h+='</div>';
    });
    if(!anyTbl){h+='<p class="muted" style="color:#065f46">DROP対象のテーブルはありません。</p>';}
    // blueprint unregister（外す方・折りたたみ）
    if(r.details.blueprint_unregister){
        h+=`<details style="margin-top:10px"><summary style="cursor:pointer;font-size:.85rem;color:#64748b">🧩 参考: 削除するアプリの登録（外す行）</summary>
            <textarea id="gc-bp" readonly style="width:100%;min-height:70px;font-family:monospace;font-size:.82rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px;margin-top:6px">${esc(r.details.blueprint_unregister)}</textarea>
            <div><button class="secondary btn-sm" onclick="copyEl('gc-bp',this)">📋 コピー</button></div></details>`;
    }
    // kept summary
    h+=`<details style="margin-top:10px"><summary style="cursor:pointer;font-size:.85rem;color:#64748b">保持されるもの（参考）</summary>
        <div style="font-size:.82rem;color:#475569;margin-top:6px">登録アプリ: ${(r.details.registered_apps||[]).map(esc).join(', ')||'なし'}<br>
        保護ディレクトリ・非アプリのディレクトリ: ${(r.details.kept_dirs||[]).concat(r.details.non_app_dirs_skipped||[]).map(esc).join(', ')||'なし'}<br>
        <span style="color:#64748b">${esc(r.details.match_note||'')}</span></div></details>`;
    $('#gc-preview-area').html(h).show();
    $('#gc-confirm').val('');$('#gc-exec-btn').prop('disabled',true);
    if(r.dir_count+r.table_count>0){gcShowConfirm();}
    else{gcHideConfirm();showResult('削除対象はありませんでした。',false);}
}
function gcConfirmChanged(){
    $('#gc-exec-btn').prop('disabled', $('#gc-confirm').val()!=='DELETE' || !gcToken);
}
function runGCExecute(){
    if(!gcToken||$('#gc-confirm').val()!=='DELETE')return;
    if(!confirm('本当に削除しますか？この操作は元に戻せません。'))return;
    $('#loading').show();
    $.ajax({url:'/app_share/gc_execute',method:'POST',contentType:'application/json',
        data:JSON.stringify({token:gcToken,confirm:'DELETE'}),
        success(r){
            if(!r.success){
                showResult('実行エラー: '+r.error,true);
                if(r.changed){gcHideConfirm();$('#gc-preview-area').hide();$('#gc-confirm').val('');}
                return;
            }
            gcReport=r;
            let h=`<div class="success-box"><strong>✅ 完了</strong> — ディレクトリ ${r.deleted_dir_count}件削除 ／ テーブル ${r.dropped_table_count}件DROP（${esc(r.generated_at)}）</div>`;
            h+='<h3>🗑 削除したディレクトリ</h3>';
            h+=r.deleted_dirs.length?('<div class="gc-list">'+r.deleted_dirs.map(esc).join('<br>')+'</div>'):'<p class="muted">なし</p>';
            h+='<h3>🗑 DROPしたテーブル</h3>';
            h+=r.dropped_tables.length?('<div class="gc-list">'+r.dropped_tables.map(t=>esc(t.database)+' . '+esc(t.table)).join('<br>')+'</div>'):'<p class="muted">なし</p>';
            if(r.blueprint_keep){h+=`<h3>🧩 削除後の app.py Blueprint登録（この内容で置き換え）</h3><div style="font-size:.8rem;color:#64748b;margin-bottom:4px">生き残るアプリ全部の登録です。app.py の該当ブロックをこれで置き換えてリロードしてください（auth等の fujinp配下以外の行は残す）。</div><textarea id="gc-bpk2" readonly style="width:100%;min-height:180px;font-family:monospace;font-size:.82rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px">${esc(r.blueprint_keep)}</textarea><div><button class="secondary btn-sm" onclick="copyEl('gc-bpk2',this)">📋 コピー</button></div>`;}
            if(r.blueprint_unregister){h+=`<details style="margin-top:10px"><summary style="cursor:pointer;font-size:.85rem;color:#64748b">🧩 参考: 削除したアプリの登録（外す行）</summary><textarea id="gc-bp2" readonly style="width:100%;min-height:70px;font-family:monospace;font-size:.82rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px;margin-top:6px">${esc(r.blueprint_unregister)}</textarea><div><button class="secondary btn-sm" onclick="copyEl('gc-bp2',this)">📋 コピー</button></div></details>`;}
            const errs=(r.dir_errors||[]).concat([]);
            if((r.dir_errors||[]).length||(r.table_errors||[]).length){
                h+='<h3 style="color:#991b1b">⚠ エラー・スキップ</h3><div class="gc-list">';
                (r.dir_errors||[]).forEach(e=>{h+='📁 '+esc(e.name)+': '+esc(e.error)+'<br>'});
                (r.table_errors||[]).forEach(e=>{h+='🗄 '+esc(e.database||'')+(e.table?'.'+esc(e.table):'')+': '+esc(e.error)+'<br>'});
                h+='</div>';
            }
            $('#gc-result').html(h).show();
            gcHideConfirm();
            $('#gc-download').show();
            loadLocalApps();
            showResult('ガーベージコレクションを実行しました。',false);
        },
        error(xhr){showResult('実行エラー: '+(xhr.responseJSON?.error||xhr.statusText),true)},
        complete(){$('#loading').hide()}});
}
function downloadGCReport(){
    if(!gcReport)return;
    const blob=new Blob([JSON.stringify(gcReport,null,2)],{type:'application/json'});
    const a=document.createElement('a');
    a.href=URL.createObjectURL(blob);
    a.download='gc_report_'+(gcReport.generated_at||'').replace(/[^0-9]/g,'')+'.json';
    document.body.appendChild(a);a.click();document.body.removeChild(a);
}

// ========== アプリ管理（診断・管理ノート、admin専用） ==========
let mgApp=null, mgDiag=null, _mgId=0;
function openMgmt(name){mgApp=name;$('#mg-app').text(name);$('#mg-body').html('<p style="color:#9ca3af">診断中...</p>');$('#mgmt-modal').addClass('active');runDiag();}
function closeMgmt(){$('#mgmt-modal').removeClass('active');mgApp=null;mgDiag=null}
$('#mgmt-modal').click(function(e){if(e.target===this)closeMgmt()});
function mgOK(b,ok,ng){return b?('<span class="badge badge-success">✅ '+(ok||'あり')+'</span>'):('<span class="badge badge-danger">❌ '+(ng||'なし')+'</span>')}
function mgBox(title,inner,status){return `<div class="vs"><div class="vs-h" style="display:flex;justify-content:space-between;align-items:center"><span>${title}</span><span>${status||''}</span></div><div class="vs-b">${inner}</div></div>`}
function mgSql(id,text,rows){return `<textarea id="${id}" readonly style="width:100%;min-height:${rows||70}px;font-family:monospace;font-size:.8rem;background:#1e293b;color:#e2e8f0;border-radius:6px;padding:8px;margin-top:4px">${esc(text)}</textarea>`}
function runDiag(){
    if(!mgApp)return;$('#loading').show();
    $.ajax({url:'/app_share/app_diagnosis/'+encodeURIComponent(mgApp),
        success(r){
            if(!r.success){showResult('診断エラー: '+r.error,true);return}
            mgDiag=r.diagnosis;renderDiag(r.diagnosis);
        },
        error(xhr){showResult('診断エラー: '+(xhr.responseJSON?.error||xhr.statusText),true)},
        complete(){$('#loading').hide()}});
}
function renderDiag(d){
    let h='';
    // 📦 ファイル構成
    const f=d.files||{};
    h+=mgBox('📦 ファイル構成',
        `ディレクトリ ${mgOK(f.dir_exists)}　__init__.py ${mgOK(f.has_init)}　routes.py ${mgOK(f.has_routes)}　templates ${mgOK(f.has_templates)}　app_info ${mgOK(f.has_app_info)}`,
        (f.dir_exists&&f.has_init)?'<span class="badge badge-success">OK</span>':'<span class="badge badge-danger">要確認</span>');
    // 🗂 レジストリ
    const g=d.registry||{};
    h+=mgBox('🗂 レジストリ（カード表示）',
        g.registered?`登録済み: ${esc(g.icon||'')} ${esc(g.display_name||'')}　<span style="font-size:.8rem;color:#64748b">版: ${esc(g.updated_at||'-')}　ID: <code>${esc(g.version_id||'-')}</code></span>`
            :`未登録です。 <button class="primary btn-sm" onclick="mgRegAdd()">＋ レジストリに登録</button>`,
        mgOK(g.registered,'登録済み','未登録'));
    // 🧩 Blueprint
    const b=d.blueprint||{};
    let bph='';
    if(!b.defined){bph='<span style="font-size:.85rem;color:#991b1b">Blueprint 定義が見つかりません（__init__.py / routes.py を確認してください）。</span>';}
    else{
        bph=b.registered_in_app_py
            ?'<div style="color:#065f46;font-size:.85rem">app.py に登録済みです。</div>'
            :'<div style="color:#991b1b;font-size:.85rem">app.py に未登録の可能性があります。以下を app.py に追記してリロードしてください。</div>';
        if(b.snippet){const id='mg-bp-'+(_mgId++);bph+=mgSql(id,b.snippet)+`<div style="margin-top:4px"><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`}
    }
    h+=mgBox('🧩 Blueprint登録（app.py）',bph,
        b.defined?mgOK(b.registered_in_app_py,'登録済み','未登録?'):'<span class="badge badge-gray">不明</span>');
    // 🔗 ランチャ
    let lh='',lfound=false;
    (d.launchers||[]).forEach(l=>{
        lh+=`<div style="margin-bottom:6px"><strong style="font-size:.85rem">${esc(l.source)}</strong>: ${l.found?'<span class="badge badge-success">✅ あり</span>':'<span class="badge badge-warning">なし</span>'}`;
        if(l.found&&l.snippet){lfound=true;const id='mg-ln-'+(_mgId++);lh+=mgSql(id,l.snippet,60)+`<div style="margin-top:4px"><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`}
        lh+='</div>';
    });
    h+=mgBox('🔗 ランチャ（ダッシュボード掲載）',lh||'<span style="color:#64748b;font-size:.85rem">情報なし</span>',
        lfound?'<span class="badge badge-success">OK</span>':'<span class="badge badge-warning">未設置?</span>');
    // 🗄 SQLテーブル
    // 1テーブル = ヘッダ1行（名前・バッジ・ボタン・確認結果を左から並べる）＋ SQL。
    // テーブル間は破線（---）で仕切る。
    let th='',tmiss=0;
    const tbls=d.tables||[];
    if(!tbls.length)th='<span style="color:#64748b;font-size:.85rem">スキーマ情報（app_info.json の mysql_schema / schema.sql）が見つかりません。</span>';
    const mgRow=(inner)=>`<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">${inner}</div>`;
    const mgHr='<hr style="border:none;border-top:1px dashed #cbd5e1;margin:12px 0">';
    tbls.forEach((t,i)=>{
        if(i>0)th+=mgHr;
        const id='mg-tb-'+i;
        const nm=`<code style="font-weight:700">${esc(t.table)}</code>`;
        if(t.status==='missing'){
            tmiss++;
            th+=mgRow(`${nm} <span class="badge badge-danger">❌ 未作成</span>
                <button class="primary btn-sm" onclick="copyEl('${id}',this)">📋 コピーしてMySQLコンソールで実行</button>
                <button class="success btn-sm" onclick="mgTblCheck(${i},'${id}')">✅ 実行後確認</button>
                <span id="${id}-st"></span>`)+mgSql(id,t.create_sql||'');
        }else if(t.status==='diff'&&t.alter_sql){
            th+=mgRow(`${nm} <span class="badge badge-warning">⚠ カラム不足</span>
                <button class="primary btn-sm" onclick="copyEl('${id}',this)">📋 コピーしてMySQLコンソールで実行</button>
                <button class="success btn-sm" onclick="mgTblCheck(${i},'${id}')">✅ 実行後確認</button>
                <span id="${id}-st"></span>`)+mgSql(id,t.alter_sql,50);
        }else if(t.status==='same'||t.status==='diff'){
            th+=mgRow(`${nm} <span class="badge badge-success">✅ 作成済み</span>${t.database?' <span style="font-size:.75rem;color:#64748b">('+esc(t.database)+')</span>':''}${(t.status==='diff')?' <span style="font-size:.75rem;color:#92400e">※定義差あり（追加不要）</span>':''}`);
        }else{
            th+=mgRow(`${nm} <span class="badge badge-gray">${esc(t.status)}</span>`);
        }
    });
    h+=mgBox('🗄 SQLテーブル（技術仕様書のスキーマと照合）',th,
        tbls.length?(tmiss?`<span class="badge badge-danger">未作成 ${tmiss}件</span>`:'<span class="badge badge-success">OK</span>'):'<span class="badge badge-gray">-</span>');
    // 📚 ライブラリ
    const libs=d.libraries||[];const miss=libs.filter(x=>!x.installed);
    let ph=libs.length?libs.map(x=>`<code>${esc(x.name)}</code> ${x.installed?'✅':'❌'}`).join('　'):'<span style="color:#64748b;font-size:.85rem">サードパーティ依存なし</span>';
    if(miss.length){const id='mg-pip-'+(_mgId++);ph+=mgSql(id,'pip install --user '+miss.map(x=>x.pip_name).join(' '),40)+`<div style="margin-top:4px"><button class="secondary btn-sm" onclick="copyEl('${id}',this)">📋 コピー</button></div>`}
    h+=mgBox('📚 ライブラリ',ph,
        miss.length?`<span class="badge badge-danger">未検出 ${miss.length}件</span>`:'<span class="badge badge-success">OK</span>');
    // 📖 ドキュメント
    // 技術仕様書＝アプリ内の app_info.json（📋 仕様書ボタンで編集）。has_app_info を見る。
    // dc.spec は doc_type='spec' の「仕様書メモ」で別物。あれば併記する。
    const dc=d.docs||{};
    const hasSpec=!!(d.files&&d.files.has_app_info);
    let docLine=`マニュアル ${mgOK(dc.manual&&dc.manual.exists)}　技術仕様書 ${mgOK(hasSpec)}　管理ノート ${mgOK(dc.note&&dc.note.exists)}`;
    if(dc.spec&&dc.spec.exists) docLine+=`　仕様書メモ ${mgOK(true)}`;
    h+=mgBox('📖 ドキュメント',docLine,'');
    // 🗒 管理ノート
    const note=dc.note||{};
    let nh='';
    if(note.exists&&note.content){
        nh+=`<div class="md-r" style="max-height:280px;overflow-y:auto;border:1px solid #e5e7eb;border-radius:6px;padding:12px;background:#fff">${marked.parse(note.content)}</div>
            <div style="font-size:.75rem;color:#64748b;margin-top:4px">最終更新: ${esc(note.updated_at||'-')}</div>`;
    }else{
        nh+='<div style="color:#9ca3af;font-size:.85rem">まだノートがありません。下から追記するか、エディタで作成してください。</div>';
    }
    nh+=`<div style="margin-top:8px">
        <textarea id="mg-note-quick" rows="2" style="width:100%;padding:8px;border:1px solid #d1d5db;border-radius:6px;font-size:.85rem" placeholder="ここに書いて「追記」→ 日付見出し（## YYYY-MM-DD HH:MM）つきでノート末尾に追加されます"></textarea>
        <div style="margin-top:4px">
            <button class="success btn-sm" onclick="mgNoteAppend()">➕ 日付つきで追記</button>
            <button class="primary btn-sm" onclick="location.href='/app_share/doc/'+encodeURIComponent(mgApp)+'/note/edit'">📝 エディタで編集（Markdown）</button>
        </div></div>`;
    h+=mgBox('🗒 管理ノート（admin専用）',nh,
        note.exists?'<span class="badge badge-success">あり</span>':'<span class="badge badge-gray">なし</span>');
    h+=`<div style="font-size:.72rem;color:#94a3b8;text-align:right">診断: ${esc(d.generated_at||'')}</div>`;
    $('#mg-body').html(h);
}
function mgRegAdd(){
    if(!mgApp)return;
    $.ajax({url:'/app_share/registry/add',method:'POST',contentType:'application/json',
        data:JSON.stringify({app_name:mgApp,display_name:mgApp,icon:'📦',description:''}),
        success(r){if(r.success){showResult(r.message,false);loadLocalApps();runDiag();}else showResult('エラー: '+r.error,true)},
        error(){showResult('登録エラー',true)}});
}
function mgTblCheck(i,stPrefix){
    const t=(mgDiag&&mgDiag.tables||[])[i];if(!t)return;
    $('#loading').show();
    $.ajax({url:'/app_share/import_table_check',method:'POST',contentType:'application/json',
        data:JSON.stringify({table:t.table,create_sql:t.create_sql||''}),
        success(r){
            const $st=$('#'+stPrefix+'-st');
            if(r.success&&r.resolved)$st.html('<span class="badge badge-success">✅ 確認済み・完了</span>');
            else if(r.success&&r.status==='missing')$st.html('<span class="badge badge-danger">確認できません（未作成）</span>');
            else if(r.success)$st.html('<span class="badge badge-warning">確認できません（不足カラム: '+(r.added_columns||[]).map(a=>esc(a.name)).join(', ')+'）</span>');
            else $st.html('<span class="badge badge-danger">確認エラー</span>');
        },
        error(){showResult('確認エラー',true)},complete(){$('#loading').hide()}});
}
function mgNoteAppend(){
    const t=$('#mg-note-quick').val().trim();
    if(!t){alert('追記する内容を入力してください');return}
    $('#loading').show();
    $.ajax({url:'/app_share/app_note_append/'+encodeURIComponent(mgApp),method:'POST',contentType:'application/json',
        data:JSON.stringify({text:t}),
        success(r){if(r.success){showResult('ノートに追記しました',false);runDiag();}else showResult('エラー: '+r.error,true)},
        error(xhr){showResult('追記エラー: '+(xhr.responseJSON?.error||xhr.statusText),true)},
        complete(){$('#loading').hide()}});
}

