    <style>
        *{margin:0;padding:0;box-sizing:border-box}
        body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;background:linear-gradient(135deg,#6366f1 0%,#8b5cf6 100%);min-height:100vh;padding:15px}
        .container{max-width:1400px;margin:0 auto}
        .header{background:#fff;padding:15px 25px;border-radius:10px;margin-bottom:15px;box-shadow:0 2px 4px rgba(0,0,0,.1)}
        h1{color:#333;font-size:1.5rem;margin-bottom:5px}.subtitle{color:#666;font-size:.9rem}
        .hdr-btns{float:right;display:flex;gap:8px;align-items:center}
        .hdr-btns a{padding:8px 16px;border:none;border-radius:5px;cursor:pointer;text-decoration:none;font-size:.85rem;font-weight:600;color:#fff;background:#6366f1}
        .hdr-btns a:hover{background:#4f46e5}
        .role-badge{display:inline-block;padding:3px 10px;border-radius:12px;font-size:.75rem;font-weight:600;margin-left:10px;background:#f3e8ff;color:#7c3aed}
        .panel{background:#fff;padding:20px;border-radius:10px;box-shadow:0 2px 4px rgba(0,0,0,.1)}
        h2{color:#333;margin-bottom:15px;font-size:1.2rem}
        button{padding:8px 16px;border:none;border-radius:5px;cursor:pointer;font-weight:600;font-size:.85rem;transition:.3s}
        button.primary{background:#6366f1;color:#fff}button.primary:hover{background:#4f46e5}
        button.secondary{background:#e5e7eb;color:#374151}button.secondary:hover{background:#d1d5db}
        .app-list{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:15px;margin:15px 0}
        .app-card{background:#f9fafb;border:1px solid #e5e7eb;border-radius:8px;padding:15px;transition:.3s}
        .app-card:hover{border-color:#a5b4fc;box-shadow:0 2px 8px rgba(99,102,241,.15)}
        .app-card .card-top{display:flex;align-items:center;gap:10px;margin-bottom:6px}
        .app-card .card-icon{font-size:1.8rem;line-height:1}
        .app-card .card-titles{flex:1;min-width:0}
        .app-card .card-name{font-weight:700;color:#333;font-size:.95rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
        .app-card .card-dir{font-size:.75rem;color:#999}
        .app-card .card-desc{font-size:.82rem;color:#555;line-height:1.4;height:2.8em;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;margin-bottom:10px}
        .app-card .card-actions{display:flex;gap:6px;flex-wrap:wrap;border-top:1px solid #e5e7eb;padding-top:10px}
        .app-card .card-actions button{padding:5px 10px;font-size:.78rem;border-radius:4px}
        .btn-manual{background:#0ea5e9;color:#fff}.btn-manual:hover{background:#0284c7}
