        /* モーダル */
        .modal-overlay{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.5);z-index:1000;overflow-y:auto}
        .modal-overlay.active{display:flex;justify-content:center;align-items:flex-start;padding:20px}
        .modal{background:#fff;border-radius:10px;max-width:1100px;width:100%;max-height:95vh;overflow-y:auto;margin:20px 0}
        .modal-header{padding:15px 20px;border-bottom:1px solid #e5e7eb;display:flex;justify-content:space-between;align-items:center;position:sticky;top:0;background:#fff;z-index:10}
        .modal-header h2{margin:0;font-size:1.2rem}
        .modal-close{background:none;border:none;font-size:1.5rem;cursor:pointer;color:#666;padding:0}
        .modal-body{padding:20px}
        .modal-footer{padding:15px 20px;border-top:1px solid #e5e7eb;display:flex;gap:10px;justify-content:flex-end;position:sticky;bottom:0;background:#fff}
        .man-meta{font-size:.8rem;color:#888;margin-bottom:15px;padding-bottom:10px;border-bottom:1px solid #eee;display:flex;gap:20px}
        .man-empty{text-align:center;padding:40px;color:#9ca3af}
        .man-empty .me-icon{font-size:3rem;margin-bottom:10px}
        /* Markdownレンダリング */
        .md-r{line-height:1.8;color:#374151}
        .md-r h1{font-size:1.5rem;border-bottom:2px solid #e2e8f0;padding-bottom:8px;margin:18px 0 12px}
        .md-r h2{font-size:1.25rem;border-bottom:1px solid #e2e8f0;padding-bottom:6px;color:#1e40af;margin:16px 0 10px}
        .md-r h3{font-size:1.05rem;color:#555;margin:14px 0 8px}
        .md-r p{margin:8px 0}
        .md-r ul,.md-r ol{margin:8px 0 8px 24px}
        .md-r li{margin:4px 0}
        .md-r code{background:#f1f5f9;padding:2px 6px;border-radius:4px;font-family:Consolas,Monaco,monospace;font-size:.85em}
        .md-r pre{background:#1e293b;color:#e2e8f0;padding:16px;border-radius:8px;overflow-x:auto;margin:12px 0}
        .md-r pre code{background:none;color:inherit;padding:0}
        .md-r table{border-collapse:collapse;width:100%;margin:12px 0;font-size:.9rem}
        .md-r th,.md-r td{border:1px solid #d1d5db;padding:8px 12px;text-align:left}
        .md-r th{background:#f3f4f6}
        .md-r blockquote{border-left:4px solid #c7d2fe;padding-left:12px;color:#666;margin:10px 0}
        .md-r img{max-width:100%;height:auto}
    </style>
</head>
<body>
<div class="container">
    <div class="header">
        <div class="hdr-btns">
            <a href="{{ url_for('guest.dashboard') }}">← ダッシュボードに戻る</a>
        </div>
        <h1>📦 アプシャ（App Share）<span class="role-badge">マニュアル閲覧</span></h1>
        <p class="subtitle">FUJIN-P アプリのユーザーズマニュアル</p>
    </div>
    <div class="panel">
        <h2>📖 アプリ一覧</h2>
        <p style="margin-bottom:15px;color:#666">各アプリの「📖 マニュアル」ボタンでユーザーズマニュアルを表示します。</p>
        <div id="app-list" class="app-list">
            <div class="empty-msg">読み込み中...</div>
        </div>
    </div>
</div>

<div id="manual-modal" class="modal-overlay">
    <div class="modal">
        <div class="modal-header"><h2>📖 <span id="man-title">ユーザマニュアル</span></h2><button class="modal-close" onclick="closeManual()">&times;</button></div>
        <div class="modal-body">
            <div class="man-meta" id="man-meta" style="display:none"><span>📝 更新: <span id="man-date"></span></span><span>👤 <span id="man-author"></span></span></div>
            <div id="man-body"></div>
        </div>
        <div class="modal-footer">
            <button class="secondary" onclick="openManualPage()">🔗 単独ページ</button>
            <button class="secondary" onclick="copyManualUrl()">📋 URLコピー</button>
            <button class="secondary" onclick="closeManual()">閉じる</button>
        </div>
    </div>
</div>

<script>
marked.setOptions({breaks:true,gfm:true});
function esc(t){return t?t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'):''}

// ========== アプリ一覧 ==========
function loadApps(){
    $.ajax({url:'/app_share/get_registry_apps',success(r){
        const $l=$('#app-list').empty();
        if(!r.success){$l.html('<div class="empty-msg">読み込みエラー</div>');return}
        if(!r.apps||!r.apps.length){$l.html('<div class="empty-msg">登録されているアプリがありません。</div>');return}
        r.apps.forEach(a=>{
            $l.append(`<div class="app-card" data-name="${a.app_name}">
                <div class="card-top">
                    <div class="card-icon">${a.icon||'📦'}</div>
                    <div class="card-titles">
                        <div class="card-name">${esc(a.display_name||a.app_name)}</div>
                        <div class="card-dir">${esc(a.app_name)}</div>
                    </div>
                </div>
                <div class="card-desc">${esc(a.description||'')}</div>
                <div class="card-actions">
                    <button class="btn-manual" onclick="openManual('${a.app_name}','${esc(a.display_name||a.app_name)}')">📖 マニュアル</button>
                </div>
            </div>`);
        });
    },error(){$('#app-list').html('<div class="empty-msg">読み込みエラー</div>')}});
}

// ========== マニュアル閲覧モーダル ==========
let manApp=null;
function openManual(name,display){
    manApp=name;
    $('#man-title').text('ユーザマニュアル - '+(display||name));
    $('#man-body').html('<p style="text-align:center;padding:40px;color:#9ca3af">読み込み中...</p>');
    $('#man-meta').hide();$('#manual-modal').addClass('active');
    $.ajax({url:`/app_share/doc/${name}/manual/get`,success(r){
        if(r.success&&r.doc&&r.doc.content){
            const d=r.doc;
            $('#man-body').html('<div class="md-r">'+marked.parse(d.content)+'</div>');
            if(d.updated_at||d.updated_by_name){
                $('#man-date').text(d.updated_at||'');
                $('#man-author').text(d.updated_by_name||'');
                $('#man-meta').show();
            }
        }else{
            $('#man-body').html('<div class="man-empty"><div class="me-icon">📖</div><p>まだマニュアルが作成されていません。</p></div>');
        }
    },error(){$('#man-body').html('<p style="color:red;text-align:center;padding:40px">読み込みエラー</p>')}});
}
function closeManual(){$('#manual-modal').removeClass('active');manApp=null}
// マニュアル単独ページ（URL直アクセス）: /app_share/manual/<app_name>
function openManualPage(){if(manApp)window.open('/app_share/manual/'+encodeURIComponent(manApp),'_blank')}
function copyManualUrl(){if(!manApp)return;const u=location.origin+'/app_share/manual/'+encodeURIComponent(manApp);
    if(navigator.clipboard){navigator.clipboard.writeText(u).then(()=>alert('マニュアルURLをコピーしました:\n'+u)).catch(()=>prompt('このURLをコピーしてください',u))}
    else prompt('このURLをコピーしてください',u)}
$('#manual-modal').click(function(e){if(e.target===this)closeManual()});
$(document).on('keydown',function(e){if(e.key==='Escape')closeManual()});

// ========== 初期化 ==========
$(document).ready(loadApps);
</script>
</body>
</html>

