           background:#fdfdfe;overflow:hidden;max-width:980px}
.bulk-head{display:flex;align-items:center;flex-wrap:wrap;gap:6px 14px;
           padding:11px 15px;background:#f4f7fa;border-bottom:1px solid #e0e4e8}
.bulk-title{font-size:13.5px;font-weight:700;color:#1a3a5c}
.bulk-desc{flex:1;min-width:200px;font-size:11.5px;color:#777}
.bulk-ops{display:flex;gap:6px;align-items:center}
.bulk-ops .b-copy:disabled{opacity:.4;cursor:not-allowed}
.bulk-ops .b-copy.copied{background:#27ae60;color:#fff;border-color:#27ae60}
.bulk-ops a.btn-toggle{text-decoration:none;display:inline-block}
.bulk-pre{margin:0;padding:13px 16px;background:#1e272e;color:#e8edf1;
          font-family:Consolas,Monaco,'Courier New',monospace;font-size:12px;
          line-height:1.55;white-space:pre;overflow:auto;max-height:380px;
          border-top:1px solid #2c3a44}
.bulk-pre.b-loading{color:#9fb3c8;font-style:italic}
.bulk-pre.b-error{color:#ffb4b4}

/* ページャー */
#pager{display:none;align-items:center;gap:6px;padding:6px 12px;
       background:#f8f9fa;border-top:1px solid #ddd;flex-shrink:0;flex-wrap:wrap}
.pg-btn{padding:3px 9px;border:1px solid #ddd;border-radius:3px;
        cursor:pointer;font-size:11px;background:#fff}
.pg-btn.active{background:#2e6da4;color:#fff;border-color:#2e6da4;font-weight:bold}
.pg-btn:disabled{opacity:.4;cursor:not-allowed}
#pager-info{font-size:11px;color:#888;margin-left:4px}

.loading-msg{color:#aaa;padding:40px;text-align:center;font-style:italic}

/* モーダル（共通） */
.modal-bg{display:none;position:fixed;inset:0;background:rgba(0,0,0,.45);z-index:100;
          align-items:center;justify-content:center}
.modal-box{background:#fff;border-radius:8px;width:380px;max-width:92vw;
           max-height:92vh;display:flex;flex-direction:column;
           box-shadow:0 8px 30px rgba(0,0,0,.3)}
.modal-box.wide{width:640px}
.modal-box h2{background:#1a3a5c;color:#fff;font-size:14px;padding:11px 16px;
              border-radius:8px 8px 0 0;flex-shrink:0}
.modal-box .body{padding:16px;overflow-y:auto}
.modal-box label{display:block;font-size:11px;font-weight:700;color:#555;margin:10px 0 3px}
.modal-box label:first-child{margin-top:0}
.modal-box input,.modal-box select,.modal-box textarea{
  width:100%;padding:7px 9px;border:1px solid #ccc;border-radius:4px;font-size:13px}
.modal-box textarea{font-family:Consolas,Monaco,'Courier New',monospace;
                    font-size:12px;resize:vertical;min-height:110px}
.modal-box .req{color:#e74c3c}
.modal-box .hint{font-size:10px;color:#999;margin-top:2px}
.modal-box .actions{display:flex;justify-content:flex-end;gap:8px;
                    padding:12px 16px;border-top:1px solid #eee;flex-shrink:0}
.modal-box .actions button{padding:7px 16px;border:none;border-radius:4px;
                           font-size:12px;font-weight:700;cursor:pointer}
.btn-ok{background:#27ae60;color:#fff}
.btn-ok:hover{background:#219150}
.btn-cancel{background:#ecf0f1;color:#555}
.btn-preview{background:#2e6da4;color:#fff;margin-right:auto}
.btn-preview:hover{background:#255a8a}

/* 試し実行プレビュー */
#iv-preview{display:none;margin-top:10px;border:1px solid #e2e8f0;border-radius:4px;
            max-height:200px;overflow:auto}
#iv-preview-info{display:none;font-size:11px;margin-top:8px;font-weight:600}
#iv-preview-info.ok{color:#065f46}
#iv-preview-info.ng{color:#991b1b}

/* トースト */
#toast{position:fixed;bottom:22px;right:22px;padding:13px 20px;border-radius:8px;
       font-size:13px;font-weight:600;z-index:9999;display:none;max-width:340px;
       box-shadow:0 4px 12px rgba(0,0,0,.2)}
#toast.success{background:#d1fae5;color:#065f46}
#toast.error{background:#fee2e2;color:#991b1b}
</style>
</head>
<body>

<div id="header">
  <h1>📚 公式データ集（内容確認中）</h1>
  <a href="{{ url_for('official_data_archive.return_to_fujin') }}" class="btn-return">🏠 FUJIN-Pダッシュボードに戻る</a>
</div>

<!-- トップメニュー（タブ切り替え） -->
<div id="tabs">
  <button class="tab active" data-tab="tables">📁 公式テーブル</button>
  <button class="tab" data-tab="indicator-views">📈 単一指標</button>
  <button class="tab" data-tab="composites">📉 複合指標</button>
  <button class="tab" data-tab="bulk">📦 一括ダウンロード</button>
  <button class="tab" data-tab="updates">🔄 データ更新</button>
</div>

<!-- ============================================================
     タブ：公式テーブル
============================================================ -->
<div class="tab-pane" id="pane-tables">
<div class="split">

  <!-- 左ペイン -->
  <div class="left-pane">
    <div class="left-header">
      <span>📁 公式テーブル一覧</span>
      <button id="btn-add" class="btn-add">➕ 追加</button>
    </div>
    <div id="table-list" class="item-list">
      <div class="loading-msg">取得中...</div>
    </div>
  </div>

  <!-- 右ペイン -->
  <div class="right-pane">

    <div id="placeholder" class="placeholder">
      <div style="font-size:36px">📋</div>
      <div>左のリストから公式テーブルを選んでください</div>
      <div style="font-size:11px">読み取り専用で閲覧できます</div>
    </div>

    <div id="viewer-toolbar" class="viewer-toolbar">
      <span id="viewer-title" class="viewer-title"></span>
      <span class="readonly-badge">🔒 読み取り専用</span>
      <span id="viewer-count" class="viewer-count"></span>
      <input id="search-input" type="text" placeholder="絞り込み検索...">
      <a id="dl-btn" href="#" class="dl-btn">⬇️ XLSX</a>
    </div>
    <div id="viewer-note"></div>

    <div id="viewer-scroll" class="viewer-scroll" style="display:none">
      <table id="data-table" class="dtable">
        <thead id="data-thead"></thead>
        <tbody id="data-tbody"></tbody>
      </table>
    </div>

    <div id="pager"></div>

  </div>
</div>
</div><!-- /pane-tables -->

<!-- ============================================================
     タブ：単一指標
============================================================ -->
<div class="tab-pane hidden" id="pane-indicator-views">
<div class="split">

  <!-- 左ペイン -->
  <div class="left-pane">
    <div class="left-header">
      <span>📊 単一指標一覧</span>
      <button id="iv-btn-add" class="btn-add">➕ 追加</button>
    </div>
    <div id="iv-list" class="item-list">
      <div class="loading-msg">取得中...</div>
    </div>
  </div>

  <!-- 右ペイン -->
  <div class="right-pane">

    <div id="iv-placeholder" class="placeholder">
      <div style="font-size:36px">📊</div>
      <div>左のリストから単一指標を選んでください</div>
      <div style="font-size:11px">SQLクエリと実行結果（年度ごとの指標値）を表示します</div>
    </div>

    <div id="iv-toolbar" class="viewer-toolbar">
      <span id="iv-title" class="viewer-title"></span>
      <span class="readonly-badge">🔒 読み取り専用</span>
      <span id="iv-count" class="viewer-count"></span>
      <button id="iv-btn-edit" class="icon-btn" title="この単一指標を編集" style="display:none">✏️ 編集</button>
      <a id="iv-dl-btn" href="#" class="dl-btn">⬇️ XLSX</a>
    </div>

    <div id="iv-content">

      <div id="iv-sql">
        <div class="sql-label">SQLクエリ</div>
        <pre id="iv-sql-text"></pre>
      </div>
      <div id="iv-truncated"></div>

      <!-- 実行結果テーブル（展開＝全行表示／たたむ＝非表示） -->
      <div id="iv-table-sec">
        <div class="sec-header">
          <span class="g-title">📋 実行結果テーブル</span>
          <button id="iv-tbl-toggle" class="btn-toggle">▲ たたむ</button>
        </div>
        <div id="iv-scroll">
          <table id="iv-table" class="dtable">
            <thead id="iv-thead"></thead>
            <tbody id="iv-tbody"></tbody>
          </table>
        </div>
      </div>

      <!-- グラフ表示（テーブルの下） -->
      <div id="iv-graph-wrap">
        <div id="iv-graph-header">
          <span class="g-title">📊 グラフ</span>
          <div class="seg">
            <button id="iv-mode-bar"  class="active">棒グラフ</button>
            <button id="iv-mode-line">折れ線</button>
          </div>
          <button id="iv-svg-dl"   class="btn-toggle" title="グラフをSVGファイルとしてダウンロード">⬇ SVG</button>
          <button id="iv-svg-copy" class="btn-toggle" title="SVGテキストをクリップボードにコピー">📋 SVGコピー</button>
        </div>
        <div id="iv-graph-body">
          <div id="iv-graph-msg"></div>
          <canvas id="iv-chart"></canvas>
        </div>
      </div>

    </div><!-- /iv-content -->

  </div>
</div>
</div><!-- /pane-indicator-views -->

<!-- ============================================================
     タブ：複合指標
============================================================ -->
<div class="tab-pane hidden" id="pane-composites">
<div class="split">

  <!-- 左ペイン -->
  <div class="left-pane">
    <div class="left-header">
      <span>📉 複合指標一覧</span>
      <button id="cp-btn-add" class="btn-add">➕ 追加</button>
    </div>
    <div id="cp-list" class="item-list">
      <div class="loading-msg">取得中...</div>
    </div>
  </div>

  <!-- 右ペイン -->
  <div class="right-pane">

    <div id="cp-placeholder" class="placeholder">
      <div style="font-size:36px">📉</div>
      <div>左のリストから複合指標を選んでください</div>
      <div style="font-size:11px">構成する単一指標の折れ線グラフを指定色で重ねて表示します（縦軸は0〜最大値）</div>
    </div>

    <div id="cp-toolbar" class="viewer-toolbar">
      <span id="cp-title" class="viewer-title"></span>
      <span class="readonly-badge">🔒 読み取り専用</span>
      <span id="cp-count" class="viewer-count"></span>
      <button id="cp-btn-edit" class="icon-btn" title="この複合指標を編集" style="display:none">✏️ 編集</button>
      <button id="cp-svg-dl"   class="btn-toggle" title="グラフをSVGファイルとしてダウンロード">⬇ SVG</button>
      <button id="cp-svg-copy" class="btn-toggle" title="SVGテキストをクリップボードにコピー">📋 SVGコピー</button>
    </div>
    <div id="cp-errors"></div>

    <div id="cp-graph-body">
      <div id="cp-graph-msg"></div>
      <canvas id="cp-chart"></canvas>
    </div>

  </div>
</div>
</div><!-- /pane-composites -->

<!-- ============================================================
     タブ：一括ダウンロード
============================================================ -->
<div class="tab-pane hidden" id="pane-bulk">
  <div class="bulk-wrap">
    <p class="bulk-intro">
      登録されている公式テーブル・指標の定義情報を、種類ごとにまとめて取り出せます。
      各項目とも「表示」で本文を読み込み、📋 でクリップボードにコピー、⬇ でファイルとして保存できます。
    </p>

    <div class="bulk-card" data-kind="tablenames">
      <div class="bulk-head">
        <div class="bulk-title">📋 テーブル名一括</div>
        <div class="bulk-desc">登録簿に載っている公式テーブルの名前一覧（DB別・表示名つき）</div>
        <div class="bulk-ops">
          <button class="btn-toggle b-show">表示</button>
          <button class="btn-toggle b-copy" disabled>📋 コピー</button>
          <a class="btn-toggle b-dl" href="#">⬇ ダウンロード</a>
        </div>
      </div>
      <pre class="bulk-pre hidden"></pre>
    </div>

    <div class="bulk-card" data-kind="schema">
      <div class="bulk-head">
        <div class="bulk-title">🧱 スキーマ一括</div>
        <div class="bulk-desc">各テーブルの詳細な定義（SHOW CREATE TABLE による DDL）</div>
        <div class="bulk-ops">
          <button class="btn-toggle b-show">表示</button>
          <button class="btn-toggle b-copy" disabled>📋 コピー</button>
          <a class="btn-toggle b-dl" href="#">⬇ ダウンロード</a>
        </div>
      </div>
      <pre class="bulk-pre hidden"></pre>
    </div>

    <div class="bulk-card" data-kind="indicators">
      <div class="bulk-head">
        <div class="bulk-title">📈 単一指標一括</div>
        <div class="bulk-desc">登録された単一指標の定義（名称・表示順位・グラフ種別・SQL）</div>
        <div class="bulk-ops">
          <button class="btn-toggle b-show">表示</button>
          <button class="btn-toggle b-copy" disabled>📋 コピー</button>
          <a class="btn-toggle b-dl" href="#">⬇ ダウンロード</a>
        </div>
      </div>
      <pre class="bulk-pre hidden"></pre>
    </div>

    <div class="bulk-card" data-kind="composites">
      <div class="bulk-head">
        <div class="bulk-title">📉 複合指標一括</div>
        <div class="bulk-desc">登録された複合指標と、その構成（単一指標と色）の一覧</div>
        <div class="bulk-ops">
          <button class="btn-toggle b-show">表示</button>
          <button class="btn-toggle b-copy" disabled>📋 コピー</button>
          <a class="btn-toggle b-dl" href="#">⬇ ダウンロード</a>
        </div>
      </div>
      <pre class="bulk-pre hidden"></pre>
    </div>
  </div>
</div><!-- /pane-bulk -->

<!-- ============================================================
     タブ：データ更新
============================================================ -->
<div class="tab-pane hidden" id="pane-updates">
  <div class="up-bar">
    <span class="g-title">🔄 公式テーブルの更新履歴</span>
    <button id="up-btn-new" class="btn-add" style="display:none">⬆ 更新データを提供</button>
  </div>
  <div class="up-scroll">
    <table class="dtable" id="up-table">
      <thead>
        <tr>
          <th>対象テーブル</th>
          <th>提供者</th>
          <th>提供日時</th>
          <th>メモ</th>
          <th>状態</th>
          <th>転記者</th>
          <th>転記/処理日時</th>
          <th>バックアップ</th>
          <th>操作</th>
        </tr>
      </thead>
      <tbody id="up-tbody">
        <tr><td class="loading-msg" colspan="9">取得中...</td></tr>
      </tbody>
    </table>
  </div>
</div><!-- /pane-updates -->

<!-- ============================================================
     モーダル：公式テーブルの追加
============================================================ -->
<div id="modal-bg" class="modal-bg">
  <div id="modal" class="modal-box">
    <h2>➕ 公式テーブルにアイテムを追加</h2>
    <div class="body">
      <label>テーブル名 <span class="req">*</span></label>
      <input id="in-table" type="text" placeholder="例: T_10_01_貸借対照表">
      <div class="hint">英数字・日本語が使えます（空白や記号 ` ' " % ; などは不可）。登録時に実在確認をします。</div>
      <label>データベース <span class="req">*</span></label>
      <select id="in-db"></select>
      <label>管理グループ <span class="req">*</span></label>
      <select id="in-group"></select>
      <div class="hint">このアイテムを管理（追加・削除）できる まいぐるグループ。
        「公式データ集_」で始まるグループが選べます。</div>
      <label>表示名（任意）</label>
      <input id="in-disp" type="text" placeholder="例: 財務データ（収支）">
      <label>説明（任意）</label>
      <input id="in-note" type="text" placeholder="例: 業務実績報告書の基礎データ">
    </div>
    <div class="actions">
      <button id="btn-modal-cancel" class="btn-cancel">キャンセル</button>
      <button id="btn-modal-ok" class="btn-ok">登録</button>
    </div>
  </div>
</div>

<!-- ============================================================
     モーダル：単一指標の追加・編集
============================================================ -->
<div id="iv-modal-bg" class="modal-bg">
  <div class="modal-box wide">
    <h2 id="iv-modal-title">➕ 単一指標を追加</h2>
    <div class="body">
      <label>指標名 <span class="req">*</span></label>
      <input id="iv-in-name" type="text" placeholder="例: 入学定員充足率">
      <label>SQLクエリ <span class="req">*</span></label>
      <textarea id="iv-in-query" rows="7"
        placeholder="SELECT 年度, ... AS 指標値&#10;FROM T_03_01_学部入試実施状況&#10;GROUP BY 年度 ORDER BY 年度"></textarea>
      <div class="hint">単文のSELECTのみ。年度と指標値のペアを返す形を推奨します（複数列でも表示できます）。</div>
      <label>表示順位数 <span class="req">*</span></label>
      <input id="iv-in-order" type="number" value="100" step="0.001"
             min="0" max="99999999.999">
      <div class="hint">数が小さいほど一覧の上位に表示されます。整数部8桁・小数3桁まで（例: 100、100.5、100.125）。</div>
      <label>管理グループ <span class="req">*</span></label>
      <select id="iv-in-group"></select>
      <div id="iv-preview-info"></div>
      <div id="iv-preview">
        <table class="dtable">
          <thead id="iv-preview-thead"></thead>
          <tbody id="iv-preview-tbody"></tbody>
        </table>
      </div>
    </div>
    <div class="actions">
      <button id="iv-btn-preview" class="btn-preview">▶ 試し実行</button>
      <button id="iv-btn-cancel" class="btn-cancel">キャンセル</button>
      <button id="iv-btn-save" class="btn-ok">保存</button>
    </div>
  </div>
</div>

<!-- ============================================================
     モーダル：複合指標の追加・編集
============================================================ -->
<div id="cp-modal-bg" class="modal-bg">
  <div class="modal-box wide">
    <h2 id="cp-modal-title">➕ 複合指標を追加</h2>
    <div class="body">
      <label>複合指標名 <span class="req">*</span></label>
      <input id="cp-in-name" type="text" placeholder="例: 入学・就職の主要指標">
      <label>構成（単一指標と色のペア、最大5つ） <span class="req">*</span></label>
      <div id="cp-comp-rows"></div>
      <button id="cp-comp-add" class="btn-toggle" style="margin-top:8px">＋ 構成指標を追加</button>
      <label>表示順位数 <span class="req">*</span></label>
      <input id="cp-in-order" type="number" value="100" step="10">
      <div class="hint">数が小さいほど一覧の上位に表示されます。</div>
      <label>管理グループ <span class="req">*</span></label>
      <select id="cp-in-group"></select>
    </div>
    <div class="actions">
      <button id="cp-btn-cancel" class="btn-cancel">キャンセル</button>
      <button id="cp-btn-save" class="btn-ok">保存</button>
    </div>
  </div>
</div>

<!-- ============================================================
     モーダル：更新データの提供
============================================================ -->
<div id="up-modal-bg" class="modal-bg">
  <div class="modal-box">
    <h2>⬆ 更新データを提供</h2>
    <div class="body">
      <label>対象の公式テーブル <span class="req">*</span></label>
      <select id="up-in-item"></select>
      <div class="hint">担当している（管理グループに所属する）テーブルのみ選べます。</div>
      <label>Excelファイル（.xlsx） <span class="req">*</span></label>
      <input id="up-in-file" type="file" accept=".xlsx">
      <div class="hint">列構成は現テーブルと完全一致が必要です。まず公式テーブルタブから
        現在のXLSXをダウンロードし、それを編集してください。受付時に列構成を照合します。</div>
      <label>メモ（任意）</label>
      <input id="up-in-note" type="text" placeholder="例: 2026年度分を追記">
    </div>
    <div class="actions">
      <button id="up-btn-cancel" class="btn-cancel">キャンセル</button>
      <button id="up-btn-send" class="btn-ok">提供する</button>
    </div>
  </div>
</div>

<div id="toast"></div>

<script>
const URL_TABLES      = '{{ url_for("official_data_archive.api_tables") }}';
const URL_ADD         = '{{ url_for("official_data_archive.api_table_add") }}';
const URL_DELETE      = '{{ url_for("official_data_archive.api_table_delete") }}';
const URL_DATA        = '{{ url_for("official_data_archive.api_data") }}';
const URL_DOWNLOAD    = '{{ url_for("official_data_archive.api_download") }}';
const URL_IV_LIST     = '{{ url_for("official_data_archive.api_indicators") }}';
const URL_IV_RUN      = '{{ url_for("official_data_archive.api_indicator_run") }}';
const URL_IV_PREVIEW  = '{{ url_for("official_data_archive.api_indicator_preview") }}';
const URL_IV_SAVE     = '{{ url_for("official_data_archive.api_indicator_save") }}';
const URL_IV_CHARTTYPE = '{{ url_for("official_data_archive.api_indicator_chart_type") }}';
