let currentDb     = '';
let currentOffset = 0;

function esc(s){
  return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function toast(msg,isError){
  const $t=$('#toast');
  $t.text(msg).removeClass('success error')
    .addClass(isError?'error':'success').fadeIn();
  setTimeout(()=>$t.fadeOut(),4000);
}
function postJson(url, payload){
  return $.ajax({url:url, method:'POST', contentType:'application/json',
                 data:JSON.stringify(payload)});
}
// 行レンダリング（公式テーブル・単一指標・プレビュー共通）
function fillTable($thead, $tbody, columns, rows, baseOffset){
  let ths = '<th class="rn">#</th>';
  columns.forEach(function(c){ ths += '<th>'+esc(c)+'</th>'; });
  $thead.html('<tr>'+ths+'</tr>');
  $tbody.empty();
  if(!rows.length){
    $tbody.html('<tr><td class="loading-msg" colspan="'+(columns.length+1)+
                '">データがありません</td></tr>');
    return;
  }
  rows.forEach(function(row,i){
    let tds = '<td class="rn">'+((baseOffset||0)+i+1)+'</td>';
    columns.forEach(function(col){
      const v = row[col];
      tds += (v===null||v===undefined)
        ? '<td><span class="null-v">NULL</span></td>'
        : '<td title="'+esc(String(v))+'">'+esc(String(v))+'</td>';
    });
    $tbody.append('<tr>'+tds+'</tr>');
  });
}

