function loadTableList(){
  $.get(URL_TABLES, function(data){
    if(!data.success){
      $('#table-list').html('<div class="loading-msg" style="color:#e74c3c">'+esc(data.error)+'</div>');
      return;
    }
    $('#btn-add').toggle(!!data.can_add);

    // 追加モーダルのDB選択肢
    const $sel = $('#in-db').empty();
    (data.db_choices||[]).forEach(function(k){
      $sel.append($('<option>').val(k).text(k)
        .prop('selected', k==='fujinp'));
    });

    // 追加モーダルの管理グループ選択肢
    // （全体管理者には「指定なし＝全体管理者専管」も出す）
    const $grp = $('#in-group').empty();
    if(data.is_global){
      $grp.append($('<option>').val('').text('（指定なし：全体管理者のみ管理）'));
    }
    (data.manage_groups||[]).forEach(function(g){
      $grp.append($('<option>').val(g.id).text(g.name));
    });

    const $list = $('#table-list').empty();
    if(!data.tables.length){
      $list.html('<div class="loading-msg">公式テーブルはまだありません</div>');
      return;
    }
    data.tables.forEach(function(t){
      const $item = $('<div class="tbl-item">');
      const dispName = t.display_name || t.table_name;
      const rowStr   = t.row_count !== null ? t.row_count+'行' : '?';
      const sub      = t.database_name + ' / ' + t.table_name;
      const grpHtml  = t.manager_group_name
        ? '<div class="tbl-grp" title="管理グループ">👥 '+esc(t.manager_group_name)+'</div>'
        : '';
      $item.attr('title', t.note || '');
      $item.html(
        '<div style="flex:1;min-width:0">' +
          '<div class="tbl-name">'+esc(dispName)+'</div>' +
          '<div class="tbl-sub">'+esc(sub)+'</div>' +
          grpHtml +
        '</div>' +
        '<span class="tbl-rows">'+esc(rowStr)+'</span>' +
        (t.can_manage
          ? '<button class="icon-btn tbl-del" title="公式テーブルから削除">🗑</button>'
          : '')
      );
      $item.on('click', function(){
        $('#table-list .tbl-item').removeClass('active');
        $item.addClass('active');
        loadTableData(t, 0);
      });
      $item.find('.tbl-del').on('click', function(ev){
        ev.stopPropagation();
        deleteItem(t);
      });
      $list.append($item);
    });
  }).fail(function(){
    $('#table-list').html('<div class="loading-msg" style="color:#e74c3c">取得失敗</div>');
  });
}

