$('#btn-modal-cancel').on('click', function(){ $('#modal-bg').hide(); });

$('#btn-modal-ok').on('click', function(){
  const grpVal = $('#in-group').val();
  const payload = {
    table_name:       $('#in-table').val().trim(),
    database_name:    $('#in-db').val(),
    manager_group_id: grpVal ? parseInt(grpVal, 10) : null,
    display_name:     $('#in-disp').val().trim(),
    note:             $('#in-note').val().trim()
  };
  if(!payload.table_name){ toast('テーブル名を入力してください', true); return; }
  if($('#in-group option').length === 0){
    toast('指定できる管理グループがありません', true); return;
  }
  postJson(URL_ADD, payload).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    $('#modal-bg').hide();
    toast('公式テーブルに追加しました');
    loadTableList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
});

function deleteItem(t){
  const name = t.display_name || t.table_name;
  if(!confirm('「'+name+'」を公式テーブルから削除します。\n' +
              '（登録簿から外すだけで、SQLテーブル自体は削除されません）\n' +
              'よろしいですか？')) return;
  postJson(URL_DELETE, {id: t.id}).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    toast('削除しました');
    if(currentTable===t.table_name && currentDb===t.database_name){
      $('#viewer-toolbar').hide(); $('#viewer-scroll').hide();
      $('#viewer-note').hide(); $('#pager').hide();
      $('#placeholder').css('display','flex');
      currentTable=''; currentDb='';
    }
    loadTableList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
}

