function loadTableData(t, offset){
  currentTable  = t.table_name;
  currentDb     = t.database_name;
  currentOffset = offset;

  $('#placeholder').hide();
  $('#viewer-toolbar').css('display','flex');
  $('#viewer-scroll').show();
  $('#viewer-title').text(t.display_name
      ? t.display_name+'（'+t.table_name+'）' : t.table_name);
  if(t.note){ $('#viewer-note').text('📝 '+t.note).show(); }
  else      { $('#viewer-note').hide(); }
  $('#viewer-count').text('読み込み中...');
  $('#data-tbody').html('<tr><td class="loading-msg" colspan="999">取得中...</td></tr>');
  $('#pager').hide().empty();

  $.get(URL_DATA, {
    table: t.table_name, db: t.database_name,
    limit: PAGE_SIZE, offset: offset
  }, function(data){
    if(!data.success){
      $('#data-tbody').html(
        '<tr><td class="loading-msg" style="color:#e74c3c" colspan="999">'+
        esc(data.error)+'</td></tr>');
      return;
    }
    allColumns = data.columns;
    allRows    = data.rows;

    $('#viewer-count').text(
      (offset+1)+'〜'+(offset+data.fetched_count)+' 件 ／ 全'+data.total_count+'件');

    $('#dl-btn')
      .attr('href', URL_DOWNLOAD
            + '?table=' + encodeURIComponent(t.table_name)
            + '&db='    + encodeURIComponent(t.database_name))
      .show();

    fillTable($('#data-thead'), $('#data-tbody'), allColumns, allRows, offset);
    renderPager(data.total_count, offset, t);
  }).fail(function(){
    $('#data-tbody').html(
      '<tr><td class="loading-msg" style="color:#e74c3c" colspan="999">通信エラー</td></tr>');
  });
}

// ページャー
function renderPager(total, offset, t){
  const $pg = $('#pager').empty();
  if(total <= PAGE_SIZE){ $pg.hide(); return; }
  $pg.css('display','flex');

  const totalPages  = Math.ceil(total / PAGE_SIZE);
  const currentPage = Math.floor(offset / PAGE_SIZE) + 1;

  function mkBtn(label, page, disabled, active){
    const $b = $('<button class="pg-btn">').text(label)
      .prop('disabled', disabled)
      .toggleClass('active', active);
    if(!disabled) $b.on('click', function(){ loadTableData(t, (page-1)*PAGE_SIZE); });
    return $b;
  }

  $pg.append(mkBtn('«', 1, currentPage===1, false));
  $pg.append(mkBtn('‹', currentPage-1, currentPage===1, false));
  const start = Math.max(1, currentPage-3);
  const end   = Math.min(totalPages, start+6);
  for(let p=start; p<=end; p++){
    $pg.append(mkBtn(p, p, false, p===currentPage));
  }
  $pg.append(mkBtn('›', currentPage+1, currentPage===totalPages, false));
  $pg.append(mkBtn('»', totalPages, currentPage===totalPages, false));
  $pg.append($('<span id="pager-info">').text(
    currentPage+'ページ ／ 全'+totalPages+'ページ（'+total+'件）'));
}

// 絞り込み（現在ページ内のみ）
$('#search-input').on('input', function(){
  const kw = $(this).val().toLowerCase();
  if(!kw){
    fillTable($('#data-thead'), $('#data-tbody'), allColumns, allRows, currentOffset);
    return;
  }
  const filtered = allRows.filter(function(row){
    return allColumns.some(function(col){
      const v = row[col];
      return v!==null && v!==undefined && String(v).toLowerCase().includes(kw);
    });
  });
  fillTable($('#data-thead'), $('#data-tbody'), allColumns, filtered, currentOffset);
});

