// 表示順位数の整形：小数第3位までで、末尾の不要なゼロを落とす。
//   100 → "100"、100.5 → "100.5"、100.125 → "100.125"
function fmtOrder(n){
  if(n === null || n === undefined || n === '') return '';
  const num = Number(n);
  if(isNaN(num)) return String(n);
  return String(Math.round(num * 1000) / 1000);
}

