let ivChart     = null;     // Chart.js インスタンス
let ivChartMode = 'bar';    // 'bar' / 'line'
let ivChartData = null;     // 直近の実行結果 {columns, rows}

function hideIvGraph(){
  $('#iv-graph-wrap').hide();
  if(ivChart){ ivChart.destroy(); ivChart = null; }
  ivChartData = null;
}

// 実行結果からグラフ用データを取り出す。
// 1列目をX軸ラベル（年度想定）、2列目以降で最初に数値が取れる列をY値とする。
function extractSeries(columns, rows){
  if(!columns || columns.length < 2 || !rows || !rows.length) return null;
  const xCol = columns[0];
  for(let i = 1; i < columns.length; i++){
    const c = columns[i];
    const vals = rows.map(r => parseFloat(r[c]));
    if(vals.some(v => !isNaN(v))){
      return {
        xLabel: xCol,
        yLabel: c,
        labels: rows.map(r => String(r[xCol] ?? '')),
        values: vals.map(v => isNaN(v) ? null : v)
      };
    }
  }
  return null;
}

function renderIvChart(){
  if(!ivChartData) return;
  const s = extractSeries(ivChartData.columns, ivChartData.rows);
  $('#iv-graph-wrap').css('display','flex');
  if(ivChart){ ivChart.destroy(); ivChart = null; }
  if(!s){
    $('#iv-chart').hide();
    $('#iv-graph-msg').text('数値列が見つからないためグラフ化できません')
                      .css('display','flex');
    return;
  }
  $('#iv-graph-msg').hide();
  $('#iv-chart').show();

  // 縦軸は 0〜最大値（＋10%の頭上余白）
  const nums = s.values.filter(v => v !== null);
  let vmax = Math.max.apply(null, nums);
  if(!isFinite(vmax) || vmax <= 0) vmax = 1;

  ivChart = new Chart(document.getElementById('iv-chart'), {
    type: ivChartMode,
    data: {
      labels: s.labels,
      datasets: [{
        label: s.yLabel,
        data: s.values,
        backgroundColor: 'rgba(46,109,164,0.65)',
        borderColor: '#2e6da4',
        borderWidth: 2,
        pointBackgroundColor: '#2e6da4',
        pointRadius: ivChartMode === 'line' ? 3 : 0,
        tension: 0,
        spanGaps: true
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 200 },
      plugins: { legend: { display: false } },
      scales: {
        x: { title: { display: true, text: s.xLabel,
                      font: { size: 11 } },
             ticks: { font: { size: 11 } } },
        y: { min: 0, max: vmax * 1.1,
             title: { display: true, text: s.yLabel,
                      font: { size: 11 } },
             ticks: { font: { size: 11 } } }
      }
    }
  });
}

// グラフ種別の見た目（ボタンのactive状態）と変数を同期する。
