// ============================================================
// 単一指標：SVGアウトプット
//   Chart.js は canvas 描画のため、同じデータ・同じスケールから
//   スタンドアロンのSVGを自前生成する（テキストとして持ち出せる）。
// ============================================================
function niceTicks(min, max, n){
  const span  = (max - min) || 1;
  const step0 = span / n;
  const mag   = Math.pow(10, Math.floor(Math.log(step0)/Math.LN10));
  let step = 10 * mag;
  [1, 2, 5, 10].some(function(m){
    if(step0 <= m * mag){ step = m * mag; return true; }
    return false;
  });
  const ticks = [];
  const i0 = Math.ceil(min / step), i1 = Math.floor(max / step);
  for(let i = i0; i <= i1; i++){
    // 浮動小数の誤差を丸める
    ticks.push(parseFloat((i * step).toPrecision(12)));
  }
  return ticks;
}

function buildIvSvg(){
  if(!ivChartData) return null;
  const s = extractSeries(ivChartData.columns, ivChartData.rows);
  if(!s) return null;
  const nums = s.values.filter(v => v !== null);
  if(!nums.length) return null;

  let vmax0 = Math.max.apply(null, nums);
  if(!isFinite(vmax0) || vmax0 <= 0) vmax0 = 1;
  const ymin = 0, ymax = vmax0 * 1.1;

  const W = 720, H = 340, mL = 76, mR = 24, mT = 40, mB = 64;
  const pw = W - mL - mR, ph = H - mT - mB;
  const n  = s.labels.length;
  const X  = i => mL + pw * (i + 0.5) / n;
  const Y  = v => mT + ph * (1 - (v - ymin) / (ymax - ymin));
  const title = ivCurrent ? ivCurrent.name : s.yLabel;

  const o = [];
  o.push('<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H +
         '" viewBox="0 0 ' + W + ' ' + H + '" font-family="sans-serif">');
  o.push('<rect width="' + W + '" height="' + H + '" fill="#ffffff"/>');
  // タイトル
  o.push('<text x="' + (W/2) + '" y="22" text-anchor="middle" font-size="14" ' +
         'font-weight="bold" fill="#1a3a5c">' + esc(title) + '</text>');
  // 横グリッドとY目盛
  niceTicks(ymin, ymax, 5).forEach(function(t){
    const y = Y(t);
    o.push('<line x1="' + mL + '" y1="' + y + '" x2="' + (W - mR) + '" y2="' + y +
           '" stroke="#e5e7eb" stroke-width="1"/>');
    o.push('<text x="' + (mL - 8) + '" y="' + (y + 3.5) +
           '" text-anchor="end" font-size="11" fill="#6b7280">' + t + '</text>');
  });
  // 軸線
  o.push('<line x1="' + mL + '" y1="' + mT + '" x2="' + mL + '" y2="' + (mT + ph) +
         '" stroke="#9ca3af" stroke-width="1"/>');
  o.push('<line x1="' + mL + '" y1="' + (mT + ph) + '" x2="' + (W - mR) + '" y2="' +
         (mT + ph) + '" stroke="#9ca3af" stroke-width="1"/>');
  // データ
  if(ivChartMode === 'bar'){
    const bw = pw / n * 0.6;
    s.values.forEach(function(v, i){
      if(v === null) return;
      const y = Y(v);
      o.push('<rect x="' + (X(i) - bw/2) + '" y="' + Math.min(y, mT + ph) +
             '" width="' + bw + '" height="' + Math.abs(mT + ph - y) +
             '" fill="#2e6da4" fill-opacity="0.75"/>');
    });
  } else {
    const pts = [];
    s.values.forEach(function(v, i){
      if(v !== null) pts.push(X(i) + ',' + Y(v));
    });
    if(pts.length > 1){
      o.push('<polyline points="' + pts.join(' ') +
             '" fill="none" stroke="#2e6da4" stroke-width="2"/>');
    }
    s.values.forEach(function(v, i){
      if(v === null) return;
      o.push('<circle cx="' + X(i) + '" cy="' + Y(v) +
             '" r="3" fill="#2e6da4"/>');
    });
  }
  // X軸ラベル（多いときは斜めに）
  const rotate = n > 12;
  s.labels.forEach(function(lb, i){
    const x = X(i), y = mT + ph + 16;
    if(rotate){
      o.push('<text x="' + x + '" y="' + y + '" text-anchor="end" font-size="10" ' +
             'fill="#374151" transform="rotate(-45 ' + x + ' ' + y + ')">' +
             esc(lb) + '</text>');
    } else {
      o.push('<text x="' + x + '" y="' + y +
             '" text-anchor="middle" font-size="11" fill="#374151">' +
             esc(lb) + '</text>');
    }
  });
  // 軸タイトル
  o.push('<text x="' + (mL + pw/2) + '" y="' + (H - 10) +
         '" text-anchor="middle" font-size="11" fill="#6b7280">' +
         esc(s.xLabel) + '</text>');
  o.push('<text x="16" y="' + (mT + ph/2) + '" text-anchor="middle" font-size="11" ' +
         'fill="#6b7280" transform="rotate(-90 16 ' + (mT + ph/2) + ')">' +
         esc(s.yLabel) + '</text>');
  o.push('</svg>');
  return o.join('\n');
}

$('#iv-svg-dl').on('click', function(){
  const svg = buildIvSvg();
  if(!svg){ toast('グラフ化できるデータがありません', true); return; }
  const blob = new Blob([svg], {type: 'image/svg+xml;charset=utf-8'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const base = (ivCurrent ? ivCurrent.name : 'indicator')
                 .replace(/[\\/:*?"<>|]/g, '_');
  a.download = base + '.svg';
  document.body.appendChild(a);
  a.click();
  setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 500);
});

$('#iv-svg-copy').on('click', function(){
  const svg = buildIvSvg();
  if(!svg){ toast('グラフ化できるデータがありません', true); return; }
  function ok(){ toast('SVGをクリップボードにコピーしました'); }
  function ng(){ toast('クリップボードへのコピーに失敗しました', true); }
  function fallback(){
    const ta = document.createElement('textarea');
    ta.value = svg;
    document.body.appendChild(ta);
    ta.select();
    try { document.execCommand('copy') ? ok() : ng(); }
    catch(e){ ng(); }
    ta.remove();
  }
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(svg).then(ok, fallback);
  } else {
    fallback();
  }
});

function runIndicator(v){
