$('#iv-btn-save').on('click', function(){
  const grpVal = $('#iv-in-group').val();
  // グラフ種別は既存値を維持する。表示中の指標を編集している場合は
  // いま選ばれているモードを優先（直前のトグル操作も保持される）。
  let chartType = ivEditingChartType;
  if(ivEditingId && ivCurrent && ivCurrent.id === ivEditingId){
    chartType = ivChartMode;
  }
  const payload = {
    id:               ivEditingId,
    name:             $('#iv-in-name').val().trim(),
    query:            $('#iv-in-query').val().trim(),
    sort_order:       parseFloat($('#iv-in-order').val()),
    chart_type:       chartType,
    manager_group_id: grpVal ? parseInt(grpVal, 10) : null
  };
  if(!payload.name){ toast('指標名を入力してください', true); return; }
  if(!payload.query){ toast('SQLクエリを入力してください', true); return; }
  if(isNaN(payload.sort_order)){
    toast('表示順位数は数値で入力してください', true); return;
  }
  if(payload.sort_order < 0 || payload.sort_order > 99999999.999){
    toast('表示順位数は0〜99999999.999の範囲で入力してください', true); return;
  }
  // 小数第3位までに丸める（整数部8桁・小数3桁）
  payload.sort_order = Math.round(payload.sort_order * 1000) / 1000;
  postJson(URL_IV_SAVE, payload).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    $('#iv-modal-bg').hide();
    toast(ivEditingId ? '単一指標を更新しました' : '単一指標を追加しました');
    // 編集した指標を表示中なら再実行して反映
    if(ivEditingId && ivCurrent && ivCurrent.id === ivEditingId){
      ivCurrent.name       = payload.name;
      ivCurrent.query      = payload.query;
      ivCurrent.sort_order = payload.sort_order;
      ivCurrent.chart_type = payload.chart_type;
      runIndicator(ivCurrent);
    }
    loadIvList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
});

