const CP_PALETTE = ['#2e6da4','#e74c3c','#27ae60','#f59e0b','#8e44ad'];
let cpCurrent   = null;   // 表示中の複合指標
let cpChart     = null;   // Chart.js インスタンス
let cpSeries    = null;   // 直近の実行結果（抽出済み系列の配列）
let cpMax       = 5;      // 構成の最大数（APIから上書き）
let cpOptions   = [];     // 単一指標の選択肢
