      $item.html(
        '<div style="flex:1;min-width:0">' +
          '<div class="tbl-name">'+esc(c.name)+'</div>' +
          '<div class="tbl-sub">表示順位 '+esc(c.sort_order)+
          '　構成 '+(c.components||[]).length+'</div>' +
