// ── 実行・オーバーレイ描画 ──
function unionLabels(seriesList){
  const set = new Set();
  seriesList.forEach(function(s){ s.labels.forEach(function(l){ set.add(l); }); });
  return Array.from(set).sort(function(a,b){
    return String(a).localeCompare(String(b), 'ja', {numeric:true});
  });
}

function runComposite(c){
  cpCurrent = c;
  $('#cp-placeholder').hide();
  $('#cp-toolbar').css('display','flex');
  $('#cp-title').text(c.name);
  $('#cp-count').text('実行中...');
  $('#cp-btn-edit').toggle(!!c.can_manage);
  $('#cp-errors').hide();
  $('#cp-graph-body').show();
  $('#cp-graph-msg').hide();
  $('#cp-chart').show();
  if(cpChart){ cpChart.destroy(); cpChart = null; }
  cpSeries = null;

  $.get(URL_CP_RUN, {id: c.id}, function(data){
    if(!data.success){
      $('#cp-count').text('');
      $('#cp-chart').hide();
      $('#cp-graph-msg').text(data.error).css('display','flex');
      return;
    }
    const errs = [];
    const extracted = [];
    (data.series||[]).forEach(function(sr){
      if(sr.error){ errs.push(sr.name+'：'+sr.error); return; }
      const s = extractSeries(sr.columns, sr.rows);
      if(!s){ errs.push(sr.name+'：数値列が見つかりません'); return; }
      extracted.push({name: sr.name, color: sr.color,
                      labels: s.labels, values: s.values, xLabel: s.xLabel});
    });
    if(errs.length){
      $('#cp-errors').html('⚠️ '+errs.map(esc).join('<br>⚠️ ')).show();
    }
    $('#cp-count').text('構成 '+extracted.length+'／'+(data.series||[]).length);
    if(!extracted.length){
      $('#cp-chart').hide();
      $('#cp-graph-msg').text('表示できる系列がありません').css('display','flex');
      return;
    }
    cpSeries = extracted;
    renderCpChart();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    $('#cp-count').text('');
    $('#cp-chart').hide();
    $('#cp-graph-msg').text(err).css('display','flex');
  });
}

function renderCpChart(){
  if(!cpSeries || !cpSeries.length) return;
  const labels = unionLabels(cpSeries);
  let vmax = -Infinity;
  const datasets = cpSeries.map(function(s){
    const map = {};
    s.labels.forEach(function(l,i){ map[l] = s.values[i]; });
    const data = labels.map(function(l){
      const v = map.hasOwnProperty(l) ? map[l] : null;
      if(v !== null && v > vmax) vmax = v;
      return v;
    });
    return {
      label: s.name, data: data,
      borderColor: s.color, backgroundColor: s.color,
      pointBackgroundColor: s.color,
      borderWidth: 2, pointRadius: 3, tension: 0, spanGaps: true, fill: false
    };
  });
  if(!isFinite(vmax) || vmax <= 0) vmax = 1;

  if(cpChart){ cpChart.destroy(); }
  cpChart = new Chart(document.getElementById('cp-chart'), {
    type: 'line',
    data: { labels: labels, datasets: datasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: { duration: 200 },
      plugins: { legend: { display: true, position: 'top',
                           labels: { font: { size: 11 } } } },
      scales: {
        x: { title: { display: true, text: cpSeries[0].xLabel,
                      font: { size: 11 } },
             ticks: { font: { size: 11 } } },
        y: { min: 0, max: vmax * 1.1,
             ticks: { font: { size: 11 } } }
      }
    }
  });
}

// ── SVGアウトプット（複数系列・凡例付き、縦軸0〜最大値） ──
function buildCpSvg(){
  if(!cpSeries || !cpSeries.length) return null;
  const labels = unionLabels(cpSeries);
  let vmax = -Infinity;
  const mapped = cpSeries.map(function(s){
    const map = {};
    s.labels.forEach(function(l,i){ map[l] = s.values[i]; });
    const data = labels.map(function(l){
      const v = map.hasOwnProperty(l) ? map[l] : null;
      if(v !== null && v > vmax) vmax = v;
      return v;
    });
    return {name: s.name, color: s.color, data: data};
  });
  if(!isFinite(vmax) || vmax <= 0) vmax = 1;
  const ymin = 0, ymax = vmax * 1.1;

  const legH = 18 * mapped.length;
  const W = 720, mL = 76, mR = 24, mT = 44 + legH, mB = 64;
  const ph = 240, H = mT + ph + mB;
  const pw = W - mL - mR;
  const n  = labels.length;
  const X  = function(i){ return mL + pw * (i + 0.5) / n; };
  const Y  = function(v){ return mT + ph * (1 - (v - ymin) / (ymax - ymin)); };

  const o = [];
  o.push('<svg xmlns="http://www.w3.org/2000/svg" width="' + W + '" height="' + H +
         '" viewBox="0 0 ' + W + ' ' + H + '" font-family="sans-serif">');
  o.push('<rect width="' + W + '" height="' + H + '" fill="#ffffff"/>');
  o.push('<text x="' + (W/2) + '" y="22" text-anchor="middle" font-size="14" ' +
         'font-weight="bold" fill="#1a3a5c">' +
         esc(cpCurrent ? cpCurrent.name : '複合指標') + '</text>');
  // 凡例
  mapped.forEach(function(s, i){
    const ly = 38 + i * 18;
    o.push('<line x1="' + mL + '" y1="' + ly + '" x2="' + (mL + 24) + '" y2="' + ly +
           '" stroke="' + esc(s.color) + '" stroke-width="2"/>');
    o.push('<circle cx="' + (mL + 12) + '" cy="' + ly + '" r="3" fill="' +
           esc(s.color) + '"/>');
    o.push('<text x="' + (mL + 30) + '" y="' + (ly + 3.5) +
           '" font-size="11" fill="#374151">' + esc(s.name) + '</text>');
  });
  // 横グリッドとY目盛
  niceTicks(ymin, ymax, 5).forEach(function(t){
    const y = Y(t);
    o.push('<line x1="' + mL + '" y1="' + y + '" x2="' + (W - mR) + '" y2="' + y +
           '" stroke="#e5e7eb" stroke-width="1"/>');
    o.push('<text x="' + (mL - 8) + '" y="' + (y + 3.5) +
           '" text-anchor="end" font-size="11" fill="#6b7280">' + t + '</text>');
  });
  // 軸線
  o.push('<line x1="' + mL + '" y1="' + mT + '" x2="' + mL + '" y2="' + (mT + ph) +
         '" stroke="#9ca3af" stroke-width="1"/>');
  o.push('<line x1="' + mL + '" y1="' + (mT + ph) + '" x2="' + (W - mR) + '" y2="' +
         (mT + ph) + '" stroke="#9ca3af" stroke-width="1"/>');
  // 各系列の折れ線
  mapped.forEach(function(s){
    const pts = [];
    s.data.forEach(function(v, i){
      if(v !== null) pts.push(X(i) + ',' + Y(v));
    });
    if(pts.length > 1){
      o.push('<polyline points="' + pts.join(' ') +
             '" fill="none" stroke="' + esc(s.color) + '" stroke-width="2"/>');
    }
    s.data.forEach(function(v, i){
      if(v === null) return;
      o.push('<circle cx="' + X(i) + '" cy="' + Y(v) + '" r="3" fill="' +
             esc(s.color) + '"/>');
    });
  });
  // X軸ラベル
  const rotate = n > 12;
  labels.forEach(function(lb, i){
    const x = X(i), y = mT + ph + 16;
    if(rotate){
      o.push('<text x="' + x + '" y="' + y + '" text-anchor="end" font-size="10" ' +
             'fill="#374151" transform="rotate(-45 ' + x + ' ' + y + ')">' +
             esc(lb) + '</text>');
    } else {
      o.push('<text x="' + x + '" y="' + y +
             '" text-anchor="middle" font-size="11" fill="#374151">' +
             esc(lb) + '</text>');
    }
  });
  o.push('<text x="' + (mL + pw/2) + '" y="' + (H - 10) +
         '" text-anchor="middle" font-size="11" fill="#6b7280">' +
         esc(cpSeries[0].xLabel) + '</text>');
  o.push('</svg>');
  return o.join('\n');
}

$('#cp-svg-dl').on('click', function(){
  const svg = buildCpSvg();
  if(!svg){ toast('グラフ化できるデータがありません', true); return; }
  const blob = new Blob([svg], {type: 'image/svg+xml;charset=utf-8'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  const base = (cpCurrent ? cpCurrent.name : 'composite')
                 .replace(/[\\/:*?"<>|]/g, '_');
  a.download = base + '.svg';
