function openCpModal(c){
  if(!cpOptions.length){
    toast('先に単一指標を作成してください', true); return;
  }
  cpEditingId = c ? c.id : null;
  $('#cp-modal-title').text(c ? '✏️ 複合指標を編集' : '➕ 複合指標を追加');
  $('#cp-in-name').val(c ? c.name : '');
  $('#cp-in-order').val(c ? c.sort_order : 100);
  if(c && c.manager_group_id){
    $('#cp-in-group').val(String(c.manager_group_id));
  } else {
    $('#cp-in-group').prop('selectedIndex', 0);
  }
  $('#cp-comp-rows').empty();
  if(c && c.components && c.components.length){
    c.components.forEach(function(k){ cpAddCompRow(k.indicator_view_id, k.color); });
  } else {
    cpAddCompRow(null, null);
  }
  $('#cp-modal-bg').css('display','flex');
  $('#cp-in-name').trigger('focus');
}

$('#cp-btn-add').on('click', function(){ openCpModal(null); });
$('#cp-btn-edit').on('click', function(){ if(cpCurrent) openCpModal(cpCurrent); });
$('#cp-comp-add').on('click', function(){ cpAddCompRow(null, null); });
$('#cp-btn-cancel').on('click', function(){ $('#cp-modal-bg').hide(); });

$('#cp-btn-save').on('click', function(){
  const grpVal = $('#cp-in-group').val();
  const components = [];
  $('#cp-comp-rows .comp-row').each(function(){
    components.push({
      indicator_view_id: parseInt($(this).find('select').val(), 10),
      color: $(this).find('input[type=color]').val()
    });
  });
  const payload = {
    id:               cpEditingId,
    name:             $('#cp-in-name').val().trim(),
    sort_order:       parseInt($('#cp-in-order').val(), 10),
    manager_group_id: grpVal ? parseInt(grpVal, 10) : null,
    components:       components
  };
  if(!payload.name){ toast('複合指標名を入力してください', true); return; }
  if(!components.length){ toast('構成を1つ以上指定してください', true); return; }
  if(isNaN(payload.sort_order)){ toast('表示順位数は整数で入力してください', true); return; }
  postJson(URL_CP_SAVE, payload).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    $('#cp-modal-bg').hide();
    toast(cpEditingId ? '複合指標を更新しました' : '複合指標を追加しました');
    cpEditingId = null;
    // 表示中の複合指標を編集した場合に備え、一覧再取得後に再実行
    const shownId = cpCurrent ? cpCurrent.id : null;
    $.get(URL_CP_LIST, function(d){
      loadCpListRender(d);
      if(shownId && d.success){
        const again = (d.composites||[]).find(function(x){ return x.id===shownId; });
        if(again) runComposite(again);
      }
    });
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
});

// 保存後の再取得用：loadCpList の描画部だけ呼べるように薄く包む
function loadCpListRender(d){
  if(d && d.success){
    // 既存の loadCpList と同じ描画を流用するため、単純に再読込する
  }
  loadCpList();
}

function deleteComposite(c){
  if(!confirm('複合指標「'+c.name+'」を削除します。よろしいですか？\n' +
              '（構成する単一指標そのものは削除されません）')) return;
  postJson(URL_CP_DELETE, {id: c.id}).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    toast('削除しました');
    if(cpCurrent && cpCurrent.id === c.id){
      $('#cp-toolbar').hide();
      $('#cp-errors').hide();
      $('#cp-graph-body').hide();
      if(cpChart){ cpChart.destroy(); cpChart = null; }
      $('#cp-placeholder').css('display','flex');
      cpCurrent = null; cpSeries = null;
    }
    loadCpList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
}

// ============================================================
// 各種データ一括ダウンロード
// ============================================================
// カードごとに読み込んだ本文を保持（コピー用）
const bulkText = {};

// ダウンロードリンクの href を組み立てる
$('#pane-bulk .bulk-card').each(function(){
  const kind = $(this).data('kind');
  $(this).find('.b-dl').attr('href', URL_BULK_DL + '?kind=' + encodeURIComponent(kind));
});

// 「表示」：本文を読み込んで <pre> に表示し、コピーを有効化する
$('#pane-bulk').on('click', '.b-show', function(){
  const $card = $(this).closest('.bulk-card');
  const kind  = $card.data('kind');
  const $pre  = $card.find('.bulk-pre');
  const $copy = $card.find('.b-copy');
  const $btn  = $(this);

  // すでに表示済みなら開閉トグル
  if($pre.data('loaded')){
    if($pre.hasClass('hidden')){
      $pre.removeClass('hidden'); $btn.text('隠す');
    } else {
      $pre.addClass('hidden'); $btn.text('表示');
    }
    return;
  }

  $pre.removeClass('hidden b-error').addClass('b-loading')
      .text('読み込み中…');
  $btn.prop('disabled', true);
  $.get(URL_BULK, {kind: kind}, function(data){
    if(!data.success){
      $pre.removeClass('b-loading').addClass('b-error').text('エラー: '+data.error);
      $btn.prop('disabled', false);
      return;
    }
    bulkText[kind] = data.text;
    $pre.removeClass('b-loading').text(data.text);
    $pre.data('loaded', true);
    $btn.prop('disabled', false).text('隠す');
    $copy.prop('disabled', false);
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    $pre.removeClass('b-loading').addClass('b-error').text('エラー: '+err);
    $btn.prop('disabled', false);
  });
});

// 「📋 コピー」：表示済みの本文をクリップボードへ
$('#pane-bulk').on('click', '.b-copy', function(){
  const $card = $(this).closest('.bulk-card');
  const kind  = $card.data('kind');
  const $btn  = $(this);
  const text  = bulkText[kind];
  if(text == null){ return; }

  const ok = function(){
    $btn.addClass('copied').text('✓ コピー済み');
    setTimeout(function(){ $btn.removeClass('copied').text('📋 コピー'); }, 1600);
  };
  const ng = function(){ toast('コピーに失敗しました', true); };
  const fallback = function(){
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed'; ta.style.left = '-9999px';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy') ? ok() : ng(); }
    catch(e){ ng(); }
    document.body.removeChild(ta);
  };
  if(navigator.clipboard && navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(ok, fallback);
  } else {
    fallback();
  }
});

// ============================================================
// データ更新（公式テーブルのExcel更新ワークフロー）
// ============================================================
function loadUpList(){
  $.get(URL_UP_LIST, function(data){
    if(!data.success){
      $('#up-tbody').html('<tr><td class="loading-msg" style="color:#e74c3c" colspan="9">'+
        esc(data.error)+'</td></tr>');
      return;
    }
    // 提供ボタン：担当テーブルが1つでもあれば表示
    $('#up-btn-new').toggle((data.uploadable_items||[]).length > 0);
    const $sel = $('#up-in-item').empty();
    (data.uploadable_items||[]).forEach(function(it){
      $sel.append($('<option>').val(it.id).text(it.label));
    });

    const $tb = $('#up-tbody').empty();
    if(!(data.updates||[]).length){
      $tb.html('<tr><td class="loading-msg" colspan="9">更新履歴はまだありません</td></tr>');
      return;
    }
    data.updates.forEach(function(u){
      const tblLabel = (u.display_name || u.table_name) +
        '<br><span class="tbl-sub">' + esc(u.database_name + ' / ' + u.table_name) + '</span>';
      const stCls = {pending:'st-pending', applied:'st-applied',
                     rejected:'st-rejected'}[u.status] || 'st-rejected';
      let stHtml = '<span class="st-badge '+stCls+'">'+esc(u.status_label)+'</span>';
      if(u.status==='rejected' && u.reject_reason){
        stHtml += '<div class="tbl-sub" title="'+esc(u.reject_reason)+'">理由: '+
                  esc(u.reject_reason)+'</div>';
      }
      let ops = '<div class="up-ops">';
      if(u.can_file){
        ops += '<a class="btn-toggle" href="'+URL_UP_FILE+'?id='+u.id+
               '" title="提供されたExcelをダウンロード">⬇ 提供ファイル</a>';
      }
      if(u.status==='pending' && data.can_apply){
        ops += '<a class="btn-toggle" href="'+URL_DOWNLOAD+
               '?table='+encodeURIComponent(u.table_name)+
               '&db='+encodeURIComponent(u.database_name)+
               '" title="転記前の正式データをXLSXで保存">⬇ 現在の正式データ</a>';
        ops += '<button class="btn-toggle btn-apply up-apply" data-id="'+u.id+
               '">✔ 転記</button>';
        ops += '<button class="btn-toggle btn-reject up-reject" data-id="'+u.id+
               '">✖ 却下</button>';
      }
      ops += '</div>';
      const $tr = $('<tr>').html(
        '<td>'+ (u.display_name ? esc(u.display_name) : esc(u.table_name)) +
          '<div class="tbl-sub">'+esc(u.database_name+' / '+u.table_name)+'</div></td>' +
        '<td>'+esc(u.uploaded_by_name || '')+'</td>' +
        '<td style="white-space:nowrap">'+esc(u.uploaded_at || '')+'</td>' +
        '<td>'+esc(u.note || '')+
          (u.original_filename ? '<div class="tbl-sub">📎 '+esc(u.original_filename)+'</div>' : '')+'</td>' +
        '<td>'+stHtml+'</td>' +
        '<td>'+esc(u.applied_by_name || '')+'</td>' +
        '<td style="white-space:nowrap">'+esc(u.applied_at || '')+'</td>' +
        '<td>'+(u.backup_table ? '<span class="bak-name">'+esc(u.backup_table)+'</span>' : '')+'</td>' +
        '<td>'+ops+'</td>'
      );
      $tb.append($tr);
    });

    $('.up-apply').on('click', function(){
      applyUpdate(parseInt($(this).data('id'), 10));
    });
    $('.up-reject').on('click', function(){
      rejectUpdate(parseInt($(this).data('id'), 10));
    });
  }).fail(function(){
    $('#up-tbody').html('<tr><td class="loading-msg" style="color:#e74c3c" colspan="9">取得失敗</td></tr>');
  });
}

// ── 提供モーダル ──
$('#up-btn-new').on('click', function(){
  $('#up-in-file').val('');
  $('#up-in-note').val('');
  $('#up-modal-bg').css('display','flex');
});
$('#up-btn-cancel').on('click', function(){ $('#up-modal-bg').hide(); });

$('#up-btn-send').on('click', function(){
  const itemId = $('#up-in-item').val();
  const file   = $('#up-in-file')[0].files[0];
  if(!itemId){ toast('対象テーブルを選んでください', true); return; }
  if(!file){ toast('Excelファイルを選択してください', true); return; }
  if(!/\.xlsx$/i.test(file.name)){ toast('.xlsx ファイルのみ受け付けます', true); return; }

  const $btn = $(this).prop('disabled', true).text('送信中…');
  const fd = new FormData();
  fd.append('item_id', itemId);
  fd.append('note', $('#up-in-note').val().trim());
  fd.append('excel_file', file);

  $.ajax({
    url: URL_UP_UPLOAD, method: 'POST', data: fd,
    processData: false, contentType: false
  }).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    $('#up-modal-bg').hide();
    toast('更新データを提供しました（'+resp.rows+'行）。全体管理者の転記をお待ちください');
    loadUpList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  }).always(function(){
    $btn.prop('disabled', false).text('提供する');
  });
});

// ── 転記・却下 ──
function applyUpdate(id){
  if(!confirm('転記を実行します。\n\n' +
              '1. 正式テーブルのバックアップ（_bak_日時）を自動作成\n' +
              '2. 正式テーブルを全件削除し、提供Excelの内容で置き換え\n\n' +
              'よろしいですか？')) return;
  postJson(URL_UP_APPLY, {id: id}).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    toast('転記しました（'+resp.rows+'行）。バックアップ: '+resp.backup_table);
    loadUpList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
}

function rejectUpdate(id){
  const reason = prompt('却下の理由（任意）を入力してください：', '');
  if(reason === null) return;   // キャンセル
  postJson(URL_UP_REJECT, {id: id, reason: reason}).done(function(resp){
    if(!resp.success){ toast('エラー: '+resp.error, true); return; }
    toast('却下しました');
    loadUpList();
  }).fail(function(xhr){
    const err = (xhr.responseJSON && xhr.responseJSON.error) || '通信エラー';
    toast('エラー: '+err, true);
  });
}

$(function(){ loadTableList(); });
</script>
