<style>
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%;overflow:hidden}
body{font-family:'Helvetica Neue',Arial,'Hiragino Kaku Gothic ProN',sans-serif;
     font-size:13px;background:#1a2535;color:#eef1f5;display:flex;flex-direction:column}

/* ヘッダー */
#header{background:#0e1c2b;color:#fff;padding:8px 16px;
        display:flex;align-items:center;gap:10px;flex-shrink:0;
        border-bottom:2px solid #2e6da4}
#header h1{font-size:14px;font-weight:600;color:#aed6f1}
#story-title-hdr{font-size:15px;font-weight:700;color:#fff;flex:1}
.nav-links{display:flex;gap:8px}
.nav-links a{color:#7fb3d3;text-decoration:none;font-size:12px;
             padding:3px 8px;border:1px solid #2e6da4;border-radius:3px}
.nav-links a:hover{background:#2e6da4;color:#fff}

/* 3ゾーンレイアウト */
#workspace{display:flex;flex:1;overflow:hidden}

/* ===== 左サイドバー：ミニマップ ===== */
#sidebar{width:240px;min-width:180px;background:#111d2b;border-right:1px solid #243447;
         display:flex;flex-direction:column;flex-shrink:0;overflow:hidden}
#sidebar-header{padding:8px 12px;font-size:11px;font-weight:600;color:#5d8aad;
                border-bottom:1px solid #243447;letter-spacing:.05em;text-transform:uppercase}
#minimap{flex:1;overflow-y:auto;padding:6px 0}
#minimap::-webkit-scrollbar{width:4px}
