}
function toast(msg, type='ok'){
  $('#toast').attr('class',type).text(msg).fadeIn(200);
  setTimeout(()=>$('#toast').fadeOut(400), 3000);
}

// キーボードナビゲーション
$(document).on('keydown', function(e){
  if(['INPUT','TEXTAREA'].includes(e.target.tagName)) return;
  if(e.key === 'ArrowRight' || e.key === 'ArrowDown') goNext();
  if(e.key === 'ArrowLeft'  || e.key === 'ArrowUp')   goPrev();
  if(e.key === 'ArrowRight' && e.shiftKey) goFirstChild();
  if(e.key === 'Escape') goParent();
});

// ============================================================
// 包括Report：preorder順で全ノードをHTML化
// ============================================================

// HTMLエスケープ
function escHtml(s){
  return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;')
                      .replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// preorder走査：treeData → 平坦な配列（node_number順）
function flattenPreorder(nodes, depth, out){
  if(!nodes) return;
  nodes.forEach(function(n){
    out.push({ node: n, depth: depth });
    if(n.children?.length) flattenPreorder(n.children, depth+1, out);
  });
}

// SVGの固定サイズを除去（part_htmlのSVGをレスポンシブに）
function normalizeSvgInHtml(htmlStr){
  if(!htmlStr) return '';
  const tmp = document.createElement('div');
  tmp.innerHTML = DOMPurify.sanitize(htmlStr);
  tmp.querySelectorAll('svg').forEach(function(svg){
    if(!svg.getAttribute('viewBox')){
      const w = parseFloat(svg.getAttribute('width'))  || 800;
      const h = parseFloat(svg.getAttribute('height')) || 400;
      svg.setAttribute('viewBox', '0 0 '+w+' '+h);
    }
    svg.removeAttribute('width');
    svg.removeAttribute('height');
    svg.setAttribute('preserveAspectRatio','xMidYMid meet');
  });
  return tmp.innerHTML;
}

// 本文MDから先頭の見出し相当を抽出（タイトル用）
function extractNodeTitle(bodyMd){
  if(!bodyMd) return '';
  const m = bodyMd.match(/^#+\s*(.+)/m);
  if(m) return m[1].trim();
  return bodyMd.split('\n')[0].trim().slice(0,60);
}

