// クリップボードへコピー（フォールバック付き）
async function copyToClipboard(text){
  if(navigator.clipboard && window.isSecureContext){
    try{ await navigator.clipboard.writeText(text); return true; }
    catch(e){ /* fall through */ }
  }
  // フォールバック：textarea経由
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.position = 'fixed';
  ta.style.opacity = '0';
  document.body.appendChild(ta);
  ta.select();
  let ok = false;
  try{ ok = document.execCommand('copy'); }catch(e){}
  document.body.removeChild(ta);
  return ok;
}

// ファイルとしてダウンロード
function downloadHtml(html, filename){
  const blob = new Blob([html], {type:'text/html;charset=utf-8'});
  const url  = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click();
  document.body.removeChild(a);
  setTimeout(()=>URL.revokeObjectURL(url), 1000);
}

// ボタンクリック：クリップボードへコピー＋ダウンロード
$('#btn-report').on('click', async function(e){
  e.preventDefault();
  if(!treeData.length){ toast('ノードがありません','err'); return; }

  try{
    const result = buildReportHtml();
    const safeTitle = result.title.replace(/[\\\/:*?"<>|]/g,'_').slice(0,60);
    const filename = safeTitle + '_report.html';

    // 1) クリップボードへコピー
    const copied = await copyToClipboard(result.html);
    // 2) ファイルとしてダウンロードも実行
    downloadHtml(result.html, filename);

    if(copied){
      toast('包括レポート（'+result.count+'ノード）をクリップボードにコピー＆ダウンロードしました','ok');
    } else {
      toast('ダウンロードしました（クリップボードはブラウザ制限で不可）','ok');
    }
  } catch(err){
    console.error(err);
    toast('レポート生成に失敗：'+err.message,'err');
  }
});
