.tb-item.active{background:#d0e4f7;border-left:3px solid #2e6da4;font-weight:600;}
.tb-item .tb-name{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.tb-item .tb-cnt{font-size:.65rem;color:#95a5a6;white-space:nowrap;}
.tb-back-btn{display:flex;align-items:center;gap:5px;padding:7px 11px;background:#ebf5fb;border-bottom:2px solid #aed6f1;font-size:.73rem;color:#1a5276;font-weight:600;cursor:pointer;flex-shrink:0;}
.tb-back-btn:hover{background:#d6eaf8;}
#tb-right{flex:1;display:flex;flex-direction:column;overflow:hidden;min-width:0;}
#tb-right-placeholder{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#aab;gap:8px;font-size:.88rem;}
#tb-right-placeholder .ph-icon{font-size:2.5rem;opacity:.4;}
#tb-tabs{display:flex;border-bottom:2px solid #e0e0e0;background:#f5f7fa;flex-shrink:0;}
.tb-tab{padding:7px 18px;font-size:.76rem;font-weight:600;border:none;background:none;cursor:pointer;color:var(--gray-500);border-bottom:2px solid transparent;margin-bottom:-2px;transition:all .15s;}
.tb-tab.active{color:#2e6da4;border-bottom-color:#2e6da4;background:#fff;}
#tb-pane{flex:1;overflow:auto;padding:11px 14px;font-size:.76rem;}
#tb-schema-pre{background:#f4f6f8;border:1px solid #dde3ea;border-radius:5px;padding:12px;font-family:'Courier New',Consolas,monospace;font-size:.71rem;line-height:1.7;color:#2c3e50;white-space:pre-wrap;word-break:break-all;margin:0;}
#tb-data-info{font-size:.7rem;color:var(--gray-500);margin-bottom:7px;display:flex;align-items:center;gap:9px;flex-wrap:wrap;}
.tb-data-table-wrap{overflow:auto;border:1px solid #e0e0e0;border-radius:5px;max-height:calc(100% - 60px);}
.tb-data-table{border-collapse:collapse;width:100%;font-size:.7rem;}
.tb-data-table th{background:#2e6da4;color:#fff;padding:6px 9px;text-align:left;white-space:nowrap;position:sticky;top:0;z-index:1;font-weight:600;}
.tb-data-table td{padding:5px 9px;border-bottom:1px solid #eee;white-space:nowrap;max-width:260px;overflow:hidden;text-overflow:ellipsis;}
.tb-data-table tr:hover td{background:#f0f6ff;}
.tb-null{color:#e74c3c;font-style:italic;opacity:.7;}
.tb-proj-card{display:flex;flex-direction:column;gap:2px;padding:7px 11px;border-bottom:1px solid #eee;cursor:pointer;transition:background .1s;}
.tb-proj-card:hover{background:#e8f0fe;}
.tb-proj-card.active{background:#d0e4f7;border-left:3px solid #2e6da4;}
.tb-proj-name{font-weight:600;font-size:.76rem;color:#1a3a5c;}
.tb-proj-desc{font-size:.66rem;color:var(--gray-500);}
.tb-proj-meta{font-size:.63rem;color:var(--gray-400);}

/* ── インポート・エクスポートモーダル ── */
#import-modal .modal-box{width:min(600px,94vw);}
#exp-modal .modal-box{width:min(860px,92vw);max-height:88vh;}
#schema-modal .modal-box{width:min(820px,94vw);max-height:88vh;}

/* ── レスポンシブ ── */
@media(max-width:899px){
  #layout,#layout.editor-open{grid-template-columns:1fr;}
  #left-col,#editor-col{position:static;max-height:none;}
  #chart-container{height:240px;}
}
@media(max-width:599px){
  body{font-size:12px;}
  #app-header{padding:7px 10px;}
  #app-header h1{font-size:.86rem;}
  #layout{padding:7px 7px 28px;gap:7px;}
  .card{padding:9px;}
  #chart-container{height:200px;}
}
</style>
</head>
<body>

<div id="app-header">
  <span style="font-size:1.2rem">📈</span>
  <div>
    <h1>時系列指標ビジュアル</h1>
  </div>
  <div style="margin-left:auto;display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
    <a href="{{ url_for('index_review.table_manager') }}" class="hdr-btn">📁 テーブル管理</a>
    <button id="btn-refresh-layout" class="hdr-btn" title="レイアウト再計算">🔄 画面調整</button>
    <button id="btn-toggle-editor" class="hdr-btn">✏️ 指標エディタ</button>
    <button id="btn-export-json" class="hdr-btn">📤 指標エクスポート</button>
    <button id="btn-import-json" class="hdr-btn">📥 指標インポート</button>
    <button id="btn-export-chart" class="hdr-btn">📊 グラフ出力</button>
    <a href="{{ url_for('index_review.return_to_fujin') }}" class="btn-return">🏠 FUJIN-Pダッシュボードに戻る</a>
  </div>
</div>

<div id="layout">

  <!-- ═══ 左カラム ═══ -->
  <div id="left-col">

    <!-- プロジェクトパネル -->
    <div class="card" id="project-panel">
      <div class="card-title">📁 プロジェクト
        <button id="btn-new-project" class="btn btn-primary"
                style="margin-left:auto;padding:2px 8px;font-size:.65rem;">＋ 新規</button>
      </div>
      <select id="project-select">
        <option value="">— プロジェクトを選択 —</option>
      </select>
      <div id="project-info" style="display:none;"></div>
    </div>

    <!-- 指標パネル -->
    <div class="card">
      <div class="card-title">📋 指標
        <span id="ind-count" class="badge-count">—</span>
        <span id="selected-count" class="badge-selected">選択中 0</span>
            <button id="btn-select-all" style="margin-left:auto;padding:2px 6px;font-size:.63rem;display:none;">
          ✅ 全選択
        </button>
        <button id="btn-clear-all" class="btn btn-outline"
                style="margin-left:auto;padding:2px 6px;font-size:.63rem;display:none;">✕ 全解除</button>
      </div>
      <!-- ★追加：指標検索 -->
        <div id="ind-search-wrap" style="display:none;margin-bottom:5px;">
          <input id="ind-search" type="text" placeholder="🔍 指標名を検索…"
                 style="width:100%;padding:4px 8px;border:1.5px solid var(--gray-300);
                        border-radius:5px;font-size:.72rem;color:var(--gray-800);
                        background:#fff;outline:none;transition:border-color .15s;"
                 autocomplete="off">
          <div id="ind-search-info"
               style="font-size:.63rem;color:var(--gray-400);margin-top:2px;min-height:14px;"></div>
      </div>
      <div id="ind-list">
        <span style="color:var(--gray-400);font-size:.75rem;">プロジェクトを選択してください</span>
      </div>
    </div>
  </div>

  <!-- ═══ 中央カラム ═══ -->
  <div id="right-col">
    <div class="card">
      <div class="card-title">📈 推移グラフ</div>
      <div id="chart-toolbar">
        <button class="btn-type active" data-type="line">折れ線</button>
        <button class="btn-type" data-type="bar">棒グラフ</button>
        <div style="width:1px;height:16px;background:var(--gray-300);margin:0 2px;"></div>
        <button class="btn-type active" id="btn-scale-zero" data-scale="zero">絶対値</button>
        <button class="btn-type" id="btn-scale-abs"  data-scale="abs">絶対値変動</button>
        <button class="btn-type" id="btn-scale-norm" data-scale="norm">相対値</button>
        <div id="zoom-control">
          <span>ズーム</span>
          <button class="btn-zoom" id="btn-zoom-in">＋</button>
          <span id="zoom-label">標準</span>
          <button class="btn-zoom" id="btn-zoom-out">－</button>
        </div>
      </div>
      <div id="chart-legend"></div>
      <div id="chart-container">
        <canvas id="myChart"></canvas>
        <div id="chart-no-data" class="show">
          <span style="font-size:2rem">🔍</span>
          <span>左パネルで指標を選択してください</span>
        </div>
      </div>
      <div id="scale-info">縦軸：絶対値表示（全系列共通スケール / 線形）</div>
    </div>

    <div class="card">
      <div class="card-title">🔢 統計サマリー</div>
      <div id="stats-bar">
        <span id="stats-empty">指標を選択すると統計が表示されます</span>
      </div>
    </div>
  </div>

  <!-- ═══ エディタ列 ═══ -->
  <div id="editor-col">
    <div class="card">
      <div class="card-title">✏️ 指標エディタ
        <button id="btn-close-editor"
                style="margin-left:auto;background:none;border:none;cursor:pointer;color:var(--gray-400);font-size:.95rem;">✕</button>
      </div>
      <div id="editor-proj-notice"
           style="display:none;background:#fef3c7;border:1px solid #fde68a;border-radius:5px;padding:5px 8px;font-size:.68rem;color:#92400e;margin-bottom:6px;">
        ⚠️ プロジェクトを選択してから指標を編集・追加してください
      </div>
      <div id="table-list-toggle">
        <span id="tl-arrow">▶</span> 利用可能なテーブル一覧
        <span style="font-size:.61rem;color:var(--gray-400)">(クリックでSQLに挿入)</span>
      </div>
      <div id="table-list-box"></div>
      <div id="sql-hint">
        <strong>指標名のプレフィクスで表示順を制御：</strong><br>
        例）<code>I01_標準年限卒業率_地域経営</code>　<code>I02_就職率_全体</code><br>
        <strong>SQL形式：</strong><code>SELECT `年度`, &lt;値カラム&gt; AS 値 FROM `テーブル` ORDER BY `年度`</code>
      </div>
      <textarea id="sql-editor" placeholder="SELECT文を入力…"></textarea>
      <div class="btn-row">
        <button class="btn btn-primary" id="btn-sql-run">▶ SQLを実行</button>
        <button class="btn btn-outline" id="btn-sql-clear">クリア</button>
        <div id="edit-action-sep" style="display:none;width:1px;height:22px;background:var(--gray-300);margin:0 4px;align-self:center;"></div>
        <button class="btn btn-danger" id="btn-update-confirm" style="display:none;">💾 更新する</button>
        <button class="btn btn-outline" id="btn-update-cancel" style="display:none;">✕ キャンセル</button>
      </div>
      <div id="sql-result"></div>
      <div id="save-form">
        <div id="save-form-title" style="font-size:.68rem;font-weight:700;color:var(--primary);margin-bottom:6px;">
          ✅ SQL が実行できました。指標として登録します：
        </div>
        <div class="form-grid">
          <div class="form-group full">
            <label class="form-label">指標名 <span class="req">*</span></label>
            <input class="form-input" id="f-name" type="text" placeholder="例：I01_標準年限卒業率_地域経営">
          </div>
          <div class="form-group">
            <label class="form-label">年度カラム <span class="req">*</span></label>
            <select class="form-select" id="f-year-col"></select>
          </div>
          <div class="form-group">
            <label class="form-label">値カラム <span class="req">*</span></label>
            <select class="form-select" id="f-val-col"></select>
          </div>
          <div class="form-group full">
            <label class="form-label">説明（任意）</label>
            <input class="form-input" id="f-desc" type="text" placeholder="指標の内容・出典など">
          </div>
        </div>
        <div class="btn-row" id="save-form-btns">
          <button class="btn btn-primary" id="btn-save">💾 <span id="btn-save-label">登録する</span></button>
          <button class="btn btn-outline" id="btn-save-cancel">キャンセル</button>
        </div>
      </div>
    </div>

    <!-- ═══ 基準値ラインカード ═══ -->
    <div class="card" id="ann-card">
      <div class="card-title">📏 基準値ライン
        <span id="ann-ind-name"
              style="font-size:.68rem;font-weight:400;color:var(--gray-500);margin-left:4px;"></span>
      </div>
      <div id="ann-list" style="margin-bottom:6px;min-height:18px;">
        <span style="color:var(--gray-400);font-size:.71rem;">指標を1件選択すると管理できます</span>
      </div>
      <div style="display:grid;grid-template-columns:1fr 88px 36px;gap:5px;align-items:end;margin-bottom:5px;">
        <div class="form-group">
          <label class="form-label">ラベル</label>
          <input class="form-input" id="ann-label" type="text" placeholder="例：上限" style="font-size:.72rem;">
        </div>
        <div class="form-group">
          <label class="form-label">値</label>
          <input class="form-input" id="ann-value" type="number" step="any" placeholder="0.9" style="font-size:.72rem;">
        </div>
        <div class="form-group">
          <label class="form-label">色</label>
          <input type="color" id="ann-color" value="#ef4444"
                 style="width:36px;height:32px;border:1.5px solid var(--gray-300);border-radius:5px;padding:2px;cursor:pointer;display:block;">
        </div>
      </div>
      <button class="btn btn-outline" id="btn-ann-add" style="width:100%;font-size:.72rem;">＋ 追加</button>
      <button class="btn btn-outline" id="btn-ann-cancel-edit"
        style="width:100%;font-size:.72rem;margin-top:4px;display:none;">✕ キャンセル</button>
    </div>

  </div>
</div>

<!-- ═══ プロジェクト作成・編集モーダル ═══ -->
<div id="proj-modal" class="modal-overlay">
  <div class="modal-box">
    <div class="modal-hdr">
      <span style="font-size:1.1rem">📁</span>
      <h2 id="proj-modal-title">プロジェクトを作成</h2>
      <button class="modal-close" id="proj-modal-close">✕ 閉じる</button>
    </div>
    <div class="modal-body" style="min-width:400px;">
      <div class="form-grid">
        <div class="form-group full">
          <label class="form-label">プロジェクト名 <span class="req">*</span></label>
          <input class="form-input" id="pf-name" type="text" placeholder="例：2024年度評価指標集">
        </div>
        <div class="form-group full">
          <label class="form-label">説明（任意）</label>
          <textarea class="form-input" id="pf-desc" rows="2" placeholder="このプロジェクトの目的・対象など" style="resize:vertical;"></textarea>
        </div>
        <div class="form-group full">
          <label class="form-label">編集権限グループ（まいぐる）
            <span style="font-weight:400;color:var(--gray-400);margin-left:4px;">未選択=オーナーのみ編集可</span>
          </label>
          <select class="form-select" id="pf-group">
            <option value="">— なし（オーナーのみ）—</option>
          </select>
        </div>
        <div class="form-group full">
          <label class="form-label">公開範囲</label>
            <select class="form-select" id="pf-policy">
              <option value="public">🔓 パブリック（全ユーザが閲覧可）</option>
              <option value="domestic">🏫 学内公開（regularユーザのみ閲覧可）</option>
              <option value="group">👥 グループのみ（設定グループメンバーが閲覧可）</option>
              <option value="private">🔒 プライベート（オーナーのみ閲覧可）</option>
            </select>
        </div>

        <!-- ★ここに追加 -->
        <div class="form-group full" id="access-group-wrap" style="display:none;">
          <label class="form-label">閲覧可能グループ（複数選択可）</label>
          <div id="access-group-list"
               style="max-height:120px;overflow-y:auto;border:1.5px solid var(--gray-300);
                      border-radius:5px;padding:5px 8px;background:#fff;font-size:.73rem;">
          </div>
        </div>

      </div><!-- /.form-grid -->
      <div style="display:flex;gap:7px;margin-top:10px;">
        <button class="btn btn-primary" id="pf-save">💾 <span id="pf-save-label">作成する</span></button>
        <button class="btn btn-outline" id="pf-cancel">キャンセル</button>
      </div>
    </div><!-- /.modal-body -->
  </div><!-- /.modal-box -->
</div><!-- /#proj-modal -->

<!-- ═══ 指標インポートモーダル ═══ -->
<div id="import-modal" class="modal-overlay">
  <div class="modal-box">
    <div class="modal-hdr">
      <span style="font-size:1.1rem">📥</span>
      <h2>指標インポート</h2>
      <button class="modal-close" id="import-modal-close">✕ 閉じる</button>
    </div>
    <div class="modal-body" style="min-width:420px;">
      <div style="font-size:.72rem;color:var(--gray-600);margin-bottom:8px;">
        💡 エクスポートしたJSONをここに貼り付けると、現在のプロジェクトに指標を一括追加できます。<br>
        同名の指標はスキップされます。
      </div>
      <textarea id="import-json-text" rows="10"
                style="width:100%;font-family:monospace;font-size:.73rem;border:1.5px solid var(--gray-300);border-radius:6px;padding:8px;resize:vertical;"
                placeholder='[{"name":"I01_例","sql_query":"SELECT ...","value_column":"値","year_column":"年度"}]'></textarea>
      <div id="import-result" style="margin-top:6px;font-size:.72rem;"></div>
      <div style="display:flex;gap:7px;margin-top:8px;">
        <button class="btn btn-primary" id="import-execute">📥 インポート実行</button>
        <button class="btn btn-outline" id="import-cancel">キャンセル</button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ テーブルブラウザモーダル ═══ -->
<div id="tb-modal" class="modal-overlay">
  <div class="modal-box">
    <div class="modal-hdr">
      <span style="font-size:1.1rem">🗂️</span>
      <h2>テーブルブラウザ</h2>
      <button class="tb-mode-btn active" data-mode="tables">全テーブル</button>
      <button class="tb-mode-btn" data-mode="projects">プロジェクト</button>
      <button class="modal-close" id="tb-close">✕ 閉じる</button>
    </div>
    <div id="tb-body">
      <div id="tb-left">
        <input id="tb-left-search" type="text" placeholder="🔍 検索...">
        <div id="tb-list"><div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">読込中...</div></div>
      </div>
      <div id="tb-right">
        <div id="tb-right-placeholder"><span class="ph-icon">📋</span><span>左のリストからテーブルを選んでください</span></div>
        <div id="tb-tabs" style="display:none;">
          <button class="tb-tab active" data-pane="schema">📐 スキーマ</button>
          <button class="tb-tab" data-pane="data">📊 データ</button>
          <span id="tb-table-label" style="margin-left:auto;padding:0 13px;font-size:.7rem;color:var(--gray-500);align-self:center;"></span>
        </div>
        <div id="tb-pane" style="display:none;">
          <div id="tb-pane-schema"><pre id="tb-schema-pre">取得中...</pre></div>
          <div id="tb-pane-data" style="display:none;">
            <div id="tb-data-info"></div>
            <div class="tb-data-table-wrap"><table class="tb-data-table" id="tb-data-table"></table></div>
          </div>
        </div>
      </div>
    </div>
  </div>
</div>

<!-- ═══ エクスポートモーダル ═══ -->
<div id="exp-modal" class="modal-overlay">
  <div class="modal-box" style="max-height:88vh;">
    <div class="modal-hdr">
      <span style="font-size:1.1rem">📤</span>
      <h2>指標エクスポート（AI連携用JSON）</h2>
      <span id="exp-count" style="background:rgba(255,255,255,.2);border-radius:10px;padding:1px 8px;font-size:.7rem;"></span>
      <button id="exp-copy-selected" style="margin-left:auto;padding:4px 14px;border-radius:6px;border:1.5px solid rgba(255,255,255,.6);background:rgba(255,255,255,.2);color:#fff;font-size:.76rem;font-weight:600;cursor:pointer;">📋 選択中をコピー</button>
      <button id="exp-copy-all" style="padding:4px 14px;border-radius:6px;border:1.5px solid rgba(255,255,255,.6);background:rgba(255,255,255,.2);color:#fff;font-size:.76rem;font-weight:600;cursor:pointer;">📋 全件をコピー</button>
      <button class="modal-close" id="exp-close">✕ 閉じる</button>
    </div>
    <div style="padding:7px 14px;background:#f0f6ff;border-bottom:1px solid #dde8f5;font-size:.7rem;color:#1a3a5c;">
      💡 このJSONをコピーして生成AIに貼り付けると、指標レビューや合成指標の提案を依頼できます。
    </div>
    <pre id="exp-json" style="flex:1;overflow:auto;margin:0;padding:14px;font-family:'Courier New',Consolas,monospace;font-size:.71rem;line-height:1.7;color:#2c3e50;background:#f8f9fa;white-space:pre-wrap;word-break:break-all;"></pre>
  </div>
</div>

<!-- ═══ スキーマダンプモーダル ═══ -->
<div id="schema-modal" class="modal-overlay">
  <div class="modal-box" style="max-height:88vh;">
    <div class="modal-hdr">
      <span style="font-size:1.1rem">📄</span>
      <h2>スキーマダンプ（AI連携用）</h2>
      <span id="schema-count" style="font-size:.72rem;margin-left:4px;opacity:.8;"></span>
      <button id="schema-copy" style="margin-left:auto;padding:4px 12px;border-radius:6px;border:1.5px solid rgba(255,255,255,.6);background:rgba(255,255,255,.2);color:#fff;font-size:.74rem;font-weight:600;cursor:pointer;">📋 コピー</button>
      <button id="schema-dl" style="padding:4px 12px;border-radius:6px;border:1.5px solid rgba(255,255,255,.6);background:rgba(255,255,255,.2);color:#fff;font-size:.74rem;font-weight:600;cursor:pointer;">⬇ DL</button>
      <button class="modal-close" id="schema-close">✕ 閉じる</button>
    </div>
