<div id="toast-container"></div>

<script>
/* ====================================================
   定数・グローバル
   ==================================================== */
const API = {
  projects    : "{{ url_for('index_review.api_projects') }}",
  groups      : "{{ url_for('index_review.api_groups') }}",
  sqlTest     : "{{ url_for('index_review.api_sql_test') }}",
  tableList   : "{{ url_for('index_review.api_table_list') }}",
  browserTables        : "{{ url_for('index_review.api_browser_tables') }}",
  browserProjects      : "{{ url_for('index_review.api_browser_projects') }}",
  browserProjectTables : "{{ url_for('index_review.api_browser_project_tables') }}",
  browserSchema        : "{{ url_for('index_review.api_browser_schema') }}",
  browserData          : "{{ url_for('index_review.api_browser_data') }}",
  schemaDump  : "{{ url_for('index_review.api_schema_dump') }}",
  // 動的（プロジェクトスコープ）
  projIndicators : (pid)      => `${API.projects}/${pid}/indicators`,
  projIndicator  : (pid, iid) => `${API.projects}/${pid}/indicators/${iid}`,
  projIndData    : (pid, iid) => `${API.projects}/${pid}/indicators/${iid}/data`,
  projExport     : (pid)      => `${API.projects}/${pid}/export`,
  projImport     : (pid)      => `${API.projects}/${pid}/import`,
  projIndAnnotations : (pid, iid)       => `${API.projects}/${pid}/indicators/${iid}/annotations`,
  projIndAnnotation  : (pid, iid, aid)  => `${API.projects}/${pid}/indicators/${iid}/annotations/${aid}`,
};

const PALETTE = [
  '#6366f1','#10b981','#f59e0b','#ef4444',
  '#8b5cf6','#06b6d4','#f97316','#84cc16',
  '#ec4899','#14b8a6','#a855f7','#3b82f6',
];

/* ── 状態 ── */
let activeDatasets   = {};
let hiddenDatasets   = new Set();
let colorCounter     = 0;
let myChart          = null;
let currentChartType = 'line';
let currentScaleMode = 'zero';
let lastSqlTestResult = null;
let editingIndicatorId = null;
let editModeBackup     = null;

// プロジェクト管理状態
let allProjects      = [];
let currentProjectId = null;
let currentProject   = null;
let editingProjectId = null;  // null=新規、数値=編集中
let annotationsByKey = {};
let editingAnnId = null;   // アノテーション編集中のID

const ZOOM_LEVELS = [0.5,1,2,3,5,8];
const ZOOM_LABELS = ['×6拡大','×3拡大','×1.5拡大','標準','広域','超広域'];
let zoomIdx = 3;


/* ====================================================
   ユーティリティ
   ==================================================== */
function toast(msg, type='info') {
  const el = $('<div>').addClass(`toast ${type}`).text(msg);
  $('#toast-container').append(el);
  setTimeout(() => el.fadeOut(300, () => el.remove()), 3200);
}

function fmt(n, unit='') {
  if (n===null||n===undefined||isNaN(n)) return '—';
  const abs = Math.abs(n);
  let s;
  if      (abs>=1_000_000) s=(n/1_000_000).toFixed(1)+'M';
  else if (abs>=10_000)    s=n.toLocaleString('ja-JP',{maximumFractionDigits:0});
  else                     s=n.toLocaleString('ja-JP',{maximumFractionDigits:3});
  return unit ? `${s} ${unit}` : s;
}
function fmtPct(n){
  if(n===null||n===undefined||isNaN(n))return'—';
  return`${n>=0?'+':''}${n.toFixed(1)}%`;
}


/* ====================================================
   tanh 正規化
   ==================================================== */
function seriesMeanSigma(data){
  const vals=data.map(d=>d.値).filter(v=>v!==null&&v!==undefined);
  if(!vals.length)return{mean:0,sigma:0};
  const n=vals.length,mu=vals.reduce((a,b)=>a+b,0)/n;
  const sig=Math.sqrt(vals.reduce((a,b)=>a+(b-mu)**2,0)/n);
  return{mean:mu,sigma:sig};
}
function applyTanh(v,mean,sigma,zoom){
  if(sigma===0)return 0;
  return Math.tanh((v-mean)/(zoom*sigma));
}

Chart.register({
  id: 'hAnnotations',
  afterDraw(chart) {
    const { ctx, scales: { x, y } } = chart;
    Object.keys(activeDatasets).forEach(key => {
      const dataset = activeDatasets[key];
      const { mean, sigma } = seriesMeanSigma(dataset.data);
      (annotationsByKey[key] || []).forEach(ann => {
        const displayValue = currentScaleMode === 'norm'
          ? applyTanh(ann.value, mean, sigma, ZOOM_LEVELS[zoomIdx])
          : ann.value;
        const yPx = y.getPixelForValue(displayValue);
        if (yPx < y.top - 1 || yPx > y.bottom + 1) return;
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(x.left, yPx);
        ctx.lineTo(x.right, yPx);
        ctx.strokeStyle = ann.color;
        ctx.lineWidth   = 1.5;
        ctx.setLineDash([6, 3]);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle    = ann.color;
        ctx.font         = 'bold 11px sans-serif';
        ctx.textAlign    = 'right';
        ctx.textBaseline = 'bottom';
        ctx.fillText(ann.label, x.right - 4, yPx - 2);
        ctx.restore();
      });
    });
  }
});


/* ====================================================
   Chart.js
   ==================================================== */
function initChart(){
  const ctx=document.getElementById('myChart').getContext('2d');
  myChart=new Chart(ctx,{
    type:'line',
    data:{labels:[],datasets:[]},
    options:{
      responsive:true,maintainAspectRatio:false,resizeDelay:0,
      interaction:{mode:'nearest',intersect:true},
      plugins:{
        legend:{display:false},
        tooltip:{callbacks:{label(ctx){
          const raw=ctx.dataset._rawData?.[ctx.dataIndex];
          const unit=ctx.dataset._unit||'';
          if(raw===null||raw===undefined)return` ${ctx.dataset.label}: —`;
          return` ${ctx.dataset.label}: ${fmt(raw,unit)}`;
        }}}
      },
      scales:{
        x:{grid:{color:'#f0f0f0'},ticks:{font:{size:11}}},
        y:{min:-1.05,max:1.05,grid:{color:'#f0f0f0'},ticks:{display:true,font:{size:10},color:'#9ca3af',
          callback:v=>{
            if(Math.abs(v-1)<.01)return'+1';
            if(Math.abs(v)<.01)return'0';
            if(Math.abs(v+1)<.01)return'−1';
            return null;
          }
        }}
      },
      animation:{duration:350}
    }
  });
}

function rebuildChart(){
  const keys=Object.keys(activeDatasets);
  if(!keys.length){
    myChart.data.labels=[]; myChart.data.datasets=[];
    myChart.update();
    $('#chart-no-data').addClass('show');
    $('#chart-legend').empty();
    return;
  }
  $('#chart-no-data').removeClass('show');
  const years=[2016,2017,2018,2019,2020,2021,2022,2023,2024,2025];
  const zoom=ZOOM_LEVELS[zoomIdx];

  // ── スケール計算（datasets構築の前に確定） ──
  let globalMin=Infinity, globalMax=-Infinity;
  if(currentScaleMode==='abs'){
    keys.forEach(k=>activeDatasets[k].data.forEach(d=>{
      if(d.値!==null&&d.値!==undefined){
        globalMin=Math.min(globalMin,d.値);
        globalMax=Math.max(globalMax,d.値);
      }
    }));
    const pad=(globalMax-globalMin)*.08||Math.abs(globalMax)*.1||1;
    globalMin-=pad; globalMax+=pad;
  } else if(currentScaleMode==='zero'){
    keys.forEach(k=>activeDatasets[k].data.forEach(d=>{
      if(d.値!==null&&d.値!==undefined) globalMax=Math.max(globalMax,d.値);
    }));
    globalMin=0;
    globalMax+=globalMax*.08||1;
  }

  // ── datasets構築 ──
  myChart.data.labels=years.map(String);
  myChart.data.datasets=keys.map(k=>{
    const ds=activeDatasets[k];
    const color=PALETTE[ds.colorIdx%PALETTE.length];
    const yearMap={};
    ds.data.forEach(d=>yearMap[d.年度]=d.値);
    const rawData=years.map(y=>yearMap[y]??null);

    let displayData;
    if(currentScaleMode==='norm'){
      const{mean,sigma}=seriesMeanSigma(ds.data);
      displayData=rawData.map(v=>v===null?null:applyTanh(v,mean,sigma,zoom));
    } else {
      displayData=rawData;  // abs / zero ともに実値をそのまま使う
    }

    const base={
      label:ds.label, data:displayData, _rawData:rawData, _unit:ds.unit,
      borderColor:color,
      backgroundColor:color+(currentChartType==='bar'?'cc':'22'),
      tension:0, pointRadius:4, pointHoverRadius:7, borderWidth:2,
      fill:false, spanGaps:false,
      hidden:hiddenDatasets.has(k),
    };
    if(currentChartType==='bar'){
      base.type='bar';
      delete base.tension; delete base.pointRadius;
      delete base.pointHoverRadius; delete base.fill;
    }
    return base;
  });

  // ── Y軸スケール設定 ──
  if(currentScaleMode==='norm'){
    myChart.options.scales.y.min=-1.05;
    myChart.options.scales.y.max=1.05;
    myChart.options.scales.y.ticks={
      display:true, font:{size:10}, color:'var(--gray-400)',
      callback:v=>{
        if(Math.abs(v-1)<.01)return'+1';
        if(Math.abs(v)<.01)return'0';
        if(Math.abs(v+1)<.01)return'−1';
        return null;
      }
    };
  } else {
    myChart.options.scales.y.min=globalMin;
    myChart.options.scales.y.max=globalMax;
    myChart.options.scales.y.ticks={
      display:true, font:{size:10}, color:'var(--gray-400)', maxTicksLimit:6,
      callback:v=>{
        const abs=Math.abs(v);
        if(abs>=1_000_000) return(v/1_000_000).toFixed(1)+'M';
        if(abs>=10_000)    return v.toLocaleString('ja-JP',{maximumFractionDigits:0});
        return v.toLocaleString('ja-JP',{maximumFractionDigits:3});
      }
    };
  }

  myChart.config.type=currentChartType;
  myChart.update();
  renderLegend();
}

function renderLegend(){
  const keys=Object.keys(activeDatasets);
  const container=$('#chart-legend');
  container.empty();
  if(!keys.length)return;
  keys.forEach(k=>{
    const ds=activeDatasets[k],color=PALETTE[ds.colorIdx%PALETTE.length],hidden=hiddenDatasets.has(k);
    container.append(`<button class="legend-btn ${hidden?'legend-hidden':''}" data-dskey="${k}" style="--lc:${color}"><span class="legend-dot"></span><span class="legend-name">${ds.label}</span></button>`);
  });
  const allHidden=keys.every(k=>hiddenDatasets.has(k));
  container.append(`<button id="btn-legend-hide-all" style="margin-left:auto;padding:2px 9px;border:1.5px solid var(--gray-300);border-radius:20px;background:#fff;font-size:.68rem;color:var(--gray-600);cursor:pointer;white-space:nowrap;">${allHidden?'◎ 全表示':'◉ 全非表示'}</button>`);
}

function updateZoomLabel(){
  $('#zoom-label').text(ZOOM_LABELS[zoomIdx]);
  $('#btn-zoom-in').prop('disabled',zoomIdx===0);
  $('#btn-zoom-out').prop('disabled',zoomIdx===ZOOM_LEVELS.length-1);
}


/* ====================================================
   統計
   ==================================================== */
function computeStats(label,unit,data){
  if(!data.length)return null;
  const sorted=[...data].sort((a,b)=>a.年度-b.年度);
  const years=sorted.map(d=>d.年度),vals=sorted.map(d=>d.値),n=vals.length;
  const mean=vals.reduce((a,b)=>a+b,0)/n,min=Math.min(...vals),max=Math.max(...vals);
  const latest=vals[n-1];
  let avgAnnual=null,cagr=null;
  if(n>=2&&years[n-1]!==years[0]){avgAnnual=(vals[n-1]-vals[0])/(years[n-1]-years[0]);}
  if(n>=2&&vals[0]>0&&vals[n-1]>0&&years[n-1]!==years[0]){cagr=(Math.pow(vals[n-1]/vals[0],1/(years[n-1]-years[0]))-1)*100;}
  return{label,unit,n,mean,min,minYear:years[vals.indexOf(min)],max,maxYear:years[vals.indexOf(max)],avgAnnual,cagr,latest,latestYear:years[n-1]};
}

function renderStats(){
  const keys=Object.keys(activeDatasets),bar=$('#stats-bar');
  bar.empty();
  if(!keys.length){bar.html('<span id="stats-empty">指標を選択すると統計が表示されます</span>');return;}
  keys.forEach(k=>{
    const ds=activeDatasets[k],s=computeStats(ds.label,ds.unit,ds.data);
    if(!s)return;
    const color=PALETTE[ds.colorIdx%PALETTE.length];
    const cagrHtml=s.cagr!==null?`<span class="${s.cagr>=0?'pos':'neg'}">${fmtPct(s.cagr)}/年</span>`:'—';
    const trendHtml=s.avgAnnual!==null?`<span class="${s.avgAnnual>=0?'pos':'neg'}">${s.avgAnnual>=0?'+':''}${fmt(s.avgAnnual,s.unit)}/年</span>`:'—';
    const card=$(`<div class="stat-card"><div class="stat-label"><span class="stat-dot" style="background:${color}"></span>${s.label}<span style="font-size:.61rem;color:var(--gray-400)">(${s.n}年分)</span></div><div class="stat-grid"><div class="stat-item">最新(${s.latestYear})<br><span class="val">${fmt(s.latest,s.unit)}</span></div><div class="stat-item">平均<br><span class="val">${fmt(s.mean,s.unit)}</span></div><div class="stat-item">最大(${s.maxYear})<br><span class="val">${fmt(s.max,s.unit)}</span></div><div class="stat-item">最小(${s.minYear})<br><span class="val">${fmt(s.min,s.unit)}</span></div><div class="stat-item">平均年増<br><span class="val">${trendHtml}</span></div><div class="stat-item">CAGR<br><span class="val">${cagrHtml}</span></div></div></div>`);
    card.css('border-left-color',color);
    bar.append(card);
  });
}


/* ====================================================
   プロジェクト管理
   ==================================================== */
function loadProjects(){
  $.get(API.projects).done(res=>{
    if(!res.success){toast('プロジェクトの読込に失敗','error');return;}
    allProjects=res.projects;
    renderProjectSelector(res.projects);
  }).fail(()=>toast('通信エラー','error'));
}

function renderProjectSelector(projects){
  const sel=$('#project-select');
  const prevId=currentProjectId;
  sel.empty().append('<option value="">— プロジェクトを選択 —</option>');
  projects.forEach(p=>{
    const icon={'public':'🔓','domestic':'🏫','group':'👥','private':'🔒'}[p.access_policy]||'🔒';
    sel.append(`<option value="${p.id}">${icon} ${p.name} (${p.indicator_count}件)</option>`);
  });
  if(prevId) sel.val(prevId);
}

function renderProjectInfo(p){
  if(!p){$('#project-info').hide();return;}
    const policyLabel={'public':'🔓 パブリック','domestic':'🏫 学内公開','group':'👥 グループ','private':'🔒 プライベート'}[p.access_policy]||p.access_policy;
    const policyClass={'public':'policy-public','domestic':'policy-domestic','group':'policy-group','private':'policy-private'}[p.access_policy]||'policy-public';
  let html=`<div><span class="pi-policy ${policyClass}">${policyLabel}</span></div>`;
  if(p.group_name) html+=`<div style="font-size:.67rem;color:var(--gray-500);">👥 ${p.group_name}</div>`;
  html+=`<div style="font-size:.67rem;color:var(--gray-500);">👤 ${p.owner_name||'—'}</div>`;
  if(p.description) html+=`<div style="font-size:.67rem;color:var(--gray-500);margin-top:3px;">${p.description}</div>`;
  if(p.can_edit){
    html+=`<div class="pi-actions"><button class="btn btn-outline" id="btn-edit-project" style="font-size:.67rem;padding:2px 7px;">✏️ 編集</button><button class="btn" id="btn-delete-project" style="font-size:.67rem;padding:2px 7px;background:#fee2e2;color:#b91c1c;border:none;">🗑 削除</button></div>`;
  }
  $('#project-info').html(html).show();
}

$('#project-select').on('change',function(){
  const pid=parseInt($(this).val());
  if(!pid){
    currentProjectId=null;currentProject=null;
    $('#project-info').hide();
    clearAllDatasets();
    $('#ind-list').html('<span style="color:var(--gray-400);font-size:.75rem;">プロジェクトを選択してください</span>');
    $('#ind-count').text('—');
    return;
  }
  currentProjectId=pid;
  currentProject=allProjects.find(p=>p.id===pid)||null;
  renderProjectInfo(currentProject);
  clearAllDatasets();
  loadProjectIndicators(pid);
});

$(document).on('click','#btn-edit-project',function(){
  openProjectModal(currentProject);
});

$(document).on('click','#btn-delete-project',function(){
  if(!currentProject)return;
  if(!confirm(`プロジェクト「${currentProject.name}」を削除しますか？\n含まれる全指標も削除されます。`))return;
  $.ajax({url:`${API.projects}/${currentProjectId}`,method:'DELETE'})
    .done(res=>{
      if(res.success){
        toast('プロジェクトを削除しました','success');
        currentProjectId=null;currentProject=null;
        clearAllDatasets();
        $('#ind-list').html('<span style="color:var(--gray-400);font-size:.75rem;">プロジェクトを選択してください</span>');
        $('#ind-count').text('—');
        $('#project-info').hide();
        loadProjects();
      }else toast(res.error||'削除に失敗','error');
    }).fail(()=>toast('通信エラー','error'));
});

/* ── プロジェクトモーダル ── */
function openProjectModal(project=null){
  editingProjectId = project ? project.id : null;
  $('#proj-modal-title').text(project ? 'プロジェクトを編集' : 'プロジェクトを作成');
  $('#pf-save-label').text(project ? '更新する' : '作成する');
  $('#pf-name').val(project ? (project.name || '') : '');
  $('#pf-desc').val(project ? (project.description || '') : '');

  const policyVal = (project && project.access_policy) ? project.access_policy : 'public';
  document.getElementById('pf-policy').value = policyVal;
  toggleAccessGroupWrap(policyVal);

  $.get(API.groups).done(res => {
    const sel = $('#pf-group');
    sel.empty().append('<option value="">— なし（オーナーのみ）—</option>');
    const agList = $('#access-group-list');
    agList.empty();
    if(res.success){
      res.groups.forEach(g => {
        sel.append(`<option value="${g.id}">${g.name}</option>`);
        const checked = (project && (project.access_group_ids||[]).includes(g.id)) ? 'checked' : '';
        agList.append(`
          <label style="display:flex;align-items:center;gap:6px;padding:2px 0;cursor:pointer;">
            <input type="checkbox" class="ag-check" value="${g.id}" ${checked}
                   style="width:13px;height:13px;accent-color:var(--primary);">
            ${g.name}
          </label>`);
      });
    }
    if(project && project.group_id) sel.val(project.group_id);
  });

  $('#proj-modal').addClass('open');
}

$('#btn-new-project').on('click',()=>openProjectModal(null));
$('#proj-modal-close,#pf-cancel').on('click',()=>$('#proj-modal').removeClass('open'));
$('#proj-modal').on('click',function(e){if(e.target===this)$(this).removeClass('open');});

$('#pf-save').on('click',function(){
  const name=$('#pf-name').val().trim();
  if(!name){toast('プロジェクト名を入力してください','info');return;}
        const payload={
          name,
          description:$('#pf-desc').val().trim(),
          group_id:$('#pf-group').val()||null,
          access_policy:$('#pf-policy').val(),
          access_group_ids:$('.ag-check:checked').map(function(){ return parseInt($(this).val()); }).get()
        };
  const $btn=$(this);
  $btn.prop('disabled',true).html('<span class="spinner"></span> 処理中…');

  const isEdit=editingProjectId!==null;
  const req=isEdit
    ?$.ajax({url:`${API.projects}/${editingProjectId}`,method:'PUT',contentType:'application/json',data:JSON.stringify(payload)})
    :$.ajax({url:API.projects,method:'POST',contentType:'application/json',data:JSON.stringify(payload)});

  req.done(res=>{
    if(res.success){
      toast(isEdit?'プロジェクトを更新しました':'プロジェクトを作成しました','success');
      $('#proj-modal').removeClass('open');
      // ★ loadProjects().then?... を削除し、以下だけに統一
      $.get(API.projects).done(r=>{
        if(r.success){
          allProjects=r.projects;
          renderProjectSelector(r.projects);
          if(currentProjectId){
            currentProject=r.projects.find(p=>p.id===currentProjectId)||null;
            renderProjectInfo(currentProject);
          }
          if(!isEdit&&res.id){
            currentProjectId=res.id;
            currentProject=r.projects.find(p=>p.id===res.id)||null;
            $('#project-select').val(res.id);
            renderProjectInfo(currentProject);
            loadProjectIndicators(res.id);
          }
        }
      });
    }else toast(res.error||'処理に失敗','error');
  }).fail(()=>toast('通信エラー','error'))
    .always(()=>$btn.prop('disabled',false).html(`💾 <span id="pf-save-label">${isEdit?'更新する':'作成する'}</span>`));
});

/* ====================================================
   policy切替でグループ選択欄を表示切替
   ==================================================== */

function toggleAccessGroupWrap(val){
  $('#access-group-wrap').toggle(val === 'group');
}

$('#pf-policy').on('change', function(){
  toggleAccessGroupWrap($(this).val());
});

/* ====================================================
   指標パネル（プロジェクトスコープ）
   ==================================================== */
function loadProjectIndicators(pid){
  $('#ind-list').html('<span style="color:var(--gray-400);font-size:.75rem;">読込中…</span>');
  $('#ind-count').text('読込中…');
  $.get(API.projIndicators(pid)).done(res=>{
    if(!res.success){toast('指標の読込に失敗','error');return;}
    renderIndicatorList(res.indicators,res.can_edit,pid);
    $('#ind-count').text(res.indicators.length+'件');
    updateEditBtnStates();
  }).fail(()=>toast('通信エラー','error'));
}

function renderIndicatorList(indicators, canEdit, pid){
  const list=$('#ind-list');
  list.empty();
  // ★追加：指標が存在する場合のみ検索ボックスを表示
  if (indicators.length) {
      $('#ind-search').val('');
      $('#ind-search-info').text('');
      $('#ind-search-wrap').show();
    } else {
      $('#ind-search-wrap').hide();
  }
  if(!indicators.length){
    list.html('<span style="color:var(--gray-400);font-size:.73rem;">指標がありません。<br>右のエディタで追加できます。</span>');
    return;
  }
  indicators.forEach(ind=>{
    const row=$(`
      <div class="ind-row" data-id="${ind.id}" data-pid="${pid}">
        <input type="checkbox">
        <span class="ind-color-dot"></span>
        <span class="ind-row-label">${ind.name}
          ${ind.description?`<div class="ind-meta" style="font-size:.61rem;color:var(--gray-400);">${ind.description}</div>`:''}
        </span>
        ${canEdit?`<button class="ind-edit-btn" data-id="${ind.id}" title="編集">✏️</button><button class="ind-del-btn" data-id="${ind.id}" title="削除">🗑</button>`:''}
      </div>`);
    list.append(row);
    // 既に activeDatasets にあれば復元
    const dsKey=`ind_${pid}_${ind.id}`;
    if(activeDatasets[dsKey]){
      const color=PALETTE[activeDatasets[dsKey].colorIdx%PALETTE.length];
      row.addClass('active');
      row.find('.ind-color-dot').css('background',color);
      row.find('input[type="checkbox"]').prop('checked',true);
    }
  });

  list.off('change','input[type="checkbox"]').on('change','input[type="checkbox"]',function(){
    const row=$(this).closest('.ind-row');
    toggleDataset(row.data('id'),row.find('.ind-row-label').contents().first().text().trim(),'',row.data('pid'));
  });

  list.off('click','.ind-edit-btn').on('click','.ind-edit-btn',function(e){
    e.stopPropagation();
    startEditIndicator($(this).data('id'));
  });

  list.off('click','.ind-del-btn').on('click','.ind-del-btn',function(e){
    e.stopPropagation();
    const iid=$(this).data('id');
    const name=$(this).closest('.ind-row').find('.ind-row-label').contents().first().text().trim();
    if(!confirm(`「${name}」を削除しますか？`))return;
    $.ajax({url:API.projIndicator(currentProjectId,iid),method:'DELETE'})
      .done(res=>{
        if(res.success){removeDataset(currentProjectId,iid);loadProjectIndicators(currentProjectId);toast('削除しました','success');}
        else toast(res.error||'削除に失敗','error');
      });
  });
  updateEditBtnStates();
}


/* ====================================================
   データセット管理
   ==================================================== */
function addDataset(pid, iid, label, unit, data){
  const dsKey=`ind_${pid}_${iid}`;
  if(activeDatasets[dsKey])return;
  activeDatasets[dsKey]={label,unit,data,id:iid,pid,colorIdx:colorCounter++};
  const color=PALETTE[activeDatasets[dsKey].colorIdx%PALETTE.length];
  const row=$(`.ind-row[data-id="${iid}"]`);
  row.addClass('active').find('.ind-color-dot').css('background',color);
  row.find('input[type="checkbox"]').prop('checked',true);
  updateSelectedCount();rebuildChart();renderStats();updateEditBtnStates();
  loadAnnotationsForIndicator(pid, iid);   // ★追加
  renderAnnotationList();
}

function removeDataset(pid, iid){
  const dsKey=`ind_${pid}_${iid}`;
  delete activeDatasets[dsKey];
  hiddenDatasets.delete(dsKey);
  const row=$(`.ind-row[data-id="${iid}"]`);
  row.removeClass('active').find('.ind-color-dot').css('background','');
  row.find('input[type="checkbox"]').prop('checked',false);
  updateSelectedCount();rebuildChart();renderStats();updateEditBtnStates();
  renderAnnotationList();   // ★追加
}

function clearAllDatasets(){
  activeDatasets={};hiddenDatasets.clear();colorCounter=0;
  $('.ind-row').removeClass('active');
  $('.ind-color-dot').css('background','');
  $('input[type="checkbox"]').prop('checked',false);
  updateSelectedCount();rebuildChart();renderStats();
  // ★追加
  $('#ind-search').val('');
  $('#ind-search-info').text('');
  $('#ind-search-wrap').hide();
  clearAnnotations();        // ★追加
  renderAnnotationList();    // ★追加
}

function toggleDataset(iid, label, unit, pid){
  const dsKey=`ind_${pid}_${iid}`;
  if(activeDatasets[dsKey]){
    removeDataset(pid,iid);
    // 編集中の指標を外したら編集モードを抜ける（グラフの他系列は維持）
    if(editingIndicatorId===iid) exitEditModeKeepEditorOpen();
    return;
  }
  $.get(API.projIndData(pid,iid)).done(res=>{
    if(res.success){
      addDataset(pid,iid,label,unit||res.unit||'',res.data);
      // ★チェックした瞬間にエディタを開いてこの指標を編集対象にする
      startEditIndicator(iid,{scroll:false});
    }
    else{toast(res.error||'データ取得に失敗','error');$(`.ind-row[data-id="${iid}"] input`).prop('checked',false);}
  }).fail(()=>{toast('通信エラー','error');$(`.ind-row[data-id="${iid}"] input`).prop('checked',false);});
}

function exitEditModeKeepEditorOpen(){
  editingIndicatorId=null;
  editModeBackup=null;
  lastSqlTestResult=null;
  $('#sql-editor').val('');
  $('#sql-result').empty();
  $('#save-form').removeClass('show');
  $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();
  $('#save-form-btns').show();
  $('#save-form-title').text('✅ SQL が実行できました。指標として登録します：');
  $('#btn-save-label').text('登録する');
  renderAnnotationList();
}


function updateSelectedCount(){
  const n=Object.keys(activeDatasets).length;
  if(n>0){$('#selected-count').text(`選択中 ${n}`).show();$('#btn-clear-all').show();}
  else{$('#selected-count').hide();$('#btn-clear-all').hide();}
}

function updateEditBtnStates(){
  // 鉛筆ボタンは常時有効（SQLが壊れて選択不能な指標も修復できるようにする）
  $('.ind-edit-btn').each(function(){
    const iid=$(this).data('id');
    const pid=currentProjectId;
    const active=!!activeDatasets[`ind_${pid}_${iid}`];
    $(this).removeClass('disabled').attr('title',active?'編集（グラフ表示中）':'編集');
  });
}


/* ====================================================
   レイアウト
   ==================================================== */
function forceRelayout(){
  requestAnimationFrame(()=>{
    requestAnimationFrame(()=>{
      if(myChart){
        myChart.resize();
        myChart.update('none');
      }
    });
  });
}

$('#btn-refresh-layout').on('click',function(){
  forceRelayout();
  const $btn=$(this);
  $btn.css('background','rgba(255,255,255,.4)');
  setTimeout(()=>$btn.css('background','rgba(255,255,255,.15)'),400);
});

$(window).on('resize', function(){
