});


/* ====================================================
   エディタパネル
   ==================================================== */
function openEditor(){
  $('#editor-col').css('display','flex');
  $('#layout').addClass('editor-open');

  if(!currentProjectId){
    $('#editor-proj-notice').show();
  }else{
    $('#editor-proj-notice').hide();
  }

  $('#btn-toggle-editor').addClass('active');

  if($('#table-list-box').hasClass('open') && !$('#table-list-box').children().length){
    loadTableList();
  }

  requestAnimationFrame(() => forceRelayout());
}

function closeEditor(){
  $('#editor-col').css('display','none');
  $('#layout').removeClass('editor-open');
  $('#btn-toggle-editor').removeClass('active');

  if(editingIndicatorId!==null){
    if(editModeBackup){
      const { dsKey, data } = editModeBackup;
      if(activeDatasets[dsKey]){
        activeDatasets[dsKey].data = data;
        rebuildChart();
        renderStats();
      }
    }
    editingIndicatorId = null;
    editModeBackup = null;
    lastSqlTestResult = null;
    $('#sql-editor').val('');
    $('#sql-result').empty();
    $('#save-form').removeClass('show');
    $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();
    $('#save-form-btns').show();
    $('#save-form-title').text('✅ SQL が実行できました。指標として登録します：');
    $('#btn-save-label').text('登録する');
  }

  requestAnimationFrame(() => forceRelayout());
}

$('#btn-toggle-editor').on('click',function(){
  if($('#layout').hasClass('editor-open'))closeEditor();else openEditor();
});
$('#btn-close-editor').on('click',()=>closeEditor());


/* ====================================================
   テーブル一覧（エディタ補助）
   ==================================================== */
function loadTableList(){
  $.get(API.tableList).done(res=>{
    if(!res.success)return;
    const box=$('#table-list-box');
    box.empty();
    res.tables.forEach(t=>{
      const span=$(`<span class="tname">\`${t}\`</span>`);
      span.on('click',function(){
        const ta=document.getElementById('sql-editor');
        const s=ta.selectionStart,ins='`'+t+'`';
        ta.value=ta.value.slice(0,s)+ins+ta.value.slice(ta.selectionEnd);
        ta.focus();ta.setSelectionRange(s+ins.length,s+ins.length);
      });
      box.append(span);
    });
  });
}

$('#table-list-toggle').on('click',function(){
  const box=$('#table-list-box');
  box.toggleClass('open');
  $('#tl-arrow').text(box.hasClass('open')?'▼':'▶');
  if(box.hasClass('open')&&!box.children().length)loadTableList();
});


/* ====================================================
   SQL エディタ
   ==================================================== */
$('#btn-sql-run').on('click',function(){
  const sql=$('#sql-editor').val().trim();
  if(!sql){toast('SQLを入力してください','info');return;}
  const $btn=$(this);
  $btn.prop('disabled',true).html('<span class="spinner"></span> 実行中…');
  $('#sql-result').empty();
  if(editingIndicatorId===null)$('#save-form').removeClass('show');
  lastSqlTestResult=null;

  $.ajax({url:API.sqlTest,method:'POST',contentType:'application/json',data:JSON.stringify({sql})})
    .done(res=>{
      if(res.success){
        renderSqlResult(res);lastSqlTestResult=res;
        if(editingIndicatorId!==null){
          prepSaveForm(res.columns);
          // グラフプレビュー更新
          const dsKey=`ind_${currentProjectId}_${editingIndicatorId}`;
          const yearCol=$('#f-year-col').val(),valCol=$('#f-val-col').val();
          if(activeDatasets[dsKey]){
            const newData=res.rows.map(r=>({年度:parseInt(r[yearCol]),値:parseFloat(r[valCol])})).filter(d=>!isNaN(d.年度)&&!isNaN(d.値));
            if(newData.length){activeDatasets[dsKey].data=newData;rebuildChart();renderStats();}
          }
          $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').show();
          $('#save-form-btns').hide();
        }else{
          prepSaveForm(res.columns);
        }
      }else{
        $('#sql-result').html(`<div class="err-msg">⚠️ ${res.error}</div>`);
      }
    })
    .fail(xhr=>{
      let msg='通信エラー';
      try{const r=JSON.parse(xhr.responseText);if(r&&r.error)msg=r.error;}catch(e){}
      $('#sql-result').html(`<div class="err-msg">⚠️ ${msg}</div>`);
    })
    .always(()=>$btn.prop('disabled',false).html('▶ SQLを実行'));
});

$('#btn-sql-clear').on('click',function(){
  if(editingIndicatorId!==null&&editModeBackup){
    const{dsKey,data}=editModeBackup;
    if(activeDatasets[dsKey]){activeDatasets[dsKey].data=data;rebuildChart();renderStats();}
  }
  $('#sql-editor').val('');$('#sql-result').empty();$('#save-form').removeClass('show');
  lastSqlTestResult=null;editingIndicatorId=null;editModeBackup=null;
  $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();
  $('#save-form-btns').show();
  $('#save-form-title').text('✅ SQL が実行できました。指標として登録します：');
  $('#btn-save-label').text('登録する');
});

function renderSqlResult(res){
  if(!res.rows.length){$('#sql-result').html('<div class="result-info">✅ 実行成功（0件）</div>');return;}
  let html=`<div class="result-info">✅ ${res.rows.length}行（最大20行）</div><div class="result-table-wrap"><table class="result-table"><thead><tr>`;
  res.columns.forEach(c=>{html+=`<th>${c}</th>`;});
  html+='</tr></thead><tbody>';
  res.rows.forEach(r=>{
    html+='<tr>';
    res.columns.forEach(c=>{const v=r[c];html+=`<td>${v===null?'<span style="color:#ccc">NULL</span>':v}</td>`;});
    html+='</tr>';
  });
  html+='</tbody></table></div>';
  $('#sql-result').html(html);
}

function prepSaveForm(columns){
  const yearSel=$('#f-year-col'),valSel=$('#f-val-col');
  yearSel.empty();valSel.empty();
  columns.forEach(c=>{yearSel.append(`<option value="${c}">${c}</option>`);valSel.append(`<option value="${c}">${c}</option>`);});
  yearSel.val(columns.find(c=>c.includes('年度')||c.toLowerCase().includes('year'))||columns[0]);
  valSel.val(columns.find(c=>c==='値'||c.includes('値'))||columns[columns.length-1]);
  $('#save-form').addClass('show');
}


/* ── 新規登録ボタン ── */
$('#btn-save').on('click',function(){
  if(!lastSqlTestResult||editingIndicatorId!==null)return;
  if(!currentProjectId){toast('プロジェクトを選択してください','info');return;}
  let name=$('#f-name').val().trim();
  const $btn=$(this);
  $btn.prop('disabled',true).html('<span class="spinner"></span> 保存中…');

  const doSave=(resolvedName,autoNamed)=>{
    $.ajax({url:API.projIndicators(currentProjectId),method:'POST',contentType:'application/json',
      data:JSON.stringify({name:resolvedName,sql_query:$('#sql-editor').val().trim(),
        value_column:$('#f-val-col').val(),year_column:$('#f-year-col').val(),
        description:$('#f-desc').val().trim()})})
      .done(res=>{
        if(res.success){
          toast(autoNamed?`「${resolvedName}」として自動登録しました`:`「${resolvedName}」を登録しました`,autoNamed?'info':'success');
          resetForm();loadProjectIndicators(currentProjectId);
        }else toast(res.error||'保存に失敗','error');
      })
      .fail(()=>toast('通信エラー','error'))
      .always(()=>$btn.prop('disabled',false).html('💾 <span id="btn-save-label">登録する</span>'));
  };

  if(name){doSave(name,false);return;}
  // 名前省略 → I999_N 自動採番
  $.get(API.projIndicators(currentProjectId)).done(res=>{
    let maxN=0;
    if(res.success)res.indicators.forEach(ind=>{const m=ind.name.match(/^I999_(\d+)/);if(m)maxN=Math.max(maxN,parseInt(m[1],10));});
    doSave(`I999_${maxN+1}`,true);
  }).fail(()=>doSave('I999_1',true));
});

$('#btn-save-cancel').on('click',function(){
  $('#save-form').removeClass('show');lastSqlTestResult=null;editingIndicatorId=null;editModeBackup=null;
  $('#save-form-title').text('✅ SQL が実行できました。指標として登録します：');
  $('#btn-save-label').text('登録する');
  $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();
  $('#save-form-btns').show();
});


/* ── 編集モード開始 ── */
function startEditIndicator(iid, opts){
  opts = opts || {};
  if(!currentProjectId)return;
  const dsKey=`ind_${currentProjectId}_${iid}`;
  // 選択中ならグラフ復元用にバックアップ。未選択（SQLエラー等で選択不能含む）でも編集は可能。
  editModeBackup=activeDatasets[dsKey]
    ?{dsKey,data:activeDatasets[dsKey].data.map(d=>({...d}))}
    :null;

  $.get(API.projIndicator(currentProjectId,iid)).done(res=>{
    if(!res.success){toast('指標の取得に失敗','error');return;}
    const g=res.indicator;
    editingIndicatorId=g.id;
    renderAnnotationList();   // ★追加（編集モード開始時にリストを更新）
    openEditor();
    $('#sql-editor').val(g.sql_query);
    $('#f-name').val(g.name);$('#f-desc').val(g.description||'');
    $('#sql-result').empty();lastSqlTestResult=null;
    $('#save-form-title').text('✏️ 指標を編集します（SQLを実行でグラフも更新されます）：');
    $('#save-form-btns').hide();
    $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();

    $.ajax({url:API.sqlTest,method:'POST',contentType:'application/json',data:JSON.stringify({sql:g.sql_query})})
      .done(sr=>{
        const columns=sr.success?sr.columns:[g.year_column,g.value_column];
        const yearSel=$('#f-year-col'),valSel=$('#f-val-col');
        yearSel.empty();valSel.empty();
        columns.forEach(c=>{yearSel.append(`<option value="${c}">${c}</option>`);valSel.append(`<option value="${c}">${c}</option>`);});
        yearSel.val(g.year_column);valSel.val(g.value_column);
        if(sr.success){lastSqlTestResult=sr;renderSqlResult(sr);$('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').show();$('#save-form-btns').hide();}
        else{$('#sql-result').html(`<div class="err-msg">⚠️ 保存されているSQLの実行に失敗しています：${sr.error||''}<br>SQLを修正して「SQLを実行」→「更新する」で修復できます。</div>`);}
      });
    $('#save-form').addClass('show');
    if(opts.scroll!==false){
      document.getElementById('sql-editor').scrollIntoView({behavior:'smooth',block:'center'});
    }
  }).fail(()=>toast('通信エラー','error'));
}


/* ── 更新確定 ── */
$('#btn-update-confirm').on('click',function(){
  if(!lastSqlTestResult||editingIndicatorId===null){toast('先にSQLを実行してください','info');return;}
  const name=$('#f-name').val().trim();
  if(!name){toast('指標名を入力してください','info');return;}
  const $btn=$(this),updatedId=editingIndicatorId;
  const dsKey=`ind_${currentProjectId}_${updatedId}`;
  $btn.prop('disabled',true).html('<span class="spinner"></span> 更新中…');

  $.ajax({url:API.projIndicator(currentProjectId,updatedId),method:'PUT',contentType:'application/json',
    data:JSON.stringify({name,sql_query:$('#sql-editor').val().trim(),value_column:$('#f-val-col').val(),year_column:$('#f-year-col').val(),description:$('#f-desc').val().trim()})})
    .done(res=>{
      if(res.success){
        toast(`「${name}」を更新しました`,'success');
        resetForm();loadProjectIndicators(currentProjectId);
        if(activeDatasets[dsKey]){
          $.get(API.projIndData(currentProjectId,updatedId)).done(dr=>{
            if(dr.success&&activeDatasets[dsKey]){activeDatasets[dsKey].data=dr.data;rebuildChart();renderStats();}
          });
        }
      }else toast(res.error||'更新に失敗','error');
    })
    .fail(()=>toast('通信エラー','error'))
    .always(()=>$btn.prop('disabled',false).html('💾 更新する'));
});

$('#btn-update-cancel').on('click',function(){
  if(editModeBackup){const{dsKey,data}=editModeBackup;if(activeDatasets[dsKey]){activeDatasets[dsKey].data=data;rebuildChart();renderStats();}}
  editingIndicatorId=null;editModeBackup=null;lastSqlTestResult=null;
  $('#save-form').removeClass('show');$('#sql-editor').val('');$('#sql-result').empty();
  $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();
  $('#save-form-btns').show();
  $('#save-form-title').text('✅ SQL が実行できました。指標として登録します：');
});

function resetForm(){
  $('#save-form').removeClass('show');$('#sql-editor').val('');$('#sql-result').empty();$('#f-name,#f-desc').val('');
  lastSqlTestResult=null;editingIndicatorId=null;editModeBackup=null;
  $('#save-form-title').text('✅ SQL が実行できました。指標として登録します：');
  $('#btn-save-label').text('登録する');
  $('#edit-action-sep,#btn-update-confirm,#btn-update-cancel').hide();
  $('#save-form-btns').show();
}


/* ====================================================
   凡例・ズーム・スケール
   ==================================================== */
$('#chart-legend').on('click','.legend-btn',function(){
