  if(hiddenDatasets.has(k))hiddenDatasets.delete(k);else hiddenDatasets.add(k);
  rebuildChart();
});
$('#chart-legend').on('click','#btn-legend-hide-all',function(){
  const keys=Object.keys(activeDatasets),allHidden=keys.every(k=>hiddenDatasets.has(k));
  if(allHidden)keys.forEach(k=>hiddenDatasets.delete(k));else keys.forEach(k=>hiddenDatasets.add(k));
  rebuildChart();
});

$('#btn-zoom-in').on('click',function(){if(zoomIdx>0){zoomIdx--;updateZoomLabel();rebuildChart();}});
$('#btn-zoom-out').on('click',function(){if(zoomIdx<ZOOM_LEVELS.length-1){zoomIdx++;updateZoomLabel();rebuildChart();}});

$('#btn-scale-norm,#btn-scale-abs,#btn-scale-zero').on('click',function(){
  currentScaleMode=$(this).data('scale');
  $('#btn-scale-norm,#btn-scale-abs,#btn-scale-zero').removeClass('active');
  $(this).addClass('active');
  const isNorm=(currentScaleMode==='norm');
