    abs : '縦軸：絶対値表示（全系列共通スケール / 線形）',
    zero: '縦軸：0ベース表示（最小値=0固定 / 上限自動調整）',
    norm: '縦軸：相対値表示（各系列の平均=中央 / tanh圧縮）| ツールチップで実値表示'
  };
  $('#scale-info').text(infoMap[currentScaleMode]);
  rebuildChart();
});

/* ====================================================
   指標検索（部分一致フィルタ）
   ==================================================== */
$('#ind-search').on('input', function() {
  const kw = $(this).val().trim().toLowerCase();
  let visible = 0, total = 0;

  $('#ind-list .ind-row').each(function() {
    const name = $(this).find('.ind-row-label').contents().first().text().trim().toLowerCase();
    const desc = $(this).find('.ind-meta').text().toLowerCase();
    const match = !kw || name.includes(kw) || desc.includes(kw);
    $(this).toggle(match);
    if (match) visible++;
    total++;
  });

  if (kw) {
    $('#ind-search-info').text(`${visible} / ${total} 件表示`);
  } else {
    $('#ind-search-info').text('');
  }
}).on('focus', function() {
  $(this).css('border-color', 'var(--primary)');
}).on('blur', function() {
  $(this).css('border-color', 'var(--gray-300)');
});

