/** 指標のアノテーションをDBから取得してキャッシュ */
function loadAnnotationsForIndicator(pid, iid) {
  const key = `ind_${pid}_${iid}`;
  return $.get(API.projIndAnnotations(pid, iid)).done(res => {
    if (res.success) {
      annotationsByKey[key] = res.annotations;
      rebuildChart();
      renderAnnotationList();   // ★追加
    }
  });
}

/** プロジェクト切替時：全キャッシュをクリア */
function clearAnnotations() {
  annotationsByKey = {};
  rebuildChart();
}

/**
 * エディタ上のアノテーションリストを描画
 * editing中の指標（editingIndicatorId）またはチェック中1件に対応
 */
function renderAnnotationList() {
  const list    = $('#ann-list');
  const canEdit = currentProject && currentProject.can_edit;
  const iid     = currentAnnIndicatorId();
  const pid     = currentProjectId;

  list.empty();

  if (!iid) {
    list.html('<span style="color:var(--gray-400);font-size:.71rem;">指標を1件選択すると管理できます</span>');
    $('#ann-ind-name').text('');
    return;
  }

  const key  = `ind_${pid}_${iid}`;
  const anns = annotationsByKey[key] || [];
  const ds   = activeDatasets[key];
  $('#ann-ind-name').text(ds ? ds.label : '');

  if (!anns.length) {
    list.html('<span style="color:var(--gray-400);font-size:.71rem;">ラインなし</span>');
    return;
  }

  anns.forEach(ann => {
    const editBtn = canEdit
      ? `<button class="ann-edit-btn" data-id="${ann.id}"
                 style="background:none;border:none;cursor:pointer;
                        color:var(--gray-400);font-size:.78rem;line-height:1;padding:0 2px;"
                 title="編集">✏️</button>
         <button class="ann-del-btn" data-id="${ann.id}"
                 style="background:none;border:none;cursor:pointer;
                        color:var(--gray-400);font-size:.78rem;line-height:1;padding:0;"
                 title="削除">🗑</button>`
      : '';
    list.append(`
      <div style="display:flex;align-items:center;gap:5px;padding:3px 5px;
                  border-radius:4px;background:var(--gray-50);margin-bottom:3px;">
        <span style="width:11px;height:11px;border-radius:2px;flex-shrink:0;
                     background:${ann.color};border:1px solid rgba(0,0,0,.12);"></span>
        <span style="flex:1;font-size:.71rem;color:var(--gray-700);">
          ${ann.label}
          <span style="color:var(--gray-400)">= ${ann.value}</span>
        </span>
        ${editBtn}
      </div>`);
  });
}

/**
 * 現在アノテーション操作対象の indicator_id を返す。
 * 編集モード中はその指標、そうでなければ選択中の指標が1件だけのときその指標。
 */
function currentAnnIndicatorId() {
  if (editingIndicatorId !== null) return editingIndicatorId;
  const keys = Object.keys(activeDatasets);
  if (keys.length === 1) {
    return activeDatasets[keys[0]].id;
  }
  return null;
}

$('#btn-ann-add').on('click', function () {
  if (!currentProjectId) { toast('プロジェクトを選択してください', 'info'); return; }
  if (!currentProject || !currentProject.can_edit) { toast('編集権限がありません', 'error'); return; }
  const iid = currentAnnIndicatorId();
  if (!iid) { toast('指標を1件だけ選択してください', 'info'); return; }

  const label = $('#ann-label').val().trim();
  const value = parseFloat($('#ann-value').val());
  const color = $('#ann-color').val();
  if (!label)       { toast('ラベルを入力してください', 'info'); return; }
  if (isNaN(value)) { toast('値を入力してください',   'info'); return; }

  const $btn = $(this);
  $btn.prop('disabled', true);

  // ── 更新モード ──
  if (editingAnnId !== null) {
    const aid = editingAnnId;
    $.ajax({
      url: API.projIndAnnotation(currentProjectId, iid, aid),
      method: 'PUT', contentType: 'application/json',
      data: JSON.stringify({ label, value, color })
    }).done(res => {
      if (res.success) {
        const key = `ind_${currentProjectId}_${iid}`;
        const ann = (annotationsByKey[key] || []).find(a => a.id === aid);
        if (ann) { ann.label = label; ann.value = value; ann.color = color; }
        renderAnnotationList();
        rebuildChart();
        cancelAnnEdit();
        toast('基準線を更新しました', 'success');
      } else {
        toast(res.error || '更新に失敗', 'error');
      }
    }).fail(() => toast('通信エラー', 'error'))
      .always(() => $btn.prop('disabled', false));
    return;
  }

  // ── 追加モード ──
  $.ajax({
    url: API.projIndAnnotations(currentProjectId, iid),
    method: 'POST', contentType: 'application/json',
    data: JSON.stringify({ label, value, color })
  }).done(res => {
    if (res.success) {
      const key = `ind_${currentProjectId}_${iid}`;
      if (!annotationsByKey[key]) annotationsByKey[key] = [];
      annotationsByKey[key].push({ id: res.id, label, value, color });
      renderAnnotationList();
      rebuildChart();
      $('#ann-label').val('');
      $('#ann-value').val('');
      toast('基準線を追加しました', 'success');
    } else {
      toast(res.error || '追加に失敗', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'))
    .always(() => $btn.prop('disabled', false));
});

$('#ann-list').on('click', '.ann-del-btn', function () {
  const aid = parseInt($(this).data('id'));
  const iid = currentAnnIndicatorId();
  if (!iid) return;
  $.ajax({
    url: API.projIndAnnotation(currentProjectId, iid, aid),
    method: 'DELETE'
  }).done(res => {
    if (res.success) {
      const key = `ind_${currentProjectId}_${iid}`;
      annotationsByKey[key] = (annotationsByKey[key] || []).filter(a => a.id !== aid);
      renderAnnotationList();
      rebuildChart();
      toast('削除しました', 'success');
    } else {
      toast(res.error || '削除に失敗', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

// ── 編集ボタン：フォームに値を流し込む ──

$('#ann-list').on('click', '.ann-edit-btn', function () {
  const aid  = parseInt($(this).data('id'));
  const iid  = currentAnnIndicatorId();
  if (!iid) return;
  const key  = `ind_${currentProjectId}_${iid}`;
  const ann  = (annotationsByKey[key] || []).find(a => a.id === aid);
  if (!ann) return;

  // フォームに値を設定
  $('#ann-label').val(ann.label);
  $('#ann-value').val(ann.value);
  $('#ann-color').val(ann.color);
  editingAnnId = aid;

  // ボタンを「更新」モードに切替
  $('#btn-ann-add')
    .text('💾 更新する')
    .removeClass('btn-outline')
    .addClass('btn-primary');
  $('#btn-ann-cancel-edit').show();
});

// ── 編集キャンセル ──
$('#btn-ann-cancel-edit').on('click', function () {
  cancelAnnEdit();
});

function cancelAnnEdit() {
  editingAnnId = null;
  $('#ann-label').val('');
  $('#ann-value').val('');
  $('#ann-color').val('#ef4444');
  $('#btn-ann-add')
    .text('＋ 追加')
    .removeClass('btn-primary')
    .addClass('btn-outline');
  $('#btn-ann-cancel-edit').hide();
}

