$('#btn-export-json').on('click', function() {
  const $pre   = $('#exp-json');
  const $count = $('#exp-count');

  if (!currentProjectId) {
    toast('プロジェクトを選択してください', 'info');
    return;
  }

  // activeDatasets の label（= 指標名）を収集
  const selectedNames = Object.values(activeDatasets).map(ds => ds.label);

  if (selectedNames.length === 0) {
    $pre.text('指標が選択されていません。\n左カラムのチェックボックスで指標を選択してから\nエクスポートしてください。');
    $count.text('0件（選択中）');
    $('#exp-modal').addClass('open');
    return;
  }

  $pre.text('読込中...');
  $count.text('');
  $('#exp-modal').addClass('open');

  // プロジェクトの全指標を取得してから選択中のものだけ絞り込む
  $.get(API.projExport(currentProjectId)).done(res => {
    if (!res.success) {
      $pre.text('エラー: ' + (res.error || '取得失敗'));
      return;
    }
    const payload = res.indicators
      .filter(ind => selectedNames.includes(ind.name))
      .map(ind => ({
        name        : ind.name,
        sql_query   : ind.sql_query,
        value_column: ind.value_column,
        year_column : ind.year_column,
        description : ind.description || ''
      }));

    if (payload.length === 0) {
      $pre.text('選択中の指標がデータベースに見つかりませんでした。');
      $count.text('0件（選択中）');
      return;
    }
    $pre.text(JSON.stringify(payload, null, 2));
    $count.text(payload.length + '件（選択中）');
  }).fail(() => {
    $pre.text('通信エラーが発生しました');
  });
});


