$('#import-execute').on('click',function(){
  const text=$('#import-json-text').val().trim();
  if(!text){toast('JSONを入力してください','info');return;}
  let indicators;
  try{indicators=JSON.parse(text);}catch(e){toast('JSONの形式が正しくありません: '+e.message,'error');return;}
  if(!Array.isArray(indicators)){toast('JSONは配列形式にしてください','error');return;}

  const $btn=$(this);
  $btn.prop('disabled',true).html('<span class="spinner"></span> インポート中…');
  $('#import-result').empty();

  $.ajax({url:API.projImport(currentProjectId),method:'POST',contentType:'application/json',data:JSON.stringify({indicators})})
    .done(res=>{
      if(res.success){
        let html=`<div style="color:var(--success);font-weight:600;">✅ ${res.imported}件をインポートしました（スキップ: ${res.skipped}件）</div>`;
        if(res.messages&&res.messages.length){
          html+=`<ul style="margin-top:4px;font-size:.68rem;color:var(--gray-500);">`;
          res.messages.forEach(m=>{html+=`<li>${m}</li>`;});
          html+=`</ul>`;
        }
        $('#import-result').html(html);
        loadProjectIndicators(currentProjectId);
        setTimeout(()=>$('#import-modal').removeClass('open'),2000);
      }else $('#import-result').html(`<div class="err-msg">⚠️ ${res.error}</div>`);
    })
    .fail(()=>$('#import-result').html('<div class="err-msg">⚠️ 通信エラー</div>'))
    .always(()=>$btn.prop('disabled',false).html('📥 インポート実行'));
});


