/* ====================================================
   テーブルブラウザ（変更なし）
   ==================================================== */
const TBrowser=(()=>{
  let mode='tables',allTables=[],allProjects=[],projTables=[],selectedProj=null,currentDb=null,currentTbl=null,currentPane='schema';

  function open(){$('#tb-modal').addClass('open');if(mode==='tables'&&!allTables.length)loadTables();else if(mode==='projects'&&!allProjects.length)loadProjects_tb();}
  function close(){$('#tb-modal').removeClass('open');}
  function setMode(m){mode=m;$('.tb-mode-btn').removeClass('active');$(`.tb-mode-btn[data-mode="${m}"]`).addClass('active');selectedProj=null;currentDb=currentTbl=null;resetRight();if(m==='tables'){if(!allTables.length)loadTables();else renderTableList();}else{if(!allProjects.length)loadProjects_tb();else renderProjectList_tb();}}

  function loadTables(){$('#tb-list').html('<div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">読込中...</div>');$.get(API.browserTables).done(res=>{if(res.success){allTables=res.tables;renderTableList();}else $('#tb-list').html('<div style="padding:20px;color:#e74c3c;font-size:.78rem;">取得失敗</div>');}).fail(()=>$('#tb-list').html('<div style="padding:20px;color:#e74c3c;font-size:.78rem;">通信エラー</div>'));}

  function renderTableList(){const kw=$('#tb-left-search').val().toLowerCase();const $list=$('#tb-list');$list.empty();let filtered=allTables;if(kw)filtered=allTables.filter(t=>t.table_name.toLowerCase().includes(kw)||t.database.toLowerCase().includes(kw));const byDb={};filtered.forEach(t=>(byDb[t.database]=byDb[t.database]||[]).push(t));Object.keys(byDb).sort().forEach(db=>{$list.append(`<div class="tb-group-hd">📁 ${db}</div>`);byDb[db].sort((a,b)=>a.table_name.localeCompare(b.table_name)).forEach(t=>{const active=(currentDb===t.database&&currentTbl===t.table_name)?' active':'';$list.append(`<div class="tb-item${active}" data-db="${t.database}" data-tbl="${t.table_name}"><span class="tb-name">${t.table_name}</span><span class="tb-cnt">${t.row_count}行</span></div>`);});});if(!filtered.length)$list.html('<div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">該当なし</div>');}

  function loadProjects_tb(){$('#tb-list').html('<div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">読込中...</div>');$.get(API.browserProjects).done(res=>{if(res.success){allProjects=res.projects;renderProjectList_tb();}else $('#tb-list').html('<div style="padding:20px;color:#e74c3c;font-size:.78rem;">取得失敗</div>');}).fail(()=>$('#tb-list').html('<div style="padding:20px;color:#e74c3c;font-size:.78rem;">通信エラー</div>'));}

  function renderProjectList_tb(){const kw=$('#tb-left-search').val().toLowerCase();const $list=$('#tb-list');$list.empty();let filtered=allProjects;if(kw)filtered=allProjects.filter(p=>p.name.toLowerCase().includes(kw));filtered.forEach(p=>{const active=(selectedProj&&selectedProj.id===p.id)?' active':'';$list.append(`<div class="tb-proj-card${active}" data-proj-id="${p.id}"><span class="tb-proj-name">📁 ${p.name}</span>${p.description?`<span class="tb-proj-desc">${p.description}</span>`:''}<span class="tb-proj-meta">テーブル ${p.table_count}件 / ビュー ${p.view_count}件</span></div>`);});if(!filtered.length)$list.html('<div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">プロジェクトなし</div>');}

  function loadProjectTables_tb(projId){$('#tb-list').html('<div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">読込中...</div>');$.get(API.browserProjectTables+'?project_id='+projId).done(res=>{if(!res.success){$('#tb-list').html('<div style="padding:20px;color:#e74c3c;font-size:.78rem;">取得失敗</div>');return;}projTables=res.tables||[];renderProjectTables_tb(selectedProj?selectedProj.name:'');}).fail(()=>$('#tb-list').html('<div style="padding:20px;color:#e74c3c;font-size:.78rem;">通信エラー</div>'));}

  function renderProjectTables_tb(projName){const kw=$('#tb-left-search').val().toLowerCase();const $list=$('#tb-list');$list.empty();$list.append(`<div class="tb-back-btn" id="tb-proj-back">← プロジェクト一覧</div>`);let filtered=projTables;if(kw)filtered=projTables.filter(t=>t.table_name.toLowerCase().includes(kw)||t.database_name.toLowerCase().includes(kw));if(!filtered.length){$list.append('<div style="padding:20px;color:#aaa;text-align:center;font-size:.78rem;">テーブルなし</div>');return;}const byDb={};filtered.forEach(t=>(byDb[t.database_name]=byDb[t.database_name]||[]).push(t));Object.keys(byDb).sort().forEach(db=>{$list.append(`<div class="tb-group-hd">📁 ${db}</div>`);byDb[db].forEach(t=>{const active=(currentDb===t.database_name&&currentTbl===t.table_name)?' active':'';$list.append(`<div class="tb-item${active}" data-db="${t.database_name}" data-tbl="${t.table_name}"><span class="tb-name">${t.table_name}</span></div>`);});});}

  function selectTable(db,tbl){currentDb=db;currentTbl=tbl;$('.tb-item').removeClass('active');$(`.tb-item[data-db="${db}"][data-tbl="${tbl}"]`).addClass('active');$('#tb-right-placeholder').hide();$('#tb-tabs,#tb-pane').show();$('#tb-table-label').text(`${db}.${tbl}`);showPane(currentPane);}
  function resetRight(){currentDb=currentTbl=null;$('#tb-right-placeholder').show();$('#tb-tabs,#tb-pane').hide();$('#tb-table-label').text('');}
  function showPane(pane){currentPane=pane;$('.tb-tab').removeClass('active');$(`.tb-tab[data-pane="${pane}"]`).addClass('active');$('#tb-pane-schema,#tb-pane-data').hide();if(pane==='schema'){$('#tb-pane-schema').show();loadSchema();}else{$('#tb-pane-data').show();loadData();}}
  function loadSchema(){$('#tb-schema-pre').text('取得中...');$.ajax({url:API.browserSchema,method:'POST',contentType:'application/json',data:JSON.stringify({database:currentDb,table_name:currentTbl})}).done(res=>$('#tb-schema-pre').text(res.success?res.schema:'エラー: '+res.error)).fail(()=>$('#tb-schema-pre').text('通信エラー'));}
  function loadData(){$('#tb-data-info').text('取得中...');$('#tb-data-table').empty();$.ajax({url:API.browserData,method:'POST',contentType:'application/json',data:JSON.stringify({database:currentDb,table_name:currentTbl,limit:500,offset:0})}).done(res=>{if(!res.success){$('#tb-data-info').html(`<span style="color:#e74c3c;">エラー: ${res.error}</span>`);return;}const{columns,rows,total_count}=res;$('#tb-data-info').html(`<span>${rows.length} 行表示（全 ${total_count} 行）</span><span style="color:var(--gray-400);font-size:.66rem;">※最大500行 / 読み取り専用</span>`);let html='<thead><tr>'+columns.map(c=>`<th>${c}</th>`).join('')+'</tr></thead><tbody>';rows.forEach(row=>{html+='<tr>'+columns.map(c=>{const v=row[c];return v===null||v===undefined?'<td><span class="tb-null">NULL</span></td>':`<td title="${String(v).replace(/"/g,'&quot;')}">${String(v)}</td>`;}).join('')+'</tr>';});html+='</tbody>';$('#tb-data-table').html(html);}).fail(()=>$('#tb-data-info').html('<span style="color:#e74c3c;">通信エラー</span>'));}

  function init(){
    $('#tb-close').on('click',close);
    $('#tb-modal').on('click',function(e){if(e.target===this)close();});
    $(document).on('click','.tb-mode-btn',function(){setMode($(this).data('mode'));});
    $('#tb-left-search').on('input',function(){if(mode==='tables')renderTableList();else if(selectedProj)renderProjectTables_tb(selectedProj.name);else renderProjectList_tb();});
    $(document).on('click','#tb-list .tb-item',function(){selectTable($(this).data('db'),$(this).data('tbl'));});
    $(document).on('click','#tb-list .tb-proj-card',function(){const id=parseInt($(this).data('proj-id'));selectedProj=allProjects.find(p=>p.id===id);$('.tb-proj-card').removeClass('active');$(this).addClass('active');resetRight();loadProjectTables_tb(id);});
    $(document).on('click','#tb-proj-back',function(){selectedProj=null;projTables=[];resetRight();renderProjectList_tb();});
    $(document).on('click','.tb-tab',function(){if(currentDb&&currentTbl)showPane($(this).data('pane'));});
    $(document).on('click','#tb-list .tb-group-hd',function(){$(this).nextUntil('.tb-group-hd').toggle();});
  }
  return{init};
})();

/* ====================================================
   グラフHTML出力
   ==================================================== */
$('#btn-export-chart').on('click', function() {
  const keys = Object.keys(activeDatasets);
  if (!keys.length) { toast('指標を選択してください', 'info'); return; }

  const years = [2016,2017,2018,2019,2020,2021,2022,2023,2024,2025];
  const PAL   = ['#6366f1','#10b981','#f59e0b','#ef4444','#8b5cf6',
                 '#06b6d4','#f97316','#84cc16','#ec4899','#14b8a6','#a855f7','#3b82f6'];

  const W=960, H=520, MT=20, MR=30, MB=60, ML=80;
  const PW=W-ML-MR, PH=H-MT-MB;

  const series = keys.map(k => {
    const ds = activeDatasets[k];
    const yearMap = {};
    ds.data.forEach(d => yearMap[d.年度] = d.値);
    const rawValues = years.map(y => yearMap[y] ?? null);
    let values = rawValues;
    if (currentScaleMode === 'norm') {
      const { mean, sigma } = seriesMeanSigma(ds.data);
      values = rawValues.map(v => v == null
        ? null
        : applyTanh(v, mean, sigma, ZOOM_LEVELS[zoomIdx]));
    }
    return { key: k, label: ds.label, color: PAL[ds.colorIdx % PAL.length],
             rawValues, values };
  });

  // ── Y軸範囲計算（共通） ──
  let yMin = 0, yMax = -Infinity;
  if (currentScaleMode === 'norm') {
    yMin = -1.05; yMax = 1.05;
  } else if (currentScaleMode === 'abs') {
    let rawMin = Infinity;
    series.forEach(s => s.values.forEach(v => {
      if (v != null) { rawMin = Math.min(rawMin, v); yMax = Math.max(yMax, v); }
    }));
    const pad = (yMax - rawMin) * 0.08 || Math.abs(yMax) * 0.1 || 1;
    yMin = rawMin - pad; yMax += pad;
  } else {
    series.forEach(s => s.values.forEach(v => {
      if (v != null) yMax = Math.max(yMax, v);
    }));
    yMax += yMax * 0.08 || 1;
  }

  const yPos = v => MT + PH - ((v - yMin) / (yMax - yMin)) * PH;

  const tickCount = 6;
  const ticks = [];
  for (let i = 0; i <= tickCount; i++) ticks.push(yMin + (yMax - yMin) * i / tickCount);

  function fmtTick(v) {
    const a = Math.abs(v);
    if (a >= 1000000) return (v/1000000).toFixed(1) + 'M';
    if (a >= 10000)   return v.toLocaleString('ja-JP', {maximumFractionDigits:0});
    return v.toLocaleString('ja-JP', {maximumFractionDigits:3});
  }

  // ── SVG共通部分（背景・グリッド・軸ラベル） ──
  let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">`;
  svg += `<rect width="${W}" height="${H}" fill="#fff"/>`;

  ticks.forEach(v => {
    const y = yPos(v);
    svg += `<line x1="${ML}" y1="${y}" x2="${ML+PW}" y2="${y}" stroke="#f0f0f0" stroke-width="1"/>`;
    svg += `<text x="${ML-6}" y="${y+4}" text-anchor="end" font-family="sans-serif" font-size="10" fill="#9ca3af">${fmtTick(v)}</text>`;
  });

  svg += `<rect x="${ML}" y="${MT}" width="${PW}" height="${PH}" fill="none" stroke="#e5e7eb" stroke-width="1"/>`;
  svg += `<text x="${ML+PW/2}" y="${H-8}" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#374151">年度</text>`;
  svg += `<text x="14" y="${MT+PH/2}" text-anchor="middle" font-family="sans-serif" font-size="12" fill="#374151" transform="rotate(-90,14,${MT+PH/2})">値</text>`;

  // ── 基準値ライン（共通） ──
  const drawnAnns = new Map();
  Object.keys(activeDatasets).forEach(k => {
    const dataset = activeDatasets[k];
    const { mean, sigma } = seriesMeanSigma(dataset.data);
    (annotationsByKey[k] || []).forEach(ann => {
      const displayValue = currentScaleMode === 'norm'
        ? applyTanh(ann.value, mean, sigma, ZOOM_LEVELS[zoomIdx])
        : ann.value;
      const dupKey = `${displayValue}_${ann.color}_${ann.label}`;
      if (drawnAnns.has(dupKey)) return;
      drawnAnns.set(dupKey, true);
      if (displayValue < yMin || displayValue > yMax) return;
      const yPx = yPos(displayValue);
      svg += `<line x1="${ML}" y1="${yPx}" x2="${ML+PW}" y2="${yPx}" stroke="${ann.color}" stroke-width="1.5" stroke-dasharray="6,3"/>`;
      svg += `<text x="${ML+PW-4}" y="${yPx-3}" text-anchor="end" font-family="sans-serif" font-size="11" font-weight="bold" fill="${ann.color}">${ann.label}</text>`;
    });
  });

  // ── 折れ線 / 棒グラフ 分岐 ──
  if (currentChartType === 'bar') {
    // ── 棒グラフ ──
    // データがある年度のみ表示対象
    const activeYearIndices = years.map((y, i) => i).filter(i =>
      series.some(s => s.values[i] != null)
    );
    const nYears   = activeYearIndices.length;
    const nSeries  = series.length;
    const slotW    = PW / years.length;           // 年度1コマの幅
    const barGap   = slotW * 0.12;               // コマ両端の余白
    const groupW   = slotW - barGap * 2;          // グループ全体の幅
    const barW     = Math.max(4, groupW / nSeries - 2); // 1本の棒幅
    const groupGap = (groupW - barW * nSeries) / Math.max(nSeries - 1, 1);

    activeYearIndices.forEach(i => {
      const yr  = years[i];
      const cx  = ML + (i + 0.5) * slotW;        // 年度コマの中心X
      const gx0 = cx - groupW / 2;               // グループ左端

      // X軸ラベル
      svg += `<text x="${cx}" y="${MT+PH+16}" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#6b7280">${yr}</text>`;

      series.forEach((s, si) => {
        const v = s.values[i];
        if (v == null) return;
        const bx  = gx0 + si * (barW + groupGap);
        const baseValue = Math.min(Math.max(0, yMin), yMax);
        const valueY = yPos(v);
        const baseY  = yPos(baseValue);
        const by  = Math.min(valueY, baseY);
        const bh  = Math.abs(baseY - valueY);
        const rx  = Math.min(3, barW / 4);
        // 角丸上部のみの棒
        svg += `<path d="M${bx},${by+bh} L${bx},${by+rx} Q${bx},${by} ${bx+rx},${by} L${bx+barW-rx},${by} Q${bx+barW},${by} ${bx+barW},${by+rx} L${bx+barW},${by+bh} Z" fill="${s.color}cc"/>`;
        // 値ラベル（棒の上）
        if (bh > 12) {
          svg += `<text x="${bx+barW/2}" y="${by-3}" text-anchor="middle" font-family="sans-serif" font-size="9" fill="${s.color}">${fmtTick(v)}</text>`;
        }
      });
    });

  } else {
    // ── 折れ線グラフ ──
    const xPos = i => ML + (i / (years.length - 1)) * PW;

    years.forEach((yr, i) => {
      const x = xPos(i);
      svg += `<line x1="${x}" y1="${MT}" x2="${x}" y2="${MT+PH}" stroke="#f0f0f0" stroke-width="1"/>`;
      svg += `<text x="${x}" y="${MT+PH+16}" text-anchor="middle" font-family="sans-serif" font-size="11" fill="#6b7280">${yr}</text>`;
    });

    series.forEach(s => {
      let pathD = '';
      s.values.forEach((v, i) => {
        if (v == null) return;
        const x = xPos(i), y = yPos(v);
        pathD += pathD === '' ? `M${x},${y}` : `L${x},${y}`;
      });
      if (pathD) svg += `<path d="${pathD}" fill="none" stroke="${s.color}" stroke-width="2" stroke-linejoin="round"/>`;
      s.values.forEach((v, i) => {
        if (v == null) return;
        svg += `<circle cx="${xPos(i)}" cy="${yPos(v)}" r="4" fill="#fff" stroke="${s.color}" stroke-width="2"/>`;
      });
    });
  }

  // ── 凡例（共通） ──
  const legY = MT + PH + 38;
  let legX = ML;
  series.forEach(s => {
    if (currentChartType === 'bar') {
      // 棒グラフ凡例：四角
      svg += `<rect x="${legX}" y="${legY-9}" width="12" height="12" rx="2" fill="${s.color}cc"/>`;
    } else {
      // 折れ線凡例：丸
      svg += `<rect x="${legX}" y="${legY-9}" width="12" height="12" rx="6" fill="${s.color}"/>`;
    }
    svg += `<text x="${legX+16}" y="${legY}" font-family="sans-serif" font-size="11" fill="#374151">${s.label}</text>`;
    legX += 16 + s.label.length * 7 + 20;
  });

  svg += `</svg>`;

  // ── HTMLとしてモーダルに埋め込んでプレビュー ──
  const html = `<!DOCTYPE html>
<html lang="ja"><head><meta charset="UTF-8">
<style>body{margin:0;background:#fff;display:flex;justify-content:center;padding:16px;}</style>
</head><body>${svg}</body></html>`;

  $('#svg-text').text(svg);
  $('#svg-ind-count').text(series.length + '系列 / ' + (currentChartType === 'bar' ? '棒グラフ' : '折れ線'));
  $('#svg-modal').addClass('open');
});


$('#svg-close').on('click', () => $('#svg-modal').removeClass('open'));
$('#svg-modal').on('click', function(e) { if (e.target === this) $(this).removeClass('open'); });
$('#svg-copy').on('click', function() {
  const text = $('#svg-text').text();
  if (!text) return;
  navigator.clipboard.writeText(text).then(() => {
    const $b = $(this);
    $b.text('✓ コピー完了');
    setTimeout(() => $b.text('📋 コピー'), 2000);
  });
});
/* ====================================================
   初期化
   ==================================================== */
$(document).ready(function(){
  initChart();
  updateZoomLabel();
  TBrowser.init();
  loadProjects();
});
</script>
