<body>

<div id="app-header">
  <span style="font-size:1.3rem">🔄</span>
  <div>
    <h1>データ更新</h1>
    <div class="subtitle">{{ item.table_name }}</div>
  </div>
  <div style="margin-left:auto; display:flex; gap:8px;">
    <a href="{{ url_for('index_review.table_manager') }}" class="hdr-btn">
      ← テーブル集管理に戻る
    </a>
  </div>
</div>

<div class="container">

  <!-- テーブル情報 -->
  <div class="card">
    <div class="table-info-name">{{ item.table_name }}</div>
    <div class="table-info-meta">
      データベース：{{ item.database_name }}　／　テーブル集：{{ item.set_name }}
    </div>
  </div>

  <!-- 警告 -->
  <div class="warning-box">
    <strong>⚠️ 操作前にご確認ください</strong>
    <ul>
      <li>アップロード時、テーブル内の既存データは<strong>全件削除</strong>されてExcelの内容で上書きされます。</li>
      <li>外部キー制約は一時的に無効化されます。データの整合性は担当者の責任で確認してください。</li>
      <li>必ずステップ1でダウンロードしてからローカル編集してください。</li>
    </ul>
  </div>

  <!-- 操作ステップ -->
  <div class="card">
    <div class="card-title">🔄 データ更新手順</div>

    <!-- Step 1 -->
    <div class="step">
      <div class="step-num">1</div>
      <div class="step-body">
        <div class="step-title">現在のデータをExcelでダウンロード</div>
        <div class="step-desc">
          現在のテーブル内容をExcelファイルとして取得します。<br>
          このファイルがバックアップ兼編集テンプレートになります。
        </div>
        <a href="{{ url_for('index_review.table_data_update_download', item_id=item.id) }}"
           class="btn btn-primary" id="btn-download">
          ⬇ Excelをダウンロード
        </a>
      </div>
    </div>

    <!-- Step 2 -->
    <div class="step">
      <div class="step-num">2</div>
      <div class="step-body">
        <div class="step-title">ローカルでデータを編集</div>
        <div class="step-desc">
          ダウンロードしたExcelをPC上で編集してください。<br>
          カラム構成（列の順序・名称・型）は変更しないでください。
        </div>
      </div>
    </div>

    <!-- Step 3 -->
    <div class="step">
      <div class="step-num">3</div>
      <div class="step-body">
        <div class="step-title">編集済みExcelをアップロード</div>
        <div class="step-desc">
          編集済みのExcelファイルを選択してアップロードしてください。<br>
          テーブルの内容がExcelの内容で完全に置き換えられます。
        </div>
        <label class="file-label" for="upload-file">
          📂 Excelファイルを選択
        </label>
        <input type="file" id="upload-file" accept=".xlsx">
        <div id="file-name">ファイルが選択されていません</div>
        <div style="margin-top:10px;">
          <button class="btn btn-success" id="btn-upload" disabled>
            ⬆ アップロードして更新
          </button>
        </div>
        <div id="result"></div>
      </div>
    </div>

  </div>
</div>

<script>
const UPLOAD_URL = "{{ url_for('index_review.table_data_update_upload', item_id=item.id) }}";

// ファイル選択
$('#upload-file').on('change', function() {
  const file = this.files[0];
  if (file) {
    $('#file-name').text(file.name);
    $('#btn-upload').prop('disabled', false);
  } else {
    $('#file-name').text('ファイルが選択されていません');
    $('#btn-upload').prop('disabled', true);
  }
});

// アップロード
$('#btn-upload').on('click', function() {
  const file = $('#upload-file')[0].files[0];
  if (!file) return;

  if (!confirm(
    'テーブルの既存データは全て削除され、Excelの内容で上書きされます。\n' +
    '本当に続行しますか？'
  )) return;

  const $btn = $(this);
  $btn.prop('disabled', true).html('<span class="spinner"></span> 処理中…');
  $('#result').hide().removeClass('success error');

  const formData = new FormData();
  formData.append('excel_file', file);

  $.ajax({
    url: UPLOAD_URL,
    method: 'POST',
    data: formData,
    processData: false,
    contentType: false,
  }).done(res => {
    if (res.success) {
      $('#result').addClass('success').text('✅ ' + res.message).show();
      $('#upload-file').val('');
      $('#file-name').text('ファイルが選択されていません');
    } else {
      $('#result').addClass('error').text('⚠️ ' + res.error).show();
    }
  }).fail(() => {
    $('#result').addClass('error').text('⚠️ 通信エラーが発生しました').show();
  }).always(() => {
    $btn.prop('disabled', false).html('⬆ アップロードして更新');
  });
});
</script>
</body>
</html>

