  tableSetById : (id) => `/index_review/api/table_sets/${id}`,
  itemsBySet   : (id) => `/index_review/api/table_sets/${id}/items`,
  itemById     : (sid, iid) => `/index_review/api/table_sets/${sid}/items/${iid}`,
  browserTables: "{{ url_for('index_review.api_browser_tables') }}",
  groups       : "{{ url_for('index_review.api_groups') }}",
};

let isAdmin        = false;
let currentUserId  = null;
let allTableSets   = [];
let selectedSetId  = null;
let canEditCurrent = false;
let allBrowserTbls = [];  // {database, table_name, row_count}
let allUsers       = [];  // {id, full_name}
let editingItemId  = null;

/* ====================================================
   ユーティリティ
   ==================================================== */
function toast(msg, type='info') {
  const el = $('<div>').addClass(`toast ${type}`).text(msg);
  $('#toast-container').append(el);
  setTimeout(() => el.fadeOut(300, () => el.remove()), 3200);
}

function ajax(url, method, data) {
  return $.ajax({ url, method: method || 'GET',
    contentType: 'application/json',
    data: data ? JSON.stringify(data) : undefined });
}

/* ====================================================
   初期ロード
   ==================================================== */
$(document).ready(function() {
  loadTableSets();
  loadBrowserTables();
});

/* ====================================================
   テーブル集一覧
   ==================================================== */
function loadTableSets() {
  $('#ts-list').html('<div class="placeholder-msg"><span class="icon">⏳</span>読込中…</div>');
  $.get(API.tableSets).done(res => {
    if (!res.success) { toast('取得に失敗しました', 'error'); return; }
    allTableSets  = res.table_sets;
    isAdmin       = res.is_admin;
    currentUserId = res.current_user_id;

    $('#ts-count').text(allTableSets.length + '件');
    if (isAdmin) {
      $('#create-form').show();
      $('#admin-badge').show();
    }

    renderTableSetList();
  }).fail(() => toast('通信エラー', 'error'));
}

function renderTableSetList() {
  const $list = $('#ts-list');
  $list.empty();
  if (!allTableSets.length) {
    $list.html('<div class="placeholder-msg"><span class="icon">📭</span>テーブル集がありません</div>');
    return;
  }
  allTableSets.forEach(ts => {
    const active = ts.id === selectedSetId ? ' active' : '';
    const $item = $(`
      <div class="ts-item${active}" data-id="${ts.id}">
        <div style="flex:1; min-width:0;">
          <div class="ts-item-name">${ts.name}</div>
          <div class="ts-item-meta">${ts.owner_name} ／ ${ts.created_at || ''}</div>
        </div>
        <span class="ts-item-cnt">${ts.item_count}件</span>
      </div>`);
    $list.append($item);
  });
}

$(document).on('click', '.ts-item', function() {
  const id = parseInt($(this).data('id'));
  selectedSetId = id;
  $('.ts-item').removeClass('active');
  $(this).addClass('active');
  loadItems(id);
});

/* ====================================================
   テーブル集 作成
   ==================================================== */
$('#btn-create-ts').on('click', function() {
  const name = $('#new-ts-name').val().trim();
  if (!name) { toast('テーブル集名を入力してください', 'info'); return; }
  ajax(API.tableSetsPost, 'POST', {
    name, description: $('#new-ts-desc').val().trim()
  }).done(res => {
    if (res.success) {
      toast('テーブル集を作成しました', 'success');
      $('#new-ts-name, #new-ts-desc').val('');
      loadTableSets();
    } else {
      toast(res.error || '作成に失敗しました', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

/* ====================================================
   テーブル集 詳細・アイテム
   ==================================================== */
function loadItems(setId) {
  const ts = allTableSets.find(t => t.id === setId);
  if (!ts) return;

  $('#no-selection').hide();
  $('#ts-detail').show();

  $('#detail-name').text(ts.name);
  $('#detail-meta').text(`作成者：${ts.owner_name}　／　${ts.created_at || ''}`);
  $('#detail-desc').text(ts.description || '');

  // 編集ボタン表示
  if (ts.can_edit) {
    $('#detail-edit-btns').show();
    $('#add-item-form').show();
  } else {
    $('#detail-edit-btns').hide();
    $('#add-item-form').hide();
  }

  // ★追加：閲覧ボタンは常に表示
  $('#detail-view-btns').show();

  canEditCurrent = ts.can_edit;

  // DB選択のセットアップ
  setupDbSelect();
  // ユーザ一覧（管理者のみ取得済み）
  if (ts.can_edit && !allUsers.length) loadGroups();
  setupMgrSelect('#add-mgr-select');

  // アイテム取得
  $.get(API.itemsBySet(setId)).done(res => {
    if (!res.success) { toast('取得失敗', 'error'); return; }
    renderItems(res.items, res.can_edit);
  }).fail(() => toast('通信エラー', 'error'));
}

function renderItems(items, canEdit) {
  const $tbody = $('#items-tbody');
  $tbody.empty();
  $('#item-count').text(`（${items.length} 件）`);
  const showOps = canEdit || items.some(it => it.can_update);
  $('#col-ops').toggle(showOps);

  if (!items.length) {
    $('#items-empty').show();
    return;
  }
  $('#items-empty').hide();

  items.forEach(it => {
    const mgrCell = canEdit
      ? `<button class="btn btn-outline btn-sm btn-set-mgr"
             data-id="${it.id}" data-tbl="${it.table_name}" data-mgr="${it.manager_group_id || ''}"
             title="責任グループを変更">
           ${it.manager_group_name}
         </button>`
      : it.manager_group_name;

    const updateBtn = it.can_update
      ? `<a href="/index_review/table_data_update/${it.id}"
            class="btn btn-primary btn-sm" title="データ更新">🔄 更新</a>`
      : '';
    const deleteBtn = canEdit
      ? `<button class="btn btn-outline btn-sm btn-del-item" data-id="${it.id}"
             title="テーブル集から外す"
             style="border-color:#d1d5db;color:#6b7280;">✕ 外す</button>`
      : '';
    const opsCell = updateBtn || deleteBtn
      ? `${updateBtn} ${deleteBtn}`
      : '';

    $tbody.append(`
      <tr>
        <td>${it.database_name}</td>
        <td><code style="font-size:.72rem;">${it.table_name}</code></td>
        <td>${mgrCell}</td>
        <td style="font-size:.68rem; color:var(--gray-400);">${it.added_at || ''}</td>
        ${showOps ? `<td>${opsCell}</td>` : ''}
      </tr>`);
  });
}

/* ====================================================
   DB・テーブル選択プルダウン
   ==================================================== */
function loadBrowserTables() {
  $.get(API.browserTables).done(res => {
    if (res.success) allBrowserTbls = res.tables;
  });
}

function setupDbSelect() {
  const $dbSel = $('#add-db-select');
  $dbSel.empty().append('<option value="">DB を選択…</option>');
  const dbs = [...new Set(allBrowserTbls.map(t => t.database))].sort();
  dbs.forEach(db => $dbSel.append(`<option value="${db}">${db}</option>`));
  $('#add-tbl-select').empty().append('<option value="">テーブルを選択…</option>').prop('disabled', true);
}

$('#add-db-select').on('change', function() {
  const db = $(this).val();
  const $tbl = $('#add-tbl-select');
  $tbl.empty().append('<option value="">テーブルを選択…</option>');
  if (!db) { $tbl.prop('disabled', true); return; }
  const tables = allBrowserTbls.filter(t => t.database === db).sort((a,b) => a.table_name.localeCompare(b.table_name));
  tables.forEach(t => $tbl.append(`<option value="${t.table_name}">${t.table_name}（${t.row_count}行）</option>`));
  $tbl.prop('disabled', false);
});

/* ====================================================
   ユーザ一覧（責任者用）
   ==================================================== */
function loadGroups() {
  $.get(API.groups).done(res => {
    if (res.success) {
      allUsers = res.groups;  // 変数名はそのまま流用
      setupMgrSelect('#add-mgr-select');
      setupMgrSelect('#mgr-select');
    }
  });
}

function setupMgrSelect(selector) {
  const $sel = $(selector);
  const cur = $sel.val();
  $sel.empty().append('<option value="">― 未設定 ―</option>');
  allUsers.forEach(g => $sel.append(`<option value="${g.id}">${g.name}</option>`));
  if (cur) $sel.val(cur);
}

/* ====================================================
   アイテム追加
   ==================================================== */
$('#btn-add-item').on('click', function() {
  const db  = $('#add-db-select').val();
  const tbl = $('#add-tbl-select').val();
  if (!db || !tbl) { toast('DBとテーブルを選択してください', 'info'); return; }

  ajax(API.itemsBySet(selectedSetId), 'POST', {
    database_name: db,
    table_name:    tbl,
    manager_group_id: $('#add-mgr-select').val() || null
  }).done(res => {
    if (res.success) {
      toast('テーブルを追加しました', 'success');
      loadItems(selectedSetId);
      loadTableSets(); // 件数更新
    } else {
      toast(res.error || '追加に失敗しました', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

/* ====================================================
   アイテム削除
   ==================================================== */
$(document).on('click', '.btn-del-item', function() {
  const itemId = $(this).data('id');
  if (!confirm('このテーブルをテーブル集から外しますか？\n（テーブル自体は削除されません）')) return;
  ajax(API.itemById(selectedSetId, itemId), 'DELETE').done(res => {
    if (res.success) {
      toast('削除しました', 'success');
      loadItems(selectedSetId);
      loadTableSets();
    } else {
      toast(res.error || '削除に失敗しました', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

/* ====================================================
   テーブル集 名称変更
   ==================================================== */
$('#btn-edit-ts').on('click', function() {
  const ts = allTableSets.find(t => t.id === selectedSetId);
  if (!ts) return;
  $('#edit-ts-name').val(ts.name);
  $('#edit-ts-desc').val(ts.description || '');
  $('#edit-modal').css('display', 'flex');
});

$('#edit-cancel').on('click', () => $('#edit-modal').hide());
$('#edit-modal').on('click', function(e) { if (e.target === this) $(this).hide(); });

$('#edit-confirm').on('click', function() {
  const name = $('#edit-ts-name').val().trim();
  if (!name) { toast('テーブル集名は必須です', 'info'); return; }
  ajax(API.tableSetById(selectedSetId), 'PUT', {
    name, description: $('#edit-ts-desc').val().trim()
  }).done(res => {
    if (res.success) {
      toast('更新しました', 'success');
      $('#edit-modal').hide();
      loadTableSets().then ? loadTableSets() : loadTableSets();
      // 詳細ヘッダーも即時更新
      $('#detail-name').text(name);
    } else {
      toast(res.error || '更新に失敗しました', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

/* ====================================================
   テーブル集 削除
   ==================================================== */
$('#btn-delete-ts').on('click', function() {
  const ts = allTableSets.find(t => t.id === selectedSetId);
  if (!ts) return;
  if (!confirm(`「${ts.name}」を削除しますか？\n中のテーブル登録もすべて削除されます。`)) return;
  ajax(API.tableSetById(selectedSetId), 'DELETE').done(res => {
    if (res.success) {
      toast('削除しました', 'success');
      selectedSetId = null;
      $('#ts-detail').hide();
      $('#no-selection').show();
      loadTableSets();
    } else {
      toast(res.error || '削除に失敗しました', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

/* ====================================================
   責任者変更モーダル
   ==================================================== */
$(document).on('click', '.btn-set-mgr', function() {
  editingItemId = $(this).data('id');
  const tbl = $(this).data('tbl');
  const mgr = $(this).data('mgr');
  $('#mgr-table-label').text(`テーブル：${tbl}`);
  if (!allUsers.length) {
    loadGroups();
    // ユーザ読込後に選択値をセット
    setTimeout(() => { setupMgrSelect('#mgr-select'); $('#mgr-select').val(mgr || ''); }, 600);
  } else {
    setupMgrSelect('#mgr-select');
    $('#mgr-select').val(mgr || '');
  }
  $('#mgr-modal').css('display', 'flex');
});

$('#mgr-cancel').on('click', () => $('#mgr-modal').hide());
$('#mgr-modal').on('click', function(e) { if (e.target === this) $(this).hide(); });

$('#mgr-confirm').on('click', function() {
  const mgrId = $('#mgr-select').val() || null;
  ajax(API.itemById(selectedSetId, editingItemId), 'PUT', {
    manager_group_id: mgrId
  }).done(res => {
    if (res.success) {
      toast('責任グループを更新しました', 'success');
      $('#mgr-modal').hide();
      loadItems(selectedSetId);
    } else {
      toast(res.error || '更新に失敗しました', 'error');
    }
  }).fail(() => toast('通信エラー', 'error'));
});

/* ====================================================
   テーブルブラウザ（テーブル集スコープ）
   ==================================================== */
const API_BROWSER = {
  schema : "{{ url_for('index_review.api_browser_schema') }}",
  data   : "{{ url_for('index_review.api_browser_data') }}",
  schema_dump: "{{ url_for('index_review.api_schema_dump') }}",
};

let tbCurrentDb  = null;
let tbCurrentTbl = null;
let tbCurrentPane = 'schema';
let tbItems = [];  // 現在のテーブル集のアイテム

// ボタンクリック → モーダルを開く
$('#btn-tbl-browser').on('click', function() {
  const ts = allTableSets.find(t => t.id === selectedSetId);
  if (!ts) return;
  $('#tb-set-label').text(`— ${ts.name}`);
  tbCurrentDb = tbCurrentTbl = null;
  $('#tb-placeholder').show();
  $('#tb-content').hide();
  renderTbList('');
  $('#tb-modal').css('display', 'flex');
});

$('#tb-close').on('click', () => $('#tb-modal').hide());
$('#tb-modal').on('click', function(e) { if (e.target === this) $(this).hide(); });

$('#tb-search').on('input', function() {
  renderTbList($(this).val().toLowerCase());
});

function renderTbList(kw) {
  // items-tbody から現在表示中のテーブルリストを使う
  const $list = $('#tb-list');
  $list.empty();
  const rows = [];
  $('#items-tbody tr').each(function() {
    const db  = $(this).find('td:eq(0)').text().trim();
    const tbl = $(this).find('td:eq(1) code').text().trim();
    if (db && tbl) rows.push({db, tbl});
  });

  const filtered = kw ? rows.filter(r =>
    r.db.toLowerCase().includes(kw) || r.tbl.toLowerCase().includes(kw)
  ) : rows;

  // DBごとにグループ化
  const byDb = {};
  filtered.forEach(r => (byDb[r.db] = byDb[r.db] || []).push(r.tbl));

  Object.keys(byDb).sort().forEach(db => {
    $list.append(`<div style="background:#34495e; color:#ecf0f1; padding:4px 11px;
                              font-size:.68rem; font-weight:700; cursor:pointer;"
                      class="tb-db-hd">${db}</div>`);
    byDb[db].sort().forEach(tbl => {
      const active = (tbCurrentDb === db && tbCurrentTbl === tbl) ? 'background:#d0e4f7;border-left:3px solid #2e6da4;font-weight:600;' : '';
      $list.append(`<div class="tb-item-row"
                        data-db="${db}" data-tbl="${tbl}"
                        style="padding:6px 11px; cursor:pointer; border-bottom:1px solid #eee;
                               ${active} transition:background .1s;"
                        onmouseover="this.style.background='#e8f0fe'"
                        onmouseout="this.style.background='${active?'#d0e4f7':'#fff'}'"
                        >${tbl}</div>`);
    });
  });
}

$(document).on('click', '.tb-item-row', function() {
  tbCurrentDb  = $(this).data('db');
  tbCurrentTbl = $(this).data('tbl');
  $('#tb-placeholder').hide();
  $('#tb-content').css('display', 'flex');
  $('#tb-tbl-label').text(`${tbCurrentDb}.${tbCurrentTbl}`);
  renderTbList($('#tb-search').val().toLowerCase());
  showTbPane(tbCurrentPane);
});

$(document).on('click', '.tb-tab-btn', function() {
  const pane = $(this).data('pane');
  tbCurrentPane = pane;
  $('.tb-tab-btn').css({'border-bottom-color':'transparent','color':'#6b7280'});
  $(this).css({'border-bottom-color':'#2e6da4','color':'#2e6da4'});
  showTbPane(pane);
});

function showTbPane(pane) {
  if (!tbCurrentDb || !tbCurrentTbl) return;
  $('#tb-pane-schema, #tb-pane-data').hide();
  if (pane === 'schema') {
    $('#tb-pane-schema').show();
    $('#tb-schema-pre').text('取得中…');
    $.ajax({ url: API_BROWSER.schema, method: 'POST',
             contentType: 'application/json',
             data: JSON.stringify({database: tbCurrentDb, table_name: tbCurrentTbl})
    }).done(res => $('#tb-schema-pre').text(res.success ? res.schema : 'エラー: ' + res.error));
  } else {
    $('#tb-pane-data').show();
    $('#tb-data-info').text('取得中…');
    $('#tb-data-table').empty();
    $.ajax({ url: API_BROWSER.data, method: 'POST',
             contentType: 'application/json',
             data: JSON.stringify({database: tbCurrentDb, table_name: tbCurrentTbl, limit:500, offset:0})
    }).done(res => {
      if (!res.success) { $('#tb-data-info').text('エラー: ' + res.error); return; }
      const {columns, rows, total_count} = res;
      $('#tb-data-info').html(`${rows.length} 行表示（全 ${total_count} 行）`);
      let html = '<thead><tr>' + columns.map(c=>`<th style="background:#2e6da4;color:#fff;padding:6px 9px;white-space:nowrap;">${c}</th>`).join('') + '</tr></thead><tbody>';
      rows.forEach(row => {
        html += '<tr>' + columns.map(c => {
          const v = row[c];
          return v===null||v===undefined ? '<td style="padding:5px 9px;border-bottom:1px solid #eee;color:#e74c3c;font-style:italic;">NULL</td>'
                                        : `<td style="padding:5px 9px;border-bottom:1px solid #eee;white-space:nowrap;">${String(v)}</td>`;
        }).join('') + '</tr>';
      });
      html += '</tbody>';
      $('#tb-data-table').html(html);
    });
  }
}

/* ====================================================
   スキーマダンプ（テーブル集スコープ）
   ==================================================== */
$('#btn-schema-dump').on('click', function() {
  $('#schema-text').text('読込中…');
  $('#schema-count').text('');
  $('#schema-modal').css('display', 'flex');
  // テーブル集IDをクエリパラメータで渡す
  $.get(API_BROWSER.schema_dump + '?table_set_id=' + selectedSetId).done(res => {
    if (!res.success) { $('#schema-text').text('エラー: ' + res.error); return; }
    $('#schema-text').text(res.text);
    $('#schema-count').text(res.table_count + ' テーブル');
  }).fail(() => $('#schema-text').text('通信エラー'));
});

$('#schema-close').on('click', () => $('#schema-modal').hide());
$('#schema-copy').on('click', function() {
  const text = $('#schema-text').text();
  if (!text || text === '読込中…') return;
  navigator.clipboard.writeText(text).then(() => {
    const $b = $(this); $b.text('✓ コピー完了');
    setTimeout(() => $b.text('📋 コピー'), 2000);
  });
});
$('#schema-dl').on('click', function() {
  const text = $('#schema-text').text();
  if (!text || text === '読込中…') return;
  const blob = new Blob([text], {type: 'text/plain;charset=utf-8'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a'); a.href = url;
  a.download = 'schema_dump_' + new Date().toISOString().slice(0,10) + '.txt';
  a.click(); URL.revokeObjectURL(url);
});
</script>
</body>
</html>

