        $('.node-box[data-id="' + id + '"]').addClass('in-sel'));
    edgeMode.outputs.forEach(id =>
        $('.node-box[data-id="' + id + '"]').addClass('out-sel'));
    const m = edgeMode.inputs.length, n = edgeMode.outputs.length;
    if (edgeMode.phase === 'nodes') {
        // 第1段階：ノード選択（入力／出力を切り替えつつクリックでトグル）
        $('#edgeNodeStep').css('display', 'inline-flex');
