            items.push({ label: '✏️ 編集', fn: () => openNodeModal(n) });
            items.push({ sep: true });
            items.push({ label: '🗑 削除', danger: true, fn: function() {
                if (confirm('ノード「' + n.label + '」を削除します．このノードを端点とするエッジも調整されます．よろしいですか？'))
                    apiPost('node/' + id + '/delete', {}, () => loadData(false));
            }});
        }
        if (items.length) showMenu(ev.clientX, ev.clientY, items);
    } else if (edgeHit.length) {
        const eid = parseInt(edgeHit.attr('data-edge'));
        const e = state.edges.find(x => x.id === eid);
        if (!e) return;
        const items = [{ label: '📄 詳細表示', fn: () => showEdgeDetail(e) }];
        if (IS_OWNER) {
            items.push({ sep: true });
            items.push({ label: '⬅ 入力リンクの追加・削除',
                fn: () => startLinkMode(e, 'in') });
            items.push({ label: '➡ 出力リンクの追加・削除',
                fn: () => startLinkMode(e, 'out') });
            items.push({ sep: true });
            items.push({ label: '✏️ 編集（タイプ・注記）', fn: () => openEdgeModal(e) });
            items.push({ label: '📍 ラベル位置を自動配置に戻す', fn: function() {
                apiPost('edge/' + eid + '/label_move', { x: null, y: null },
                        () => loadData(false));
            }});
            items.push({ sep: true });
            items.push({ label: '🗑 削除', danger: true, fn: function() {
                if (confirm('この結合子（' + e.type_name + '）を削除しますか？'))
                    apiPost('edge/' + eid + '/delete', {}, () => loadData(false));
            }});
        }
        showMenu(ev.clientX, ev.clientY, items);
    } else if (IS_OWNER && !edgeMode && !mergeMode && !linkMode) {
        pendingXY = screenToWorld(ev.clientX, ev.clientY);
        showMenu(ev.clientX, ev.clientY, [
            { label: '＋ ここにノードを作成', fn: () => openNodeModal(null) }
        ]);
    }
});
