// =============== 新規文書を生成してリンク（CoRePo連携） ===============
// 既存の「保存」＝既存文書へのリンク行為はそのまま。こちらは新規文書がまだ
// 無い場合の動線：CoRePoに新規プロジェクトを作成（作成者＝責任者兼担当者）し、
// 公開範囲を同期し、共有プレビューURLを実体URLとするノードをその場に作り、
// 外部入力画面（エディタ）を別タブで開いて本文の執筆を開始できるようにする。
function setCreateDocBusy(busy) {
    $('#ndCreateDoc').prop('disabled', busy)
        .text(busy ? '⏳ CoRePoに作成中…' : '📄 新規文書を生成してリンク');
}
$('#ndCreateDoc').on('click', function() {
    const label = $('#ndLabel').val().trim();
    if (!label) { showResult('ラベルは必須です（プロジェクト名になります）', true); return; }
    if ($('#ndUrl').val().trim()) {
        showResult('実体URL欄に入力があります．新規文書を生成する場合は空欄にしてください', true);
        return;
    }
    const policy = $('input[name=ndPolicy]:checked').val();
    const groupIds = $('.ndGroupChk:checked')
        .map((i, e) => parseInt(e.value)).get();
    if ((policy === 'group' || policy === 'domestic_group') && groupIds.length === 0) {
        showResult('グループ公開では，許可するグループを1つ以上選んでください', true);
        return;
    }
    // CoRePo側に同期する公開範囲：「↰ キャンバスに従う」はキャンバスの範囲に読み替える
    const effPolicy = (policy === 'inherit') ? CANVAS_POLICY : policy;
    const effGroups = (policy === 'inherit') ? CANVAS_GROUP_IDS : groupIds;
    // ポップアップブロック対策：クリックと同期して先に空タブを確保しておく
    const editorWin = window.open('', '_blank');
    setCreateDocBusy(true);
    $.ajax({
        url: COLREP_CREATE_URL, method: 'POST', contentType: 'application/json',
        data: JSON.stringify({
            project_name: label,
            access_policy: effPolicy,
            access_group_ids: effGroups
        }),
        success: function(resp) {
            if (!resp || !resp.success) {
                if (editorWin) editorWin.close();
                setCreateDocBusy(false);
                showResult('CoRePoエラー: ' + ((resp && resp.error) || '作成に失敗しました'), true);
                return;
            }
            // すぐ執筆を始められるよう，先にエディタ（外部入力画面）へ遷移させる
            if (editorWin) editorWin.location = resp.editor_url;
            // 生成された文書URLをフォームにも反映しておく
            // （万一ノード作成に失敗しても「保存」で作成をやり直せる）
            $('#ndUrl').val(resp.entity_url);
            const payload = {
                label: label, url: resp.entity_url, note: $('#ndNote').val(),
                access_policy: policy === 'inherit' ? null : policy,
                access_group_ids: groupIds,
                x: pendingXY ? pendingXY.x : 0,
                y: pendingXY ? pendingXY.y : 0
            };
            apiPost('canvas/' + CANVAS_ID + '/node/create', payload, function() {
                $('#nodeModalBg').hide();
                loadData(false);
                showResult('CoRePoプロジェクト「' + resp.project_name +
                           '」を作成し，ノードをリンクしました．別タブで本文の執筆を開始できます', false);
            });
            // ノード作成に失敗した場合は apiPost がエラー表示する．モーダルは
            // 開いたまま・実体URL欄に文書URLが残るので「保存」で復旧できる．
            setCreateDocBusy(false);
        },
        error: function(xhr) {
            if (editorWin) editorWin.close();
            setCreateDocBusy(false);
            let resp = null;
            try { resp = JSON.parse(xhr.responseText); } catch (e) {}
            if (resp && resp.error_code === 'duplicate_name') {
                showResult('同名のCoRePoプロジェクトが既にあります．ラベルを変えてください', true);
            } else if (xhr.status === 403) {
                showResult('CoRePoのプロジェクト作成権限（コレポ管理者以上）が必要です', true);
            } else {
                showResult('CoRePoエラー（HTTP ' + (xhr.status || '応答なし') + '）: ' +
                           ((resp && resp.error) || '作成に失敗しました'), true);
            }
        }
    });
});
// =============== ノード統合文書生成（CoRePo連携） ===============
// 画面上の複数ノードを選択順に番号づけし，CoRePoに統合文書プロジェクトを
// 新規作成（「本文」タスク・initial_content にノード別リンク一覧を注入）して
// 外部入力画面を別タブで開く。「選択したノードを消去して完了」なら選択ノードを
// キャンバスから削除する（空間的なメモ書き→構造的な記述への移行を支援）。
function updateMergeHighlights() {
    $('.node-box').removeClass('merge-sel');
    const layer = document.getElementById('mergeLayer');
    layer.innerHTML = '';
    if (!mergeMode) { $('#mergePanel').hide(); return; }
    // 再読込等で消えたノードは選択から外す
    mergeMode.order = mergeMode.order.filter(id => state.nodes[id]);
    mergeMode.order.forEach(function(id, i) {
        const n = state.nodes[id];
        $('.node-box[data-id="' + id + '"]').addClass('merge-sel');
        // ノード左上に選択順の番号バッジを描く
        const bx = n.x - n.w / 2, by = n.y - n.h / 2;
        const c = document.createElementNS(SVGNS, 'circle');
        c.setAttribute('cx', bx); c.setAttribute('cy', by); c.setAttribute('r', 11);
        c.setAttribute('fill', '#6a4fa3');
        c.setAttribute('stroke', '#fff'); c.setAttribute('stroke-width', 1.5);
        c.setAttribute('pointer-events', 'none');
        const t = document.createElementNS(SVGNS, 'text');
        t.setAttribute('x', bx); t.setAttribute('y', by);
        t.setAttribute('text-anchor', 'middle');
        t.setAttribute('dominant-baseline', 'central');
        t.setAttribute('font-size', '12'); t.setAttribute('fill', '#fff');
        t.setAttribute('font-family', 'inherit');
        t.setAttribute('pointer-events', 'none');
        t.textContent = String(i + 1);
        layer.appendChild(c); layer.appendChild(t);
    });
    $('#mergeStatus').text('🧩 選択：' + mergeMode.order.length +
        '個（クリックで選択順に番号づけ／再クリックで解除）');
    $('#mergePanel').show();
}
function pad2(v) { return (v < 10 ? '0' : '') + v; }
function defaultMergeName() {
    const d = new Date();
    return CANVAS_NAME + ' 統合 ' + d.getFullYear() + '-' +
           pad2(d.getMonth() + 1) + '-' + pad2(d.getDate()) + ' ' +
           pad2(d.getHours()) + ':' + pad2(d.getMinutes());
}
$('#btnMerge').on('click', function() {
    if (!IS_OWNER) return;
    if (mergeMode) { mergeMode = null; updateMergeHighlights(); return; }  // トグルで解除
    edgeMode = null; linkMode = null; clearSelHighlights();
    updateEdgeModeHighlights(); updateLinkModeHighlights();
    mergeMode = { order: [] };
    $('#mergeName').val(defaultMergeName());
    updateMergeHighlights();
});
$('#mergeCancel').on('click', function() {
    mergeMode = null; updateMergeHighlights();
});
function setMergeBusy(busy) {
    $('#mergeDoneDelete, #mergeDoneKeep, #mergeCancel').prop('disabled', busy);
    if (busy) $('#mergeStatus').text('⏳ CoRePoに統合文書を作成中…');
}
// 選択順に「1. [ラベル](URL)」の並びを作る（URL無しノードはリンクなしの行）
function buildMergeContent(ids) {
    return ids.map(function(id, i) {
        const n = state.nodes[id];
        const label = (n.label || ('ノード#' + id)).replace(/([\[\]])/g, '\\$1');
        if (n.url) return (i + 1) + '. [' + label + '](' + n.url + ')';
        return (i + 1) + '. ' + label + '（リンクなし）';
    }).join('\n') + '\n';
}
// 1個ずつ順に削除（各削除でエッジ端点の調整が走るため並行にしない）
function deleteNodesSequentially(ids, failed, done) {
    if (!ids.length) { done(failed); return; }
    const id = ids.shift();
    $.ajax({
        url: API_BASE + 'node/' + id + '/delete', method: 'POST',
        contentType: 'application/json', data: '{}',
        success: function(resp) {
            if (!resp || !resp.success) failed.push(id);
            deleteNodesSequentially(ids, failed, done);
        },
        error: function() {
            failed.push(id);
            deleteNodesSequentially(ids, failed, done);
        }
    });
}
function finishMerge(deleteNodes) {
    if (!mergeMode) return;
    const ids = mergeMode.order.filter(id => state.nodes[id]);
    if (ids.length < 1) {
        showResult('統合するノードをクリックで1つ以上選んでください', true); return;
    }
    const name = $('#mergeName').val().trim();
    if (!name) {
        showResult('統合文書名を入力してください（CoRePoプロジェクト名になります）', true);
        $('#mergeName').focus(); return;
    }
    const content = buildMergeContent(ids);
    // 統合ノードの生成位置＝選択ノード群の重心（消去前に計算しておく）
    let cx = 0, cy = 0;
    ids.forEach(function(id) { cx += state.nodes[id].x; cy += state.nodes[id].y; });
    cx /= ids.length; cy /= ids.length;
    // ポップアップブロック対策：クリックと同期して先に空タブを確保しておく
    const editorWin = window.open('', '_blank');
    setMergeBusy(true);
    $.ajax({
        url: COLREP_CREATE_URL, method: 'POST', contentType: 'application/json',
        data: JSON.stringify({
            project_name: name,
            access_policy: CANVAS_POLICY,          // 公開範囲はキャンバスに合わせる
            access_group_ids: CANVAS_GROUP_IDS,
            initial_content: content
        }),
        success: function(resp) {
            if (!resp || !resp.success) {
                if (editorWin) editorWin.close();
                setMergeBusy(false); updateMergeHighlights();
                showResult('CoRePoエラー: ' + ((resp && resp.error) || '作成に失敗しました'), true);
                return;
            }
            // すぐ編集を始められるよう，先にエディタ（外部入力画面）へ遷移させる
            if (editorWin) editorWin.location = resp.editor_url;
            const finish = function(mergeNodeFailed, failed) {
                mergeMode = null;
                setMergeBusy(false);
                updateMergeHighlights();
                loadData(false);
                let msg = '統合文書「' + resp.project_name +
                          '」を作成し，統合ノードを重心位置に置きました．別タブで本文を編集できます';
                if (mergeNodeFailed) {
                    msg = '統合文書「' + resp.project_name +
                          '」は作成しましたが，統合ノードの作成に失敗しました．' +
                          '実体URL ' + resp.entity_url + ' で手動作成してください';
                }
                if (deleteNodes) {
                    msg += (failed && failed.length)
                        ? '（ノード消去：' + (ids.length - failed.length) + '個成功／' +
                          failed.length + '個失敗）'
                        : '（選択した' + ids.length + '個のノードを消去しました）';
                }
                showResult(msg, !!mergeNodeFailed);
            };
            // 統合ノード（実体URL＝共有プレビュー）を選択ノード群の重心に作成。
            // 公開範囲は「↰ キャンバスに従う」（文書側もキャンバスの範囲に同期済みで整合）
            $.ajax({
                url: API_BASE + 'canvas/' + CANVAS_ID + '/node/create',
                method: 'POST', contentType: 'application/json',
                data: JSON.stringify({
                    label: name, url: resp.entity_url, note: '',
                    access_policy: null, access_group_ids: [],
                    x: cx, y: cy
                }),
                success: function(r) {
                    const ok = r && r.success;
                    if (deleteNodes) deleteNodesSequentially(ids.slice(), [], f => finish(!ok, f));
                    else finish(!ok, null);
                },
                error: function() {
                    if (deleteNodes) deleteNodesSequentially(ids.slice(), [], f => finish(true, f));
                    else finish(true, null);
                }
            });
        },
        error: function(xhr) {
            if (editorWin) editorWin.close();
            setMergeBusy(false); updateMergeHighlights();
            let resp = null;
            try { resp = JSON.parse(xhr.responseText); } catch (e) {}
            if (resp && resp.error_code === 'duplicate_name') {
                showResult('同名のCoRePoプロジェクトが既にあります．統合文書名を変えてください', true);
                $('#mergeName').focus();
            } else if (xhr.status === 403) {
                showResult('CoRePoのプロジェクト作成権限（コレポ管理者以上）が必要です', true);
            } else {
                showResult('CoRePoエラー（HTTP ' + (xhr.status || '応答なし') + '）: ' +
                           ((resp && resp.error) || '作成に失敗しました'), true);
            }
        }
    });
}
