// =============== JSONエクスポート ===============
// いま読み込まれているキャンバスのノードと結合子（ラベル）関係を，
// メタデータ付きのJSONにまとめてダウンロードする。
// ・閲覧専用ユーザの場合は「権限のあるノードのみ」が対象（画面表示と同じ範囲）
// ・edges[].label が結合子の[ラベル]（タイプ名・カテゴリ・向き）
// ・inputs/outputs には参照整合性検査やグラフ処理がしやすいよう
//   node_id と（可読性のため）ラベル文字列の両方を入れる
function buildExportJson() {
    const nodes = Object.values(state.nodes).map(function(n) {
        const o = { id: n.id, label: n.label, url: n.url || null,
                    note: n.note || null, x: n.x, y: n.y };
        if ('access_policy' in n) {   // owner / admin のみ提供される
            o.access_policy = n.access_policy || 'inherit';
            if (n.access_group_ids && n.access_group_ids.length) {
                o.access_groups = n.access_group_ids.map(function(gid) {
                    const g = state.groups.find(x => x.id === gid);
                    return { id: gid, name: g ? g.name : null };
                });
            }
        }
        return o;
    });
    const nodeLabel = id => state.nodes[id] ? state.nodes[id].label : null;
    const edges = state.edges.map(function(e) {
        return {
            id: e.id,
            label: {
                type_id: e.type_id,
                name: e.type_name,
                category: e.type_category,
                directed: !!e.directed
            },
            note: e.note || null,
            inputs: e.inputs.map(id => ({ node_id: id, label: nodeLabel(id) })),
            outputs: e.outputs.map(id => ({ node_id: id, label: nodeLabel(id) })),
            // null＝自動配置（入力重心と出力重心の中央）
            label_position: (e.label_x !== null && e.label_x !== undefined &&
                             e.label_y !== null && e.label_y !== undefined)
                ? { x: e.label_x, y: e.label_y } : null
        };
    });
    // このキャンバスで実際に使われている結合子タイプのみ収録
    const usedTypeIds = {};
    state.edges.forEach(e => usedTypeIds[e.type_id] = true);
    const connectorTypes = state.types
        .filter(t => usedTypeIds[t.id])
        .map(t => ({ id: t.id, name: t.name, category: t.category,
                     directed: !!t.directed }));
    return {
        format: 'awami-canvas-export',
        version: 1,
        metadata: {
            canvas_id: CANVAS_ID,
            canvas_name: CANVAS_NAME,
            exported_at: new Date().toISOString(),
            exported_by_role: IS_OWNER ? 'owner' : 'viewer',
            node_count: nodes.length,
            edge_count: edges.length,
            coordinate_system: 'キャンバス座標（原点(0,0)基準・y軸下向き）',
            scope: IS_OWNER ? '全ノード・全結合子'
                            : '閲覧権限のあるノードと，その範囲で見える結合子のみ'
        },
        nodes: nodes,
        edges: edges,
        connector_types: connectorTypes
    };
}
function exportFileName() {
    const d = new Date();
    const stamp = d.getFullYear() + pad2(d.getMonth() + 1) + pad2(d.getDate()) +
                  '-' + pad2(d.getHours()) + pad2(d.getMinutes()) + pad2(d.getSeconds());
    // ファイル名に使えない文字と空白を _ に置換（長すぎる名前は切り詰め）
    const safeName = (CANVAS_NAME || 'canvas')
        .replace(/[\\\/:*?"<>|\s]+/g, '_').slice(0, 40);
    return 'awami_' + safeName + '_c' + CANVAS_ID + '_' + stamp + '.json';
}
$('#btnExport').on('click', function() {
    const data = buildExportJson();
    const json = JSON.stringify(data, null, 2);
    const blob = new Blob([json], { type: 'application/json;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = exportFileName();
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
    showResult('JSONをダウンロードしました（ノード' + data.metadata.node_count +
               '個・結合子' + data.metadata.edge_count + '個）', false);
});
// =============== JSONインポート（取込・owner専用） ===============
// エクスポートしたJSONをこのキャンバスに「新規追加」する。
// ・💾 JSONエクスポート形式（awami-canvas-export）と
//   サーバ書出形式（awami-canvas-json）の両方を受け付ける
// ・IDはすべてサーバ側で新規発番。既存のノード・結合子には一切触れない
$('#btnImport').on('click', function() { $('#importFile').trigger('click'); });
$('#importFile').on('change', function() {
    const f = this.files && this.files[0];
    this.value = '';    // 同じファイルを続けて選び直せるように
    if (!f) return;
    const reader = new FileReader();
    reader.onload = function() {
        let data;
        try { data = JSON.parse(reader.result); }
        catch (e) { showResult('JSONとして読めませんでした: ' + e, true); return; }
        const fmt = data && data.format;
        if (fmt !== 'awami-canvas-export' && fmt !== 'awami-canvas-json') {
            showResult('あわみのJSONエクスポート形式ではありません', true);
            return;
        }
        const nn = (data.nodes || []).length, ne = (data.edges || []).length;
        const srcName = (data.metadata && data.metadata.canvas_name) ||
                        (data.canvas && data.canvas.name) || '';
        if (!confirm('JSON' + (srcName ? '「' + srcName + '」' : '') +
                     ' からノード' + nn + '個・結合子' + ne +
                     '本を，このキャンバスに新規追加します．\n' +
                     '既存のノード・結合子には触れません（IDはすべて新規発番）．' +
                     'よろしいですか？')) return;
        apiPost('canvas/' + CANVAS_ID + '/import', data, function(resp) {
            loadData(false);
            showResult('取込完了：ノード' + resp.imported_nodes + '個・結合子' +
                resp.imported_edges + '本' +
                (resp.added_connector_types
                    ? '・ラベル' + resp.added_connector_types + '種を自動追加' : '') +
                (resp.skipped_edges
                    ? '（端点不備で' + resp.skipped_edges + '本スキップ）' : ''),
                false);
        });
    };
    reader.readAsText(f, 'utf-8');
});
// =============== 意見募集・プレゼン計画・記録 ===============
let PLANS = [];
function loadPlans(cb) {
    $.getJSON(API_BASE + 'canvas/' + CANVAS_ID + '/plans', function(d) {
        if (d && d.success) { PLANS = d.plans; if (cb) cb(); }
    });
}
{% if is_owner %}
function addNodeToPlan(n) {
    loadPlans(function() {
        if (PLANS.length === 0) {
            const name = prompt('計画がありません。新しい計画の名前は？', '計画 1');
            if (name === null) return;
            $.ajax({ url: API_BASE + 'canvas/' + CANVAS_ID + '/plans/create',
                method: 'POST', contentType: 'application/json',
                data: JSON.stringify({ name: name }),
                success: function(resp) {
                    if (resp.success) doPlanAdd(n, resp.id, resp.name);
                } });
            return;
        }
        let target = PLANS[0];
        if (PLANS.length > 1) {
            const msg = 'どの計画に追加しますか？番号を入力:\n' +
                PLANS.map((p, i) => (i + 1) + '. ' + p.name).join('\n');
            const pick = prompt(msg, '1');
            if (pick === null) return;
            const idx = parseInt(pick) - 1;
            if (isNaN(idx) || idx < 0 || idx >= PLANS.length) return;
            target = PLANS[idx];
        }
        doPlanAdd(n, target.id, target.name);
    });
}
function doPlanAdd(n, planId, planName) {
    $.ajax({ url: API_BASE + 'canvas/' + CANVAS_ID + '/plan/add',
        method: 'POST', contentType: 'application/json',
        data: JSON.stringify({ node_id: n.id, plan_id: planId }),
        success: function(resp) {
            if (resp.success) showResult('計画「' + planName + '」の最後（' + resp.position + '番目）に「' + resp.label + '」を追加しました', false);
            else showResult('エラー: ' + resp.error, true);
        } });
}
$('#btnPlan').on('click', function() {
    window.open('/awami/canvas/' + CANVAS_ID + '/plans',
                'awamiPlans' + CANVAS_ID, 'width=760,height=820');
});
$('#btnRecords').on('click', function() {
    window.open('/awami/canvas/' + CANVAS_ID + '/records',
                'awamiRecords' + CANVAS_ID, 'width=820,height=820');
});
$('#btnPollNew').on('click', function() {
    window.open('/awami/canvas/' + CANVAS_ID + '/poll/new',
                'awamiPollNew' + CANVAS_ID, 'width=680,height=860');
});
{% endif %}
$('#btnFlow').on('click', function() {
    window.open('/awami/canvas/' + CANVAS_ID + '/flow',
                'awamiFlow' + CANVAS_ID, 'width=720,height=860');
});
$('#btnResults').on('click', function() {
    window.open('/awami/canvas/' + CANVAS_ID + '/results',
                'awamiResults' + CANVAS_ID, 'width=760,height=860');
});
// ラベル管理（結合子タイプ・admin専用。ボタンはadminのみ描画される）
$('#btnTypes').on('click', function() {
    window.open('/awami/connector_types', 'awamiTypes', 'width=900,height=920');
});
$('#btnLocate').on('click', () => locateNode($('#locateUrl').val()));
$('#locateUrl').on('keydown', function(ev) {
    if (ev.key === 'Enter') { ev.preventDefault(); locateNode($(this).val()); }
});
$(window).on('keydown', function(ev) {
    if (ev.key === 'Escape') {
        if (edgeMode) { edgeMode = null; clearSelHighlights(); updateEdgeModeHighlights(); }
        if (linkMode) { linkMode = null; clearSelHighlights(); updateLinkModeHighlights(); }
        if (mergeMode) { mergeMode = null; updateMergeHighlights(); }
        $('.modal-bg').hide(); hideMenu();
    }
});
(function initialLoad() {
    const locateTarget = getQueryParam('locate');
    if (locateTarget) {
        // locate指定時は全体表示せず、対象を中心に据える（倍率は既定1.0のまま）
        $('#locateUrl').val(locateTarget);
        loadData(false, function() { locateNode(locateTarget); });
    } else {
        loadData(true);
    }
})();
</script>
