<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>討論の展開 - あわみ</title>
<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
       background: #f4f6f8; color: #2b3440; line-height: 1.6; padding: 16px;
       height: 100vh; display: flex; flex-direction: column; }
h1 { font-size: 1.12em; margin-bottom: 2px; }
.sub { color: #7a8694; font-size: .8em; margin-bottom: 10px; }
.toolbar { margin-bottom: 10px; display: flex; gap: 8px; align-items: center; }
.btn { padding: 5px 12px; border: 1px solid #ccd4dc; border-radius: 6px;
       background: #fff; font-size: .82em; cursor: pointer; font-family: inherit; }
.btn:hover { background: #eef2f6; }
.list { flex: 1; overflow-y: auto; background: #fff;
        border: 1px solid #dde3ea; border-radius: 8px; padding: 10px 14px; }
.empty { color: #98a3ae; font-size: .88em; padding: 16px 4px; }
.chip { display: inline-block; font-size: .7em; padding: 1px 8px; border-radius: 10px; }
.chip.open { background: #e4f3e8; color: #21663a; }
.chip.closed { background: #eef2f6; color: #7a8694; }
a.evlink { color: #35618f; }
a.small { font-size: .78em; color: #6b86a5; margin-left: 8px; }

.ev { border-bottom: 1px solid #eef2f6; padding: 8px 2px; }
.ev .meta { color: #98a3ae; font-size: .74em; }
.ev .meta .qlabel { color: #6b86a5; }
.ev .body-text { white-space: pre-wrap; font-size: .95em; margin-top: 1px; }
.ev.node_open .body-text, .ev.poll_start .body-text { color: #3d4c5c; }
.ev .icon { margin-right: 4px; }
</style>
</head>
<body>
<h1>💬 討論の展開</h1>
<div class="sub">{{ canvas.name }}　／　3秒ごとに自動更新</div>
<div id="frozenBar" style="display:none;background:#eef2f6;color:#5a6672;border-radius:6px;padding:6px 10px;margin-bottom:8px;font-size:.82em;"></div>
<div class="toolbar">
    <button class="btn" id="btnOrder">表示順：新しい順</button>
</div>
<div class="list" id="evList"><div class="empty">まだ記録はありません</div></div>

<script>
const CANVAS_ID = {{ canvas.id }};
const FROZEN_RECORD = {{ sel_record if sel_record else "null" }};
let newestFirst = true;
let lastJson = null;

$('#btnOrder').on('click', function() {
    newestFirst = !newestFirst;
    $(this).text('表示順：' + (newestFirst ? '新しい順' : '古い順'));
    if (lastJson) render(lastJson);
});

function render(d) {
    lastJson = d;
    if (d.frozen) { $('#frozenBar').text('🗂 記録：' + (d.record_name||'') + '（保存時点の内容・自動更新なし）').show(); }
    const $l = $('#evList').empty();
    let evs = d.events.slice();
    if (newestFirst) evs.reverse();
    if (evs.length === 0) {
        $l.append($('<div class="empty">').text('まだ記録はありません'));
        return;
    }
    evs.forEach(function(e) {
        const $item = $('<div class="ev">').addClass(e.type);
        if (e.type === 'writein') {
            $item.append($('<div class="meta">')
                .append(document.createTextNode('✍ #' + e.no + '　' + e.time + '　'))
                .append($('<span class="qlabel">').text(e.question ? '〔' + e.question + '〕' : '')));
            $item.append($('<div class="body-text">').text(e.content));
        } else if (e.type === 'node_open') {
            $item.append($('<div class="meta">').text('📖 ' + e.time + '　資料を開いた'));
            const $b = $('<div class="body-text">');
            $b.append($('<a class="evlink" target="_blank">')
                .attr('href', e.url).text(e.label || e.url));
            $item.append($b);
        } else if (e.type === 'poll_start') {
            $item.append($('<div class="meta">').text('📢 ' + e.time + '　意見募集を開始（' + e.kind + '）'));
            const $b = $('<div class="body-text">').text(e.question);
            $b.append($('<a class="small" target="_blank">')
                .attr('href', e.vote_url).text('投票ページ'));
            if (e.console_url) {
                $b.append($('<a class="small" target="_blank">')
                    .attr('href', e.console_url).text('司会コンソール'));
            }
            $item.append($b);
        }
        $l.append($item);
    });
}

function load() {
    $.getJSON('/awami/api/canvas/' + CANVAS_ID + '/record' + (FROZEN_RECORD ? '?record_id=' + FROZEN_RECORD : ''), function(d) {
        if (d && d.success) render(d);
    });
}
load();
if (!FROZEN_RECORD) setInterval(load, 3000);
</script>
</body>
</html>

