<body>
<h1>📋 プレゼン計画</h1>
<div class="sub">{{ canvas.name }}</div>

<div class="toolbar" style="margin-bottom:6px;">
    <span style="font-size:.82em;color:#5a6672;">計画:</span>
    <select id="planSel" style="padding:5px 8px;border:1px solid #ccd4dc;border-radius:6px;font-size:.85em;font-family:inherit;max-width:220px;"></select>
    <button class="btn" id="btnPlanNew">＋ 新規</button>
    <button class="btn" id="btnPlanRename">改名</button>
    <button class="btn" id="btnPlanDel">削除</button>
</div>

<div class="toolbar">
    <button class="mode-btn sel" data-mode="edit">✏️ 編集</button>
    <button class="mode-btn" data-mode="rehearsal">🎧 リハーサル</button>
    <button class="mode-btn live" data-mode="live">🔴 実行</button>
    <span class="spacer"></span>
    <button class="done-btn" id="btnDone">完了</button>
</div>
<div class="mode-note" id="modeNote">キャンバスのノードを右クリック→「プレゼン計画に追加」で末尾に加わります．↑↓で並べ替え，⇥で直上ノードのsub（オプショナル提示）にできます．</div>

<div class="list" id="planList"><div class="empty">まだ計画はありません</div></div>

<script>
const CANVAS_ID = {{ canvas.id }};
let mode = 'edit';           // edit / rehearsal / live
let lastJson = null;
let PLANS = [];
let currentPlan = null;

function loadPlans(selId) {
    $.getJSON('/awami/api/canvas/' + CANVAS_ID + '/plans', function(d) {
        if (!d || !d.success) return;
        PLANS = d.plans;
        const $s = $('#planSel').empty();
        PLANS.forEach(p => $s.append($('<option>').val(p.id).text(p.name)));
        if (PLANS.length === 0) {
            currentPlan = null;
            $('#planList').empty().append($('<div class="empty">').text('計画がありません。「＋ 新規」で作成し、キャンバスのノードから追加してください。'));
            return;
        }
        currentPlan = (selId && PLANS.some(p => p.id == selId)) ? selId : PLANS[0].id;
        $s.val(currentPlan);
        load();
    });
}
$('#planSel').on('change', function() { currentPlan = parseInt($(this).val()); load(); });
$('#btnPlanNew').on('click', function() {
    const name = prompt('新しい計画の名前は？', '計画 ' + (PLANS.length + 1));
    if (name === null) return;
    $.ajax({ url: '/awami/api/canvas/' + CANVAS_ID + '/plans/create',
        method: 'POST', contentType: 'application/json',
        data: JSON.stringify({ name: name }),
        success: r => { if (r.success) loadPlans(r.id); } });
});
$('#btnPlanRename').on('click', function() {
    if (!currentPlan) return;
    const cur = PLANS.find(p => p.id == currentPlan);
    const name = prompt('計画名を変更:', cur ? cur.name : '');
    if (name === null) return;
    $.ajax({ url: '/awami/api/plan/' + currentPlan + '/rename',
        method: 'POST', contentType: 'application/json',
        data: JSON.stringify({ name: name }),
        success: r => { if (r.success) loadPlans(currentPlan); } });
});
$('#btnPlanDel').on('click', function() {
    if (!currentPlan) return;
    if (!confirm('この計画を削除します（計画の項目も消えます。ノード自体は残ります）。よろしいですか？')) return;
    $.ajax({ url: '/awami/api/plan/' + currentPlan + '/delete',
        method: 'POST', contentType: 'application/json', data: '{}',
        success: r => { if (r.success) loadPlans(); } });
});

const NOTES = {
    edit: 'キャンバスのノードを右クリック→「プレゼン計画に追加」で末尾に加わります．↑↓で並べ替え，⇥で直上ノードのsub（オプショナル提示）にできます．',
    rehearsal: 'リハーサルモード：「開く」で資料を別ウィンドウに開きます．討論の展開には記録されません．',
    live: '実行モード：「開く」で資料を開き，討論の展開に記録されます（即興で開いたものと同じ扱い）．'
};

$('.mode-btn').on('click', function() {
    $('.mode-btn').removeClass('sel');
    $(this).addClass('sel');
    mode = $(this).data('mode');
    $('#modeNote').text(NOTES[mode]).toggleClass('live', mode === 'live');
    if (lastJson) render(lastJson);
});


$('#btnDone').on('click', () => window.close());

function api(url, data, done) {
    $.ajax({ url: url, method: 'POST', contentType: 'application/json',
             data: JSON.stringify(data || {}),
             success: resp => { if (resp.success) { if (done) done(resp); load(); } },
           });
}

function render(d) {
    lastJson = d;
    const $l = $('#planList').empty();
    if (d.items.length === 0) {
        $l.append($('<div class="empty">').text('まだ計画はありません．キャンバスのノードを右クリック→「プレゼン計画に追加」．'));
        return;
    }
    let mainNo = 0;
    d.items.forEach(function(it, i) {
        const $row = $('<div class="item">').toggleClass('indent', !!it.indent)
                                            .toggleClass('deleted', !!it.deleted);
        if (!it.indent) mainNo += 1;
        $row.append($('<div class="num">').text(it.indent ? '' : mainNo + '.'));
        const $label = $('<div class="label">').text(it.label).attr('title', it.label);
        $row.append($label);
        if (it.indent) $row.append($('<span class="sub-badge">').text('sub'));

        if (mode === 'edit') {
            const $up = $('<button class="op">↑</button>').prop('disabled', i === 0)
                .on('click', () => api('/awami/api/plan_item/' + it.id + '/move', { direction: 'up' }));
            const $dn = $('<button class="op">↓</button>').prop('disabled', i === d.items.length - 1)
                .on('click', () => api('/awami/api/plan_item/' + it.id + '/move', { direction: 'down' }));
            const $ind = $('<button class="op">')
                .text(it.indent ? '⇤ 解除' : '⇥ sub')
                .prop('disabled', i === 0 && !it.indent)
                .on('click', () => api('/awami/api/plan_item/' + it.id + '/indent', { indent: it.indent ? 0 : 1 }));
            const $del = $('<button class="op del">✕</button>')
                .on('click', () => api('/awami/api/plan_item/' + it.id + '/delete'));
            $row.append($up, $dn, $ind, $del);
        } else {
            const live = (mode === 'live');
            const $open = $('<button class="open-btn">')
                .addClass(live ? 'live' : 'rehearsal')
                .text('開く')
                .prop('disabled', !it.url || it.deleted)
                .on('click', function() {
                    if (live) {
                        // 実行：討論の展開に記録してから開く（即興openと同じイベント）
                        $.ajax({ url: '/awami/api/canvas/' + CANVAS_ID + '/node_open',
                                 method: 'POST', contentType: 'application/json',
                                 data: JSON.stringify({ node_id: it.node_id }) });
                    }
                    window.open(it.url, '_blank');
                });
            $row.append($open);
        }
        $l.append($row);
    });
}

function load() {
    if (!currentPlan) return;
    $.getJSON('/awami/api/canvas/' + CANVAS_ID + '/plan?plan_id=' + currentPlan, function(d) {
        if (d && d.success) render(d);
    });
}
loadPlans({{ sel_plan if sel_plan else 'null' }});
setInterval(load, 3000);   // キャンバス側からの追加を拾う
</script>
</body>
</html>

