$('#btnReload').on('click', load);
$('#btnSnap').on('click', function() {
    const name = prompt('この記録の名前は？（例：第3回・前半の投票まで）', '記録');
    if (name === null) return;
    $.ajax({ url: '/awami/api/canvas/' + CANVAS_ID + '/records/snapshot', method: 'POST',
        contentType: 'application/json', data: JSON.stringify({ name: name }),
        success: function(x) {
            if (x.success) { showResult('「' + x.name + '」を記録しました（展開' + x.flow_count + '件・投票' + x.poll_count + '件）', false); load(); }
            else showResult('エラー: ' + x.error, true);
        },
        error: () => showResult('通信エラー', true) });
});
load();
</script>
</body>
</html>

