<body>
<h1>🎛 司会コンソール　<span class="chip {{ poll.status }}">{{ '受付中' if poll.status == 'open' else '締切' }}</span></h1>
<div class="sub">キャンバス：{{ poll.canvas_name }}</div>
<div id="result"></div>

<div class="card">
    {% if poll.choice_question %}<div class="q">n択：{{ poll.choice_question }}</div>
    <div class="muted">{% for o in options %}{{ loop.index }}. {{ o.label }}　{% endfor %}</div>{% endif %}
    {% if poll.writein_question %}<div class="q" style="margin-top:8px;">write-in：{{ poll.writein_question }}</div>{% endif %}
</div>

<div class="card">
    <div class="form-row"><label>参加者URL（このURLを知っている人だけがアクセスできます）</label>
        <div class="url-box" id="voteUrl">{{ vote_url }}</div>
    </div>
    <div class="ops">
        <button class="btn" id="btnDisplay">🖥 URLを大きく表示（投影用）</button>
        <button class="btn" id="btnStats">📊 stats表示</button>
        <button class="btn secondary" id="btnVoteTest">🗳 投票画面を開く（確認用）</button>
        <button class="btn secondary" id="btnCopy">URLをコピー</button>
        <button class="btn" id="btnToggle" style="background:#a53d3d;">
            {{ '締め切る' if poll.status == 'open' else '再開する' }}</button>
    </div>
</div>

<script>
const TOKEN = '{{ poll.token }}';
function showResult(m, e) {
    $('#result').text(m).removeClass('success error')
        .addClass(e ? 'error' : 'success').show();
    setTimeout(() => $('#result').fadeOut(), 4000);
}
$('#btnDisplay').on('click', () =>
    window.open('/awami/poll/' + TOKEN + '/display', 'awamiDisp' + TOKEN, 'width=1100,height=520'));
$('#btnStats').on('click', () =>
    window.open('/awami/poll/' + TOKEN + '/stats', 'awamiStats' + TOKEN, 'width=900,height=820'));
$('#btnVoteTest').on('click', () =>
    window.open('/awami/vote/' + TOKEN, 'awamiVote' + TOKEN, 'width=560,height=820'));
$('#btnCopy').on('click', function() {
    navigator.clipboard.writeText($('#voteUrl').text().trim())
        .then(() => showResult('コピーしました', false));
});
$('#btnToggle').on('click', function() {
    $.ajax({ url: '/awami/api/poll/' + TOKEN + '/toggle', method: 'POST',
             contentType: 'application/json', data: '{}',
        success: function(resp) {
            if (resp.success) location.reload();
            else showResult('エラー: ' + resp.error, true);
        },
        error: () => showResult('通信エラー', true) });
});
</script>
</body>
