<!DOCTYPE html>
<html lang="ja">
<head>
<meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>意見募集の作成 - あわみ</title>
<script src="https://code.jquery.com/jquery-3.6.0.min.js"></script>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: "Hiragino Kaku Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
       background: #f4f6f8; color: #2b3440; line-height: 1.6; padding: 18px; }
h1 { font-size: 1.15em; margin-bottom: 4px; }
.sub { color: #7a8694; font-size: .82em; margin-bottom: 14px; }
.card { background: #fff; border: 1px solid #dde3ea; border-radius: 10px;
        padding: 16px 18px; margin-bottom: 12px; }
.btn { display: inline-block; padding: 8px 16px; border: none; border-radius: 6px;
       background: #35618f; color: #fff; font-size: .95em; cursor: pointer; }
.btn:hover { background: #2a4d72; }
.btn.secondary { background: #fff; color: #2b3440; border: 1px solid #ccd4dc; }
.btn.secondary:hover { background: #eef2f6; }
.btn.big { font-size: 1.1em; padding: 12px 26px; }
.form-row { margin-bottom: 12px; }
.form-row label { display: block; font-size: .85em; color: #5a6672; margin-bottom: 4px; }
.form-row input[type=text], .form-row textarea {
    width: 100%; padding: 8px 10px; border: 1px solid #ccd4dc; border-radius: 6px;
    font-size: .95em; font-family: inherit; }
.form-row textarea { min-height: 110px; resize: vertical; }
#result { display: none; padding: 9px 13px; border-radius: 6px; margin-bottom: 12px; font-size: .9em; }
#result.success { background: #e4f3e8; color: #21663a; }
#result.error { background: #fbe4e4; color: #8f2323; }
.chip { display: inline-block; font-size: .76em; padding: 2px 10px; border-radius: 10px; }
.chip.open { background: #e4f3e8; color: #21663a; }
.chip.closed { background: #fbe4e4; color: #8f2323; }
.q { font-size: 1.02em; font-weight: bold; margin-bottom: 8px; }
.bar-row { display: flex; align-items: center; gap: 8px; margin-bottom: 7px; }
.bar-label { width: 32%; min-width: 110px; font-size: .92em; text-align: right; }
.bar-track { flex: 1; background: #eef2f6; border-radius: 5px; height: 22px; position: relative; }
.bar-fill { background: #4a7ebb; height: 100%; border-radius: 5px;
            transition: width .4s; min-width: 2px; }
.bar-count { width: 46px; font-size: .95em; font-weight: bold; }
.wi-item { border-top: 1px solid #eef2f6; padding: 8px 2px; }
.wi-meta { color: #98a3ae; font-size: .76em; margin-bottom: 2px; }
.wi-body { white-space: pre-wrap; font-size: .95em; }
.muted { color: #98a3ae; font-size: .85em; }

.opt-row { display: flex; gap: 6px; margin-bottom: 6px; }
.opt-row input { flex: 1; padding: 8px 10px; border: 1px solid #ccd4dc;
                 border-radius: 6px; font-size: .95em; font-family: inherit; }
.opt-row button { flex-shrink: 0; }
.mode-sel { display: flex; gap: 8px; margin-bottom: 16px; flex-wrap: wrap; }
.mode-btn {
    flex: 1; min-width: 150px; padding: 14px 10px; text-align: center;
    border: 2px solid #ccd4dc; border-radius: 10px; background: #fff;
    font-size: .98em; cursor: pointer; font-family: inherit;
}
.mode-btn:hover { background: #eef2f6; }
.mode-btn.sel { border-color: #35618f; background: #eaf1f8; font-weight: bold; }
.mode-btn .d { display: block; font-size: .74em; color: #7a8694;
               font-weight: normal; margin-top: 3px; }
</style>
</head>
<body>
<h1>📢 意見募集の作成</h1>
<div class="sub">キャンバス：{{ canvas.name }}　／　n択・write-inのどちらか一方だけでも作れます</div>
<div id="result"></div>

<div class="mode-sel">
    <button class="mode-btn sel" data-mode="choice" type="button">
        🗳 投票（n択）<span class="d">選択肢から選んでもらう</span></button>
    <button class="mode-btn" data-mode="writein" type="button">
        ✍ 自由意見<span class="d">文章で書いてもらう</span></button>
</div>
<div class="muted" style="margin:-8px 0 14px;">意見募集は単機能です。投票と自由意見の両方が必要なときは、それぞれ別に発行してください（受講生の画面にはボタンが並んで表示されます）。</div>

<div class="card" id="choiceCard">
    <div class="form-row">
        <label>選択式（n択）の問い</label>
        <input type="text" id="choiceQ" maxlength="500" placeholder="例：次に扱ってほしいテーマは？">
    </div>
    <div class="form-row">
        <label>選択肢（2つ以上・登録順に表示されます）</label>
        <div id="optList"></div>
        <button class="btn secondary" id="btnAddOpt" type="button">＋ 選択肢を追加</button>
    </div>
</div>

<div class="card" id="writeinCard" style="display:none;">
    <div class="form-row">
        <label>write-in（自由記述）の問い</label>
        <input type="text" id="writeinQ" maxlength="500" placeholder="例：今日の説明で分かりにくかった点を教えてください">
    </div>
</div>

<button class="btn big" id="btnCreate">意見募集を開始する</button>
<div class="muted" style="margin-top:8px;">開始すると、受講生の画面の隅に投票ボタンが現れ、司会コンソールに移ります。</div>

<script>
const CANVAS_ID = {{ canvas.id }};
let mode = 'choice';   // choice / writein（単機能）

$('.mode-btn').on('click', function() {
    $('.mode-btn').removeClass('sel');
    $(this).addClass('sel');
    mode = $(this).data('mode');
    $('#choiceCard').toggle(mode === 'choice');
    $('#writeinCard').toggle(mode === 'writein');
});

function showResult(m, e) {
    $('#result').text(m).removeClass('success error')
        .addClass(e ? 'error' : 'success').show();
}
function addOpt(v) {
    const row = $('<div class="opt-row">');
    row.append($('<input type="text" maxlength="255" placeholder="選択肢">').val(v || ''));
    row.append($('<button class="btn secondary" type="button">×</button>')
        .on('click', () => row.remove()));
    $('#optList').append(row);
}
for (let i = 0; i < 4; i++) addOpt();
$('#btnAddOpt').on('click', () => addOpt());

$('#btnCreate').on('click', function() {
    const useChoice = (mode === 'choice');
    const useWritein = (mode === 'writein');
    const cq = useChoice ? $('#choiceQ').val().trim() : '';
    const opts = useChoice ? $('#optList input').map((i, e) => e.value).get()
                             .filter(v => v.trim()) : [];
    const wq = useWritein ? $('#writeinQ').val().trim() : '';
    if (useChoice && !cq) { showResult('選択式の問いを入力してください', true); return; }
    if (useChoice && opts.length < 2) { showResult('選択肢を2つ以上入力してください', true); return; }
    if (useWritein && !wq) { showResult('自由記述の問いを入力してください', true); return; }
    const payload = {
        choice_question: cq,
        options: opts,
        writein_question: wq
    };
    $.ajax({
        url: '/awami/api/canvas/' + CANVAS_ID + '/poll/create',
        method: 'POST', contentType: 'application/json',
        data: JSON.stringify(payload),
        success: function(resp) {
            if (resp.success) { window.location.href = resp.console_url; }
            else showResult('エラー: ' + resp.error, true);
        },
        error: function(xhr) {
            let d = '';
            try { d = JSON.parse(xhr.responseText).error; } catch (e) {}
            showResult('エラー（HTTP ' + xhr.status + '）: ' + (d || '失敗しました'), true);
        }
    });
});
</script>
</body>
</html>

