body { font-size: 1.06em; }
.bar-track { height: 30px; }
</style>
</head>
<body>
<h1>📊 意見募集 stats　<span class="chip open" id="statusChip">受付中</span></h1>
<div class="sub">キャンバス：{{ poll.canvas_name }}　／　2秒ごとに自動更新</div>

<div class="card" id="choiceBlock" style="display:none;">
    <div class="q" id="choiceQ"></div>
    <div id="bars"></div>
    <div class="muted" id="totalVotes"></div>
</div>

<div class="card" id="writeinBlock" style="display:none;">
    <div class="q" id="writeinQ"></div>
    <div id="wiList"></div>
</div>

<script>
const TOKEN = '{{ poll.token }}';

function renderResults(d) {
    const $c = $('#choiceBlock');
    if (d.choice_question) {
        $c.show();
        $('#choiceQ').text(d.choice_question);
        const maxN = Math.max.apply(null, d.options.map(o => o.count).concat([1]));
        const $bars = $('#bars').empty();
        d.options.forEach(function(o) {
            const pct = Math.round(o.count / maxN * 100);
            $bars.append(
                $('<div class="bar-row">')
                    .append($('<div class="bar-label">').text(o.label))
                    .append($('<div class="bar-track">')
                        .append($('<div class="bar-fill">').css('width', pct + '%')))
                    .append($('<div class="bar-count">').text(o.count)));
        });
        $('#totalVotes').text('投票数：' + d.total_votes);
    } else { $c.hide(); }
    const $w = $('#writeinBlock');
    if (d.writein_question) {
        $w.show();
        $('#writeinQ').text(d.writein_question);
        const $list = $('#wiList').empty();
        if (d.writeins.length === 0) {
            $list.append($('<div class="muted">').text('まだ投稿はありません'));
        }
        d.writeins.forEach(function(x) {
            $list.append($('<div class="wi-item">')
                .append($('<div class="wi-meta">').text('#' + x.no + '　' + x.time))
                .append($('<div class="wi-body">').text(x.content)));
        });
    } else { $w.hide(); }
    $('#statusChip').text(d.status === 'open' ? '受付中' : '締切')
        .removeClass('open closed').addClass(d.status);
}
function pollResults() {
    $.getJSON('/awami/api/poll/' + TOKEN + '/results', function(d) {
        if (d && d.success) renderResults(d);
    });
}

pollResults();
setInterval(pollResults, 2000);
</script>
</body>
</html>

