<body>
<h1>🗳 投票　<span class="chip {{ poll.status }}" id="statusChip">{{ '受付中' if poll.status == 'open' else '締切' }}</span></h1>
<div class="sub">{{ poll.canvas_name }}</div>
<div id="result"></div>

{% if poll.choice_question %}
<div class="card">
    <div class="q">{{ poll.choice_question }}</div>
    {% for o in options %}
    <button class="opt-btn" data-index="{{ o.opt_index }}">{{ loop.index }}. {{ o.label }}</button>
    {% endfor %}
</div>
{% endif %}

{% if poll.writein_question %}
<div class="card">
    <div class="q">{{ poll.writein_question }}</div>
    <div class="form-row">
        <textarea id="writein" placeholder="Markdownで記入できます"></textarea>
    </div>
</div>
{% endif %}

<button class="btn big" id="btnVote">投票</button>
<div class="muted" style="margin-top:6px;">選択とwrite-inは片方だけでも投票できます。選択は最新の投票で上書き、write-inは追記されます。</div>

<div style="margin-top:14px;"></div>
<div class="card" id="choiceBlock" style="display:none;">
    <div class="q" id="choiceQ"></div>
    <div id="bars"></div>
    <div class="muted" id="totalVotes"></div>
</div>
<div class="card" id="writeinBlock" style="display:none;">
    <div class="q" id="writeinQ"></div>
    <div id="wiList"></div>
</div>

<script>
const TOKEN = '{{ poll.token }}';
let selected = null;
function showResult(m, e) {
    $('#result').text(m).removeClass('success error')
        .addClass(e ? 'error' : 'success').show();
    setTimeout(() => $('#result').fadeOut(), 5000);
}
$('.opt-btn').on('click', function() {
    $('.opt-btn').removeClass('sel');
    $(this).addClass('sel');
    selected = parseInt($(this).data('index'));
});
$('#btnVote').on('click', function() {
    const w = ($('#writein').val() || '').trim();
    if (selected === null && !w) {
        showResult('選択かwrite-inのどちらかを入力してください', true); return;
    }
    $.ajax({
        url: '/awami/api/vote/' + TOKEN, method: 'POST',
        contentType: 'application/json',
        data: JSON.stringify({ opt_index: selected, writein: w }),
        success: function(resp) {
            if (!resp.success) { showResult('エラー: ' + resp.error, true); return; }
            let m = '投票を受け付けました';
            if (resp.writein_no) m += '（write-in #' + resp.writein_no + '）';
            showResult(m, false);
            $('#writein').val('');
            pollResults();
        },
        error: function(xhr) {
            let d = '';
            try { d = JSON.parse(xhr.responseText).error; } catch (e) {}
            showResult('エラー（HTTP ' + xhr.status + '）: ' + (d || '失敗しました'), true);
        }
    });
});

function renderResults(d) {
    const $c = $('#choiceBlock');
    if (d.choice_question) {
        $c.show();
        $('#choiceQ').text(d.choice_question);
        const maxN = Math.max.apply(null, d.options.map(o => o.count).concat([1]));
        const $bars = $('#bars').empty();
        d.options.forEach(function(o) {
            const pct = Math.round(o.count / maxN * 100);
            $bars.append(
                $('<div class="bar-row">')
                    .append($('<div class="bar-label">').text(o.label))
                    .append($('<div class="bar-track">')
                        .append($('<div class="bar-fill">').css('width', pct + '%')))
                    .append($('<div class="bar-count">').text(o.count)));
        });
        $('#totalVotes').text('投票数：' + d.total_votes);
    } else { $c.hide(); }
    const $w = $('#writeinBlock');
    if (d.writein_question) {
        $w.show();
        $('#writeinQ').text(d.writein_question);
        const $list = $('#wiList').empty();
        if (d.writeins.length === 0) {
            $list.append($('<div class="muted">').text('まだ投稿はありません'));
        }
        d.writeins.forEach(function(x) {
            $list.append($('<div class="wi-item">')
                .append($('<div class="wi-meta">').text('#' + x.no + '　' + x.time))
                .append($('<div class="wi-body">').text(x.content)));
        });
    } else { $w.hide(); }
    $('#statusChip').text(d.status === 'open' ? '受付中' : '締切')
        .removeClass('open closed').addClass(d.status);
}
function pollResults() {
    $.getJSON('/awami/api/poll/' + TOKEN + '/results', function(d) {
        if (d && d.success) renderResults(d);
    });
}

pollResults();
setInterval(pollResults, 3000);
</script>
