<body>
    <div class="header-bar">
        <div class="container">
            <h4 class="mb-1">📄 公開文書一覧</h4>
            <div class="login-hint">
                <a href="{{ url_for('auth.login') }}">ログイン</a> するとすべての機能が利用できます
            </div>
        </div>
    </div>

    <div class="container" style="max-width: 720px;">
        {% if documents %}
            {% for doc in documents %}
            <div class="card doc-card">
                <div class="card-body d-flex align-items-center justify-content-between gap-3">
                    <div>
                        <div class="doc-title">{{ doc.title }}</div>
                        <div class="doc-date">
                            更新日: {{ doc.updated_at.strftime('%Y-%m-%d') if doc.updated_at else 'N/A' }}
                        </div>
                    </div>
                    <a href="{{ url_for('document_archive.plain_view', doc_id=doc.id) }}"
                       class="btn-view">
                        閲覧
                    </a>
                </div>
            </div>
            {% endfor %}
        {% else %}
            <div class="text-center text-muted py-5">
                <p>公開中の文書はありません</p>
            </div>
        {% endif %}
    </div>
</body>
</html>

