            cursor: pointer;
            transition: all 0.3s ease;
            text-decoration: none;
            color: inherit;
            display: flex;
            flex-direction: column;
            align-items: center;
            text-align: center;
        }

        .version-card:hover {
            transform: translateY(-8px);
            border-color: #667eea;
            box-shadow: 0 8px 20px rgba(102, 126, 234, 0.3);
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
        }

        .version-card .icon {
            font-size: 40px;
            margin-bottom: 15px;
        }

        .version-card h2 {
            font-size: 20px;
            margin-bottom: 10px;
        }

        .version-card p {
            font-size: 14px;
            opacity: 0.8;
        }

